class AuditError(Exception):
    """Closed-world validation failure."""


class VerificationFailure(AuditError):
    """A complete observation that fails a semantic verification gate."""


class LocalGitInvocationFailure(AuditError):
    """A local Git child failed before producing a complete observation."""

    def __init__(self, message: str, returncode: Optional[int] = None):
        super().__init__(message)
        self.returncode = returncode


class ObservationIncomplete(AuditError):
    """A child returned bytes that cannot form the required observation."""


class SecretScanError(AuditError):
    """A redacted secret-scan failure."""

    def __init__(self, message: str, record: Mapping[str, Any]):
        super().__init__(message)
        self.record = dict(record)


class SafeCaptureError(AuditError):
    """A parser failure carrying only a redacted capture disposition."""

    def __init__(self, message: str, record: Mapping[str, Any]):
        super().__init__(message)
        self.record = dict(record)


class OwnedSecretBuffer:
    """Single-owner mutable secret storage with deterministic destruction."""

    def __init__(self, owner: bytearray):
        if not isinstance(owner, bytearray):
            raise AuditError("secret owner must be a bytearray")
        self._owner: Optional[bytearray] = owner

    @classmethod
    def take(cls, owner: bytearray) -> "OwnedSecretBuffer":
        return cls(owner)

    def __enter__(self) -> "OwnedSecretBuffer":
        if self._owner is None:
            raise AuditError("secret buffer is released")
        return self

    def __exit__(self, exc_type: Any, exc: Any, traceback: Any) -> bool:
        del exc_type, exc, traceback
        self.release()
        return False

    def __del__(self) -> None:
        try:
            self.release()
        except BaseException:
            pass

    def owner(self) -> bytearray:
        if self._owner is None:
            raise AuditError("secret buffer is released")
        return self._owner

    def view(self) -> memoryview:
        if self._owner is None:
            raise AuditError("secret buffer is released")
        return memoryview(self._owner)

    def release(self) -> None:
        owner = self._owner
        if owner is None:
            return
        for index in range(len(owner)):
            owner[index] = 0
        self._owner = None

    def move_owner(self) -> bytearray:
        """Transfer the only mutable owner to another short-lived component."""

        if self._owner is None:
            raise AuditError("secret buffer is released")
        owner = self._owner
        self._owner = None
        return owner


class DisclosureWorkBudget:
    """One pre-materialization work account shared by disclosure categories."""

    def __init__(
        self, *, maximum_count: int, maximum_bytes: int, maximum_depth: int
    ):
        for label, value in (
            ("count", maximum_count),
            ("bytes", maximum_bytes),
            ("depth", maximum_depth),
        ):
            if not isinstance(value, int) or isinstance(value, bool) or value < 0:
                raise AuditError("aggregate disclosure " + label + " bound drift")
        self.maximum_count = maximum_count
        self.maximum_bytes = maximum_bytes
        self.maximum_depth = maximum_depth
        self.consumed_count = 0
        self.consumed_bytes = 0
        self.maximum_observed_depth = 0
        self.categories: Dict[str, int] = {}

    def charge(
        self, category: str, *, count: int, byte_count: int, depth: int
    ) -> None:
        if (
            not isinstance(category, str)
            or not category
            or any(
                not isinstance(value, int)
                or isinstance(value, bool)
                or value < 0
                for value in (count, byte_count, depth)
            )
        ):
            raise AuditError("aggregate disclosure charge drift")
        next_count = self.consumed_count + count
        next_bytes = self.consumed_bytes + byte_count
        if next_count > self.maximum_count:
            raise AuditError("aggregate disclosure count exceeds bound")
        if next_bytes > self.maximum_bytes:
            raise AuditError("aggregate disclosure bytes exceed bound")
        if depth > self.maximum_depth:
            raise AuditError("aggregate disclosure depth exceeds bound")
        self.consumed_count = next_count
        self.consumed_bytes = next_bytes
        self.maximum_observed_depth = max(self.maximum_observed_depth, depth)
        self.categories[category] = self.categories.get(category, 0) + count

    def projection(self) -> Dict[str, Any]:
        return {
            "maximumCount": self.maximum_count,
            "maximumBytes": self.maximum_bytes,
            "maximumDepth": self.maximum_depth,
            "consumedCount": self.consumed_count,
            "consumedBytes": self.consumed_bytes,
            "maximumObservedDepth": self.maximum_observed_depth,
            "categories": dict(sorted(self.categories.items())),
        }

    @property
    def remaining_bytes(self) -> int:
        return self.maximum_bytes - self.consumed_bytes


@dataclass(frozen=True)
class CommandContext:
    """Explicit immutable authority passed from the sterile launcher."""

    _sterile_invocation_bytes: Optional[bytes] = None
    _sterile_invocation_start_bytes: Optional[bytes] = None
    runtime: Optional[Any] = None
    policy_capture: Optional[Any] = None

    @property
    def sterile_invocation(self) -> Optional[Mapping[str, Any]]:
        payload = self._sterile_invocation_bytes
        if self._sterile_invocation_start_bytes is not None:
            start = parse_canonical_json(
                self._sterile_invocation_start_bytes
            )
            if not isinstance(start, dict) or not isinstance(
                start.get("invocation"), dict
            ):
                raise AuditError("sterile invocation start context drift")
            payload = canonical_json_bytes(start["invocation"])
        if payload is None:
            return None
        value = parse_canonical_json(payload)
        if not isinstance(value, dict):
            raise AuditError("sterile invocation context shape drift")
        return MappingProxyType(value)

    @property
    def sterile_invocation_start(
        self,
    ) -> Optional[Mapping[str, Any]]:
        if self._sterile_invocation_start_bytes is None:
            return None
        value = parse_canonical_json(
            self._sterile_invocation_start_bytes
        )
        if not isinstance(value, dict):
            raise AuditError("sterile invocation start context drift")
        return MappingProxyType(value)

    def with_sterile_invocation(
        self, invocation: Mapping[str, Any]
    ) -> "CommandContext":
        if (
            self._sterile_invocation_bytes is not None
            or self._sterile_invocation_start_bytes is not None
        ):
            raise AuditError("sterile invocation already bound")
        if not isinstance(invocation, Mapping):
            raise AuditError("sterile invocation context type drift")
        return CommandContext(
            _sterile_invocation_bytes=canonical_json_bytes(dict(invocation)),
            runtime=self.runtime,
            policy_capture=self.policy_capture,
        )

    def with_sterile_invocation_start(
        self, start_record: Mapping[str, Any]
    ) -> "CommandContext":
        if (
            self._sterile_invocation_bytes is not None
            or self._sterile_invocation_start_bytes is not None
        ):
            raise AuditError("sterile invocation already bound")
        if not isinstance(start_record, Mapping):
            raise AuditError("sterile invocation start context type drift")
        start = dict(start_record)
        _verify_self_digest(start)
        _validate_ledger_record_shape(start)
        invocation = start.get("invocation")
        if not isinstance(invocation, Mapping):
            raise AuditError("sterile invocation start context drift")
        invocation_copy = dict(invocation)
        _verify_self_digest(invocation_copy)
        if (
            start.get("operationKind")
            != "sterile-invocation-started-linked"
            or start.get("completionState") != "open"
            or start.get("inputDigest")
            != invocation_copy.get("recordDigest")
        ):
            raise AuditError("sterile invocation start context drift")
        return CommandContext(
            _sterile_invocation_start_bytes=canonical_json_bytes(start),
            runtime=self.runtime,
            policy_capture=self.policy_capture,
        )


def _sha256(payload: bytes) -> str:
    return hashlib.sha256(payload).hexdigest()


def _validate_unicode(value: str) -> None:
    try:
        value.encode("utf-8", "strict")
    except UnicodeEncodeError as exc:
        raise AuditError("invalid Unicode") from exc
    if any(0xD800 <= ord(character) <= 0xDFFF for character in value):
        raise AuditError("invalid Unicode surrogate")


def _validate_json_value(value: Any) -> None:
    if value is None or isinstance(value, bool):
        return
    if isinstance(value, int):
        if abs(value) > MAX_SAFE_INTEGER:
            raise AuditError("unsafe integer")
        return
    if isinstance(value, float):
        raise AuditError("floats are forbidden")
    if isinstance(value, str):
        _validate_unicode(value)
        return
    if isinstance(value, list):
        for item in value:
            _validate_json_value(item)
        return
    if isinstance(value, dict):
        for key, item in value.items():
            if not isinstance(key, str):
                raise AuditError("JSON object key must be a string")
            _validate_unicode(key)
            _validate_json_value(item)
        return
    raise AuditError("unsupported JSON type")


def canonical_json_bytes(value: Any) -> bytes:
    _validate_json_value(value)
    try:
        encoded = json.dumps(
            value,
            ensure_ascii=False,
            allow_nan=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8", "strict") + b"\n"
    except (TypeError, ValueError, UnicodeEncodeError) as exc:
        raise AuditError("noncanonical JSON value") from exc
    if len(encoded) > MAX_JSON_BYTES:
        raise AuditError("canonical JSON exceeds bound")
    return encoded


def _reject_constant(_value: str) -> None:
    raise AuditError("non-finite number")


def _parse_integer(value: str) -> int:
    parsed = int(value, 10)
    if abs(parsed) > MAX_SAFE_INTEGER:
        raise AuditError("unsafe integer")
    return parsed


def _reject_float(_value: str) -> None:
    raise AuditError("floats are forbidden")


def _pairs_no_duplicates(pairs: Sequence[Tuple[str, Any]]) -> Dict[str, Any]:
    result: Dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise AuditError("duplicate JSON key")
        result[key] = value
    return result


def parse_canonical_json(payload: bytes) -> Any:
    if not isinstance(payload, bytes) or not payload or len(payload) > MAX_JSON_BYTES:
        raise AuditError("invalid canonical JSON byte count")
    try:
        text = payload.decode("utf-8", "strict")
    except UnicodeDecodeError as exc:
        raise AuditError("invalid UTF-8") from exc
    try:
        value = json.loads(
            text,
            object_pairs_hook=_pairs_no_duplicates,
            parse_int=_parse_integer,
            parse_float=_reject_float,
            parse_constant=_reject_constant,
        )
    except AuditError:
        raise
    except (json.JSONDecodeError, ValueError) as exc:
        raise AuditError("malformed JSON") from exc
    _validate_json_value(value)
    if canonical_json_bytes(value) != payload:
        raise AuditError("noncanonical JSON bytes")
    return value


def _require_lower_hex(value: Any, length: int, label: str) -> str:
    if not isinstance(value, str) or re.fullmatch(r"[0-9a-f]{%d}" % length, value) is None:
        raise AuditError(label + " must be full lowercase hex")
    return value


@dataclass(frozen=True)
class RawDiffEntry:
    old_mode: str
    new_mode: str
    old_oid: str
    new_oid: str
    status: str
    old_path_b64: str
    new_path_b64: str


def _raw_entry_projection(entry: RawDiffEntry) -> Dict[str, Any]:
    if not isinstance(entry, RawDiffEntry):
        raise AuditError("raw manifest entry type drift")
    return asdict(entry)


def parse_raw_diff_z(payload: bytes, object_format: str) -> List[RawDiffEntry]:
    """Parse the closed ``git diff --raw -z`` grammar without decoding paths."""

    if not isinstance(payload, bytes):
        raise AuditError("raw diff must be bytes")
    oid_length = OBJECT_HEX_LENGTH.get(object_format)
    if oid_length is None:
        raise AuditError("unknown object format")
    if payload == b"":
        return []
    fields_raw = payload.split(b"\x00")
    if fields_raw[-1] != b"":
        raise AuditError("raw diff lacks terminal NUL")
    fields_raw.pop()
    entries: List[RawDiffEntry] = []
    destination_paths = set()
    cursor = 0
    while cursor < len(fields_raw):
        header = fields_raw[cursor]
        cursor += 1
        match = RAW_HEADER.fullmatch(header)
        if match is None:
            raise AuditError("raw diff header drift")
        old_mode_b, new_mode_b, old_oid_b, new_oid_b, status_b = match.groups()
        if len(old_oid_b) != oid_length or len(new_oid_b) != oid_length:
            raise AuditError("abbreviated or wrong-format object ID")
        status = status_b.decode("ascii")
        status_kind = status[0]
        if status_kind not in RAW_STATUS_KINDS:
            raise AuditError("unknown raw diff status")
        score = status[1:]
        if status_kind in ("R", "C"):
            if not score or int(score, 10) > 100:
                raise AuditError("rename/copy status score drift")
            path_count = 2
        else:
            if score:
                raise AuditError("unexpected status score")
            path_count = 1
        if cursor + path_count > len(fields_raw):
            raise AuditError("raw diff path arity/truncation")
        paths = fields_raw[cursor : cursor + path_count]
        cursor += path_count
        if any(path == b"" for path in paths):
            raise AuditError("empty raw diff path")
        old_path = paths[0]
        new_path = paths[-1]
        if new_path in destination_paths:
            raise AuditError("duplicate destination raw path")
        destination_paths.add(new_path)
        entries.append(
            RawDiffEntry(
                old_mode=old_mode_b.decode("ascii"),
                new_mode=new_mode_b.decode("ascii"),
                old_oid=old_oid_b.decode("ascii"),
                new_oid=new_oid_b.decode("ascii"),
                status=status,
                old_path_b64=base64.b64encode(old_path).decode("ascii"),
                new_path_b64=base64.b64encode(new_path).decode("ascii"),
            )
        )
    return entries


def parse_cat_file_batch_results(
    payload: bytes,
    requested_oids: Sequence[str],
) -> List[Tuple[str, bytes]]:
    """Parse exact ``git cat-file --batch`` framing, including binary bodies."""

    if not isinstance(payload, bytes) or not isinstance(requested_oids, (list, tuple)):
        raise AuditError("cat-file batch input type drift")
    if len(requested_oids) > MAX_OBJECT_COUNT:
        raise AuditError("cat-file batch object count exceeds bound")
    if not requested_oids:
        if payload:
            raise AuditError("cat-file batch returned unrequested bytes")
        return []
    expected_length: Optional[int] = None
    for oid in requested_oids:
        if not isinstance(oid, str) or re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", oid) is None:
            raise AuditError("cat-file batch request OID drift")
        if expected_length is None:
            expected_length = len(oid)
        elif len(oid) != expected_length:
            raise AuditError("mixed object formats in cat-file batch")
    cursor = 0
    aggregate_size = 0
    results: List[Tuple[str, bytes]] = []
    for expected_oid in requested_oids:
        newline = payload.find(b"\n", cursor)
        if newline < 0:
            raise AuditError("truncated cat-file batch header")
        header = payload[cursor:newline]
        cursor = newline + 1
        try:
            oid_b, type_b, size_b = header.split(b" ")
        except ValueError as exc:
            raise AuditError("cat-file batch header grammar drift") from exc
        if oid_b != expected_oid.encode("ascii"):
            raise AuditError("cat-file batch response order/OID drift")
        if type_b not in (b"blob", b"tree", b"commit", b"tag"):
            raise AuditError("cat-file batch object type drift")
        if re.fullmatch(rb"0|[1-9][0-9]*", size_b) is None:
            raise AuditError("cat-file batch size grammar drift")
        size = int(size_b, 10)
        if size > 256 * 1024 * 1024:
            raise AuditError("cat-file batch object exceeds bound")
        aggregate_size += size
        if aggregate_size > MAX_OBJECT_BYTES:
            raise AuditError("cat-file batch aggregate object bytes exceed bound")
        terminal = cursor + size
        if terminal >= len(payload) or payload[terminal : terminal + 1] != b"\n":
            raise AuditError("truncated or unterminated cat-file batch object")
        results.append((type_b.decode("ascii"), payload[cursor:terminal]))
        cursor = terminal + 1
    if cursor != len(payload):
        raise AuditError("trailing cat-file batch bytes")
    return results


class _GitTopologyAdapter:
    def __init__(self, repository: Path):
        self.repository = Path(repository)

    def ordered_parents(self, oid: str) -> List[str]:
        try:
            line = _ascii_git_line(
                self.repository,
                ["rev-list", "--parents", "-n", "1", oid],
                "commit parent line",
            )
        except AuditError as exc:
            raise ObservationIncomplete(str(exc)) from exc
        words = line.split()
        if not words or words[0] != oid:
            raise ObservationIncomplete("commit parent observation drift")
        return words[1:]

    def is_ancestor(self, ancestor: str, descendant: str) -> bool:
        try:
            _run_git(self.repository, ["merge-base", "--is-ancestor", ancestor, descendant])
        except LocalGitInvocationFailure as exc:
            if exc.returncode == 1:
                return False
            raise ObservationIncomplete(str(exc)) from exc
        return True


def _frozen_value(frozen: Mapping[str, Any], *names: str) -> str:
    present = [frozen[name] for name in names if name in frozen]
    if len(present) != 1 or not isinstance(present[0], str) or not present[0]:
        raise AuditError("missing or ambiguous frozen topology field")
    return present[0]


def verify_convergence_topology(
    repository: Path,
    frozen: Mapping[str, Any],
    *,
    adapter: Optional[Any] = None,
) -> Dict[str, Any]:
    """Verify the ordered merge and containment facts without changing Git state."""

    if not isinstance(frozen, Mapping):
        raise AuditError("topology identity must be a mapping")
    source_tip = _frozen_value(frozen, "sourceTip", "S", "source")
    design_base = frozen.get("designBase", source_tip)
    if not isinstance(design_base, str) or not design_base:
        raise AuditError("design base topology field drift")
    design_tip = _frozen_value(frozen, "designTip", "design_tip")
    D = _frozen_value(frozen, "D", "designMerge")
    C = _frozen_value(frozen, "C", "convergenceMerge")
    H = _frozen_value(frozen, "H", "head")
    selected = adapter if adapter is not None else _GitTopologyAdapter(Path(repository))
    c_parents = list(selected.ordered_parents(C))
    if c_parents != [source_tip, D]:
        raise AuditError("convergence merge ordered-parent drift")
    if not selected.is_ancestor(design_base, D) or not selected.is_ancestor(design_tip, D):
        raise AuditError("design merge containment drift")
    if not selected.is_ancestor(C, H):
        raise AuditError("candidate does not contain convergence merge")
    return _self_digest_record(
        {
            "schemaVersion": "qinao.convergence-topology.v1",
            "sourceTip": source_tip,
            "designBase": design_base,
            "designTip": design_tip,
            "D": D,
            "C": C,
            "H": H,
            "orderedCParents": c_parents,
            "designContainsS": True,
            "designContainsTip": True,
            "headContainsC": True,
        }
    )


@dataclass(frozen=True)
class ProtectedSnapshot:
    head_oid: str
    index_tree_oid: str
    index_sha256: str
    index_stage_sha256: str
    index_stage_flags_sha256: str
    porcelain_v1_z_sha256: str
    porcelain_v2_z_sha256: str
    binary_diff_sha256: str
    manifest_entry_count: int
    raw_manifest_sha256: str
    content_manifest_sha256: str


def _validate_protected_snapshot(snapshot: ProtectedSnapshot) -> None:
    if not isinstance(snapshot, ProtectedSnapshot):
        raise AuditError("protected snapshot type drift")
    _require_lower_hex(snapshot.head_oid, 40, "protected head")
    _require_lower_hex(snapshot.index_tree_oid, 40, "protected index tree")
    for field in fields(ProtectedSnapshot):
        if field.name.endswith("sha256"):
            _require_lower_hex(getattr(snapshot, field.name), 64, field.name)
    if not isinstance(snapshot.manifest_entry_count, int) or isinstance(snapshot.manifest_entry_count, bool):
        raise AuditError("protected manifest count type")
    if snapshot.manifest_entry_count < 0:
        raise AuditError("protected manifest count negative")


def verify_protected_projection(
    snapshot: ProtectedSnapshot,
    observed: Mapping[str, Any],
) -> ProtectedSnapshot:
    _validate_protected_snapshot(snapshot)
    expected_names = {field.name for field in fields(ProtectedSnapshot)}
    if not isinstance(observed, Mapping) or set(observed) != expected_names:
        raise AuditError("protected projection field drift")
    try:
        reopened = ProtectedSnapshot(**dict(observed))
    except TypeError as exc:
        raise AuditError("protected projection shape drift") from exc
    _validate_protected_snapshot(reopened)
    if reopened != snapshot:
        raise AuditError("protected projection drift")
    return snapshot


def _optional_nonnegative_bound(value: Optional[int], label: str) -> Optional[int]:
    if value is None:
        return None
    if not isinstance(value, int) or isinstance(value, bool) or value < 0:
        raise AuditError(label + " bound must be a nonnegative integer")
    return value


def _parse_ls_tree_z(
    payload: bytes,
    *,
    maximum_entries: Optional[int] = None,
    maximum_path_bytes: Optional[int] = None,
    maximum_path_depth: Optional[int] = None,
    maximum_aggregate_path_bytes: Optional[int] = None,
) -> Dict[bytes, Tuple[str, str, str]]:
    if not isinstance(payload, bytes):
        raise AuditError("ls-tree output must be bytes")
    if payload and not payload.endswith(b"\x00"):
        raise AuditError("ls-tree output lacks terminal NUL")
    maximum_entries = _optional_nonnegative_bound(
        maximum_entries, "ls-tree entry count"
    )
    maximum_path_bytes = _optional_nonnegative_bound(
        maximum_path_bytes, "ls-tree path bytes"
    )
    maximum_path_depth = _optional_nonnegative_bound(
        maximum_path_depth, "ls-tree path depth"
    )
    maximum_aggregate_path_bytes = _optional_nonnegative_bound(
        maximum_aggregate_path_bytes, "ls-tree aggregate path bytes"
    )
    rows: Dict[bytes, Tuple[str, str, str]] = {}
    aggregate_path_bytes = 0
    cursor = 0
    while cursor < len(payload):
        token_end = payload.find(b"\x00", cursor)
        if token_end < 0:
            raise AuditError("ls-tree output lacks terminal NUL")
        token = payload[cursor:token_end]
        cursor = token_end + 1
        if not token:
            raise AuditError("ls-tree row grammar drift")
        try:
            header, path = token.split(b"\t", 1)
            mode_b, type_b, oid_b = header.split(b" ")
        except ValueError as exc:
            raise AuditError("ls-tree row grammar drift") from exc
        if not path or path in rows:
            raise AuditError("empty or duplicate ls-tree path")
        if maximum_entries is not None and len(rows) >= maximum_entries:
            raise AuditError("ls-tree entry count exceeds bound")
        if maximum_path_bytes is not None and len(path) > maximum_path_bytes:
            raise AuditError("ls-tree path bytes exceeds bound")
        if (
            maximum_path_depth is not None
            and path.count(b"/") + 1 > maximum_path_depth
        ):
            raise AuditError("ls-tree path depth exceeds bound")
        aggregate_path_bytes += len(path)
        if (
            maximum_aggregate_path_bytes is not None
            and aggregate_path_bytes > maximum_aggregate_path_bytes
        ):
            raise AuditError("ls-tree aggregate path bytes exceeds bound")
        if re.fullmatch(rb"[0-7]{6}", mode_b) is None:
            raise AuditError("ls-tree mode drift")
        if type_b not in (b"blob", b"tree", b"commit", b"tag"):
            raise AuditError("ls-tree object type drift")
        if re.fullmatch(rb"(?:[0-9a-f]{40}|[0-9a-f]{64})", oid_b) is None:
            raise AuditError("ls-tree object ID drift")
        rows[path] = (
            mode_b.decode("ascii"),
            type_b.decode("ascii"),
            oid_b.decode("ascii"),
        )
    return rows


def _validate_disclosure_paths(paths: Sequence[bytes]) -> List[bytes]:
    if not isinstance(paths, (list, tuple)):
        raise AuditError("disclosure path set type drift")
    if len(paths) > MAX_DISCLOSURE_PATHS:
        raise AuditError("disclosure path count exceeds bound")
    aggregate_path_bytes = 0
    validated: List[bytes] = []
    seen = set()
    for path in paths:
        if not isinstance(path, bytes) or not path:
            raise AuditError("disclosure path is absent or ambiguous")
        if path in seen:
            raise AuditError("duplicate disclosure path")
        seen.add(path)
        if len(path) > MAX_RESOURCE_PATH_BYTES:
            raise AuditError("disclosure path bytes exceeds bound")
        if path.count(b"/") + 1 > MAX_DISCLOSURE_PATH_DEPTH:
            raise AuditError("disclosure path depth exceeds bound")
        aggregate_path_bytes += len(path)
        if aggregate_path_bytes > MAX_DISCLOSURE_PATH_BYTES:
            raise AuditError("disclosure aggregate path bytes exceeds bound")
        validated.append(path)
    return validated


def _parse_porcelain_v1_paths(payload: bytes) -> List[bytes]:
    if payload and not payload.endswith(b"\x00"):
        raise AuditError("porcelain-v1 output lacks terminal NUL")
    tokens = payload.split(b"\x00")
    if tokens and tokens[-1] == b"":
        tokens.pop()
    paths = []
    cursor = 0
    while cursor < len(tokens):
        token = tokens[cursor]
        cursor += 1
        if len(token) < 4 or token[2:3] != b" ":
            raise AuditError("porcelain-v1 row grammar drift")
        status = token[:2]
        path = token[3:]
        if not path:
            raise AuditError("empty porcelain path")
        paths.append(path)
        if status[:1] in (b"R", b"C") or status[1:2] in (b"R", b"C"):
            if cursor >= len(tokens) or not tokens[cursor]:
                raise AuditError("porcelain rename path truncation")
            cursor += 1
    if len(set(paths)) != len(paths):
        raise AuditError("duplicate porcelain destination path")
    return paths


class _ProtectedGitAdapter:
    def capture(self, repository: Path) -> ProtectedSnapshot:
        repository = Path(repository).resolve()
        if str(repository) != PROTECTED_WITNESS["worktree"]:
            raise AuditError("protected worktree path drift")
        branch = _ascii_git_line(repository, ["symbolic-ref", "-q", "HEAD"], "protected branch")
        if branch != PROTECTED_WITNESS["branch"]:
            raise AuditError("protected branch drift")
        head = _ascii_git_line(repository, ["rev-parse", "HEAD"], "protected HEAD")
        tree = _ascii_git_line(repository, ["rev-parse", "HEAD^{tree}"], "protected tree")
        if head != PROTECTED_WITNESS["head"] or tree != PROTECTED_WITNESS["tree"]:
            raise AuditError("protected HEAD/tree drift")
        _run_git(repository, ["diff", "--cached", "--quiet", "HEAD", "--"])
        index_name = _ascii_git_line(repository, ["rev-parse", "--git-path", "index"], "protected index path")
        index_path = Path(index_name)
        if not index_path.is_absolute():
            index_path = repository / index_path
        index_payload = _read_ordinary(index_path.resolve(), maximum=256 * 1024 * 1024)
        stage = _run_git(repository, ["ls-files", "--stage", "-z"])
        stage_flags = _run_git(repository, ["ls-files", "--stage", "-v", "-z"])
        porcelain_v1 = _run_git(repository, ["status", "--porcelain=v1", "-z", "--untracked-files=all"])
        porcelain_v2 = _run_git(repository, ["status", "--porcelain=v2", "-z", "--untracked-files=all"])
        binary_diff = _run_git(
            repository,
            ["diff", "--binary", "--full-index", "--no-ext-diff", "--no-textconv"],
        )
        raw_manifest = _run_git(
            repository,
            [
                "diff-tree", "--no-commit-id", "-r", "--raw", "-z", "--no-renames",
                "--abbrev=40", PROTECTED_WITNESS["head"], FROZEN_S,
            ],
        )
        if _sha256(raw_manifest) != PROTECTED_WITNESS["preservationManifestSha256"]:
            raise AuditError("protected raw manifest drift")
        entries = parse_raw_diff_z(raw_manifest, "sha1")
        if len(entries) != 33:
            raise AuditError("protected raw manifest count drift")
        if any(entry.status not in ("A", "M") or entry.new_mode != "100644" for entry in entries):
            raise AuditError("protected raw manifest status/mode drift")
        status_paths = _parse_porcelain_v1_paths(porcelain_v1)
        raw_paths = [base64.b64decode(entry.new_path_b64, validate=True) for entry in entries]
        if set(status_paths) != set(raw_paths):
            raise AuditError("protected status/raw path-set drift")
        # The frozen path-set receipt digest is already bound inside the
        # immutable witness object.  The live check above is stronger for the
        # current observation: it compares the complete raw byte sets while
        # the exact porcelain stream and raw-manifest stream are also closed.
        frozen_tree = _parse_ls_tree_z(
            _run_git(repository, ["ls-tree", "-r", "-z", "--full-tree", FROZEN_S, "--"])
        )
        content_hasher = hashlib.sha256()
        for entry, path_bytes in zip(entries, raw_paths):
            tree_row = frozen_tree.get(path_bytes)
            if tree_row != ("100644", "blob", entry.new_oid):
                raise AuditError("protected frozen tree/raw manifest drift")
            relative = _safe_relative_bytes(path_bytes)
            working_path = repository / relative
            observed = working_path.lstat()
            if not stat.S_ISREG(observed.st_mode) or stat.S_ISLNK(observed.st_mode):
                raise AuditError("protected working object type drift")
            working = _read_ordinary(working_path, maximum=256 * 1024 * 1024)
            blob = _run_git(repository, ["cat-file", "blob", entry.new_oid])
            if working != blob:
                raise AuditError("protected working blob content drift")
            hashed = _run_git(repository, ["hash-object", "--no-filters", "--stdin"], input_bytes=working)
            if hashed != (entry.new_oid + "\n").encode("ascii"):
                raise AuditError("protected working blob Git identity drift")
            for field_value in (
                path_bytes,
                entry.status.encode("ascii"),
                entry.old_mode.encode("ascii"),
                entry.new_mode.encode("ascii"),
                entry.old_oid.encode("ascii"),
                entry.new_oid.encode("ascii"),
                _sha256(working).encode("ascii"),
            ):
                content_hasher.update(field_value)
                content_hasher.update(b"\x00")
        return ProtectedSnapshot(
            head_oid=head,
            index_tree_oid=tree,
            index_sha256=_sha256(index_payload),
            index_stage_sha256=_sha256(stage),
            index_stage_flags_sha256=_sha256(stage_flags),
            porcelain_v1_z_sha256=_sha256(porcelain_v1),
            porcelain_v2_z_sha256=_sha256(porcelain_v2),
            binary_diff_sha256=_sha256(binary_diff),
            manifest_entry_count=len(entries),
            raw_manifest_sha256=_sha256(raw_manifest),
            content_manifest_sha256=content_hasher.hexdigest(),
        )


def _protected_expected(frozen: Mapping[str, Any]) -> ProtectedSnapshot:
    dataclass_names = {field.name for field in fields(ProtectedSnapshot)}
    if set(frozen) == dataclass_names:
        try:
            return ProtectedSnapshot(**dict(frozen))
        except TypeError as exc:
            raise AuditError("protected frozen projection shape drift") from exc
    if dict(frozen) != PROTECTED_WITNESS:
        raise AuditError("protected witness constant set drift")
    return ProtectedSnapshot(
        head_oid=PROTECTED_WITNESS["head"],
        index_tree_oid=PROTECTED_WITNESS["tree"],
        index_sha256=PROTECTED_WITNESS["indexSha256"],
        index_stage_sha256=PROTECTED_WITNESS["stageSha256"],
        index_stage_flags_sha256=PROTECTED_WITNESS["stageFlagsSha256"],
        porcelain_v1_z_sha256=PROTECTED_WITNESS["porcelainV1Sha256"],
        porcelain_v2_z_sha256=PROTECTED_WITNESS["porcelainV2Sha256"],
        binary_diff_sha256=PROTECTED_WITNESS["trackedDiffSha256"],
        manifest_entry_count=33,
        raw_manifest_sha256=PROTECTED_WITNESS["preservationManifestSha256"],
        content_manifest_sha256=PROTECTED_CONTENT_MANIFEST_SHA256,
    )


def verify_protected_snapshot(
    repository: Path,
    frozen: Mapping[str, Any],
    *,
    adapter: Optional[Any] = None,
) -> Dict[str, Any]:
    expected = _protected_expected(_require_mapping(frozen, "protected frozen witness"))
    selected = adapter if adapter is not None else _ProtectedGitAdapter()
    if not hasattr(selected, "capture"):
        raise AuditError("protected observation adapter drift")
    first = selected.capture(Path(repository))
    second = selected.capture(Path(repository))
    if first != second:
        raise AuditError("concurrent protected snapshot drift")
    verify_protected_projection(expected, asdict(first))
    return _self_digest_record(
        {
            "schemaVersion": "qinao.protected-snapshot.v1",
            "repository": str(Path(repository)),
            "snapshot": asdict(first),
            "witnessDigest": _sha256(canonical_json_bytes(dict(frozen))),
        }
    )


def _require_mapping(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise AuditError(label + " must be an object")
    return value


def _ci_observation(observation: Mapping[str, Any]) -> Dict[str, Any]:
    observation = _require_mapping(observation, "CI observation")
    required = {"head", "tree", "parents", "mergeTree", "baseIsAncestor", "policyInputsSha256", "V"}
    if set(observation) != required:
        raise AuditError("CI observation field drift")
    head = _require_lower_hex(observation["head"], 40, "observed HEAD")
    tree = _require_lower_hex(observation["tree"], 40, "observed tree")
    merge_tree = _require_lower_hex(observation["mergeTree"], 40, "observed merge tree")
    policy = _require_lower_hex(observation["policyInputsSha256"], 64, "policy inputs")
    version = _require_lower_hex(observation["V"], 64, "policy version")
    parents = observation["parents"]
    if not isinstance(parents, list):
        raise AuditError("ordered parents must be a list")
    normalized_parents = [_require_lower_hex(parent, 40, "parent") for parent in parents]
    if len(set(normalized_parents)) != len(normalized_parents):
        raise AuditError("duplicate ordered parent")
    if not isinstance(observation["baseIsAncestor"], bool):
        raise AuditError("base ancestry observation type")
    return {
        "head": head,
        "tree": tree,
        "parents": normalized_parents,
        "mergeTree": merge_tree,
        "baseIsAncestor": observation["baseIsAncestor"],
        "policyInputsSha256": policy,
        "V": version,
    }


def _ci_repository(event: Mapping[str, Any]) -> str:
    repository = _require_mapping(event.get("repository"), "event repository")
    if set(repository) != {"full_name"} or repository.get("full_name") != CI_REPOSITORY:
        raise AuditError("CI repository identity drift")
    return CI_REPOSITORY


_POLICY_PHASE_FIELDS = {
    "prepared": {"input"},
    "started": {"preparedRecordDigest"},
    "completed": {"preparedRecordDigest", "startedRecordDigest", "rowsDigest", "V"},
    "failed": {"preparedRecordDigest", "startedRecordDigest", "failureStage", "errorClass"},
}


def _validate_policy_phase(value: Mapping[str, Any]) -> str:
    _verify_self_digest(value)
    phase = next((key for key in _POLICY_PHASE_FIELDS if value.get("schemaVersion")
                  == "qinao.policy-capture-" + key + ".v1"), None)
    if phase is None or set(value) != ({"schemaVersion", "recordDigest", "captureId",
            "owner", "inputDigest"} | _POLICY_PHASE_FIELDS[phase]):
        raise AuditError("policy capture phase field/version drift")
    _require_lower_hex(value["captureId"], 32, "policy capture ID")
    _require_lower_hex(value["inputDigest"], 64, "policy input digest")
    owner = _require_mapping(value["owner"], "policy owner")
    if set(owner) != {"kind", "root", "ownerId", "outerInvocationStartRecordDigest"}:
        raise AuditError("policy capture owner field drift")
    if not isinstance(owner["root"], str) or not Path(owner["root"]).is_absolute():
        raise AuditError("policy capture root drift")
    if owner["kind"] == "ci-diagnostic":
        if (owner["ownerId"] != "capture.sterile-python." + value["captureId"]
                or owner["outerInvocationStartRecordDigest"] is not None):
            raise AuditError("CI policy owner generation drift")
    elif owner["kind"] == "ledger-outer":
        _require_lower_hex(owner["ownerId"], 64, "policy outer owner")
        if owner["outerInvocationStartRecordDigest"] != owner["ownerId"]:
            raise AuditError("ledger policy owner drift")
    else:
        raise AuditError("policy capture owner kind drift")
    if phase == "prepared":
        inputs = _require_mapping(value["input"], "policy prepared input")
        if set(inputs) != {"repository", "revision", "rows", "rowsDigest", "protocolPath",
                "protocolBlobOid", "protocolByteCount", "protocolSha256", "importInventory",
                "runtime", "launcher", "profileContext"}:
            raise AuditError("policy prepared input field drift")
        if _sha256(canonical_json_bytes(inputs)) != value["inputDigest"]:
            raise AuditError("policy capture input digest drift")
        if not isinstance(inputs["repository"], str) or not Path(inputs["repository"]).is_absolute():
            raise AuditError("policy repository drift")
        _require_lower_hex(inputs["revision"], 40, "policy revision")
        rows = inputs["rows"]
        if not isinstance(rows, list) or len(rows) != 26:
            raise AuditError("policy rows count drift")
        for row, path in zip(rows, CI_POLICY_PATHS):
            if (not isinstance(row, dict) or set(row) != {"path", "mode", "type", "blobOid"}
                    or row["path"] != path or row["mode"] != "100644" or row["type"] != "blob"):
                raise AuditError("policy row shape/order drift")
            _require_lower_hex(row["blobOid"], 40, "policy blob")
        if (inputs["rowsDigest"] != _sha256(canonical_json_bytes(rows))
                or inputs["protocolPath"] != "scripts/qinao_pr_protocol.py"
                or inputs["protocolBlobOid"] != next(row["blobOid"] for row in rows
                    if row["path"] == inputs["protocolPath"])
                or type(inputs["protocolByteCount"]) is not int
                or not 0 < inputs["protocolByteCount"] <= 16 * 1024 * 1024):
            raise AuditError("policy source/rows identity drift")
        _require_lower_hex(inputs["protocolSha256"], 64, "policy source hash")
        inventory = _require_mapping(inputs["importInventory"], "policy inventory")
        if (set(inventory) != {"candidateFileCount", "pythonSourceCount", "trackedPathDigest"}
                or any(type(inventory[key]) is not int or inventory[key] < 0
                       for key in ("candidateFileCount", "pythonSourceCount"))):
            raise AuditError("policy inventory shape drift")
        _require_lower_hex(inventory["trackedPathDigest"], 64, "policy tracked paths")
        _require_mapping(inputs["runtime"], "policy runtime")
        launcher = _require_mapping(inputs["launcher"], "policy launcher")
        if (set(launcher) != {"flags", "sysPath", "argv"}
                or launcher["flags"] != {"isolated": 1, "ignoreEnvironment": 1, "noSite": 1,
                                         "noUserSite": 1, "dontWriteBytecode": 1}
                or any(not isinstance(launcher[key], list) or any(not isinstance(item, str)
                    for item in launcher[key]) for key in ("sysPath", "argv"))):
            raise AuditError("policy launcher shape drift")
        context = inputs["profileContext"]
        if owner["kind"] == "ci-diagnostic":
            if not isinstance(context, dict) or set(context) != {"runnerProjectionDigest",
                    "eventPathSha256", "eventBytesSha256", "workflowContractDigest", "workflowRunBlockCount"}:
                raise AuditError("policy CI context field drift")
            for key in set(context) - {"workflowRunBlockCount"}:
                _require_lower_hex(context[key], 64, "policy CI context digest")
            if type(context["workflowRunBlockCount"]) is not int or context["workflowRunBlockCount"] < 1:
                raise AuditError("policy workflow count drift")
        elif context is not None:
            raise AuditError("ledger policy carries CI profile context")
    else:
        _require_lower_hex(value["preparedRecordDigest"], 64, "policy prepared digest")
        if phase in ("completed", "failed") and value["startedRecordDigest"] is not None:
            _require_lower_hex(value["startedRecordDigest"], 64, "policy started digest")
        if phase == "completed":
            _require_lower_hex(value["startedRecordDigest"], 64, "policy started digest")
            _require_lower_hex(value["rowsDigest"], 64, "policy rows digest")
            _require_lower_hex(value["V"], 64, "policy V")
        if phase == "failed" and (value["failureStage"] not in {
                "preparation", "start", "activation", "postcheck", "publication"}
                or value["errorClass"] not in {"AuditError", "KeyboardInterrupt", "SystemExit", "OSError", "Exception"}):
            raise AuditError("policy failure classification drift")
    return phase


def _project_policy_phases(values: Sequence[Mapping[str, Any]]) -> Dict[str, Any]:
    projected: Dict[str, Any] = {}
    for value in values:
        phase = _validate_policy_phase(value)
        if phase in projected or "completed" in projected or "failed" in projected:
            raise AuditError("policy capture duplicate/forked phase")
        if phase == "prepared":
            if projected:
                raise AuditError("policy preparation order drift")
        else:
            prepared = projected.get("prepared")
            if not isinstance(prepared, Mapping) or any(value[key] != prepared[key]
                    for key in ("captureId", "owner", "inputDigest")) or value["preparedRecordDigest"] != prepared["recordDigest"]:
                raise AuditError("policy phase owner/input lineage drift")
            started = projected.get("started")
            if phase == "completed" and (not isinstance(started, Mapping)
                    or value["startedRecordDigest"] != started["recordDigest"]
                    or value["rowsDigest"] != prepared["input"]["rowsDigest"]):
                raise AuditError("policy completion start/rows drift")
            if phase == "failed" and value["startedRecordDigest"] != (
                    started["recordDigest"] if started else None):
                raise AuditError("policy failed start lineage drift")
        projected[phase] = dict(value)
    return projected


def _validate_policy_ledger_record(record: Mapping[str, Any], prior: Sequence[Mapping[str, Any]],
                                   outers: Mapping[str, Any], root: Path) -> None:
    value = _require_mapping(record.get("policyCapture"), "ledger policy capture")
    phase = _validate_policy_phase(value)
    owner = value["owner"]
    outer = outers.get(owner["outerInvocationStartRecordDigest"])
    if (owner["kind"] != "ledger-outer" or owner["root"] != str(root)
            or record["operationKind"] != "policy-capture-" + phase
            or record["completionState"] != phase or record["inputDigest"] != value["inputDigest"]
            or record["declaredFilenames"] != [] or not isinstance(outer, Mapping)
            or outer.get("startKind") != "linked" or outer.get("state") != "open"):
        raise AuditError("ledger policy envelope/outer owner drift")
    all_owned = [row["policyCapture"] for row in prior if row.get("policyCapture", {}).get("owner") == owner]
    if any(row["captureId"] != value["captureId"] for row in all_owned):
        raise AuditError("policy outer owns multiple captures")
    projected = _project_policy_phases(all_owned + [value])
    inputs = projected["prepared"]["input"]
    invocation = outer["start"]["invocation"]
    if (invocation["profile"] != "ledger" or inputs["repository"] != invocation["repository"]
            or inputs["runtime"] != invocation["runtime"]
            or inputs["launcher"] != {key: invocation[key] for key in ("flags", "sysPath", "argv")}
            or not invocation["argv"] or invocation["argv"][0] not in ("ci-bind", "ci-push-bind", "ci-supplemental-bind")):
        raise AuditError("policy capture invocation input binding drift")


def _validate_policy_capture_publication(transaction: Any, record: Mapping[str, Any], authority: Any = None) -> None:
    if not str(record.get("operationKind", "")).startswith("policy-capture-"):
        return
    if (not isinstance(authority, _PolicyCaptureJournal) or authority.diagnostic is not None
            or authority.root != transaction.root or authority._pending != canonical_json_bytes(record.get("policyCapture"))):
        raise AuditError("policy publication requires live owned activation context")
    state = _recover_complete_state_fd(transaction)
    if (record["sequence"] != state["nextSequence"]
            or record["previousRecordDigest"] != state["records"][-1]["recordDigest"]):
        raise AuditError("policy publication prefix drift")
    _validate_policy_ledger_record(record, state["records"], state["sterileInvocations"], transaction.root)


def _policy_launcher_projection(argv: Sequence[str]) -> Dict[str, Any]:
    return {"flags": {"isolated": int(sys.flags.isolated),
        "ignoreEnvironment": int(sys.flags.ignore_environment), "noSite": int(sys.flags.no_site),
        "noUserSite": int(sys.flags.no_user_site), "dontWriteBytecode": int(sys.flags.dont_write_bytecode)},
        "sysPath": list(sys.path), "argv": list(argv)}


class _PolicyCaptureJournal:
    """One explicit owner, one activation, two existing durable storage surfaces."""

    def __init__(self, root: Path, *, outer: Optional[Mapping[str, Any]] = None,
                 diagnostic: Optional[Path] = None, runtime: Optional[Mapping[str, Any]] = None,
                 launcher: Optional[Mapping[str, Any]] = None):
        self.root = Path(root).resolve()
        self.capture_id = secrets.token_hex(16)
        self.diagnostic = diagnostic
        self.outer = dict(outer) if outer is not None else None
        if outer is None:
            _validate_ci_run_root(self.root)
            _ensure_private_directory(self.root / "ci")
            _ensure_private_directory(self.root / "ci/invocations")
            self.diagnostic = self.root / "ci/invocations" / ("capture.sterile-python." + self.capture_id)
            _mkdir_exclusive(self.diagnostic)
            _fsync_directory(self.diagnostic.parent)
            self.owner = {"kind": "ci-diagnostic", "root": str(self.root),
                          "ownerId": self.diagnostic.name, "outerInvocationStartRecordDigest": None}
            observed = self.diagnostic.lstat()
            self._diagnostic_identity = (observed.st_dev, observed.st_ino)
        else:
            _validate_ledger_record_shape(outer)
            if outer["operationKind"] != "sterile-invocation-started-linked":
                raise AuditError("policy requires linked outer owner")
            self.owner = {"kind": "ledger-outer", "root": str(self.root),
                "ownerId": outer["recordDigest"], "outerInvocationStartRecordDigest": outer["recordDigest"]}
        self.runtime = dict(runtime) if runtime is not None else sterile_runtime_projection()
        self.launcher = dict(launcher) if launcher is not None else _policy_launcher_projection([])
        self.profile_context: Optional[Dict[str, Any]] = None
        self._pending: Optional[bytes] = None

    def read(self) -> Dict[str, Any]:
        if self.diagnostic is not None:
            _ordinary_directory(self.diagnostic, 0o700)
            observed = self.diagnostic.lstat()
            if (observed.st_dev, observed.st_ino) != self._diagnostic_identity:
                raise AuditError("policy diagnostic owner replaced")
            values = []
            for phase in _POLICY_PHASE_FIELDS:
                path = self.diagnostic / ("policy-" + phase + ".json")
                if path.exists() or path.is_symlink():
                    values.append(parse_canonical_json(_read_ordinary(path)))
        else:
            state = _recover_complete_state(self.root)
            values = [row["policyCapture"] for row in state["records"]
                      if row.get("policyCapture", {}).get("captureId") == self.capture_id]
        projected = _project_policy_phases(values)
        if any(value["owner"] != self.owner or value["captureId"] != self.capture_id
               for value in projected.values()):
            raise AuditError("policy journal owner drift")
        return projected

    def _publish(self, phase: str, fields: Mapping[str, Any]) -> Dict[str, Any]:
        value = _self_digest_record({"schemaVersion": "qinao.policy-capture-" + phase + ".v1",
            "captureId": self.capture_id, "owner": self.owner, **dict(fields)})
        _project_policy_phases(list(self.read().values()) + [value])
        if self.diagnostic is not None:
            write_canonical_exclusive(self.diagnostic / ("policy-" + phase + ".json"), value)
            _fsync_directory(self.diagnostic)
        else:
            self._pending = canonical_json_bytes(value)
            try:
                def publish(transaction: LedgerTransaction) -> None:
                    state = _recover_complete_state_fd(transaction)
                    record = _new_record(state["identity"], state["nextSequence"],
                        state["records"][-1]["recordDigest"], "policy-capture-" + phase,
                        value["inputDigest"], [], phase, {"policyCapture": value})
                    transaction.write_record(record["sequence"], record, _policy_capture_authority=self)
                _execute_ledger_transaction(self.root, operation_kind="policy-capture-" + phase, body=publish)
            finally:
                self._pending = None
        if self.read().get(phase) != value:
            raise AuditError("policy publication reopen drift")
        return value


def capture_ci_policy_inputs(repository: Path, revision: str, *,
                             journal: Optional[_PolicyCaptureJournal] = None) -> Dict[str, Any]:
    """Reopen the Task 6 policy implementation and all 26 revision blobs."""
    repository = Path(repository).resolve()
    _require_lower_hex(revision, 40, "CI policy revision")
    inventory = _validate_import_inventory(repository)
    if not isinstance(journal, _PolicyCaptureJournal):
        raise AuditError("policy activation requires explicit durable owner")
    if (
        len(CI_POLICY_PATHS) != 26
        or tuple(sorted(CI_POLICY_PATHS, key=lambda value: value.encode("utf-8")))
        != CI_POLICY_PATHS
        or len(set(CI_POLICY_PATHS)) != len(CI_POLICY_PATHS)
    ):
        raise AuditError("CI policy path registry drift")

    def observe_rows() -> List[Dict[str, str]]:
        tree = _parse_ls_tree_z(
            _run_git(
                repository,
                ["ls-tree", "-r", "-z", "--full-tree", revision, "--"]
                + list(CI_POLICY_PATHS),
            )
        )
        expected = {path.encode("utf-8") for path in CI_POLICY_PATHS}
        if set(tree) != expected:
            raise AuditError("CI policy path set is missing or extra")
        rows: List[Dict[str, str]] = []
        for path in CI_POLICY_PATHS:
            mode, object_type, oid = tree[path.encode("utf-8")]
            if mode != "100644" or object_type != "blob":
                raise AuditError("CI policy input is not an ordinary blob")
            rows.append(
                {"path": path, "mode": mode, "type": object_type, "blobOid": oid}
            )
        return rows

    first = observe_rows()
    second = observe_rows()
    if first != second:
        raise AuditError("concurrent CI policy input drift")
    protocol_row = next(
        row for row in first if row["path"] == "scripts/qinao_pr_protocol.py"
    )
    module_path = repository / protocol_row["path"]
    _ordinary_file(module_path, single_link=False)
    source = _read_ordinary(
        module_path, maximum=16 * 1024 * 1024, single_link=False
    )
    committed = _run_git(repository, ["cat-file", "blob", protocol_row["blobOid"]])
    if source != committed:
        raise AuditError("Task 6 policy implementation differs from revision blob")
    inputs = {"repository": str(repository), "revision": revision, "rows": first,
        "rowsDigest": _sha256(canonical_json_bytes(first)), "protocolPath": protocol_row["path"],
        "protocolBlobOid": protocol_row["blobOid"], "protocolByteCount": len(source),
        "protocolSha256": _sha256(source), "importInventory": inventory,
        "runtime": journal.runtime, "launcher": journal.launcher, "profileContext": journal.profile_context}
    input_digest = _sha256(canonical_json_bytes(inputs))
    def bracket() -> None:
        if (_validate_import_inventory(repository) != inventory or observe_rows() != first
                or _read_ordinary(module_path, maximum=16 * 1024 * 1024, single_link=False) != source):
            raise AuditError("CI policy source/import closure drift")
        for row in first:
            if _read_ordinary(repository / row["path"], maximum=256 * 1024 * 1024,
                              single_link=False) != _run_git(repository, ["cat-file", "blob", row["blobOid"]]):
                raise AuditError("CI policy worktree/blob drift")
    bracket()
    existing = journal.read()
    if existing:
        if (existing.get("prepared", {}).get("input") != inputs
                or "completed" not in existing):
            raise AuditError("policy capture incomplete or input drift; activation not replayed")
        bracket()
        return {"rows": first, "V": existing["completed"]["V"]}
    prepared = journal._publish("prepared", {"input": inputs, "inputDigest": input_digest})
    stage = "start"
    started: Optional[Dict[str, Any]] = None
    completed: Optional[Dict[str, Any]] = None
    try:
        started = journal._publish("started", {"inputDigest": input_digest,
            "preparedRecordDigest": prepared["recordDigest"]})
        bracket()
        stage = "activation"
        name = "qinao_task6_policy_" + _sha256(source)
        loader = _TaskTestVerifiedSourceLoader(name, module_path, source)
        spec = importlib.util.spec_from_file_location(name, module_path, loader=loader)
        if spec is None or spec.loader is not loader or name in sys.modules:
            raise AuditError("Task 6 policy implementation loader collision")
        loaded = importlib.util.module_from_spec(spec)
        sys.modules[name] = loaded
        try:
            loader.exec_module(loaded)
        finally:
            sys.modules.pop(name, None)
        if tuple(getattr(loaded, "POLICY_PATHS", ())) != CI_POLICY_PATHS:
            raise AuditError("Task 6 policy path set disagrees with CI binder")
        policy_revision = getattr(loaded, "policy_revision", None)
        if not callable(policy_revision):
            raise AuditError("Task 6 policy revision function is unavailable")
        V = policy_revision(tuple((row["path"], row["blobOid"]) for row in first))
        _require_lower_hex(V, 64, "CI policy V")
        stage = "postcheck"
        bracket()
        stage = "publication"
        completed = journal._publish("completed", {"inputDigest": input_digest,
            "preparedRecordDigest": prepared["recordDigest"],
            "startedRecordDigest": started["recordDigest"], "rowsDigest": inputs["rowsDigest"], "V": V})
    except BaseException as primary:
        try:
            durable = journal.read()
            terminal = durable.get("completed")
            if terminal is not None:
                if (stage != "publication" or terminal["V"] != V
                        or terminal["inputDigest"] != input_digest):
                    raise AuditError("policy lost-return terminal drift")
                # Exact completed publication is already durable: never fork a failed terminal.
                bracket()
                return {"rows": first, "V": terminal["V"]}
            if "failed" not in durable:
                observed_start = durable.get("started")
                journal._publish("failed", {"inputDigest": input_digest,
                    "preparedRecordDigest": prepared["recordDigest"],
                    "startedRecordDigest": observed_start["recordDigest"] if observed_start else None,
                    "failureStage": stage, "errorClass": (
                        type(primary).__name__ if type(primary).__name__ in
                        {"AuditError", "KeyboardInterrupt", "SystemExit", "OSError"} else "Exception")})
        except BaseException as cleanup:
            _retain_git_cleanup_error(primary, cleanup)
        raise
    return {"rows": first, "V": V}


def capture_ci_observation(
    repository: Path,
    event: Mapping[str, Any],
    program: str,
    *,
    context: Optional[CommandContext] = None,
) -> Dict[str, Any]:
    repository = Path(repository).resolve()
    head = _ascii_git_line(repository, ["rev-parse", "--verify", "HEAD"], "CI HEAD")
    tree = _ascii_git_line(repository, ["rev-parse", "HEAD^{tree}"], "CI tree")
    parents = _GitTopologyAdapter(repository).ordered_parents(head)
    if context is None or not isinstance(context.policy_capture, _PolicyCaptureJournal):
        raise AuditError("CI binder requires owned policy capture context")
    policy = capture_ci_policy_inputs(repository, head, journal=context.policy_capture)
    if program == "ci-bind":
        pull_request = _require_mapping(event.get("pull_request"), "pull_request")
        base = _require_mapping(pull_request.get("base"), "pull_request base").get("sha")
        candidate = _require_mapping(pull_request.get("head"), "pull_request head").get("sha")
        _require_lower_hex(base, 40, "CI base")
        _require_lower_hex(candidate, 40, "CI candidate")
        if candidate != head:
            raise AuditError("CI checkout is not the event candidate")
        try:
            _run_git(repository, ["merge-base", "--is-ancestor", base, candidate])
        except AuditError as exc:
            raise AuditError("CI base is not an ancestor of candidate") from exc
        merge_tree = _ascii_git_line(
            repository,
            ["merge-tree", "--write-tree", "--no-messages", base, candidate],
            "CI merge tree",
        )
        _run_git(repository, ["cat-file", "-e", merge_tree + "^{tree}"])
        base_is_ancestor = True
    else:
        merge_tree = tree
        base_is_ancestor = True
    return {
        "head": head,
        "tree": tree,
        "parents": parents,
        "mergeTree": merge_tree,
        "baseIsAncestor": base_is_ancestor,
        "policyInputsSha256": _sha256(canonical_json_bytes(policy["rows"])),
        "V": policy["V"],
    }


def bind_ci_identity(event: Mapping[str, Any], observation: Mapping[str, Any]) -> Dict[str, Any]:
    event = _require_mapping(event, "PR event")
    repository = _ci_repository(event)
    pull_request = _require_mapping(event.get("pull_request"), "pull_request")
    if set(pull_request) != {"base", "head", "body"}:
        raise AuditError("pull_request field drift")
    base = _require_mapping(pull_request["base"], "pull_request base")
    head = _require_mapping(pull_request["head"], "pull_request head")
    head_repository = _require_mapping(head.get("repo"), "pull_request head repository")
    if set(base) != {"ref", "sha"} or base.get("ref") != "main":
        raise AuditError("PR base drift")
    if set(head) != {"sha", "repo"} or set(head_repository) != {"full_name"}:
        raise AuditError("PR head shape drift")
    if head_repository.get("full_name") != repository:
        raise AuditError("fork PR is not an admissible candidate")
    B = _require_lower_hex(base["sha"], 40, "PR base")
    H = _require_lower_hex(head["sha"], 40, "PR head")
    observed = _ci_observation(observation)
    if observed["head"] != H:
        raise AuditError("checked-out PR head drift")
    if not observed["baseIsAncestor"]:
        raise AuditError("PR base is not an ancestor of head")
    if observed["tree"] != observed["mergeTree"]:
        raise AuditError("candidate tree differs from merge-tree result")
    body = pull_request["body"]
    if body is None:
        body = ""
    if not isinstance(body, str):
        raise AuditError("PR body type drift")
    try:
        body_bytes = body.encode("utf-8", "strict")
    except UnicodeEncodeError as exc:
        raise AuditError("PR body Unicode drift") from exc
    return _self_digest_record(
        {
            "schemaVersion": "qinao.ci-identity.v1",
            "event": "pull_request",
            "repository": repository,
            "B": B,
            "H": H,
            "T": observed["mergeTree"],
            "V": observed["V"],
            "prBodySha256": _sha256(body_bytes),
            "policyInputsSha256": observed["policyInputsSha256"],
        }
    )


def bind_ci_push_identity(event: Mapping[str, Any], observation: Mapping[str, Any]) -> Dict[str, Any]:
    event = _require_mapping(event, "push event")
    repository = _ci_repository(event)
    required = {"repository", "ref", "before", "after", "deleted"}
    if set(event) != required or event.get("ref") != CI_MAIN_REF or event.get("deleted") is not False:
        raise AuditError("main push event drift")
    before = _require_lower_hex(event["before"], 40, "push before")
    after = _require_lower_hex(event["after"], 40, "push after")
    observed = _ci_observation(observation)
    if observed["head"] != after:
        raise AuditError("checked-out push head drift")
    return _self_digest_record(
        {
            "schemaVersion": "qinao.ci-push-identity.v1",
            "event": "push",
            "repository": repository,
            "ref": CI_MAIN_REF,
            "before": before,
            "after": after,
            "parents": observed["parents"],
            "tree": observed["tree"],
            "V": observed["V"],
            "policyInputsSha256": observed["policyInputsSha256"],
        }
    )


def bind_ci_supplemental_identity(
    event: Mapping[str, Any], observation: Mapping[str, Any]
) -> Dict[str, Any]:
    event = _require_mapping(event, "supplemental event")
    repository = _ci_repository(event)
    event_name = event.get("event_name")
    if event_name == "workflow_dispatch":
        if set(event) != {"event_name", "repository", "ref", "sha"}:
            raise AuditError("workflow_dispatch field drift")
        ref = event.get("ref")
        event_commit = event.get("sha")
    elif event_name == "push":
        required = {"event_name", "repository", "ref", "before", "after", "deleted"}
        if set(event) != required or event.get("deleted") is not False:
            raise AuditError("supplemental push field drift")
        ref = event.get("ref")
        event_commit = event.get("after")
        if ref == CI_MAIN_REF:
            raise AuditError("main push is not supplemental")
        _require_lower_hex(event.get("before"), 40, "supplemental push before")
    else:
        raise AuditError("event is not supplemental")
    if not isinstance(ref, str) or not ref.startswith("refs/"):
        raise AuditError("supplemental ref drift")
    event_commit = _require_lower_hex(event_commit, 40, "supplemental event commit")
    observed = _ci_observation(observation)
    if observed["head"] != event_commit:
        raise AuditError("checked-out supplemental commit drift")
    return _self_digest_record(
        {
            "schemaVersion": "qinao.ci-supplemental-identity.v1",
            "event": event_name,
            "repository": repository,
            "ref": ref,
            "eventCommit": event_commit,
            "parents": observed["parents"],
            "tree": observed["tree"],
            "V": observed["V"],
            "policyInputsSha256": observed["policyInputsSha256"],
            "claimScope": "supplemental-only",
        }
    )


def validate_ci_identity(record: Mapping[str, Any], *, purpose: str) -> Dict[str, Any]:
    if not isinstance(record, Mapping):
        raise AuditError("CI identity record type")
    _verify_self_digest(record)
    schema = record.get("schemaVersion")
    closed = {
        "qinao.ci-identity.v1": {
            "schemaVersion", "event", "repository", "B", "H", "T", "V",
            "prBodySha256", "policyInputsSha256", "recordDigest",
        },
        "qinao.ci-push-identity.v1": {
            "schemaVersion", "event", "repository", "ref", "before", "after",
            "parents", "tree", "V", "policyInputsSha256", "recordDigest",
        },
        "qinao.ci-supplemental-identity.v1": {
            "schemaVersion", "event", "repository", "ref", "eventCommit", "parents",
            "tree", "V", "policyInputsSha256", "claimScope", "recordDigest",
        },
    }
    if schema not in closed or set(record) != closed[schema]:
        raise AuditError("CI identity schema/field drift")
    expected_schema = {
        "candidate": "qinao.ci-identity.v1",
        "push": "qinao.ci-push-identity.v1",
        "supplemental": "qinao.ci-supplemental-identity.v1",
    }.get(purpose)
    if expected_schema is None:
        raise AuditError("unknown CI identity purpose")
    if schema != expected_schema:
        raise AuditError("CI identity purpose/schema mismatch")
    if schema == "qinao.ci-supplemental-identity.v1" and record.get("claimScope") != "supplemental-only":
        raise AuditError("supplemental claim-scope drift")
    return dict(record)


def _raw_manifest_digest(entries: Sequence[RawDiffEntry]) -> str:
    return _sha256(canonical_json_bytes([_raw_entry_projection(entry) for entry in entries]))


def build_raw_diff_manifest(raw_bytes: bytes, object_format: str) -> Dict[str, Any]:
    entries = parse_raw_diff_z(raw_bytes, object_format)
    rows = [_raw_entry_projection(entry) for entry in entries]
    return _self_digest_record(
        {
            "schemaVersion": "qinao.raw-diff-manifest.v1",
            "objectFormat": object_format,
            "rawDiffSha256": _sha256(raw_bytes),
            "entryCount": len(rows),
            "entries": rows,
            "manifestDigest": _sha256(canonical_json_bytes(rows)),
        }
    )


def validate_raw_diff_manifest(
    raw_bytes: bytes,
    object_format: str,
    record: Mapping[str, Any],
) -> Dict[str, Any]:
    if not isinstance(record, Mapping):
        raise AuditError("raw diff manifest must be an object")
    expected = build_raw_diff_manifest(raw_bytes, object_format)
    if dict(record) != expected:
        raise AuditError("raw diff manifest bytes or identity drift")
    return dict(record)


def validate_source_identity(record: Mapping[str, Any]) -> Dict[str, Any]:
    if not isinstance(record, Mapping):
        raise AuditError("source identity must be an object")
    schema = record.get("schemaVersion")
    purposes = {
        "qinao.ci-identity.v1": "candidate",
        "qinao.ci-push-identity.v1": "push",
        "qinao.ci-supplemental-identity.v1": "supplemental",
    }
    purpose = purposes.get(schema)
    if purpose is None:
        raise AuditError("source identity schema is not admitted")
    return validate_ci_identity(record, purpose=purpose)


def _entry_id(index: int, entry: RawDiffEntry) -> str:
    digest = _sha256(canonical_json_bytes(_raw_entry_projection(entry)))
    return "%08d-%s" % (index, digest)


def _observation_specs(entries: Sequence[RawDiffEntry], object_format: str) -> List[Dict[str, str]]:
    oid_length = OBJECT_HEX_LENGTH.get(object_format)
    if oid_length is None:
        raise AuditError("unknown observation object format")
    zero = "0" * oid_length
    specs: List[Dict[str, str]] = []
    for index, entry in enumerate(entries):
        _raw_entry_projection(entry)
        identity = _entry_id(index, entry)
        for side in ("old", "new"):
            oid = entry.old_oid if side == "old" else entry.new_oid
            if oid == zero:
                continue
            _require_lower_hex(oid, oid_length, "diff object")
            specs.append(
                {
                    "entryId": identity,
                    "side": side,
                    "oid": oid,
                    "mode": entry.old_mode if side == "old" else entry.new_mode,
                    "pathB64": entry.old_path_b64 if side == "old" else entry.new_path_b64,
                }
            )
    return specs


_LFS_POINTER = re.compile(
    rb"\Aversion https://git-lfs\.github\.com/spec/v1\n"
    rb"oid sha256:([0-9a-f]{64})\nsize (0|[1-9][0-9]*)\n\Z"
)


def _classify_object_content(object_type: str, payload: bytes) -> Dict[str, Any]:
    if object_type not in ("blob", "tree", "commit", "tag"):
        raise AuditError("unexpected Git object type")
    if not isinstance(payload, bytes):
        raise AuditError("Git object payload type drift")
    projection: Dict[str, Any] = {
        "objectType": object_type,
        "byteSize": len(payload),
        "contentSha256": _sha256(payload),
    }
    if object_type != "blob":
        projection["contentKind"] = "non-blob"
        return projection
    match = _LFS_POINTER.fullmatch(payload)
    if match is not None:
        size = int(match.group(2), 10)
        if size > MAX_SAFE_INTEGER:
            raise AuditError("LFS pointer size exceeds canonical bound")
        projection.update(
            {
                "contentKind": "lfs-pointer",
                "lfsOidSha256": match.group(1).decode("ascii"),
                "lfsSize": size,
            }
        )
        return projection
    if payload.startswith(b"version https://git-lfs.github.com/spec/v1"):
        raise AuditError("malformed LFS pointer")
    if b"\x00" in payload:
        projection["contentKind"] = "binary"
        return projection
    try:
        payload.decode("utf-8", "strict")
    except UnicodeDecodeError:
        projection["contentKind"] = "binary"
    else:
        projection["contentKind"] = "text"
    return projection


def capture_diff_content_observation(
    entries: Sequence[RawDiffEntry],
    raw_bytes: bytes,
    source_identity_digest: str,
    object_format: str,
    object_reader: Any,
) -> Dict[str, Any]:
    if not isinstance(raw_bytes, bytes):
        raise AuditError("raw diff observation input must be bytes")
    parsed = parse_raw_diff_z(raw_bytes, object_format)
    if list(entries) != parsed:
        raise AuditError("raw diff entries/bytes drift")
    _require_lower_hex(source_identity_digest, 64, "source identity digest")
    if not callable(object_reader):
        raise AuditError("object reader adapter is required")
    observations = []
    for spec in _observation_specs(parsed, object_format):
        try:
            first = object_reader(spec["oid"])
            second = object_reader(spec["oid"])
        except Exception as exc:
            raise AuditError("Git object read failed without lazy fetch") from exc
        if (
            not isinstance(first, tuple)
            or len(first) != 2
            or not isinstance(first[0], str)
            or not isinstance(first[1], bytes)
        ):
            raise AuditError("Git object batch response shape drift")
        if first != second:
            raise AuditError("concurrent Git object read drift")
        row = dict(spec)
        row.update(_classify_object_content(first[0], first[1]))
        observations.append(row)
    record = {
        "schemaVersion": "qinao.diff-content-observation.v1",
        "sourceIdentityDigest": source_identity_digest,
        "objectFormat": object_format,
        "rawDiffSha256": _sha256(raw_bytes),
        "rawManifestDigest": _raw_manifest_digest(parsed),
        "entryCount": len(parsed),
        "observations": observations,
        "erratumDigest": DIFF_CONTENT_ERRATUM_DIGEST,
    }
    # The erratum says the schema contains exactly its enumerated fields.  Its
    # digest is bound transitively by the implementation/bootstrap identity,
    # so it is not persisted as an extra observation field.
    record.pop("erratumDigest")
    return _self_digest_record(record, "observationDigest")


def validate_diff_content_observation(
    entries: Sequence[RawDiffEntry],
    raw_bytes: bytes,
    record: Mapping[str, Any],
    source_identity_digest: str,
    object_format: str,
) -> Dict[str, Any]:
    if not isinstance(record, Mapping):
        raise AuditError("diff content observation type")
    required = {
        "schemaVersion", "sourceIdentityDigest", "objectFormat", "rawDiffSha256",
        "rawManifestDigest", "entryCount", "observations", "observationDigest",
    }
    if set(record) != required or record.get("schemaVersion") != "qinao.diff-content-observation.v1":
        raise AuditError("diff content observation field drift")
    _verify_self_digest(record, "observationDigest")
    parsed = parse_raw_diff_z(raw_bytes, object_format)
    if list(entries) != parsed:
        raise AuditError("raw entries drift from raw bytes")
    _require_lower_hex(source_identity_digest, 64, "source identity digest")
    expected_header = {
        "sourceIdentityDigest": source_identity_digest,
        "objectFormat": object_format,
        "rawDiffSha256": _sha256(raw_bytes),
        "rawManifestDigest": _raw_manifest_digest(parsed),
        "entryCount": len(parsed),
    }
    if any(record.get(key) != value for key, value in expected_header.items()):
        raise AuditError("diff content observation identity/raw drift")
    observations = record.get("observations")
    specs = _observation_specs(parsed, object_format)
    if not isinstance(observations, list) or len(observations) != len(specs):
        raise AuditError("missing or extra diff content observation")
    seen = set()
    for spec, row in zip(specs, observations):
        if not isinstance(row, Mapping):
            raise AuditError("observation row type drift")
        identity = (row.get("entryId"), row.get("side"))
        if identity in seen:
            raise AuditError("duplicate diff content observation")
        seen.add(identity)
        if any(row.get(key) != value for key, value in spec.items()):
            raise AuditError("swapped or mismatched diff content observation")
        base_fields = {
            "entryId", "side", "oid", "objectType", "mode", "pathB64",
            "byteSize", "contentSha256", "contentKind",
        }
        kind = row.get("contentKind")
        allowed = {"text", "binary", "lfs-pointer", "non-blob"}
        if kind not in allowed:
            raise AuditError("unknown content observation kind")
        expected_fields = base_fields | ({"lfsOidSha256", "lfsSize"} if kind == "lfs-pointer" else set())
        if set(row) != expected_fields:
            raise AuditError("content observation row field drift")
        _require_lower_hex(row.get("contentSha256"), 64, "content digest")
        if not isinstance(row.get("byteSize"), int) or isinstance(row.get("byteSize"), bool) or row["byteSize"] < 0:
            raise AuditError("content byte size drift")
        object_type = row.get("objectType")
        if object_type not in ("blob", "tree", "commit", "tag"):
            raise AuditError("content object type drift")
        if (object_type == "blob") == (kind == "non-blob"):
            raise AuditError("content kind/object type mismatch")
        if kind == "lfs-pointer":
            _require_lower_hex(row.get("lfsOidSha256"), 64, "LFS object digest")
            if not isinstance(row.get("lfsSize"), int) or isinstance(row.get("lfsSize"), bool) or row["lfsSize"] < 0:
                raise AuditError("LFS size drift")
    return dict(record)


def capture_diff_content_observation_git(
    repository: Path,
    entries: Sequence[RawDiffEntry],
    raw_bytes: bytes,
    source_identity_digest: str,
    object_format: str,
) -> Dict[str, Any]:
    specs = _observation_specs(entries, object_format)
    requested = []
    for spec in specs:
        requested.extend((spec["oid"], spec["oid"]))
    request_bytes = b"".join(oid.encode("ascii") + b"\n" for oid in requested)
    response = _run_git(Path(repository), ["cat-file", "--batch"], input_bytes=request_bytes)
    parsed = parse_cat_file_batch_results(response, requested)
    queues: Dict[str, List[Tuple[str, bytes]]] = {}
    for oid, result in zip(requested, parsed):
        queues.setdefault(oid, []).append(result)

    def reader(oid: str) -> Tuple[str, bytes]:
        values = queues.get(oid)
        if not values:
            raise AuditError("cat-file batch response missing requested object")
        return values.pop(0)

    record = capture_diff_content_observation(
        entries,
        raw_bytes,
        source_identity_digest,
        object_format,
        reader,
    )
    if any(values for values in queues.values()):
        raise AuditError("unused duplicate cat-file batch response")
    return record


def reopen_sealed_member_record(
    root: Path,
    seal_record_path: str,
    expected_record: Mapping[str, Any],
) -> Dict[str, Any]:
    """Reopen one exact canonical member through its immutable seal."""
    root = Path(root).resolve()
    recovered = recover_run_state(root)
    if recovered["classification"] != "complete":
        raise AuditError("ledger is indeterminate")
    parents = _reopen_parent_capture_records(
        root, recovered, [seal_record_path]
    )
    if len(parents) != 1:
        raise AuditError("sealed member parent is ambiguous")
    _sealed_capture_contains_record(recovered, parents[0], expected_record)
    return parents[0]


def _source_identity_digest(record: Mapping[str, Any]) -> str:
    validated = validate_source_identity(record)
    digest = validated.get("recordDigest")
    return _require_lower_hex(digest, 64, "source identity digest")


def capture_diff_content_observation_durable(
    root: Path,
    *,
    frontier_id: str,
    repository: Path,
    source_identity: Mapping[str, Any],
    raw_bytes: bytes,
    raw_manifest: Mapping[str, Any],
    raw_manifest_seal_record: str,
    object_format: str,
    object_reader: Optional[Any] = None,
    replace_incomplete_capture: Optional[str] = None,
) -> Dict[str, Any]:
    """Allocate, write, and seal the erratum-3 observation generation."""
    root = Path(root).resolve()
    identity_digest = _source_identity_digest(source_identity)
    manifest = validate_raw_diff_manifest(raw_bytes, object_format, raw_manifest)
    parent = reopen_sealed_member_record(
        root, raw_manifest_seal_record, manifest
    )
    recovered = recover_run_state(root)
    frontiers = [
        row
        for row in recovered.get("openFrontiers", [])
        if row.get("frontierId") == frontier_id
        and row.get("frontierKind") in ("task", "local-resource")
    ]
    if len(frontiers) != 1:
        raise AuditError("content observation frontier is not exactly open")
    parent_capture = recovered["captures"].get(parent["captureId"])
    if parent_capture is None or parent_capture["allocation"].get("frontierId") not in (
        None, frontier_id
    ):
        raise AuditError("raw manifest capture frontier drift")
    typed = {
        "sourceIdentityDigest": identity_digest,
        "objectFormat": object_format,
        "rawDiffSha256": manifest["rawDiffSha256"],
        "rawManifestDigest": manifest["manifestDigest"],
    }
    allocation = allocate_capture(
        root,
        CONTENT_OBSERVATION_PHASE,
        frontier_id=frontier_id,
        parent_capture_records=[raw_manifest_seal_record],
        typed_payload=typed,
        replace_incomplete_capture=replace_incomplete_capture,
        _operation_kind="content-observation-allocated",
    )
    entries = parse_raw_diff_z(raw_bytes, object_format)
    if object_reader is None:
        observation = capture_diff_content_observation_git(
            Path(repository),
            entries,
            raw_bytes,
            identity_digest,
            object_format,
        )
    else:
        observation = capture_diff_content_observation(
            entries,
            raw_bytes,
            identity_digest,
            object_format,
            object_reader,
        )
    member = Path(allocation["absolutePath"]) / "observation.json"
    write_canonical_exclusive(member, observation)
    seal = seal_capture(root, allocation["captureId"], ["observation.json"])
    seal_path = root / "ledger" / "records" / ("%016d.json" % seal["sequence"])
    return {
        "state": "content-observation-sealed",
        "captureId": allocation["captureId"],
        "absolutePath": allocation["absolutePath"],
        "allocationRecordDigest": allocation["recordDigest"],
        "sealDigest": seal["sealDigest"],
        "sealRecordDigest": seal["recordDigest"],
        "sealRecordPath": str(seal_path),
        "observation": observation,
    }


def _reopen_content_observation(
    root: Path,
    seal_record_path: str,
) -> Tuple[Dict[str, Any], Dict[str, Any], Dict[str, Any]]:
    root = Path(root).resolve()
    seal = _reopen_ledger_record_path(root, seal_record_path)
    if seal.get("operationKind") != "content-observation-sealed":
        raise AuditError("content observation seal kind drift")
    recovered = recover_run_state(root)
    if recovered["classification"] != "complete":
        raise AuditError("ledger is indeterminate")
    capture = recovered["captures"].get(seal.get("captureId"))
    if (
        capture is None
        or capture.get("state") != "sealed"
        or capture.get("seal") != seal
        or capture.get("allocation", {}).get("operationKind")
        != "content-observation-allocated"
    ):
        raise AuditError("content observation allocation/seal lineage drift")
    manifest = _require_mapping(
        capture.get("_reopenedManifest"),
        "content observation recovered manifest",
    )
    if len(manifest.get("entries", [])) != 1:
        raise AuditError("content observation capture member count drift")
    observation = _recovered_canonical_capture_member(
        capture, "observation.json", "content observation"
    )
    return dict(observation), dict(capture["allocation"]), dict(seal)


def execute_risk_check(
    root: Path,
    *,
    frontier_id: str,
    identity: Mapping[str, Any],
    raw_bytes: bytes,
    raw_manifest: Mapping[str, Any],
    raw_manifest_seal_record: str,
    observation_seal_record: str,
    classifier: Any,
) -> Dict[str, Any]:
    """Validate sealed inputs, invoke Task 5, and durably bind its result."""
    root = Path(root).resolve()
    identity_record = validate_source_identity(identity)
    identity_digest = _source_identity_digest(identity_record)
    object_format = raw_manifest.get("objectFormat")
    if object_format not in OBJECT_HEX_LENGTH:
        raise AuditError("risk raw manifest object format drift")
    manifest = validate_raw_diff_manifest(raw_bytes, object_format, raw_manifest)
    raw_parent = reopen_sealed_member_record(
        root, raw_manifest_seal_record, manifest
    )
    observation, allocation, seal = _reopen_content_observation(
        root, observation_seal_record
    )
    if allocation.get("frontierId") != frontier_id:
        raise AuditError("content observation frontier drift")
    parents = allocation.get("parentCaptures")
    if not isinstance(parents, list) or len(parents) != 1 or parents[0] != raw_parent:
        raise AuditError("content observation raw-manifest parent drift")
    entries = parse_raw_diff_z(raw_bytes, object_format)
    validate_diff_content_observation(
        entries,
        raw_bytes,
        observation,
        identity_digest,
        object_format,
    )
    typed = allocation.get("typedPayload")
    expected_typed = {
        "sourceIdentityDigest": identity_digest,
        "objectFormat": object_format,
        "rawDiffSha256": manifest["rawDiffSha256"],
        "rawManifestDigest": manifest["manifestDigest"],
    }
    if typed != expected_typed:
        raise AuditError("content observation typed identity drift")
    if type(classifier) is not _Task5ClassifierBinding:
        raise AuditError("Task 5 classifier binding is required")
    classifier_binding_digest = classifier.validate()
    decision = classifier(entries, raw_bytes, observation)
    if classifier.validate() != classifier_binding_digest:
        raise AuditError("Task 5 classifier binding drift")
    if not isinstance(decision, Mapping) or set(decision) != {
        "effectiveClass", "reasonCodes"
    }:
        raise AuditError("Task 5 risk decision shape drift")
    effective = decision.get("effectiveClass")
    reasons = decision.get("reasonCodes")
    if effective not in ("routine", "high"):
        raise AuditError("Task 5 risk class drift")
    if (
        not isinstance(reasons, list)
        or any(not isinstance(reason, str) or not reason for reason in reasons)
        or len(reasons) != len(set(reasons))
    ):
        raise AuditError("Task 5 risk reason-code drift")
    requires_high = any(
        entry.status.startswith(("U", "X")) for entry in entries
    ) or any(
        row.get("contentKind") in ("binary", "lfs-pointer", "non-blob")
        for row in observation["observations"]
    )
    if requires_high and effective != "high":
        raise AuditError("Task 5 classifier violated monotonic high requirement")
    result_base: Dict[str, Any] = {
        "schemaVersion": "qinao.risk-result.v2",
        "classifierBindingDigest": classifier_binding_digest,
        "sourceIdentityDigest": identity_digest,
        "rawDiffSha256": manifest["rawDiffSha256"],
        "rawManifestDigest": manifest["manifestDigest"],
        "rawEntryCount": manifest["entryCount"],
        "contentObservationDigest": observation["observationDigest"],
        "effectiveClass": effective,
        "reasonCodes": sorted(reasons),
    }
    for field in ("B", "H", "T", "V", "prBodySha256"):
        if field in identity_record:
            result_base[field] = identity_record[field]
    result = _self_digest_record(result_base)

    def validate_append(recovered: Mapping[str, Any]) -> None:
        open_matches = [
            row
            for row in recovered.get("openFrontiers", [])
            if row.get("frontierId") == frontier_id
        ]
        if len(open_matches) != 1:
            raise AuditError("risk frontier is not exactly open")
        duplicates = [
            row
            for row in recovered.get("records", [])
            if row.get("operationKind") == "risk-completed"
            and row.get("sourceIdentityDigest") == identity_digest
            and row.get("contentObservationDigest")
            == observation["observationDigest"]
        ]
        if duplicates:
            raise AuditError("risk result already completed")

    _append_record(
        root,
        "risk-completed",
        result["recordDigest"],
        [],
        "risk-completed",
        {
            "frontierId": frontier_id,
            "sourceIdentityDigest": identity_digest,
            "rawManifestSealRecordPath": raw_manifest_seal_record,
            "rawManifestSealRecordDigest": raw_parent["recordDigest"],
            "contentObservationSealRecordPath": observation_seal_record,
            "contentObservationSealRecordDigest": seal["recordDigest"],
            "contentObservationDigest": observation["observationDigest"],
            "riskResult": result,
        },
        state_validator=validate_append,
    )
    return result


def _parse_exact_commit_metadata(
    payload: bytes,
    *,
    expected_tree: str,
    expected_parent: str,
    expected_message: bytes,
    label: str,
) -> Dict[str, Any]:
    if not isinstance(payload, bytes) or not payload or len(payload) > MAX_JSON_BYTES:
        raise AuditError(label + " commit byte count")
    if b"\x00" in payload or payload.count(b"\n\n") != 1:
        raise AuditError(label + " commit separator")
    header_block, message = payload.split(b"\n\n", 1)
    headers = header_block.split(b"\n")
    if len(headers) != 4:
        raise AuditError(label + " commit header count")
    expected_prefixes = (b"tree ", b"parent ", b"author ", b"committer ")
    if tuple(line.split(b" ", 1)[0] + b" " for line in headers) != expected_prefixes:
        raise AuditError(label + " commit header order or optional header")
    if headers[0] != b"tree " + expected_tree.encode("ascii"):
        raise AuditError(label + " commit tree")
    if headers[1] != b"parent " + expected_parent.encode("ascii"):
        raise AuditError(label + " commit parent")
    identity_pattern = re.compile(
        rb"\A(?:author|committer) Qinao development "
        rb"<qinao-development@invalid\.local> ([1-9][0-9]*) ([+-])([0-9]{2})([0-9]{2})\Z"
    )
    identities = []
    for line in headers[2:]:
        match = identity_pattern.fullmatch(line)
        if match is None:
            raise AuditError(label + " commit identity drift")
        hours = int(match.group(3))
        minutes = int(match.group(4))
        if hours > 14 or minutes > 59 or (hours == 14 and minutes != 0):
            raise AuditError(label + " commit identity timezone")
        identities.append(line.decode("ascii"))
    if message != expected_message:
        raise AuditError(label + " commit message")
    return {
        "schemaVersion": "qinao.exact-commit.v1",
        "tree": expected_tree,
        "parent": expected_parent,
        "author": identities[0],
        "committer": identities[1],
        "message": message.decode("ascii"),
        "rawCommitSize": len(payload),
        "rawCommitSha256": _sha256(payload),
    }


def parse_bootstrap_commit_metadata(
    payload: bytes,
    *,
    expected_tree: str,
    expected_parent: str,
) -> Dict[str, Any]:
    result = _parse_exact_commit_metadata(
        payload,
        expected_tree=expected_tree,
        expected_parent=expected_parent,
        expected_message=BOOTSTRAP_COMMIT_MESSAGE,
        label="bootstrap",
    )
    result["schemaVersion"] = "qinao.bootstrap-commit.v1"
    return result


def validate_preledger_commit_chain(
    *,
    b0_oid: str,
    b0_payload: bytes,
    b1_oid: str,
    b1_payload: bytes,
    b0_changed_paths: Sequence[bytes],
    b1_changed_paths: Sequence[bytes],
) -> Dict[str, Any]:
    if b0_oid != BOOTSTRAP_IMPLEMENTATION_COMMIT:
        raise AuditError("bootstrap implementation commit drift")
    if not re.fullmatch(r"[0-9a-f]{40}", b1_oid) or b1_oid in (
        FROZEN_C,
        BOOTSTRAP_IMPLEMENTATION_COMMIT,
    ):
        raise AuditError("bootstrap repair commit identity drift")
    if _sha256(b0_payload) != BOOTSTRAP_IMPLEMENTATION_RAW_SHA256:
        raise AuditError("bootstrap implementation raw commit drift")
    b0_metadata = parse_bootstrap_commit_metadata(
        b0_payload,
        expected_tree=BOOTSTRAP_IMPLEMENTATION_TREE,
        expected_parent=FROZEN_C,
    )
    if not b1_payload.startswith(b"tree ") or b"\n" not in b1_payload:
        raise AuditError("bootstrap repair tree header")
    try:
        b1_tree = b1_payload.split(b"\n", 1)[0][5:].decode("ascii", "strict")
    except UnicodeDecodeError as exc:
        raise AuditError("bootstrap repair tree ASCII") from exc
    if not re.fullmatch(r"[0-9a-f]{40}", b1_tree):
        raise AuditError("bootstrap repair tree")
    b1_metadata = _parse_exact_commit_metadata(
        b1_payload,
        expected_tree=b1_tree,
        expected_parent=BOOTSTRAP_IMPLEMENTATION_COMMIT,
        expected_message=BOOTSTRAP_REPAIR_MESSAGE,
        label="bootstrap repair",
    )
    for label, paths in (
        ("implementation", tuple(b0_changed_paths)),
        ("repair", tuple(b1_changed_paths)),
    ):
        if paths != TASK3_TRACKED_PATHS:
            raise AuditError("bootstrap " + label + " path delta drift")
    ordered = [BOOTSTRAP_IMPLEMENTATION_COMMIT, b1_oid]
    return {
        "schemaVersion": "qinao.preledger-commit-chain.v1",
        "orderedCommitChain": ordered,
        "orderedCommitChainDigest": _sha256(canonical_json_bytes(ordered)),
        "implementationCommitMetadata": b0_metadata,
        "repairCommitMetadata": b1_metadata,
    }


def _self_digest_record(value: Mapping[str, Any], field: str = "recordDigest") -> Dict[str, Any]:
    if field in value:
        raise AuditError("self-digest field already present")
    result = dict(value)
    result[field] = _sha256(canonical_json_bytes(result))
    return result


def _verify_self_digest(value: Mapping[str, Any], field: str = "recordDigest") -> None:
    digest = value.get(field)
    if not isinstance(digest, str) or not re.fullmatch(r"[0-9a-f]{64}", digest):
        raise AuditError("missing self digest")
    unsigned = dict(value)
    del unsigned[field]
    if _sha256(canonical_json_bytes(unsigned)) != digest:
        raise AuditError("self digest mismatch")


def _write_all(fd: int, payload: bytes) -> None:
    view = memoryview(payload)
    written = 0
    while written < len(view):
        count = os.write(fd, view[written:])
        if count <= 0:
            raise OSError("short write made no progress")
        written += count


_DIRECTORY_OPEN_FLAGS = (
    os.O_RDONLY
    | getattr(os, "O_DIRECTORY", 0)
    | getattr(os, "O_NOFOLLOW", 0)
    | getattr(os, "O_CLOEXEC", 0)
)


def _absolute_path_without_symlink_resolution(path: Path) -> Path:
    raw = os.fspath(Path(path))
    if not os.path.isabs(raw):
        raw = os.path.join(os.getcwd(), raw)
    normalized = os.path.normpath(raw)
    if not os.path.isabs(normalized):
        raise AuditError("durable path is not absolute")
    return Path(normalized)


def _stat_identity(observed: os.stat_result) -> Tuple[int, int, int, int]:
    return (
        observed.st_dev,
        observed.st_ino,
        observed.st_mode,
        observed.st_nlink,
    )


def _directory_identity(observed: os.stat_result) -> Tuple[int, int, int]:
    return (
        observed.st_dev,
        observed.st_ino,
        observed.st_mode,
    )


def _fd_slots_operation(slots: Sequence["_ChildFdOwnerSlot"], operation: Any) -> Any:
    """Borrow every exact generation for one syscall, in stable owner order."""
    if any(not isinstance(slot, _ChildFdOwnerSlot) for slot in slots):
        raise AuditError("descriptor operation requires owner slots")
    owners = sorted(set(slots), key=id)
    descriptors: Dict[Any, int] = {}

    def borrow(index: int) -> Any:
        if index == len(owners):
            return operation(*(descriptors[slot] for slot in slots))
        slot = owners[index]

        def acquired(descriptor: int) -> Any:
            descriptors[slot] = descriptor
            return borrow(index + 1)

        return slot._operate(acquired)

    return borrow(0)


def _fd_call(slot: "_ChildFdOwnerSlot", operation: Any, *args: Any, **kwargs: Any) -> Any:
    return _fd_slots_operation((slot,), lambda fd: operation(fd, *args, **kwargs))


def _fd_at(slot: "_ChildFdOwnerSlot", operation: Any, *args: Any, **kwargs: Any) -> Any:
    return _fd_slots_operation((slot,), lambda fd: operation(*args, dir_fd=fd, **kwargs))


def _close_fd_slots(slots: Iterable[Optional["_ChildFdOwnerSlot"]],
                    primary: Optional[BaseException] = None) -> None:
    """Consume eligible siblings once; preserve the first and all later failures."""
    failure = primary
    seen: Set[Any] = set()
    for slot in slots:
        if slot is None or slot in seen:
            continue
        seen.add(slot)
        try:
            slot.close()
        except BaseException as cleanup:
            if failure is None:
                failure = cleanup
            else:
                _retain_git_cleanup_error(failure, cleanup)
    if primary is None and failure is not None:
        raise failure


class _FdAcquisitionArena:
    """Prepublished ownership, including an acquisition not yet registered."""

    def __init__(self) -> None:
        self.slots: List[_ChildFdOwnerSlot] = []
        self.acquisition_uncertain = False

    def acquire(self, operation: Any, label: str) -> "_ChildFdOwnerSlot":
        if self.acquisition_uncertain:
            raise AuditError("descriptor acquisition is unresolved")
        self.acquisition_uncertain = True
        try:
            descriptor = operation()
        except OSError:
            # A completed failing OS acquisition returned no generation.
            self.acquisition_uncertain = False
            raise
        # KI/SystemExit before return, or any failure before registration,
        # leaves the published tombstone set. No raw-number retry follows.
        slot = _ChildFdOwnerSlot(descriptor, label)
        self.slots.append(slot)
        self.acquisition_uncertain = False
        return slot

    def settled(self) -> bool:
        return not self.acquisition_uncertain and all(
            slot.phase == "closed" for slot in self.slots
        )


def _open_owned_at(parent: "_ChildFdOwnerSlot", name: str, flags: int,
                   mode: int = 0o777, *,
                   ownership_arena: Optional[_FdAcquisitionArena] = None) -> "_ChildFdOwnerSlot":
    # The parent lease spans acquisition and publication of the new owner.
    # An interruption before Python sees the acquisition can still leak; it
    # never grants cleanup authority over an unregistered raw number.
    def acquire(fd: int) -> "_ChildFdOwnerSlot":
        if ownership_arena is not None:
            return ownership_arena.acquire(
                lambda: os.open(name, flags, mode, dir_fd=fd),
                "durable member " + name,
            )
        return _ChildFdOwnerSlot(
            os.open(name, flags, mode, dir_fd=fd), "durable member " + name
        )
    return _fd_slots_operation((parent,), acquire)


def _close_named_fd_slots(owner: Any, names: Sequence[str]) -> None:
    """Retire independent guard siblings, retaining uncertain exact owners."""
    failure: Optional[BaseException] = None
    for name in names:
        slot = getattr(owner, name)
        if slot is None:
            continue
        try:
            slot.close()
        except BaseException as cleanup:
            if failure is None:
                failure = cleanup
            else:
                _retain_git_cleanup_error(failure, cleanup)
        else:
            setattr(owner, name, None)
    if failure is not None:
        raise failure


def _write_owned_all(slot: "_ChildFdOwnerSlot", payload: bytes) -> None:
    view = memoryview(payload)
    written = 0
    while written < len(view):
        count = _fd_call(slot, os.write, view[written:])
        if count <= 0:
            raise OSError("short write made no progress")
        written += count


def _normalize_directory_slot(slot: "_ChildFdOwnerSlot",
                              arena: _FdAcquisitionArena) -> "_ChildFdOwnerSlot":
    if slot.descriptor() >= 3:
        _fd_call(slot, os.set_inheritable, False)
        return slot
    duplicate = slot._operate(lambda fd: arena.acquire(
        lambda: fcntl.fcntl(fd, fcntl.F_DUPFD_CLOEXEC, 3),
        "normalized directory",
    ))
    slot.close()
    return duplicate


def _open_directory_fd(
    path: Path, *, descriptor_sink: Optional[List["_ChildFdOwnerSlot"]] = None,
    ownership_arena: Optional[_FdAcquisitionArena] = None,
) -> Tuple["_ChildFdOwnerSlot", Path, os.stat_result]:
    if descriptor_sink is not None and (
        type(descriptor_sink) is not list or descriptor_sink
    ):
        raise AuditError("directory descriptor sink drift")
    absolute = _absolute_path_without_symlink_resolution(path)
    arena = ownership_arena if ownership_arena is not None else _FdAcquisitionArena()
    if type(arena) is not _FdAcquisitionArena or arena.slots or arena.acquisition_uncertain:
        raise AuditError("directory acquisition arena drift")
    try:
        fd = arena.acquire(lambda: os.open("/", _DIRECTORY_OPEN_FLAGS), "directory root")
        fd = _normalize_directory_slot(fd, arena)
        for component in absolute.parts[1:]:
            if component in ("", ".", "..") or "/" in component or "\x00" in component:
                raise AuditError("unsafe durable path component")
            next_fd = _open_owned_at(fd, component, _DIRECTORY_OPEN_FLAGS,
                                     ownership_arena=arena)
            next_fd = _normalize_directory_slot(next_fd, arena)
            fd.close()
            fd = next_fd
        observed = _fd_call(fd, os.fstat)
        if not stat.S_ISDIR(observed.st_mode):
            raise AuditError("directory is not ordinary: " + str(absolute))
        if descriptor_sink is not None:
            # Publish ownership before returning so an exception between the
            # callee return and the caller's STORE_FAST cannot orphan the fd.
            descriptor_sink.append(fd)
        return fd, absolute, observed
    except BaseException as primary:
        try:
            _close_fd_slots(reversed(arena.slots), primary)
        finally:
            if descriptor_sink is not None:
                descriptor_sink.clear()
        raise


def _open_parent_dir_fd(
    path: Path,
) -> Tuple["_ChildFdOwnerSlot", str, Path, os.stat_result]:
    absolute = _absolute_path_without_symlink_resolution(path)
    name = absolute.name
    if not name or name in (".", "..") or "/" in name or "\x00" in name:
        raise AuditError("unsafe durable leaf name")
    fd, parent, observed = _open_directory_fd(absolute.parent)
    return fd, name, parent, observed


def _revalidate_directory_identity(
    path: Path, expected: os.stat_result, label: str
) -> None:
    try:
        fd, _absolute, observed = _open_directory_fd(path)
    except (AuditError, OSError) as exc:
        raise AuditError(label + " parent identity drift") from exc
    primary: Optional[BaseException] = None
    try:
        if _directory_identity(observed) != _directory_identity(expected):
            raise AuditError(label + " parent identity drift")
    except BaseException as exc:
        primary = exc
        raise
    finally:
        _close_fd_slots([fd], primary)


def _leaf_stat_at(parent_fd: "_ChildFdOwnerSlot", name: str) -> os.stat_result:
    try:
        return _fd_at(parent_fd, os.stat, name, follow_symlinks=False)
    except (FileNotFoundError, NotADirectoryError) as exc:
        raise AuditError("durable leaf disappeared") from exc


def _revalidate_leaf_identity(
    path: Path,
    expected_parent: os.stat_result,
    expected_leaf: os.stat_result,
    label: str,
) -> None:
    parent_fd, name, parent_path, parent_observed = _open_parent_dir_fd(path)
    primary: Optional[BaseException] = None
    try:
        if _directory_identity(parent_observed) != _directory_identity(expected_parent):
            raise AuditError(label + " parent identity drift")
        leaf = _leaf_stat_at(parent_fd, name)
        if _stat_identity(leaf) != _stat_identity(expected_leaf):
            raise AuditError(label + " leaf identity drift")
    except BaseException as exc:
        primary = exc
        raise
    finally:
        _close_fd_slots([parent_fd], primary)
    _revalidate_directory_identity(parent_path, expected_parent, label)


def _fsync_directory(path: Path) -> None:
    try:
        fd, absolute, observed = _open_directory_fd(path)
    except OSError as exc:
        raise AuditError("required directory absent: " + str(path)) from exc
    primary: Optional[BaseException] = None
    try:
        _fd_call(fd, os.fsync)
    except BaseException as exc:
        primary = exc
        raise
    finally:
        _close_fd_slots([fd], primary)
    _revalidate_directory_identity(absolute, observed, "directory fsync")


def _ordinary_directory(path: Path, expected_mode: Optional[int] = None) -> os.stat_result:
    try:
        fd, absolute, observed = _open_directory_fd(path)
    except OSError as exc:
        raise AuditError("required directory absent: " + str(path)) from exc
    primary: Optional[BaseException] = None
    try:
        if expected_mode is not None and stat.S_IMODE(observed.st_mode) != expected_mode:
            raise AuditError("directory mode mismatch: " + str(absolute))
    except BaseException as exc:
        primary = exc
        raise
    finally:
        _close_fd_slots([fd], primary)
    _revalidate_directory_identity(absolute, observed, "directory reopen")
    return observed


def _open_ordinary_file(
    path: Path,
    *,
    expected_mode: Optional[int] = None,
    single_link: bool = True,
) -> Tuple["_ChildFdOwnerSlot", "_ChildFdOwnerSlot", str, Path, os.stat_result, os.stat_result]:
    parent_fd, name, parent_path, parent_observed = _open_parent_dir_fd(path)
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_CLOEXEC", 0)
    try:
        fd = _open_owned_at(parent_fd, name, flags)
    except BaseException as primary:
        _close_fd_slots([parent_fd], primary)
        raise
    try:
        observed = _fd_call(fd, os.fstat)
        if not stat.S_ISREG(observed.st_mode):
            raise AuditError("path is not an ordinary file: " + str(path))
        if single_link and observed.st_nlink != 1:
            raise AuditError("hard link surprise: " + str(path))
        if expected_mode is not None and stat.S_IMODE(observed.st_mode) != expected_mode:
            raise AuditError("file mode mismatch: " + str(path))
        leaf = _leaf_stat_at(parent_fd, name)
        if _stat_identity(leaf) != _stat_identity(observed):
            raise AuditError("concurrent file change: " + str(path))
        return fd, parent_fd, name, parent_path, parent_observed, observed
    except BaseException as primary:
        _close_fd_slots([fd, parent_fd], primary)
        raise


def _ordinary_file(path: Path, *, expected_mode: Optional[int] = None, single_link: bool = True) -> os.stat_result:
    try:
        fd, parent_fd, _name, parent_path, parent_observed, observed = (
            _open_ordinary_file(
                path, expected_mode=expected_mode, single_link=single_link
            )
        )
    except FileNotFoundError as exc:
        raise AuditError("required file absent: " + str(path)) from exc
    except OSError as exc:
        raise AuditError("path is not an ordinary file: " + str(path)) from exc
    _close_fd_slots([fd, parent_fd])
    _revalidate_leaf_identity(path, parent_observed, observed, "file reopen")
    _revalidate_directory_identity(parent_path, parent_observed, "file reopen")
    return observed


@dataclass(frozen=True)
class DurabilityFaults:
    """Explicit test-only fault provider below the durable policy layer."""

    callback: Optional[Any] = None

    def hit(
        self, boundary: str, operation_kind: str, subject: str = ""
    ) -> None:
        if not isinstance(boundary, str) or not boundary:
            raise AuditError("durability fault boundary drift")
        if not isinstance(operation_kind, str) or not operation_kind:
            raise AuditError("durability fault operation drift")
        if not isinstance(subject, str):
            raise AuditError("durability fault subject drift")
        if self.callback is not None:
            self.callback(boundary, operation_kind, subject)


def _make_task_test_execution_append_capability_authority(
) -> Tuple[Any, ...]:
    """Create exact, single-publication grants in a closure-private registry."""

    class PublicationGrant:
        __slots__ = ()

    class PublicationReceipt:
        __slots__ = ()

    class RejectedGrant:
        __slots__ = ()

    class WriterPreparation:
        __slots__ = ()

    authority_lock = threading.RLock()
    grants: Dict[int, Dict[str, Any]] = {}
    receipts: Dict[int, Dict[str, Any]] = {}
    publication_events: Dict[int, Dict[str, Any]] = {}
    writer_preparations: Dict[int, Dict[str, Any]] = {}

    def owns_writer_preparation(function: Any) -> Any:
        """Admit a continuation only from one complete raw-writer call."""

        signature = inspect.signature(function)
        public_parameters = tuple(
            parameter
            for parameter in signature.parameters.values()
            if parameter.name != "_task_test_execution_writer_frame"
        )

        def prepared_entry(*args: Any, **kwargs: Any) -> Any:
            frame = WriterPreparation()
            owner = {
                "frame": frame,
                "function": function,
                "thread": threading.get_ident(),
                "state": "entered",
                "epoch": 0,
            }
            with authority_lock:
                writer_preparations[id(frame)] = owner
            kwargs["_task_test_execution_writer_frame"] = frame
            try:
                return function(*args, **kwargs)
            finally:
                with authority_lock:
                    if writer_preparations.get(id(frame)) is owner:
                        writer_preparations.pop(id(frame), None)

        prepared_entry.__name__ = function.__name__
        prepared_entry.__qualname__ = function.__qualname__
        prepared_entry.__doc__ = function.__doc__
        prepared_entry.__signature__ = signature.replace(
            parameters=public_parameters
        )
        return prepared_entry

    def prepare_writer_once(
        frame: Any,
        value: Any,
        transaction: Any,
        descriptor: _ChildFdOwnerSlot,
        staging_name: str,
        final_name: str,
        payload: bytes,
    ) -> None:
        """Seal exact post-validator writer observations into one frame."""

        observed = _fd_call(descriptor, os.fstat)
        scratch_fd = transaction._fds.get("scratch")
        visible = _fd_at(scratch_fd, os.stat, staging_name, follow_symlinks=False)
        stable = lambda item: (
            item.st_dev, item.st_ino, item.st_mode, item.st_nlink,
            item.st_size, item.st_mtime_ns, item.st_ctime_ns,
        )
        if (
            type(payload) is not bytes
            or stable(observed) != stable(visible)
            or observed.st_size != len(payload)
        ):
            raise AuditError("atomic writer preparation drift")
        with authority_lock:
            owner = writer_preparations.get(id(frame))
            if (
                type(frame) is not WriterPreparation
                or owner is None
                or owner.get("frame") is not frame
                or owner.get("thread") != threading.get_ident()
                or owner.get("state") != "entered"
            ):
                raise AuditError("atomic writer preparation is required")
            owner.update({
                "state": "prepared",
                "epoch": owner["epoch"] + 1,
                "capability": value,
                "transaction": transaction,
                "descriptor": descriptor,
                "stagingName": staging_name,
                "finalName": final_name,
                "stagingStable": stable(observed),
                "payloadDigest": _sha256(payload),
            })

    def require_live_event(
        event: Mapping[str, Any], state: str, epoch: int
    ) -> None:
        with authority_lock:
            if (
                publication_events.get(id(event["grant"])) is not event
                or event.get("state") != state
                or event.get("epoch") != epoch
                or getattr(event.get("guard"), "_quarantined", False)
            ):
                raise AuditError("publication lifecycle authority drift")

    def close_descriptors_independently(
        descriptors: Sequence[Optional[_ChildFdOwnerSlot]],
    ) -> Optional[BaseException]:
        first_error: Optional[BaseException] = None
        for descriptor in descriptors:
            if descriptor is None:
                continue
            try:
                descriptor.close()
            except BaseException as exc:
                if first_error is None:
                    first_error = exc
                else:
                    _retain_git_cleanup_error(first_error, exc)
        return first_error

    def authentic_guard(
        guard: Any,
        private_token: Any,
        root: Path,
    ) -> None:
        guard_type = globals().get("_TaskTestExecutionLeaseGuard")
        if guard_type is None or type(guard) is not guard_type:
            raise AuditError("authentic execution lease guard is required")
        guard._validate_execution_authority_registration(
            private_token,
            _absolute_path_without_symlink_resolution(Path(root)),
        )

    def issue(
        guard: Any,
        private_token: Any = None,
        *,
        root: Optional[Path] = None,
        operation_kind: Optional[str] = None,
        phase: Optional[str] = None,
        acquired_record_digest: Optional[str] = None,
        attempt_start_record_digest: Optional[str] = None,
        pending_acquisition_identity: Any = None,
        closed_lease_terminal_record_digest: Optional[str] = None,
        closed_recovery_disposition: Optional[str] = None,
        recovery_projection_digest: Optional[str] = None,
        attempt_id: Optional[str] = None,
        frontier_id: Optional[str] = None,
        outer_invocation_start_record_digest: Optional[str] = None,
        recovery_identity: Any = None,
        _reserved_recovery_authority: Any = None,
    ) -> Any:
        if root is None:
            root = getattr(guard, "root", Path("."))
        try:
            authentic_guard(guard, private_token, Path(root))
        except AuditError:
            # The callable exposes no authority for a fake guard.  Return an
            # inert exact sentinel so the durable writer owns the rejection
            # boundary and can reject before any mutation.
            return RejectedGrant()
        ordinary_phases = {
            "task-test-execution-lease-acquired": {"lease-acquired"},
            "task-test-attempt-started": {"attempt-start"},
            "task-test-attempt-terminal": {
                "attempt-terminal-incumbent",
                "attempt-terminal-closed-lease-recovery",
            },
            "task-test-execution-lease-terminal": {
                "lease-terminal",
                "lease-terminal-owner-lost-recovery",
            },
        }
        recovery_phases = {
            (
                "task-test-attempt-terminal",
                "attempt-terminal-closed-lease-recovery",
            ),
            (
                "task-test-execution-lease-terminal",
                "lease-terminal-owner-lost-recovery",
            ),
        }
        recovery_authority_digest = None
        if _reserved_recovery_authority is None:
            admitted = (
                operation_kind in ordinary_phases
                and phase in ordinary_phases[operation_kind]
            )
        else:
            admitted = (
                (operation_kind, phase) in recovery_phases
                and isinstance(_reserved_recovery_authority, Mapping)
                and _reserved_recovery_authority.get("identity")
                is recovery_identity
            )
            if admitted:
                recovery_authority_digest = _sha256(
                    canonical_json_bytes({
                        key: value
                        for key, value in
                        _reserved_recovery_authority.items()
                        if key not in ("identity", "capability")
                    })
                )
        if not admitted:
            raise AuditError("execution lease publication grant scope drift")
        grant = PublicationGrant()
        scope = MappingProxyType({
            "root": _absolute_path_without_symlink_resolution(Path(root)),
            "operationKind": operation_kind,
            "phase": phase,
            "acquiredRecordDigest": acquired_record_digest,
            "attemptStartRecordDigest": attempt_start_record_digest,
            "pendingAcquisitionIdentity": pending_acquisition_identity,
            "closedLeaseTerminalRecordDigest":
                closed_lease_terminal_record_digest,
            "closedRecoveryDisposition": closed_recovery_disposition,
            "recoveryProjectionDigest": recovery_projection_digest,
            "attemptId": attempt_id,
            "frontierId": frontier_id,
            "outerInvocationStartRecordDigest":
                outer_invocation_start_record_digest,
            "recoveryIdentity": recovery_identity,
        })
        event = {
            "grant": grant,
            "guard": guard,
            "privateToken": private_token,
            "scope": scope,
            "state": "issued",
            "epoch": 0,
            "transaction": None,
            "receipt": None,
            "reservedRecoveryAuthority":
                _reserved_recovery_authority,
            "reservedRecoveryAuthorityDigest":
                recovery_authority_digest,
        }
        with authority_lock:
            grants[id(grant)] = event
            publication_events[id(grant)] = event
        return grant

    def validate_reserved_recovery_authority(
        value: Any,
        guard: Any,
        private_token: Any,
        authority: Any,
    ) -> bool:
        if not isinstance(authority, Mapping):
            return False
        try:
            current_digest = _sha256(canonical_json_bytes({
                key: item
                for key, item in authority.items()
                if key not in ("identity", "capability")
            }))
        except (AuditError, TypeError, ValueError):
            return False
        with authority_lock:
            event = publication_events.get(id(value))
            return (
                type(value) is PublicationGrant
                and event is not None
                and event.get("grant") is value
                and event.get("guard") is guard
                and event.get("privateToken") is private_token
                and event.get("state") in ("issued", "publishing")
                and event.get("reservedRecoveryAuthority") is authority
                and event.get("reservedRecoveryAuthorityDigest")
                == current_digest
            )

    def resolve(value: Any) -> Optional[Tuple[Any, Mapping[str, Any]]]:
        if type(value) is RejectedGrant:
            raise AuditError("authentic execution lease guard is required")
        if type(value) is not PublicationGrant:
            return None
        with authority_lock:
            entry = grants.get(id(value))
            if (
                entry is None
                or entry.get("grant") is not value
                or entry.get("state") != "issued"
            ):
                return None
            guard = entry["guard"]
            private_token = entry["privateToken"]
            scope = entry["scope"]
        authentic_guard(guard, private_token, scope["root"])
        return guard, scope

    def consume(value: Any) -> Optional[Tuple[Any, Mapping[str, Any]]]:
        with authority_lock:
            entry = grants.get(id(value))
        resolved = resolve(value)
        if resolved is not None and entry is not None:
            with authority_lock:
                if grants.get(id(value)) is entry:
                    grants.pop(id(value), None)
                    entry["state"] = "revoked"
                    entry["epoch"] += 1
            abandon(entry)
        return resolved

    def abandon(entry: Mapping[str, Any]) -> None:
        guard = entry["guard"]
        private_token = entry["privateToken"]
        scope = entry["scope"]
        pending_identity = scope.get("pendingAcquisitionIdentity")
        if pending_identity is not None:
            guard._revoke_pending_acquisition(
                private_token, pending_identity
            )

    def revoke(value: Any) -> None:
        if type(value) is PublicationGrant:
            entry = None
            with authority_lock:
                candidate = grants.get(id(value))
                if (
                    candidate is not None
                    and candidate.get("grant") is value
                    and candidate.get("state") == "issued"
                ):
                    entry = candidate
                    grants.pop(id(value), None)
                    entry["state"] = "revoked"
                    entry["epoch"] += 1
            if entry is not None:
                abandon(entry)

    def publish_staged_once(
        value: Any,
        transaction: Any,
        descriptor: _ChildFdOwnerSlot,
        staging_name: str,
        final_name: str,
        writer_frame: Any = None,
    ) -> None:
        """Own one real no-replace publication; accept no claimed result."""

        if type(value) is RejectedGrant:
            raise AuditError("authentic execution lease guard is required")
        if type(value) is not PublicationGrant:
            raise AuditError(
                "live execution lease guard capability is required"
            )
        with authority_lock:
            preparation = writer_preparations.get(id(writer_frame))
            grant_entry = grants.get(id(value))
            if (
                type(writer_frame) is not WriterPreparation
                or preparation is None
                or preparation.get("frame") is not writer_frame
                or preparation.get("state") != "prepared"
                or preparation.get("thread") != threading.get_ident()
                or preparation.get("capability") is not value
                or preparation.get("transaction") is not transaction
                or preparation.get("descriptor") is not descriptor
                or preparation.get("stagingName") != staging_name
                or preparation.get("finalName") != final_name
            ):
                raise AuditError("atomic writer preparation is required")
            if (
                grant_entry is None
                or grant_entry.get("grant") is not value
                or grant_entry.get("state") != "issued"
                or publication_events.get(id(value)) is not grant_entry
                or any(
                    event.get("transaction") is transaction
                    and event.get("state") in (
                        "publishing", "sealed", "delivering"
                    )
                    for event in publication_events.values()
                )
            ):
                raise AuditError(
                    "live execution lease guard capability is required"
                )
            grants.pop(id(value), None)
            preparation["state"] = "consumed"
            preparation["epoch"] += 1
            grant_entry["state"] = "publishing"
            grant_entry["epoch"] += 1
            grant_entry["transaction"] = transaction
            event_epoch = grant_entry["epoch"]
        guard = grant_entry["guard"]
        private_token = grant_entry["privateToken"]
        scope = grant_entry["scope"]
        try:
            transaction_type = globals().get("LedgerTransaction")
            if (
                transaction_type is None
                or type(transaction) is not transaction_type
                or not transaction._locked
                or type(descriptor) is not _ChildFdOwnerSlot
                or not isinstance(staging_name, str)
                or re.fullmatch(
                    r"\.qinao-record-stage-[0-9]{16}-[0-9a-f]{16}\.json",
                    staging_name,
                ) is None
                or not isinstance(final_name, str)
                or re.fullmatch(r"[0-9]{16}\.json", final_name) is None
            ):
                raise AuditError("atomic publication event authority drift")
            transaction.revalidate()
            if transaction.root != scope["root"]:
                raise AuditError("execution lease publication grant scope drift")
            records_fd = transaction._fds.get("records")
            scratch_fd = transaction._fds.get("scratch")
            if (
                type(records_fd) is not _ChildFdOwnerSlot
                or type(scratch_fd) is not _ChildFdOwnerSlot
            ):
                raise AuditError("atomic publication event authority drift")
            before = _fd_call(descriptor, os.fstat)
            visible_before = _fd_at(scratch_fd, os.stat, staging_name, follow_symlinks=False)
            stable = lambda observed: (
                observed.st_dev, observed.st_ino, observed.st_mode,
                observed.st_nlink, observed.st_size, observed.st_mtime_ns,
                observed.st_ctime_ns,
            )
            if (
                not stat.S_ISREG(before.st_mode)
                or stat.S_IMODE(before.st_mode) != 0o600
                or before.st_nlink != 1
                or before.st_size < 1
                or before.st_size > MAX_JSON_BYTES
                or stable(before) != stable(visible_before)
                or stable(before) != preparation.get("stagingStable")
            ):
                raise AuditError("atomic publication event staging drift")
            _fd_call(descriptor, os.fsync)
            _fd_call(scratch_fd, os.fsync)
            _fd_call(descriptor, os.lseek, 0, os.SEEK_SET)
            chunks: List[bytes] = []
            total = 0
            while True:
                chunk = _fd_call(descriptor, os.read, min(1024 * 1024, MAX_JSON_BYTES + 1 - total))
                if not chunk:
                    break
                chunks.append(chunk)
                total += len(chunk)
                if total > MAX_JSON_BYTES:
                    raise AuditError(
                        "atomic publication event bytes exceed bound"
                    )
            publication_payload = b"".join(chunks)
            after = _fd_call(descriptor, os.fstat)
            visible_after = _fd_at(scratch_fd, os.stat, staging_name, follow_symlinks=False)
            if (
                stable(before) != stable(after)
                or stable(before) != stable(visible_after)
                or total != before.st_size
                or _sha256(publication_payload)
                != preparation.get("payloadDigest")
            ):
                raise AuditError("atomic publication event staging drift")
            recovered = transaction.recover()
            require_live_event(grant_entry, "publishing", event_epoch)
            authentic_guard(guard, private_token, scope["root"])
            _fd_call(descriptor, os.fsync)
            _fd_call(scratch_fd, os.fsync)
            refreshed_before = _fd_call(descriptor, os.fstat)
            refreshed_visible_before = _fd_at(scratch_fd, os.stat, staging_name, follow_symlinks=False)
            if (
                stable(after) != stable(refreshed_before)
                or stable(after) != stable(refreshed_visible_before)
            ):
                raise AuditError("atomic publication event staging drift")
            _fd_call(descriptor, os.lseek, 0, os.SEEK_SET)
            refreshed_chunks: List[bytes] = []
            refreshed_total = 0
            while True:
                chunk = _fd_call(descriptor, os.read, min(
                        1024 * 1024,
                        MAX_JSON_BYTES + 1 - refreshed_total,
                    ))
                if not chunk:
                    break
                refreshed_chunks.append(chunk)
                refreshed_total += len(chunk)
                if refreshed_total > MAX_JSON_BYTES:
                    raise AuditError(
                        "atomic publication event bytes exceed bound"
                    )
            refreshed_payload = b"".join(refreshed_chunks)
            refreshed_after = _fd_call(descriptor, os.fstat)
            refreshed_visible_after = _fd_at(scratch_fd, os.stat, staging_name, follow_symlinks=False)
            if (
                stable(after) != stable(refreshed_after)
                or stable(after) != stable(refreshed_visible_after)
                or refreshed_total != after.st_size
                or refreshed_payload != publication_payload
                or _sha256(refreshed_payload)
                != preparation.get("payloadDigest")
            ):
                raise AuditError("atomic publication event staging drift")
            publication_payload = refreshed_payload
            after = refreshed_after
            record = parse_canonical_json(publication_payload)
            if not isinstance(record, Mapping):
                raise AuditError("ledger record publication shape drift")
            _verify_self_digest(record)
            _validate_ledger_record_shape(record)
            sequence = record.get("sequence")
            if (
                type(sequence) is not int
                or final_name != "%016d.json" % sequence
            ):
                raise AuditError("atomic publication event sequence drift")
            operation_kind = record.get("operationKind")
            if not _task_test_execution_authority_record_reserved(
                operation_kind, record
            ):
                raise AuditError("atomic publication event scope drift")
            recovered_records = recovered.get("records")
            if (
                recovered.get("nextSequence") != sequence
                or not isinstance(recovered_records, list)
                or not recovered_records
                or record.get("previousRecordDigest")
                != recovered_records[-1].get("recordDigest")
            ):
                raise AuditError("atomic publication event chain drift")
            authentic_guard(guard, private_token, scope["root"])
            guard._validate_internal_append_capability(
                value,
                scope["root"],
                operation_kind,
                record,
                scope,
            )
            _project_reserved_execution_candidate(
                transaction, recovered_records, record
            )
            library = ctypes.CDLL(None, use_errno=True)
            try:
                renameatx_np = library.renameatx_np
            except AttributeError as exc:
                raise AuditError(
                    "atomic record publication unavailable"
                ) from exc
            renameatx_np.argtypes = [
                ctypes.c_int, ctypes.c_char_p, ctypes.c_int,
                ctypes.c_char_p, ctypes.c_uint,
            ]
            renameatx_np.restype = ctypes.c_int
            _fd_call(descriptor, os.lseek, 0, os.SEEK_SET)
            projected_chunks: List[bytes] = []
            projected_total = 0
            while True:
                chunk = _fd_call(descriptor, os.read, min(
                        1024 * 1024,
                        MAX_JSON_BYTES + 1 - projected_total,
                    ))
                if not chunk:
                    break
                projected_chunks.append(chunk)
                projected_total += len(chunk)
                if projected_total > MAX_JSON_BYTES:
                    raise AuditError(
                        "atomic publication event bytes exceed bound"
                    )
            projected_after = _fd_call(descriptor, os.fstat)
            projected_visible = _fd_at(scratch_fd, os.stat, staging_name, follow_symlinks=False)
            if (
                stable(after) != stable(projected_after)
                or stable(after) != stable(projected_visible)
                or projected_total != after.st_size
                or b"".join(projected_chunks) != publication_payload
            ):
                raise AuditError("atomic publication event staging drift")
            after = projected_after
            transaction.revalidate()
            authentic_guard(guard, private_token, scope["root"])
            with authority_lock:
                require_live_event(
                    grant_entry, "publishing", event_epoch
                )
                try:
                    _fd_at(records_fd, os.stat, final_name, follow_symlinks=False)
                except FileNotFoundError:
                    pass
                else:
                    raise FileExistsError(
                        errno.EEXIST, "ledger record already exists"
                    )
                result = _fd_slots_operation(
                    (scratch_fd, records_fd),
                    lambda source, target: renameatx_np(
                        source, os.fsencode(staging_name),
                        target, os.fsencode(final_name), 0x00000004,
                    ),
                )
                if result != 0:
                    observed_errno = ctypes.get_errno()
                    if observed_errno == errno.EEXIST:
                        raise FileExistsError(
                            errno.EEXIST, "ledger record already exists"
                        )
                    raise OSError(
                        observed_errno, os.strerror(observed_errno)
                    )
                grant_entry["epoch"] += 1
                event_epoch = grant_entry["epoch"]
            transaction.faults.hit(
                "record-atomic-publish", transaction.operation_kind,
                final_name,
            )
            require_live_event(grant_entry, "publishing", event_epoch)
            visible = _fd_at(records_fd, os.stat, final_name, follow_symlinks=False)
            if (
                not stat.S_ISREG(visible.st_mode)
                or stat.S_IMODE(visible.st_mode) != 0o600
                or visible.st_nlink != 1
                or visible.st_size != len(publication_payload)
                or _stat_identity(visible) != _stat_identity(after)
            ):
                raise AuditError("atomic ledger record publication drift")
            reopened, reopened_observed = transaction.read_bytes_at(
                records_fd,
                final_name,
                maximum=len(publication_payload),
                expected_mode=0o600,
            )
            if (
                _stat_identity(reopened_observed) != _stat_identity(after)
                or reopened != publication_payload
            ):
                raise AuditError("atomic ledger record payload drift")
            _fd_call(scratch_fd, os.fsync)
            transaction.faults.hit(
                "record-stage-source-fsync", transaction.operation_kind,
                final_name,
            )
            require_live_event(grant_entry, "publishing", event_epoch)
            _fd_call(records_fd, os.fsync)
            transaction.faults.hit(
                "records-fsync", transaction.operation_kind, final_name
            )
            require_live_event(grant_entry, "publishing", event_epoch)
            transaction.revalidate()
            staged_terminal = _fd_call(descriptor, os.fstat)
            if (
                not stat.S_ISREG(staged_terminal.st_mode)
                or stat.S_IMODE(staged_terminal.st_mode) != 0o600
                or staged_terminal.st_nlink != 1
                or staged_terminal.st_size != len(publication_payload)
                or _stat_identity(staged_terminal) != _stat_identity(after)
            ):
                raise AuditError(
                    "atomic ledger record terminal staged identity drift"
                )
            try:
                _fd_at(scratch_fd, os.stat, staging_name, follow_symlinks=False)
            except FileNotFoundError:
                pass
            else:
                raise AuditError(
                    "atomic ledger record terminal source reappeared"
                )
            terminal_payload, terminal_observed = transaction.read_bytes_at(
                records_fd,
                final_name,
                maximum=len(publication_payload),
                expected_mode=0o600,
            )
            if (
                _stat_identity(terminal_observed)
                != _stat_identity(staged_terminal)
                or terminal_observed.st_nlink != 1
                or len(terminal_payload) != len(publication_payload)
                or terminal_payload != publication_payload
            ):
                raise AuditError(
                    "atomic ledger record terminal payload drift"
                )
            acquisition = operation_kind == (
                "task-test-execution-lease-acquired"
            )
            with authority_lock:
                require_live_event(
                    grant_entry, "publishing", event_epoch
                )
                grant_entry.update({
                    "record": dict(record),
                    "publicationDigest": _sha256(publication_payload),
                    "publishedIdentity": (
                        _stat_identity(terminal_observed)
                        + (terminal_observed.st_size,)
                    ),
                    "finalName": final_name,
                    "sink": getattr(
                        transaction,
                        "_deferred_publication_receipt_sink", None,
                    ),
                    "acquisition": acquisition,
                    "state": "sealed",
                    "epoch": event_epoch + 1,
                })
        except BaseException:
            with authority_lock:
                if grant_entry.get("state") not in (
                    "quarantined", "revoked"
                ):
                    grant_entry["state"] = "aborted"
                    grant_entry["epoch"] += 1
            abandon(grant_entry)
            raise

    def abort_transaction(transaction: Any) -> None:
        abandoned: List[Mapping[str, Any]] = []
        with authority_lock:
            for event in publication_events.values():
                if (
                    event.get("transaction") is transaction
                    and event.get("state") in (
                        "publishing", "sealed", "delivering",
                        "receipt-registered",
                    )
                ):
                    event["state"] = "aborted"
                    event["epoch"] += 1
                    grants.pop(id(event["grant"]), None)
                    receipt = event.get("receipt")
                    if receipt is not None:
                        receipts.pop(id(receipt), None)
                    abandoned.append(event)
        for event in abandoned:
            abandon(event)

    def finish_transaction(transaction: Any) -> None:
        with authority_lock:
            matches = [
                candidate for candidate in publication_events.values()
                if candidate.get("transaction") is transaction
                and candidate.get("state") == "sealed"
            ]
            if not matches:
                return
            if len(matches) != 1:
                raise AuditError("atomic publication event lifecycle drift")
            event = matches[0]
            event["state"] = "delivering"
            event["epoch"] += 1
            delivery_epoch = event["epoch"]
        grant_entry = event
        receipt = None
        sink = event.get("sink")
        try:
            if (
                event.get("state") != "delivering"
                or transaction._locked
                or transaction._fds
            ):
                raise AuditError("atomic publication event lifecycle drift")
            guard = event["guard"]
            private_token = event["privateToken"]
            scope = event["scope"]
            authentic_guard(guard, private_token, scope["root"])
            records_fd = record_fd = None
            reopen_error: Optional[BaseException] = None
            close_error: Optional[BaseException] = None
            try:
                records_fd = _open_owned_at(guard._ledger_fd, "records", _DIRECTORY_OPEN_FLAGS)
                records_observed = _fd_call(records_fd, os.fstat)
                records_visible = _fd_at(guard._ledger_fd, os.stat, "records", follow_symlinks=False)
                if (
                    not stat.S_ISDIR(records_observed.st_mode)
                    or stat.S_IMODE(records_observed.st_mode) != 0o700
                    or _directory_identity(records_visible)
                    != _directory_identity(records_observed)
                ):
                    raise AuditError(
                        "task test execution publication event inode drift"
                    )
                record_fd = _open_owned_at(records_fd, event["finalName"], os.O_RDONLY
                    | getattr(os, "O_NOFOLLOW", 0)
                    | getattr(os, "O_CLOEXEC", 0))
                before = _fd_call(record_fd, os.fstat)
                visible = _fd_at(records_fd, os.stat, event["finalName"], follow_symlinks=False)
                if (
                    _stat_identity(before) + (before.st_size,)
                    != event["publishedIdentity"]
                    or _stat_identity(visible) != _stat_identity(before)
                    or visible.st_size != before.st_size
                ):
                    raise AuditError(
                        "task test execution publication event inode drift"
                    )
                _fd_call(record_fd, os.lseek, 0, os.SEEK_SET)
                chunks: List[bytes] = []
                total = 0
                while True:
                    chunk = _fd_call(record_fd, os.read, min(65536, MAX_JSON_BYTES + 1 - total))
                    if not chunk:
                        break
                    chunks.append(chunk)
                    total += len(chunk)
                    if total > MAX_JSON_BYTES:
                        raise AuditError(
                            "task test execution publication event drift"
                        )
                after = _fd_call(record_fd, os.fstat)
                visible_after = _fd_at(records_fd, os.stat, event["finalName"], follow_symlinks=False)
                exact_bytes = b"".join(chunks)
                if (
                    _stat_identity(after) + (after.st_size,)
                    != event["publishedIdentity"]
                    or _stat_identity(visible_after)
                    != _stat_identity(after)
                    or visible_after.st_size != after.st_size
                    or _sha256(exact_bytes) != event["publicationDigest"]
                    or exact_bytes
                    != canonical_json_bytes(event["record"])
                ):
                    raise AuditError(
                        "task test execution publication event inode drift"
                    )
            except BaseException as exc:
                reopen_error = AuditError(
                    "task test execution publication event inode drift"
                )
                reopen_error.__cause__ = exc
            finally:
                close_error = close_descriptors_independently(
                    (record_fd, records_fd)
                )
            if reopen_error is not None:
                if close_error is not None:
                    _retain_git_cleanup_error(reopen_error, close_error)
                raise reopen_error
            if close_error is not None:
                raise close_error
            guard.revalidate()
            require_live_event(event, "delivering", delivery_epoch)
            if not event["acquisition"]:
                with authority_lock:
                    require_live_event(
                        event, "delivering", delivery_epoch
                    )
                    event["state"] = "consumed"
                    event["epoch"] += 1
                return
            if sink is None:
                with authority_lock:
                    require_live_event(
                        event, "delivering", delivery_epoch
                    )
                    event["state"] = "aborted"
                    event["epoch"] += 1
                abandon(grant_entry)
                return
            if not isinstance(sink, list) or list.__len__(sink) != 0:
                raise AuditError("publication receipt sink drift")
            receipt = PublicationReceipt()
            append_error: Optional[BaseException] = None
            try:
                sink.append(receipt)
            except BaseException as exc:
                append_error = exc
            stored = (
                list.__len__(sink) == 1
                and list.__getitem__(sink, 0) is receipt
            )
            if append_error is not None:
                raise append_error
            if (
                not stored
            ):
                raise AuditError("publication receipt sink drift")
            with authority_lock:
                require_live_event(event, "delivering", delivery_epoch)
                event["receipt"] = receipt
                event["state"] = "receipt-registered"
                event["epoch"] += 1
                receipts[id(receipt)] = event
        except BaseException:
            if receipt is not None and isinstance(sink, list):
                try:
                    for index in range(list.__len__(sink) - 1, -1, -1):
                        if list.__getitem__(sink, index) is receipt:
                            list.__delitem__(sink, index)
                except BaseException:
                    pass
            if receipt is not None:
                with authority_lock:
                    receipts.pop(id(receipt), None)
            with authority_lock:
                if event.get("state") != "quarantined":
                    event["state"] = "aborted"
                    event["epoch"] += 1
            abandon(grant_entry)
            raise

    def abandon_receipt(entry: Mapping[str, Any]) -> None:
        guard = entry["guard"]
        private_token = entry["privateToken"]
        scope = entry["scope"]
        pending_identity = scope.get("pendingAcquisitionIdentity")
        if pending_identity is not None:
            guard._revoke_pending_acquisition(
                private_token, pending_identity
            )

    def consume_receipt(
        value: Any,
        guard: Any,
        private_token: Any,
        root: Path,
        record: Mapping[str, Any],
    ) -> Any:
        if type(value) is not PublicationReceipt:
            raise AuditError(
                "task test execution dead owner durable acquired record "
                "publication receipt is required"
            )
        with authority_lock:
            entry = receipts.pop(id(value), None)
            if (
                entry is None
                or entry.get("receipt") is not value
                or entry.get("state") != "receipt-registered"
            ):
                raise AuditError(
                    "task test execution acquisition publication receipt "
                    "was replayed"
                )
            entry["state"] = "consumed"
            entry["epoch"] += 1
        expected_guard = entry["guard"]
        expected_token = entry["privateToken"]
        scope = entry["scope"]
        expected_digest = entry["publicationDigest"]
        expected_identity = entry["publishedIdentity"]
        pending_identity = scope.get("pendingAcquisitionIdentity")
        try:
            authentic_guard(guard, private_token, Path(root))
            if (
                guard is not expected_guard
                or private_token is not expected_token
                or scope.get("root")
                != _absolute_path_without_symlink_resolution(Path(root))
                or scope.get("operationKind")
                != "task-test-execution-lease-acquired"
                or pending_identity is None
                or not isinstance(record, Mapping)
                or _sha256(canonical_json_bytes(record)) != expected_digest
            ):
                raise AuditError(
                    "task test execution acquisition publication receipt "
                    "drift"
                )
            sequence = record.get("sequence")
            if type(sequence) is not int or sequence < 1:
                raise AuditError(
                    "task test execution acquisition publication receipt "
                    "drift"
                )
            final_name = "%016d.json" % sequence
            records_fd = record_fd = None
            reopen_error: Optional[BaseException] = None
            close_error: Optional[BaseException] = None
            try:
                records_fd = _open_owned_at(guard._ledger_fd, "records", _DIRECTORY_OPEN_FLAGS)
                records_observed = _fd_call(records_fd, os.fstat)
                records_visible = _fd_at(guard._ledger_fd, os.stat, "records", follow_symlinks=False)
                if (
                    not stat.S_ISDIR(records_observed.st_mode)
                    or stat.S_IMODE(records_observed.st_mode) != 0o700
                    or _directory_identity(records_visible)
                    != _directory_identity(records_observed)
                ):
                    raise AuditError(
                        "task test execution acquisition publication "
                        "receipt inode drift"
                    )
                record_fd = _open_owned_at(records_fd, final_name, os.O_RDONLY
                    | getattr(os, "O_NOFOLLOW", 0)
                    | getattr(os, "O_CLOEXEC", 0))
                before = _fd_call(record_fd, os.fstat)
                visible = _fd_at(records_fd, os.stat, final_name, follow_symlinks=False)
                physical_identity = _stat_identity(before) + (
                    before.st_size,
                )
                if (
                    physical_identity != expected_identity
                    or _stat_identity(visible) != _stat_identity(before)
                    or visible.st_size != before.st_size
                ):
                    raise AuditError(
                        "task test execution acquisition publication "
                        "receipt inode drift"
                    )
                _fd_call(record_fd, os.lseek, 0, os.SEEK_SET)
                chunks: List[bytes] = []
                total = 0
                while True:
                    chunk = _fd_call(record_fd, os.read, min(65536, MAX_JSON_BYTES + 1 - total))
                    if not chunk:
                        break
                    chunks.append(chunk)
                    total += len(chunk)
                    if total > MAX_JSON_BYTES:
                        raise AuditError(
                            "task test execution acquisition publication "
                            "receipt drift"
                        )
                after = _fd_call(record_fd, os.fstat)
                visible_after = _fd_at(records_fd, os.stat, final_name, follow_symlinks=False)
                if (
                    _stat_identity(after) + (after.st_size,)
                    != expected_identity
                    or _stat_identity(visible_after)
                    != _stat_identity(after)
                    or visible_after.st_size != after.st_size
                    or b"".join(chunks) != canonical_json_bytes(record)
                ):
                    raise AuditError(
                        "task test execution acquisition publication "
                        "receipt inode drift"
                    )
            except BaseException as exc:
                reopen_error = AuditError(
                    "task test execution acquisition publication receipt "
                    "inode drift"
                )
                reopen_error.__cause__ = exc
            finally:
                close_error = close_descriptors_independently(
                    (record_fd, records_fd)
                )
            if reopen_error is not None:
                if close_error is not None:
                    _retain_git_cleanup_error(reopen_error, close_error)
                raise reopen_error
            if close_error is not None:
                raise close_error
            guard.revalidate()
        except BaseException:
            abandon_receipt(entry)
            raise
        return pending_identity

    def revoke_receipt(value: Any) -> None:
        if type(value) is PublicationReceipt:
            entry = None
            with authority_lock:
                candidate = receipts.get(id(value))
                if (
                    candidate is not None
                    and candidate.get("receipt") is value
                    and candidate.get("state") == "receipt-registered"
                ):
                    entry = candidate
                    receipts.pop(id(value), None)
                    entry["state"] = "revoked"
                    entry["epoch"] += 1
            if entry is not None:
                abandon_receipt(entry)

    def transition_guard(
        guard: Any, *, quarantine: bool
    ) -> List[Mapping[str, Any]]:
        abandoned: List[Mapping[str, Any]] = []
        with authority_lock:
            if quarantine:
                guard._quarantined = True
            for key, event in tuple(publication_events.items()):
                if event.get("guard") is not guard:
                    continue
                grants.pop(id(event["grant"]), None)
                receipt = event.get("receipt")
                if receipt is not None:
                    receipts.pop(id(receipt), None)
                if event.get("state") not in (
                    "consumed", "revoked", "aborted", "quarantined"
                ):
                    event["state"] = (
                        "quarantined"
                        if getattr(guard, "_quarantined", False)
                        else "revoked"
                    )
                    event["epoch"] += 1
                    abandoned.append(event)
                if event.get("state") in (
                    "consumed", "revoked", "aborted"
                ):
                    publication_events.pop(key, None)
        return abandoned

    def revoke_guard(guard: Any) -> None:
        abandoned = transition_guard(guard, quarantine=False)
        for event in abandoned:
            abandon(event)

    def quarantine_guard(guard: Any) -> None:
        abandoned = transition_guard(guard, quarantine=True)
        for event in abandoned:
            abandon(event)

    def reset_after_fork_child() -> None:
        """Discard inherited in-memory authority without entering old locks."""

        nonlocal authority_lock
        nonlocal grants
        nonlocal receipts
        nonlocal publication_events
        nonlocal writer_preparations
        authority_lock = threading.RLock()
        grants = {}
        receipts = {}
        publication_events = {}
        writer_preparations = {}

    return (
        issue, resolve, consume, revoke, publish_staged_once,
        abort_transaction, finish_transaction, consume_receipt,
        revoke_receipt, revoke_guard, quarantine_guard,
        owns_writer_preparation,
        prepare_writer_once,
        validate_reserved_recovery_authority,
        reset_after_fork_child,
    )


(
    _issue_task_test_execution_append_capability,
    _resolve_task_test_execution_append_capability,
    _consume_task_test_execution_append_capability,
    _revoke_task_test_execution_append_capability,
    _publish_task_test_execution_staged_once,
    _abort_task_test_execution_publication_transaction,
    _finish_task_test_execution_publication_transaction,
    _consume_task_test_execution_publication_receipt,
    _revoke_task_test_execution_publication_receipt,
    _revoke_task_test_execution_guard_capabilities,
    _quarantine_task_test_execution_guard_capabilities,
    _owns_task_test_execution_atomic_writer_preparation,
    _prepare_task_test_execution_atomic_writer_once,
    _validate_task_test_execution_reserved_recovery_authority,
    _reset_task_test_execution_authority_after_fork_child,
) = _make_task_test_execution_append_capability_authority()


def _owns_task_test_execution_append_capability(function: Any) -> Any:
    """Make one capability-taking entry own idempotent revocation."""

    def owned_entry(*args: Any, **kwargs: Any) -> Any:
        try:
            return function(*args, **kwargs)
        finally:
            _revoke_task_test_execution_append_capability(
                kwargs.get("_execution_append_capability")
            )
            for candidate in args:
                _revoke_task_test_execution_append_capability(candidate)

    owned_entry.__name__ = function.__name__
    owned_entry.__qualname__ = function.__qualname__
    owned_entry.__doc__ = function.__doc__
    owned_entry.__signature__ = inspect.signature(function)
    return owned_entry


def _task_test_execution_authority_record_reserved(
    operation_kind: str,
    payload: Mapping[str, Any],
) -> bool:
    """Classify the execution-authority records reserved to held guards."""

    if operation_kind in (
        "task-test-execution-lease-acquired",
        "task-test-execution-lease-terminal",
    ):
        return True
    if not isinstance(payload, Mapping):
        return False
    if operation_kind == "task-test-attempt-started":
        subject = payload.get("subject")
        return (
            isinstance(subject, Mapping)
            and subject.get("schemaVersion") in ("qinao.task-test-subject.v3", "qinao.task-test-subject.v4")
        ) or "executionLeaseAcquiredRecordDigest" in payload
    if operation_kind == "task-test-attempt-terminal":
        result = payload.get("result")
        return (
            isinstance(result, Mapping)
            and result.get("schemaVersion") in ("qinao.task-test-result.v3", "qinao.task-test-result.v4")
        ) or any(field in payload for field in (
            "terminalAuthority", "executionLeaseAcquiredRecordDigest",
        ))
    return False


def _require_task_test_execution_append_capability(
    root: Path,
    operation_kind: str,
    payload: Mapping[str, Any],
    capability: Any,
    pre_rename_validator: Optional[Any],
) -> Optional[Any]:
    """Resolve one live guard-bound capability for a reserved append."""

    if not _task_test_execution_authority_record_reserved(
        operation_kind, payload
    ):
        return None
    resolved = _resolve_task_test_execution_append_capability(capability)
    if resolved is None or not callable(pre_rename_validator):
        raise AuditError(
            "live execution lease guard capability is required"
        )
    guard, scope = resolved
    guard._validate_internal_append_capability(
        capability,
        _absolute_path_without_symlink_resolution(Path(root)),
        operation_kind,
        payload,
        scope,
    )
    return guard


_LEDGER_TRANSACTION_OWNERS_LOCK = threading.RLock()
_LEDGER_TRANSACTION_OWNERS: Dict[int, Any] = {}
# Keep every uncertain generation, including multiple entrants at one path.
_LEDGER_TRANSACTION_QUARANTINE: Dict["LedgerTransaction", "LedgerTransaction"] = {}
_LEDGER_TRANSACTION_FORK_MUST_EXIT = True
_LEDGER_TRANSACTION_FORK_ACQUISITION: Any = None


def _ledger_transaction_before_fork() -> bool:
    global _LEDGER_TRANSACTION_FORK_MUST_EXIT
    global _LEDGER_TRANSACTION_FORK_ACQUISITION
    _LEDGER_TRANSACTION_FORK_MUST_EXIT = True
    if _LEDGER_TRANSACTION_FORK_ACQUISITION is not None:
        raise AuditError("ledger fork lock settlement is pending")
    _LEDGER_TRANSACTION_FORK_ACQUISITION = _ForkLockAcquisition(
        _LEDGER_TRANSACTION_OWNERS_LOCK
    )
    _LEDGER_TRANSACTION_FORK_ACQUISITION.acquire()
    _LEDGER_TRANSACTION_FORK_MUST_EXIT = bool(
        _LEDGER_TRANSACTION_OWNERS or _LEDGER_TRANSACTION_QUARANTINE
    )
    return _LEDGER_TRANSACTION_FORK_MUST_EXIT


def _ledger_transaction_after_fork_parent() -> None:
    global _LEDGER_TRANSACTION_FORK_MUST_EXIT
    global _LEDGER_TRANSACTION_FORK_ACQUISITION
    _LEDGER_TRANSACTION_FORK_MUST_EXIT = True
    acquisition = _LEDGER_TRANSACTION_FORK_ACQUISITION
    if acquisition is not None:
        try:
            acquisition.settle()
        finally:
            if acquisition.settled:
                _LEDGER_TRANSACTION_FORK_ACQUISITION = None


def _ledger_transaction_after_fork_child() -> None:
    global _LEDGER_TRANSACTION_OWNERS_LOCK
    global _LEDGER_TRANSACTION_FORK_MUST_EXIT
    global _LEDGER_TRANSACTION_FORK_ACQUISITION
    if _LEDGER_TRANSACTION_FORK_MUST_EXIT:
        os._exit(70)
    _LEDGER_TRANSACTION_FORK_MUST_EXIT = True
    _LEDGER_TRANSACTION_FORK_ACQUISITION = None
    _LEDGER_TRANSACTION_OWNERS_LOCK = threading.RLock()


class LedgerTransaction:
    """One retained-fd authority for a locked ledger transaction."""

    _DIRECTORIES = (
        "records", "captures", "resources", "resource-snapshots",
    )

    def __init__(
        self,
        root: Path,
        *,
        operation_kind: str,
        faults: Optional[DurabilityFaults] = None,
    ):
        if not isinstance(operation_kind, str) or not operation_kind:
            raise AuditError("ledger transaction operation drift")
        if faults is not None and not isinstance(faults, DurabilityFaults):
            raise AuditError("ledger transaction fault provider drift")
        self.root = _absolute_path_without_symlink_resolution(Path(root))
        self.operation_kind = operation_kind
        self.faults = faults or DurabilityFaults()
        self._fds: Dict[str, _ChildFdOwnerSlot] = {}
        self._member_arena = _FdAcquisitionArena()
        self._owned_slots = self._member_arena.slots
        self._directory_handoffs: List[_FdAcquisitionArena] = []
        self._identities: Dict[str, Tuple[int, ...]] = {}
        self._links: Dict[str, Tuple[_ChildFdOwnerSlot, str, Tuple[int, ...]]] = {}
        self._locked = False
        self._retained_counter = 0
        self._deferred_publication_receipt_sink: Optional[List[Any]] = None

    def _require_unquarantined(self) -> None:
        with _LEDGER_TRANSACTION_OWNERS_LOCK:
            lock_identity = self._identities.get("lock")
            if any(
                owner.root == self.root
                or (lock_identity is not None
                    and owner._identities.get("lock") == lock_identity)
                for owner in _LEDGER_TRANSACTION_QUARANTINE.values()
            ):
                raise AuditError("ledger transaction exclusion is quarantined")

    def _open_member_at(self, parent_fd: _ChildFdOwnerSlot, name: str,
                        flags: int, mode: int = 0o777) -> _ChildFdOwnerSlot:
        return _open_owned_at(parent_fd, name, flags, mode,
                              ownership_arena=self._member_arena)

    def _open_directory_at(self, parent_fd: _ChildFdOwnerSlot, name: str) -> _ChildFdOwnerSlot:
        if name in ("", ".", "..") or "/" in name or "\x00" in name:
            raise AuditError("unsafe ledger directory component")
        descriptor = self._open_member_at(parent_fd, name, _DIRECTORY_OPEN_FLAGS)
        observed = _fd_call(descriptor, os.fstat)
        if not stat.S_ISDIR(observed.st_mode):
            primary = AuditError("ledger transaction directory is not ordinary")
            _close_fd_slots([descriptor], primary)
            raise primary
        return descriptor

    def __enter__(self) -> "LedgerTransaction":
        try:
            with _LEDGER_TRANSACTION_OWNERS_LOCK:
                self._require_unquarantined()
                _LEDGER_TRANSACTION_OWNERS[id(self)] = self
            root_arena = _FdAcquisitionArena()
            self._directory_handoffs.append(root_arena)
            root_fd, absolute, root_observed = _open_directory_fd(
                self.root, ownership_arena=root_arena
            )
            if absolute != self.root:
                raise AuditError("run root canonical identity drift")
            self._fds["root"] = root_fd
            self._identities["root"] = _directory_identity(root_observed)
            if stat.S_IMODE(root_observed.st_mode) != 0o700:
                raise AuditError("run root mode drift")
            scratch_fd = self._open_directory_at(root_fd, "tmp")
            self._fds["scratch"] = scratch_fd
            scratch_observed = _fd_call(scratch_fd, os.fstat)
            if stat.S_IMODE(scratch_observed.st_mode) != 0o700:
                raise AuditError("run scratch mode drift")
            self._fds["scratch"] = scratch_fd
            self._identities["scratch"] = _directory_identity(
                scratch_observed
            )
            self._links["scratch"] = (
                root_fd, "tmp", self._identities["scratch"]
            )
            ledger_fd = self._open_directory_at(root_fd, "ledger")
            self._fds["ledger"] = ledger_fd
            self._identities["ledger"] = _directory_identity(_fd_call(ledger_fd, os.fstat))
            self._links["ledger"] = (
                root_fd, "ledger", self._identities["ledger"]
            )
            if stat.S_IMODE(_fd_call(ledger_fd, os.fstat).st_mode) != 0o700:
                raise AuditError("ledger mode drift")
            for name in self._DIRECTORIES:
                descriptor = self._open_directory_at(ledger_fd, name)
                self._fds[name] = descriptor
                self._identities[name] = _directory_identity(
                    _fd_call(descriptor, os.fstat)
                )
                self._links[name] = (
                    ledger_fd, name, self._identities[name]
                )
                if stat.S_IMODE(_fd_call(descriptor, os.fstat).st_mode) != 0o700:
                    raise AuditError("ledger directory mode drift: " + name)
            flags = (
                os.O_RDWR | getattr(os, "O_NOFOLLOW", 0)
                | getattr(os, "O_CLOEXEC", 0)
            )
            lock_fd = self._open_member_at(ledger_fd, "lock", flags)
            self._fds["lock"] = lock_fd
            lock_observed = _fd_call(lock_fd, os.fstat)
            visible_lock = _fd_at(ledger_fd, os.stat, "lock", follow_symlinks=False)
            if (
                not stat.S_ISREG(lock_observed.st_mode)
                or stat.S_IMODE(lock_observed.st_mode) != 0o600
                or lock_observed.st_nlink != 1
                or _stat_identity(lock_observed) != _stat_identity(visible_lock)
            ):
                raise AuditError("ledger lock identity drift")
            self._fds["lock"] = lock_fd
            self._identities["lock"] = _stat_identity(lock_observed)
            while True:
                self._require_unquarantined()
                try:
                    _fd_call(lock_fd, fcntl.flock, fcntl.LOCK_EX | fcntl.LOCK_NB)
                    break
                except OSError as exc:
                    if exc.errno not in (errno.EACCES, errno.EAGAIN):
                        raise
                    time.sleep(0.01)
            self._locked = True
            self.revalidate()
            return self
        except BaseException as primary:
            self._close_without_faults(primary)
            raise

    def identity_projection(self) -> Dict[str, Any]:
        if not self._fds:
            raise AuditError("ledger transaction is not open")
        return {
            name: {
                "device": identity[0],
                "inode": identity[1],
                "mode": identity[2],
                "linkCount": identity[3] if len(identity) == 4 else None,
            }
            for name, identity in sorted(self._identities.items())
        }

    def revalidate(self) -> None:
        if not self._fds or not self._locked:
            raise AuditError("ledger transaction is not locked")
        root_handoff = _FdAcquisitionArena()
        self._directory_handoffs.append(root_handoff)
        try:
            root_fd, absolute, observed = _open_directory_fd(
                self.root, ownership_arena=root_handoff
            )
        except (AuditError, OSError) as exc:
            raise AuditError("run root identity drift") from exc
        primary: Optional[BaseException] = None
        try:
            if (
                absolute != self.root
                or _directory_identity(observed) != self._identities["root"]
            ):
                raise AuditError("run root identity drift")
            ledger_fd = self._open_directory_at(root_fd, "ledger")
            ledger_primary: Optional[BaseException] = None
            try:
                if (
                    _directory_identity(_fd_call(ledger_fd, os.fstat))
                    != self._identities["ledger"]
                ):
                    raise AuditError("ledger identity drift")
                visible_lock = _fd_at(ledger_fd, os.stat, "lock", follow_symlinks=False)
                if _stat_identity(visible_lock) != self._identities["lock"]:
                    raise AuditError("ledger lock identity drift")
            except BaseException as exc:
                ledger_primary = exc
                raise
            finally:
                _close_fd_slots([ledger_fd], ledger_primary)
        except BaseException as exc:
            primary = exc
            raise
        finally:
            _close_fd_slots([root_fd], primary)
        for name, descriptor in self._fds.items():
            if name == "root":
                continue
            observed_identity = (
                _stat_identity(_fd_call(descriptor, os.fstat))
                if name == "lock"
                else _directory_identity(_fd_call(descriptor, os.fstat))
            )
            if observed_identity != self._identities[name]:
                raise AuditError("retained ledger identity drift: " + name)

        for name, (parent_fd, component, identity) in self._links.items():
            try:
                visible = _fd_at(parent_fd, os.stat, component, follow_symlinks=False)
            except OSError as exc:
                raise AuditError(
                    "retained ledger link drift: " + name
                ) from exc
            if (
                not stat.S_ISDIR(visible.st_mode)
                or _directory_identity(visible) != identity
            ):
                raise AuditError("retained ledger link drift: " + name)

    def recover(
        self, *, allow_resource_drift_id: Optional[str] = None
    ) -> Dict[str, Any]:
        self.revalidate()
        try:
            state = _recover_complete_state_fd(
                self,
                allow_resource_drift_id=allow_resource_drift_id,
            )
        except (AuditError, OSError, ValueError, KeyError, TypeError) as exc:
            raise AuditError("ledger is indeterminate") from exc
        self.faults.hit(
            "recovery-complete", self.operation_kind, "ledger"
        )
        self.revalidate()
        return state

    def directory_fd(self, name: str) -> _ChildFdOwnerSlot:
        descriptor = self._fds.get(name)
        if descriptor is None or name not in self._DIRECTORIES:
            raise AuditError("unknown retained ledger directory")
        return descriptor

    def ledger_fd(self) -> _ChildFdOwnerSlot:
        self.revalidate()
        descriptor = self._fds.get("ledger")
        if descriptor is None:
            raise AuditError("retained ledger anchor is absent")
        return descriptor

    @staticmethod
    def _safe_relative_name(name: Any) -> str:
        if (
            not isinstance(name, str)
            or name in ("", ".", "..")
            or "/" in name
            or "\x00" in name
            or os.fsdecode(os.fsencode(name)) != name
        ):
            raise AuditError("unsafe retained directory member name")
        return name

    def list_directory(
        self, descriptor: _ChildFdOwnerSlot, *, maximum: int = MAX_RESOURCE_ENTRIES
    ) -> List[str]:
        if not isinstance(maximum, int) or maximum < 0:
            raise AuditError("directory listing bound drift")
        self.revalidate()
        names = _fd_call(descriptor, os.listdir)
        if len(names) > maximum:
            raise AuditError("directory entry count exceeds bound")
        result = [self._safe_relative_name(name) for name in names]
        if len(result) != len(set(os.fsencode(name) for name in result)):
            raise AuditError("directory member name collision")
        self.revalidate()
        return sorted(result, key=os.fsencode)

    def read_bytes_at(
        self,
        parent_fd: _ChildFdOwnerSlot,
        name: str,
        *,
        maximum: int = MAX_JSON_BYTES,
        expected_mode: Optional[int] = 0o600,
        fsync_file: bool = False,
    ) -> Tuple[bytes, os.stat_result]:
        name = self._safe_relative_name(name)
        if not isinstance(maximum, int) or maximum < 0:
            raise AuditError("retained read bound drift")
        flags = (
            os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_CLOEXEC", 0)
        )
        self.revalidate()
        try:
            descriptor = self._open_member_at(parent_fd, name, flags)
        except OSError as exc:
            raise AuditError(
                "retained member is not an ordinary file"
            ) from exc
        primary: Optional[BaseException] = None
        try:
            before = _fd_call(descriptor, os.fstat)
            visible = _fd_at(parent_fd, os.stat, name, follow_symlinks=False)
            if not stat.S_ISREG(before.st_mode):
                raise AuditError("retained member is not an ordinary file")
            if before.st_nlink != 1:
                raise AuditError("retained member hard link drift")
            if (
                _stat_identity(before) != _stat_identity(visible)
                or (
                    expected_mode is not None
                    and stat.S_IMODE(before.st_mode) != expected_mode
                )
            ):
                raise AuditError("retained member identity drift")
            if before.st_size > maximum:
                raise AuditError("retained member exceeds bound")
            chunks: List[bytes] = []
            total = 0
            while True:
                chunk = _fd_call(descriptor, os.read, min(1024 * 1024, maximum + 1 - total))
                if not chunk:
                    break
                chunks.append(chunk)
                total += len(chunk)
                if total > maximum:
                    raise AuditError("retained member exceeds bound")
            if fsync_file:
                _fd_call(descriptor, os.fsync)
                self.faults.hit(
                    "member-read-fsync", self.operation_kind, name
                )
            after = _fd_call(descriptor, os.fstat)
            visible_after = _fd_at(parent_fd, os.stat, name, follow_symlinks=False)
            stable = lambda value: (
                value.st_dev, value.st_ino, value.st_mode, value.st_nlink,
                value.st_size, value.st_mtime_ns,
            )
            if (
                stable(before) != stable(after)
                or stable(before) != stable(visible_after)
                or total != before.st_size
            ):
                raise AuditError("retained member changed during read")
            payload = b"".join(chunks)
        except BaseException as exc:
            primary = exc
            raise
        finally:
            _close_fd_slots([descriptor], primary)
        self.revalidate()
        return payload, before

    def read_canonical_at(
        self, parent_fd: _ChildFdOwnerSlot, name: str
    ) -> Dict[str, Any]:
        payload, _observed = self.read_bytes_at(parent_fd, name)
        value = parse_canonical_json(payload)
        if not isinstance(value, dict):
            raise AuditError("canonical retained member is not an object")
        return value

    def _retain_directory(
        self, descriptor: _ChildFdOwnerSlot, label: str, parent_fd: _ChildFdOwnerSlot, name: str
    ) -> _ChildFdOwnerSlot:
        self._retained_counter += 1
        key = "retained:%08d:%s" % (self._retained_counter, label)
        self._fds[key] = descriptor
        self._identities[key] = _directory_identity(
            _fd_call(descriptor, os.fstat)
        )
        self._links[key] = (
            parent_fd, name, self._identities[key]
        )
        return descriptor

    def open_directory_at(
        self,
        parent_fd: _ChildFdOwnerSlot,
        name: str,
        *,
        expected_mode: Optional[int] = 0o700,
    ) -> _ChildFdOwnerSlot:
        descriptor = self._open_directory_at(parent_fd, name)
        try:
            observed = _fd_call(descriptor, os.fstat)
            visible = _fd_at(parent_fd, os.stat, name, follow_symlinks=False)
            if (
                (
                    expected_mode is not None
                    and stat.S_IMODE(observed.st_mode) != expected_mode
                )
                or observed.st_nlink < 2
                or _stat_identity(observed) != _stat_identity(visible)
            ):
                raise AuditError("retained ledger generation drift")
            self._retain_directory(descriptor, name, parent_fd, name)
            self.revalidate()
            return descriptor
        except BaseException as primary:
            retained_key = next(
                (
                    key for key, value in self._fds.items()
                    if value is descriptor and key.startswith("retained:")
                ),
                None,
            )
            if retained_key is not None:
                self._fds.pop(retained_key, None)
                self._identities.pop(retained_key, None)
                self._links.pop(retained_key, None)
            _close_fd_slots([descriptor], primary)
            raise

    def ensure_directory_at(self, parent_fd: _ChildFdOwnerSlot, name: str) -> _ChildFdOwnerSlot:
        if not isinstance(parent_fd, _ChildFdOwnerSlot):
            raise AuditError("ledger directory parent descriptor drift")
        if name in ("", ".", "..") or "/" in name or "\x00" in name:
            raise AuditError("unsafe ledger generation component")
        created = False
        try:
            _fd_at(parent_fd, os.mkdir, name, 0o700)
            created = True
        except FileExistsError:
            pass
        descriptor = self._open_directory_at(parent_fd, name)
        try:
            if created:
                descriptor.chmod(0o700)
            observed = _fd_call(descriptor, os.fstat)
            visible = _fd_at(parent_fd, os.stat, name, follow_symlinks=False)
            if (
                stat.S_IMODE(observed.st_mode) != 0o700
                or observed.st_nlink < 2
                or _stat_identity(observed) != _stat_identity(visible)
            ):
                raise AuditError("ledger generation directory drift")
            _fd_call(descriptor, os.fsync)
            self.faults.hit(
                "directory-fsync", self.operation_kind, name
            )
            _fd_call(parent_fd, os.fsync)
            self.faults.hit(
                "directory-parent-fsync", self.operation_kind, name
            )
            self._retain_directory(descriptor, name, parent_fd, name)
            self.revalidate()
            return descriptor
        except BaseException as primary:
            retained_key = next(
                (
                    key for key, value in self._fds.items()
                    if value is descriptor and key.startswith("retained:")
                ),
                None,
            )
            if retained_key is not None:
                self._fds.pop(retained_key, None)
                self._identities.pop(retained_key, None)
                self._links.pop(retained_key, None)
            _close_fd_slots([descriptor], primary)
            raise

    def create_directory_at(self, parent_fd: _ChildFdOwnerSlot, name: str) -> _ChildFdOwnerSlot:
        if not isinstance(parent_fd, _ChildFdOwnerSlot):
            raise AuditError("ledger generation parent descriptor drift")
        if name in ("", ".", "..") or "/" in name or "\x00" in name:
            raise AuditError("unsafe ledger generation name")
        _fd_at(parent_fd, os.mkdir, name, 0o700)
        descriptor = self._open_directory_at(parent_fd, name)
        try:
            descriptor.chmod(0o700)
            observed = _fd_call(descriptor, os.fstat)
            visible = _fd_at(parent_fd, os.stat, name, follow_symlinks=False)
            if (
                stat.S_IMODE(observed.st_mode) != 0o700
                or observed.st_nlink < 2
                or _stat_identity(observed) != _stat_identity(visible)
            ):
                raise AuditError("ledger generation publication drift")
            _fd_call(descriptor, os.fsync)
            self.faults.hit(
                "generation-fsync", self.operation_kind, name
            )
            _fd_call(parent_fd, os.fsync)
            self.faults.hit(
                "generation-parent-fsync", self.operation_kind, name
            )
            self._retain_directory(descriptor, name, parent_fd, name)
            self.revalidate()
            return descriptor
        except BaseException as primary:
            retained_key = next(
                (
                    key for key, value in self._fds.items()
                    if value is descriptor and key.startswith("retained:")
                ),
                None,
            )
            if retained_key is not None:
                self._fds.pop(retained_key, None)
                self._identities.pop(retained_key, None)
                self._links.pop(retained_key, None)
            _close_fd_slots([descriptor], primary)
            raise

    @_owns_task_test_execution_append_capability
    def write_bytes_at(
        self,
        parent_fd: _ChildFdOwnerSlot,
        name: str,
        payload: bytes,
        *,
        _pre_publication_validator: Optional[Any] = None,
        _execution_append_capability: Optional[Any] = None,
    ) -> None:
        if not isinstance(payload, bytes):
            raise AuditError("ledger member payload drift")
        if name in ("", ".", "..") or "/" in name or "\x00" in name:
            raise AuditError("unsafe ledger member name")
        self.revalidate()
        try:
            parent_observed = _fd_call(parent_fd, os.fstat)
        except OSError as exc:
            raise AuditError("ledger member parent descriptor drift") from exc
        if not stat.S_ISDIR(parent_observed.st_mode):
            raise AuditError("ledger member parent descriptor drift")
        records_directory = (
            _directory_identity(parent_observed)
            == self._identities.get("records")
        )
        reserved_record: Optional[Dict[str, Any]] = None
        if (
            records_directory
            and re.fullmatch(r"[0-9]{16}\.json", name) is not None
        ):
            try:
                candidate = parse_canonical_json(payload)
            except (AuditError, ValueError, TypeError):
                candidate = None
            if (
                isinstance(candidate, Mapping)
                and _task_test_execution_authority_record_reserved(
                    candidate.get("operationKind"), candidate
                )
            ):
                reserved_record = dict(candidate)
        if reserved_record is not None:
            try:
                _require_task_test_execution_append_capability(
                    self.root,
                    reserved_record.get("operationKind"),
                    reserved_record,
                    _execution_append_capability,
                    _pre_publication_validator,
                )
                raise AuditError(
                    "execution authority append requires atomic publication"
                )
            finally:
                _revoke_task_test_execution_append_capability(
                    _execution_append_capability
                )
        flags = (
            os.O_WRONLY | os.O_CREAT | os.O_EXCL
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_CLOEXEC", 0)
        )
        descriptor: Optional[_ChildFdOwnerSlot] = None
        primary: Optional[BaseException] = None
        try:
            descriptor = self._open_member_at(parent_fd, name, flags, 0o600)
            descriptor.chmod(0o600)
            created = _fd_call(descriptor, os.fstat)
            if (
                not stat.S_ISREG(created.st_mode)
                or stat.S_IMODE(created.st_mode) != 0o600
                or created.st_nlink != 1
            ):
                raise AuditError("ledger member publication drift")
            _write_owned_all(descriptor, payload)
            _fd_call(descriptor, os.fsync)
            self.faults.hit(
                "member-fsync", self.operation_kind, name
            )
            visible = _fd_at(parent_fd, os.stat, name, follow_symlinks=False)
            if (
                _stat_identity(visible) != _stat_identity(created)
                or visible.st_size != len(payload)
            ):
                raise AuditError("ledger member publication identity drift")
            _fd_call(parent_fd, os.fsync)
            self.faults.hit(
                "member-parent-fsync", self.operation_kind, name
            )
            self.revalidate()
        except BaseException as exc:
            primary = exc
            raise
        finally:
            if descriptor is not None:
                _close_fd_slots([descriptor], primary)

    def write_canonical_at(
        self, parent_fd: _ChildFdOwnerSlot, name: str, value: Any
    ) -> None:
        self.write_bytes_at(parent_fd, name, canonical_json_bytes(value))

    @_owns_task_test_execution_append_capability
    def append_record(
        self,
        recovered: Mapping[str, Any],
        operation_kind: str,
        input_digest: str,
        declared_filenames: Sequence[str],
        completion_state: str,
        payload: Mapping[str, Any],
        *,
        predecessor: Optional[Mapping[str, Any]] = None,
        atomic_publication: bool = False,
        _pre_rename_validator: Optional[Any] = None,
        _execution_append_capability: Optional[Any] = None,
        _publication_receipt_sink: Optional[List[Any]] = None,
    ) -> Dict[str, Any]:
        try:
            return self._append_record_with_execution_capability(
                recovered,
                operation_kind,
                input_digest,
                declared_filenames,
                completion_state,
                payload,
                predecessor=predecessor,
                atomic_publication=atomic_publication,
                _pre_rename_validator=_pre_rename_validator,
                _execution_append_capability=
                    _execution_append_capability,
                _publication_receipt_sink=_publication_receipt_sink,
            )
        finally:
            _revoke_task_test_execution_append_capability(
                _execution_append_capability
            )

    @_owns_task_test_execution_append_capability
    def _append_record_with_execution_capability(
        self,
        recovered: Mapping[str, Any],
        operation_kind: str,
        input_digest: str,
        declared_filenames: Sequence[str],
        completion_state: str,
        payload: Mapping[str, Any],
        *,
        predecessor: Optional[Mapping[str, Any]] = None,
        atomic_publication: bool = False,
        _pre_rename_validator: Optional[Any] = None,
        _execution_append_capability: Optional[Any] = None,
        _publication_receipt_sink: Optional[List[Any]] = None,
    ) -> Dict[str, Any]:
        if _publication_receipt_sink is not None and (
            not isinstance(_publication_receipt_sink, list)
            or _publication_receipt_sink
        ):
            raise AuditError("publication receipt sink drift")
        authority_guard = _require_task_test_execution_append_capability(
            self.root,
            operation_kind,
            payload,
            _execution_append_capability,
            _pre_rename_validator,
        )
        if authority_guard is not None and not atomic_publication:
            raise AuditError(
                "execution authority append requires atomic publication"
            )
        if predecessor is None:
            records = recovered.get("records")
            if not isinstance(records, list) or not records:
                raise AuditError("ledger append predecessor is absent")
            previous = records[-1]
            sequence = recovered.get("nextSequence")
        else:
            previous = _require_mapping(
                predecessor, "ledger append predecessor"
            )
            sequence = previous.get("sequence", 0) + 1
        if not isinstance(sequence, int) or sequence < 1:
            raise AuditError("ledger append sequence drift")
        record = _new_record(
            _require_mapping(recovered.get("identity"), "ledger identity"),
            sequence,
            previous["recordDigest"],
            operation_kind,
            input_digest,
            declared_filenames,
            completion_state,
            payload,
        )
        _validate_cleanup_publication(self, record)
        if operation_kind == "frontier-start" and record.get("frontierKind") == "task":
            baseline = _validate_task_start(record, recovered["identity"])
            if baseline != _observe_task_start(
                recovered["identity"], baseline["taskNumber"],
                record["declaredPaths"], record["expectedTests"],
            ):
                raise AuditError("fresh task append baseline drift")
        if operation_kind == "frontier-complete" and record.get("frontierKind") == "task":
            starts = [row for row in recovered["openFrontiers"]
                      if row["frontierId"] == record.get("frontierId")]
            supplied = record.get("taskCompletion")
            if len(starts) != 1 or not isinstance(supplied, Mapping):
                raise AuditError("fresh task completion contract absent")
            expected = _ordinary_task_completion(
                starts[0], recovered, supplied.get("resultCommitOid"),
                completion_sequence=sequence, live=True,
                task_correction_record_digest=supplied.get("taskCorrectionRecordDigest"),
            )
            if supplied != expected:
                raise AuditError("fresh task completion proof drift")
        effective_pre_rename_validator = _pre_rename_validator
        if authority_guard is not None:
            def validate_reserved_authority(
                staged: Mapping[str, Any]
            ) -> None:
                _require_task_test_execution_append_capability(
                    self.root,
                    operation_kind,
                    staged,
                    _execution_append_capability,
                    _pre_rename_validator,
                )
                _pre_rename_validator(staged)
                _require_task_test_execution_append_capability(
                    self.root,
                    operation_kind,
                    staged,
                    _execution_append_capability,
                    _pre_rename_validator,
                )

            effective_pre_rename_validator = validate_reserved_authority
        if atomic_publication:
            if self._deferred_publication_receipt_sink is not None:
                raise AuditError("publication receipt sink drift")
            self._deferred_publication_receipt_sink = (
                _publication_receipt_sink
            )
            try:
                self.write_record_atomic(
                    sequence,
                    record,
                    _pre_rename_validator=effective_pre_rename_validator,
                    _execution_append_capability=
                        _execution_append_capability,
                )
            finally:
                self._deferred_publication_receipt_sink = None
        else:
            if effective_pre_rename_validator is not None:
                raise AuditError(
                    "pre-rename validation requires atomic publication"
                )
            self.write_record(
                sequence,
                record,
                _execution_append_capability=
                    _execution_append_capability,
            )
        return record

    @_owns_task_test_execution_append_capability
    def write_record_atomic(
        self,
        sequence: int,
        record: Mapping[str, Any],
        *,
        _pre_rename_validator: Optional[Any] = None,
        _execution_append_capability: Optional[Any] = None,
    ) -> Any:
        """Own and revoke one raw-writer grant from function entry."""

        try:
            return self._write_record_atomic_with_execution_capability(
                sequence,
                record,
                _pre_rename_validator=_pre_rename_validator,
                _execution_append_capability=
                    _execution_append_capability,
            )
        finally:
            _revoke_task_test_execution_append_capability(
                _execution_append_capability
            )

    @_owns_task_test_execution_append_capability
    @_owns_task_test_execution_atomic_writer_preparation
    def _write_record_atomic_with_execution_capability(
        self,
        sequence: int,
        record: Mapping[str, Any],
        *,
        _pre_rename_validator: Optional[Any] = None,
        _execution_append_capability: Optional[Any] = None,
        _task_test_execution_writer_frame: Any = None,
    ) -> Any:
        """Publish one record from retained scratch and reopen exact bytes."""

        if not isinstance(sequence, int) or sequence < 1:
            raise AuditError("ledger record sequence drift")
        if not isinstance(record, Mapping):
            raise AuditError("ledger record publication shape drift")
        _validate_current_task_publication(self, record)
        _validate_policy_capture_publication(self, record)
        _validate_cleanup_publication(self, record)
        operation_kind = record.get("operationKind")
        reserved_authority = (
            _task_test_execution_authority_record_reserved(
                operation_kind, record
            )
        )
        if reserved_authority:
            _require_task_test_execution_append_capability(
                self.root,
                operation_kind,
                record,
                _execution_append_capability,
                _pre_rename_validator,
            )
        if _pre_rename_validator is not None and (
            self.operation_kind not in (
                "secret-scan-capture-allocation",
                "secret-scan-invocation-start",
                "secret-scan-terminal",
                "secret-scan-worktree",
                "task-test-execution-lease-acquired",
                "task-test-execution-lease-terminal",
                "task-test-attempt-start",
                "task-test-attempt-started",
                "task-test-attempt-terminal",
            )
            or not callable(_pre_rename_validator)
        ):
            raise AuditError("atomic pre-rename validator authority drift")
        final_name = "%016d.json" % sequence
        staging_name = (
            ".qinao-record-stage-%016d-%s.json"
            % (sequence, secrets.token_hex(8))
        )
        payload = canonical_json_bytes(record)
        flags = (
            os.O_RDWR | os.O_CREAT | os.O_EXCL
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_CLOEXEC", 0)
        )
        records_fd = self._fds["records"]
        scratch_fd = self._fds["scratch"]
        descriptor: Optional[_ChildFdOwnerSlot] = None
        published = False
        primary: Optional[BaseException] = None
        try:
            descriptor = self._open_member_at(scratch_fd, staging_name, flags, 0o600)
            descriptor.chmod(0o600)
            staged = _fd_call(descriptor, os.fstat)
            if (
                not stat.S_ISREG(staged.st_mode)
                or stat.S_IMODE(staged.st_mode) != 0o600
                or staged.st_nlink != 1
            ):
                raise AuditError("atomic ledger record staging drift")
            _write_owned_all(descriptor, payload)
            _fd_call(descriptor, os.fsync)
            self.faults.hit(
                "record-stage-fsync", self.operation_kind, final_name
            )
            if _fd_call(descriptor, os.fstat).st_size != len(payload):
                raise AuditError("atomic ledger record staging size drift")
            _fd_call(scratch_fd, os.fsync)
            self.faults.hit(
                "record-stage-parent-fsync", self.operation_kind,
                final_name,
            )
            _fd_call(descriptor, os.fsync)
            staged_before_read = _fd_call(descriptor, os.fstat)
            source_visible = _fd_at(scratch_fd, os.stat, staging_name, follow_symlinks=False)
            if (
                not stat.S_ISREG(staged_before_read.st_mode)
                or stat.S_IMODE(staged_before_read.st_mode) != 0o600
                or staged_before_read.st_nlink != 1
                or staged_before_read.st_size < 1
                or staged_before_read.st_size > MAX_JSON_BYTES
                or _stat_identity(source_visible)
                != _stat_identity(staged_before_read)
                or source_visible.st_size != staged_before_read.st_size
            ):
                raise AuditError("atomic ledger record source identity drift")
            _fd_call(descriptor, os.lseek, 0, os.SEEK_SET)
            chunks: List[bytes] = []
            total = 0
            while True:
                chunk = _fd_call(descriptor, os.read, min(1024 * 1024, MAX_JSON_BYTES + 1 - total))
                if not chunk:
                    break
                chunks.append(chunk)
                total += len(chunk)
                if total > MAX_JSON_BYTES:
                    raise AuditError(
                        "atomic ledger record staged bytes exceed bound"
                    )
            publication_payload = b"".join(chunks)
            staged_after = _fd_call(descriptor, os.fstat)
            source_visible_after = _fd_at(scratch_fd, os.stat, staging_name, follow_symlinks=False)
            stable = lambda value: (
                value.st_dev, value.st_ino, value.st_mode,
                value.st_nlink, value.st_size, value.st_mtime_ns,
                value.st_ctime_ns,
            )
            if (
                stable(staged_before_read) != stable(staged_after)
                or stable(staged_before_read) != stable(source_visible_after)
                or total != staged_before_read.st_size
            ):
                raise AuditError(
                    "atomic ledger record changed during staged read"
                )
            publication_record = parse_canonical_json(publication_payload)
            if not isinstance(publication_record, Mapping):
                raise AuditError("atomic ledger record publication shape drift")
            publication_operation_kind = publication_record.get(
                "operationKind"
            )
            publication_reserved_authority = (
                _task_test_execution_authority_record_reserved(
                    publication_operation_kind, publication_record
                )
            )
            if (
                publication_operation_kind != operation_kind
                or publication_reserved_authority is not reserved_authority
            ):
                raise AuditError(
                    "atomic execution authority reclassification drift"
                )
            library = ctypes.CDLL(None, use_errno=True)
            try:
                renameatx_np = library.renameatx_np
            except AttributeError as exc:
                raise AuditError("atomic record publication unavailable") from exc
            renameatx_np.argtypes = [
                ctypes.c_int, ctypes.c_char_p, ctypes.c_int,
                ctypes.c_char_p, ctypes.c_uint,
            ]
            renameatx_np.restype = ctypes.c_int
            if _pre_rename_validator is not None:
                _pre_rename_validator(publication_record)
            if operation_kind in ("task-resumption", "task-correction"):
                _validate_current_task_publication(self, publication_record)
            if publication_payload != payload:
                raise AuditError(
                    "atomic ledger record expected staged bytes drift"
                )
            post_validator_before = _fd_call(descriptor, os.fstat)
            post_validator_visible = _fd_at(scratch_fd, os.stat, staging_name, follow_symlinks=False)
            if (
                not stat.S_ISREG(post_validator_before.st_mode)
                or stat.S_IMODE(post_validator_before.st_mode) != 0o600
                or post_validator_before.st_nlink != 1
                or post_validator_before.st_size != len(publication_payload)
                or _stat_identity(post_validator_before)
                != _stat_identity(staged_after)
                or _stat_identity(post_validator_visible)
                != _stat_identity(post_validator_before)
                or post_validator_visible.st_size
                != post_validator_before.st_size
            ):
                raise AuditError(
                    "atomic ledger record changed after validation"
                )
            _fd_call(descriptor, os.lseek, 0, os.SEEK_SET)
            post_validator_chunks: List[bytes] = []
            post_validator_total = 0
            while True:
                chunk = _fd_call(descriptor, os.read, min(
                        1024 * 1024,
                        MAX_JSON_BYTES + 1 - post_validator_total,
                    ))
                if not chunk:
                    break
                post_validator_chunks.append(chunk)
                post_validator_total += len(chunk)
                if post_validator_total > MAX_JSON_BYTES:
                    raise AuditError(
                        "atomic ledger record changed after validation"
                    )
            post_validator_after = _fd_call(descriptor, os.fstat)
            post_validator_visible_after = _fd_at(scratch_fd, os.stat, staging_name, follow_symlinks=False)
            if (
                stable(post_validator_before)
                != stable(post_validator_after)
                or stable(post_validator_before)
                != stable(post_validator_visible_after)
                or post_validator_total != post_validator_before.st_size
                or b"".join(post_validator_chunks) != publication_payload
            ):
                raise AuditError(
                    "atomic ledger record changed after validation"
                )
            staged_after = post_validator_after
            if reserved_authority:
                _prepare_task_test_execution_atomic_writer_once(
                    _task_test_execution_writer_frame,
                    _execution_append_capability,
                    self,
                    descriptor,
                    staging_name,
                    final_name,
                    publication_payload,
                )
                _publish_task_test_execution_staged_once(
                    _execution_append_capability,
                    self,
                    descriptor,
                    staging_name,
                    final_name,
                    _task_test_execution_writer_frame,
                )
                published = True
                return None
            result = _fd_slots_operation(
                (scratch_fd, records_fd),
                lambda source, target: renameatx_np(
                    source, os.fsencode(staging_name),
                    target, os.fsencode(final_name), 0x00000004,
                ),
            )
            if result != 0:
                observed_errno = ctypes.get_errno()
                if observed_errno == errno.EEXIST:
                    raise FileExistsError(
                        errno.EEXIST, "ledger record already exists"
                    )
                raise OSError(observed_errno, os.strerror(observed_errno))
            published = True
            self.faults.hit(
                "record-atomic-publish", self.operation_kind, final_name
            )
            visible = _fd_at(records_fd, os.stat, final_name, follow_symlinks=False)
            if (
                not stat.S_ISREG(visible.st_mode)
                or stat.S_IMODE(visible.st_mode) != 0o600
                or visible.st_nlink != 1
                or visible.st_size != len(publication_payload)
                or _stat_identity(visible) != _stat_identity(staged_after)
            ):
                raise AuditError("atomic ledger record publication drift")
            reopened, reopened_observed = self.read_bytes_at(
                records_fd,
                final_name,
                maximum=len(publication_payload),
                expected_mode=0o600,
            )
            if (
                _stat_identity(reopened_observed)
                != _stat_identity(staged_after)
                or reopened != publication_payload
            ):
                raise AuditError("atomic ledger record payload drift")
            _fd_call(scratch_fd, os.fsync)
            self.faults.hit(
                "record-stage-source-fsync", self.operation_kind,
                final_name,
            )
            _fd_call(records_fd, os.fsync)
            self.faults.hit(
                "records-fsync", self.operation_kind, final_name
            )
            self.revalidate()
            staged_terminal = _fd_call(descriptor, os.fstat)
            if (
                not stat.S_ISREG(staged_terminal.st_mode)
                or stat.S_IMODE(staged_terminal.st_mode) != 0o600
                or staged_terminal.st_nlink != 1
                or staged_terminal.st_size != len(publication_payload)
                or _stat_identity(staged_terminal)
                != _stat_identity(staged_after)
            ):
                raise AuditError(
                    "atomic ledger record terminal staged identity drift"
                )
            try:
                _fd_at(scratch_fd, os.stat, staging_name, follow_symlinks=False)
            except FileNotFoundError:
                pass
            else:
                raise AuditError(
                    "atomic ledger record terminal source reappeared"
                )
            terminal_payload, terminal_observed = self.read_bytes_at(
                records_fd,
                final_name,
                maximum=len(publication_payload),
                expected_mode=0o600,
            )
            if (
                _stat_identity(terminal_observed)
                != _stat_identity(staged_terminal)
                or terminal_observed.st_nlink != 1
                or len(terminal_payload) != len(publication_payload)
                or terminal_payload != publication_payload
            ):
                raise AuditError(
                    "atomic ledger record terminal payload drift"
                )
        except BaseException as exc:
            primary = exc
            raise
        finally:
            if reserved_authority:
                _revoke_task_test_execution_append_capability(
                    _execution_append_capability
                )
            if descriptor is not None:
                _close_fd_slots([descriptor], primary)
            if not published:
                try:
                    _fd_at(scratch_fd, os.unlink, staging_name)
                except FileNotFoundError:
                    pass
                except BaseException as cleanup:
                    if primary is None:
                        raise
                    _retain_git_cleanup_error(primary, cleanup)
        return None

    @_owns_task_test_execution_append_capability
    def write_record(
        self,
        sequence: int,
        record: Mapping[str, Any],
        *,
        _pre_publication_validator: Optional[Any] = None,
        _execution_append_capability: Optional[Any] = None,
        _policy_capture_authority: Optional[Any] = None,
    ) -> None:
        if not isinstance(sequence, int) or sequence < 1:
            raise AuditError("ledger record sequence drift")
        if not isinstance(record, Mapping):
            raise AuditError("ledger record publication shape drift")
        _validate_current_task_publication(self, record)
        _validate_policy_capture_publication(self, record, _policy_capture_authority)
        if record.get("operationKind") in ("task-resumption", "task-correction"):
            raise AuditError("task continuation requires atomic publication")
        _validate_cleanup_publication(self, record)
        operation_kind = record.get("operationKind")
        if _task_test_execution_authority_record_reserved(
            operation_kind, record
        ):
            try:
                _require_task_test_execution_append_capability(
                    self.root,
                    operation_kind,
                    record,
                    _execution_append_capability,
                    _pre_publication_validator,
                )
                raise AuditError(
                    "execution authority append requires atomic publication"
                )
            finally:
                _revoke_task_test_execution_append_capability(
                    _execution_append_capability
                )
        name = "%016d.json" % sequence
        payload = canonical_json_bytes(record)
        flags = (
            os.O_WRONLY | os.O_CREAT | os.O_EXCL
            | getattr(os, "O_NOFOLLOW", 0)
            | getattr(os, "O_CLOEXEC", 0)
        )
        descriptor: Optional[_ChildFdOwnerSlot] = None
        primary: Optional[BaseException] = None
        try:
            descriptor = self._open_member_at(self._fds["records"], name, flags, 0o600)
            descriptor.chmod(0o600)
            created = _fd_call(descriptor, os.fstat)
            if not stat.S_ISREG(created.st_mode) or created.st_nlink != 1:
                raise AuditError("ledger record publication drift")
            _write_owned_all(descriptor, payload)
            _fd_call(descriptor, os.fsync)
            self.faults.hit("record-fsync", self.operation_kind, name)
            visible = _fd_at(self._fds["records"], os.stat, name, follow_symlinks=False)
            if (
                _stat_identity(visible) != _stat_identity(created)
                or visible.st_size != len(payload)
            ):
                raise AuditError("ledger record publication identity drift")
            _fd_call(self._fds["records"], os.fsync)
            self.faults.hit("records-fsync", self.operation_kind, name)
            self.revalidate()
        except BaseException as exc:
            primary = exc
            raise
        finally:
            if descriptor is not None:
                _close_fd_slots([descriptor], primary)

    def _settle_owned_slots(self, *, faults: bool,
                            primary: Optional[BaseException]) -> Optional[BaseException]:
        failure: Optional[BaseException] = None

        def retain(error: BaseException) -> None:
            nonlocal failure
            if failure is None:
                failure = error
            else:
                _retain_git_cleanup_error(failure, error)

        lock = self._fds.get("lock")
        owned_slots = self._owned_slots + [
            slot for handoff in self._directory_handoffs for slot in handoff.slots
        ]
        try:
            _close_fd_slots(
                slot for slot in reversed(owned_slots) if slot is not lock
            )
        except BaseException as cleanup:
            retain(cleanup)
        predecessors_closed = not any(
            arena.acquisition_uncertain
            for arena in (self._member_arena, *self._directory_handoffs)
        ) and all(
            slot is lock or slot.phase == "closed" for slot in owned_slots
        )
        if predecessors_closed:
            if self._locked:
                try:
                    _fd_call(lock, fcntl.flock, fcntl.LOCK_UN)
                    self._locked = False
                    if faults:
                        self.faults.hit("unlock", self.operation_kind)
                except BaseException as cleanup:
                    retain(cleanup)
            if not self._locked:
                try:
                    _close_fd_slots((lock,))
                except BaseException as cleanup:
                    retain(cleanup)
        detached = predecessors_closed and not self._locked and (
            lock is None or lock.phase == "closed"
        )
        if detached:
            self._fds.clear()
            self._owned_slots.clear()
            self._directory_handoffs.clear()
            self._identities.clear()
            self._links.clear()
            with _LEDGER_TRANSACTION_OWNERS_LOCK:
                _LEDGER_TRANSACTION_OWNERS.pop(id(self), None)
            if faults:
                try:
                    self.faults.hit("close", self.operation_kind)
                except BaseException as cleanup:
                    retain(cleanup)
        else:
            if failure is None:
                retain(AuditError("ledger descriptor settlement is uncertain"))
            # Still in the active registry: no clean-fork publication gap.
            with _LEDGER_TRANSACTION_OWNERS_LOCK:
                _LEDGER_TRANSACTION_QUARANTINE[self] = self
            self._settlement_failure = failure
        if primary is not None and failure is not None:
            _retain_git_cleanup_error(primary, failure)
        return failure

    def _close_without_faults(self, primary: Optional[BaseException] = None) -> None:
        _abort_task_test_execution_publication_transaction(self)
        failure = self._settle_owned_slots(faults=False, primary=primary)
        if primary is None and failure is not None:
            raise failure

    def __exit__(self, exc_type: Any, exc: Any, traceback: Any) -> bool:
        del exc_type, traceback
        cleanup_error = self._settle_owned_slots(faults=True, primary=exc)
        if exc is not None or cleanup_error is not None:
            _abort_task_test_execution_publication_transaction(self)
            if exc is None:
                raise cleanup_error
            return False
        _finish_task_test_execution_publication_transaction(self)
        return False


del _owns_task_test_execution_atomic_writer_preparation


def _execute_ledger_transaction(
    root: Path,
    *,
    operation_kind: str,
    body: Any,
    faults: Optional[DurabilityFaults] = None,
) -> Any:
    if not callable(body):
        raise AuditError("ledger transaction body is not callable")
    with LedgerTransaction(
        root, operation_kind=operation_kind, faults=faults
    ) as transaction:
        result = body(transaction)
        transaction.revalidate()
        return result


def _read_ordinary_snapshot(
    path: Path,
    *,
    maximum: int = MAX_JSON_BYTES,
    single_link: bool = True,
    fsync_file: bool = False,
) -> Tuple[bytes, os.stat_result]:
    try:
        fd, parent_fd, name, parent_path, parent_observed, before = (
            _open_ordinary_file(path, single_link=single_link)
        )
    except FileNotFoundError as exc:
        raise AuditError("required file absent: " + str(path)) from exc
    except OSError as exc:
        raise AuditError("path is not an ordinary file: " + str(path)) from exc
    primary: Optional[BaseException] = None
    try:
        if before.st_size > maximum:
            raise AuditError("file exceeds bound: " + str(path))
        chunks: List[bytes] = []
        remaining = maximum + 1
        while remaining:
            chunk = _fd_call(fd, os.read, min(1024 * 1024, remaining))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        payload = b"".join(chunks)
        if len(payload) > maximum:
            raise AuditError("file exceeds bound: " + str(path))
        if fsync_file:
            _fd_call(fd, os.fsync)
        after_fd = _fd_call(fd, os.fstat)
        after_path = _leaf_stat_at(parent_fd, name)
        stable_fields = lambda value: (
            value.st_dev, value.st_ino, value.st_mode, value.st_nlink,
            value.st_size, value.st_mtime_ns,
        )
        if stable_fields(before) != stable_fields(after_fd) or stable_fields(before) != stable_fields(after_path):
            raise AuditError("concurrent file change: " + str(path))
        if single_link and after_fd.st_nlink != 1:
            raise AuditError("hard link surprise: " + str(path))
    except BaseException as exc:
        primary = exc
        raise
    finally:
        _close_fd_slots([fd, parent_fd], primary)
    _revalidate_leaf_identity(path, parent_observed, before, "file read")
    _revalidate_directory_identity(parent_path, parent_observed, "file read")
    return payload, before


def _read_ordinary(path: Path, *, maximum: int = MAX_JSON_BYTES, single_link: bool = True) -> bytes:
    payload, _observed = _read_ordinary_snapshot(
        path, maximum=maximum, single_link=single_link
    )
    return payload


def _hash_ordinary_file(
    path: Path,
    *,
    maximum: int,
    expected: Optional[os.stat_result] = None,
) -> Tuple[str, int]:
    """Hash one stable ordinary file without materializing its contents."""

    if not isinstance(maximum, int) or isinstance(maximum, bool) or maximum < 0:
        raise AuditError("file hash bound drift")
    try:
        fd, parent_fd, name, parent_path, parent_observed, before = (
            _open_ordinary_file(path, single_link=True)
        )
    except FileNotFoundError as exc:
        raise AuditError("required file absent: " + str(path)) from exc
    except OSError as exc:
        raise AuditError("path is not an ordinary file: " + str(path)) from exc
    stable_fields = lambda value: (
        value.st_dev,
        value.st_ino,
        value.st_mode,
        value.st_nlink,
        value.st_size,
        value.st_mtime_ns,
    )
    primary: Optional[BaseException] = None
    try:
        if expected is not None and stable_fields(before) != stable_fields(expected):
            raise AuditError("resource file changed before hash: " + str(path))
        if before.st_size > maximum:
            raise AuditError("file exceeds hash bound: " + str(path))
        digest = hashlib.sha256()
        byte_count = 0
        while True:
            chunk = _fd_call(fd, os.read, 1024 * 1024)
            if not chunk:
                break
            byte_count += len(chunk)
            if byte_count > maximum:
                raise AuditError("file exceeds hash bound: " + str(path))
            digest.update(chunk)
        after_fd = _fd_call(fd, os.fstat)
        after_path = _leaf_stat_at(parent_fd, name)
        if (
            stable_fields(before) != stable_fields(after_fd)
            or stable_fields(before) != stable_fields(after_path)
            or byte_count != before.st_size
        ):
            raise AuditError("concurrent file change: " + str(path))
    except BaseException as exc:
        primary = exc
        raise
    finally:
        _close_fd_slots([fd, parent_fd], primary)
    _revalidate_leaf_identity(path, parent_observed, before, "file hash")
    _revalidate_directory_identity(parent_path, parent_observed, "file hash")
    return digest.hexdigest(), byte_count


def _hit_init_fault(
    faults: DurabilityFaults, boundary: str, path: Path
) -> None:
    """Route init interruption tests through the one explicit provider."""

    if boundary not in INIT_INTERRUPTION_BOUNDARIES:
        raise AuditError("unknown initial-publication boundary")
    faults.hit(boundary, "init-run-state", str(path))


def _write_bytes_exclusive(
    path: Path,
    payload: bytes,
    mode: int = 0o600,
    *,
    _faults: Optional[DurabilityFaults] = None,
    _operation_kind: str = "exclusive-write",
) -> None:
    if not isinstance(payload, bytes):
        raise AuditError("exclusive write payload must be bytes")
    parent_fd, name, parent_path, parent_before = _open_parent_dir_fd(path)
    flags = (
        os.O_WRONLY | os.O_CREAT | os.O_EXCL
        | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_CLOEXEC", 0)
    )
    fd: Optional["_ChildFdOwnerSlot"] = None
    faults = _faults or DurabilityFaults()
    primary: Optional[BaseException] = None
    try:
        fd = _open_owned_at(parent_fd, name, flags, mode)
        fd.chmod(mode)
        created = _fd_call(fd, os.fstat)
        if not stat.S_ISREG(created.st_mode):
            raise AuditError("created object is not regular")
        if stat.S_IMODE(created.st_mode) != mode:
            raise AuditError("created file mode mismatch")
        if created.st_nlink != 1:
            raise AuditError("created file hard link surprise")
        _write_owned_all(fd, payload)
        _fd_call(fd, os.fsync)
        faults.hit("file-fsync", _operation_kind, str(path))
        completed = _fd_call(fd, os.fstat)
        visible = _leaf_stat_at(parent_fd, name)
        if completed.st_nlink != 1 or visible.st_nlink != 1:
            raise AuditError("created file hard link surprise")
        if _stat_identity(completed) != _stat_identity(visible):
            raise AuditError("created file leaf identity drift")
        if completed.st_size != len(payload):
            raise AuditError("created file size drift")
        _fd_call(parent_fd, os.fsync)
        faults.hit("parent-fsync", _operation_kind, str(path))
    except BaseException as exc:
        primary = exc
        raise
    finally:
        _close_fd_slots([fd, parent_fd], primary)
    _revalidate_directory_identity(parent_path, parent_before, "exclusive write")
    _revalidate_leaf_identity(path, parent_before, completed, "exclusive write")


def write_canonical_exclusive(
    path: Path,
    value: Any,
    *,
    _faults: Optional[DurabilityFaults] = None,
    _operation_kind: str = "canonical-write",
) -> bytes:
    payload = canonical_json_bytes(value)
    _write_bytes_exclusive(
        Path(path),
        payload,
        0o600,
        _faults=_faults,
        _operation_kind=_operation_kind,
    )
    return payload


def _mkdir_exclusive(path: Path, mode: int = 0o700) -> None:
    path = Path(path)
    parent_fd, name, parent_path, parent_before = _open_parent_dir_fd(path)
    child_fd: Optional["_ChildFdOwnerSlot"] = None
    primary: Optional[BaseException] = None
    try:
        _fd_at(parent_fd, os.mkdir, name, mode)
        # A hostile umask can create mode 000.  The stable parent fd and the
        # just-created exclusive name make this relative chmod unambiguous;
        # fchmod below remains the authoritative post-open normalization.
        _fd_at(parent_fd, os.chmod, name, mode, follow_symlinks=False)
        child_fd = _open_owned_at(parent_fd, name, _DIRECTORY_OPEN_FLAGS)
        child_fd.chmod(mode)
        observed = _fd_call(child_fd, os.fstat)
        if not stat.S_ISDIR(observed.st_mode):
            raise AuditError("created object is not a directory")
        if stat.S_IMODE(observed.st_mode) != mode:
            raise AuditError("created directory mode mismatch")
        if observed.st_nlink < 2:
            raise AuditError("directory link count invalid")
        visible = _leaf_stat_at(parent_fd, name)
        if _stat_identity(visible) != _stat_identity(observed):
            raise AuditError("created directory leaf identity drift")
        _fd_call(child_fd, os.fsync)
        _fd_call(parent_fd, os.fsync)
    except BaseException as exc:
        primary = exc
        raise
    finally:
        _close_fd_slots([child_fd, parent_fd], primary)
    _revalidate_directory_identity(parent_path, parent_before, "exclusive mkdir")
    _revalidate_directory_identity(path, observed, "exclusive mkdir child")


def _read_canonical_file(path: Path) -> Any:
    _ordinary_file(path, expected_mode=0o600)
    return parse_canonical_json(_read_ordinary(path))


def _validate_run_root(root: Path, *, allow_ledger: bool = True) -> None:
    root = Path(root)
    _ordinary_directory(root, 0o700)
    _ordinary_directory(root / "home", 0o700)
    _ordinary_directory(root / "tmp", 0o700)
    _ordinary_directory(root / "bootstrap", 0o700)
    allowed = {"home", "tmp", "bootstrap"}
    if allow_ledger:
        allowed.add("ledger")
    for child in root.iterdir():
        if child.name in allowed or child.name.startswith("ledger.init."):
            continue
        raise AuditError("unexpected run-root child: " + child.name)


def _publish_no_replace(
    root: Path,
    staging_name: str,
    *,
    _faults: Optional[DurabilityFaults] = None,
) -> None:
    if "/" in staging_name or staging_name in ("", ".", ".."):
        raise AuditError("invalid staging name")
    root_fd = os.open(
        str(root),
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    faults = _faults or DurabilityFaults()
    try:
        _hit_init_fault(
            faults, "before-atomic-publish", root / staging_name
        )
        library = ctypes.CDLL(None, use_errno=True)
        try:
            renameatx_np = library.renameatx_np
        except AttributeError as exc:
            raise AuditError("renameatx_np unavailable") from exc
        renameatx_np.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint]
        renameatx_np.restype = ctypes.c_int
        result = renameatx_np(root_fd, os.fsencode(staging_name), root_fd, b"ledger", 0x00000004)
        if result != 0:
            observed_errno = ctypes.get_errno()
            if observed_errno == errno.EEXIST:
                raise FileExistsError(errno.EEXIST, "ledger already exists")
            if observed_errno in (errno.ENOTSUP, getattr(errno, "EOPNOTSUPP", errno.ENOTSUP)):
                raise AuditError("no-replace publication unsupported")
            raise OSError(observed_errno, os.strerror(observed_errno))
        _hit_init_fault(faults, "after-atomic-publish", root / "ledger")
        os.fsync(root_fd)
        _hit_init_fault(
            faults, "after-run-root-fsync", root / "ledger"
        )
    finally:
        os.close(root_fd)


def _new_record(
    identity: Mapping[str, Any],
    sequence: int,
    previous_digest: str,
    operation_kind: str,
    input_digest: str,
    declared_filenames: Sequence[str],
    completion_state: str,
    payload: Mapping[str, Any],
) -> Dict[str, Any]:
    if not re.fullmatch(r"[0-9a-f]{64}", input_digest):
        raise AuditError("input digest must be SHA-256")
    record = {
        "schemaVersion": "qinao.ledger-record.v1",
        "runId": identity["runId"],
        "sequence": sequence,
        "previousRecordDigest": previous_digest,
        "recordId": secrets.token_hex(16),
        "operationKind": operation_kind,
        "inputDigest": input_digest,
        "declaredFilenames": list(declared_filenames),
        "completionState": completion_state,
    }
    for key, value in payload.items():
        if key in record or key == "recordDigest":
            raise AuditError("record payload field collision")
        record[key] = value
    return _self_digest_record(record)


def _write_initial_records(
    staging: Path,
    identity: Mapping[str, Any],
    imports: Sequence[Mapping[str, Any]],
    *,
    _faults: Optional[DurabilityFaults] = None,
) -> None:
    faults = _faults or DurabilityFaults()
    previous = identity["identityDigest"]
    sequence = 1
    for imported in imports:
        input_digest = _sha256(canonical_json_bytes(imported))
        record = _new_record(
            identity,
            sequence,
            previous,
            "bootstrap-import",
            input_digest,
            [],
            "complete",
            {"bootstrapImport": dict(imported)},
        )
        record_path = staging / "records" / ("%016d.json" % sequence)
        write_canonical_exclusive(record_path, record)
        _hit_init_fault(faults, "after-initial-record", record_path)
        previous = record["recordDigest"]
        sequence += 1
    terminal_payload = {
        "bootstrapImportCount": len(imports),
        "bootstrapImportsDigest": _sha256(canonical_json_bytes(list(imports))),
    }
    terminal = _new_record(
        identity,
        sequence,
        previous,
        "bootstrap-completed",
        terminal_payload["bootstrapImportsDigest"],
        [],
        "complete",
        terminal_payload,
    )
    terminal_path = staging / "records" / ("%016d.json" % sequence)
    write_canonical_exclusive(terminal_path, terminal)
    _hit_init_fault(faults, "after-initial-record", terminal_path)


def _identity_without_volatile(identity: Mapping[str, Any]) -> Dict[str, Any]:
    comparable = dict(identity)
    for volatile in ("creationNonce", "createdUnixNs", "runId", "identityDigest"):
        comparable.pop(volatile, None)
    return comparable


def _validate_complete_initial_staging(staging: Path) -> Dict[str, Any]:
    _ordinary_directory(staging, 0o700)
    required_directories = (
        "records", "phases", "captures", "resources", "resource-snapshots", "invocations"
    )
    for name in required_directories:
        _ordinary_directory(staging / name, 0o700)
    expected_names = set(required_directories) | {"identity.json", "lock"}
    if {child.name for child in staging.iterdir()} != expected_names:
        raise AuditError("initial staging child set drift")
    identity, records = _recover_records_at(staging)
    if not records or records[-1].get("operationKind") != "bootstrap-completed":
        raise AuditError("initial staging lacks terminal bootstrap record")
    if any(
        any((staging / name).iterdir())
        for name in ("phases", "captures", "resources", "resource-snapshots", "invocations")
    ):
        raise AuditError("initial staging contains post-bootstrap state")
    return identity


def _publish_recovered_staging(
    root: Path,
    supplied_identity: Mapping[str, Any],
    *,
    _faults: Optional[DurabilityFaults] = None,
) -> Optional[Dict[str, Any]]:
    complete: List[Tuple[Path, Dict[str, Any]]] = []
    for candidate in sorted(root.glob("ledger.init.*"), key=lambda path: path.name):
        try:
            identity = _validate_complete_initial_staging(candidate)
        except (AuditError, OSError, ValueError, KeyError, TypeError):
            # A partial generation is immutable forensic input.  It remains
            # present and is never promoted or repaired.
            continue
        complete.append((candidate, identity))
    if len(complete) > 1:
        raise AuditError("more than one complete staging generation")
    if not complete:
        return None
    candidate, identity = complete[0]
    if _identity_without_volatile(identity) != dict(supplied_identity):
        raise AuditError("complete staging identity mismatch")
    root_fd = os.open(
        str(root),
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0),
    )
    try:
        fcntl.flock(root_fd, fcntl.LOCK_EX)
        try:
            _publish_no_replace(
                root, candidate.name, _faults=_faults
            )
        except FileExistsError:
            winner = _read_canonical_file(root / "ledger" / "identity.json")
            if _identity_without_volatile(winner) != dict(supplied_identity):
                raise AuditError("identity mismatch after recovered staging publication race")
            recovered = recover_run_state(root)
            if recovered["classification"] != "complete":
                raise AuditError("publication-race winner is indeterminate")
            return winner
        finally:
            fcntl.flock(root_fd, fcntl.LOCK_UN)
    finally:
        os.close(root_fd)
    recovered = recover_run_state(root)
    if recovered["classification"] != "complete":
        raise AuditError("recovered staging publication is indeterminate")
    return identity


def _reopen_exact_published_ledger(
    root: Path,
    identity_fields: Mapping[str, Any],
    label: str,
) -> Dict[str, Any]:
    try:
        existing = _read_canonical_file(root / "ledger" / "identity.json")
    except (AuditError, OSError, ValueError, KeyError, TypeError) as exc:
        raise AuditError(label + " winner identity is indeterminate") from exc
    if _identity_without_volatile(existing) != dict(identity_fields):
        raise AuditError(label + " winner identity mismatch")
    recovered = recover_run_state(root)
    if recovered["classification"] != "complete":
        raise AuditError(label + " winner ledger is indeterminate")
    if recovered.get("identity") != existing:
        raise AuditError(label + " winner identity recovery drift")
    return existing


def init_run_state(
    root: Path,
    identity_fields: Mapping[str, Any],
    *,
    bootstrap_imports: Sequence[Mapping[str, Any]],
    _faults: Optional[DurabilityFaults] = None,
) -> Dict[str, Any]:
    root = Path(root).resolve()
    faults = _faults or DurabilityFaults()
    _validate_run_root(root)
    supplied = dict(identity_fields)
    supplied.setdefault("creationNonce", secrets.token_hex(16))
    # Nanosecond epoch values exceed the canonical safe-integer domain.  The
    # identity treats the timestamp as a decimal string, never as arithmetic.
    supplied.setdefault("createdUnixNs", str(time.time_ns()))
    supplied["runId"] = _sha256(canonical_json_bytes(supplied))[:32]
    identity = _self_digest_record(supplied, field="identityDigest")
    published = root / "ledger"
    if published.exists() or published.is_symlink():
        return _reopen_exact_published_ledger(
            root, identity_fields, "published"
        )

    recovered_staging = _publish_recovered_staging(
        root, identity_fields, _faults=faults
    )
    if recovered_staging is not None:
        return recovered_staging

    staging = root / ("ledger.init." + secrets.token_hex(6))
    _mkdir_exclusive(staging)
    _hit_init_fault(faults, "after-staging-directory", staging)
    for directory in ("records", "phases", "captures", "resources", "resource-snapshots", "invocations"):
        _mkdir_exclusive(staging / directory)
        _hit_init_fault(faults, "after-subdirectory", staging / directory)
    write_canonical_exclusive(staging / "identity.json", identity)
    _hit_init_fault(faults, "after-identity-file", staging / "identity.json")
    _write_bytes_exclusive(staging / "lock", b"")
    _hit_init_fault(faults, "after-lock-file", staging / "lock")
    _write_initial_records(
        staging, identity, bootstrap_imports, _faults=faults
    )
    for directory in ("records", "phases", "captures", "resources", "resource-snapshots", "invocations", ""):
        directory_path = staging / directory if directory else staging
        _fsync_directory(directory_path)
        _hit_init_fault(
            faults, "after-directory-fsync", directory_path
        )
    root_fd = os.open(str(root), os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        fcntl.flock(root_fd, fcntl.LOCK_EX)
        try:
            _publish_no_replace(
                root, staging.name, _faults=faults
            )
        except FileExistsError:
            return _reopen_exact_published_ledger(
                root, identity_fields, "publication-race"
            )
        finally:
            fcntl.flock(root_fd, fcntl.LOCK_UN)
    finally:
        os.close(root_fd)
    return identity


