def _secret_scan_subject_digest_from_binding(
    binding: Mapping[str, Any]
) -> str:
    return _sha256(canonical_json_bytes({
        field: binding.get(field)
        for field in (
            "headOid", "headTreeOid", "indexTreeOid",
            "indexEntryMapDigest",
            "stagedPathDigest", "declaredPathDigest", "dirtyPathDigest",
            "selectedEntriesDigest", "scanEntriesDigest",
            "scannerModulePath",
            "scannerModuleMode", "scannerModuleSize",
            "scannerModuleSha256",
        )
    }))


_SECRET_RULE_FROZEN_FLAG_MASK = 0x1FF
_SECRET_RULE_FORBIDDEN_FLAGS = 0x085


def _validate_secret_rule_projection(value: Any) -> None:
    if not isinstance(value, list) or not value:
        raise AuditError("secret rule projection shape drift")
    seen = set()
    for ordinal, row in enumerate(value):
        if not isinstance(row, Mapping) or set(row) != {
            "ordinal", "ruleId", "patternType", "patternB64",
            "effectiveFlags",
        }:
            raise AuditError("secret rule projection row drift")
        rule_id = row.get("ruleId")
        flags = row.get("effectiveFlags")
        encoded = row.get("patternB64")
        ordinal_value = row.get("ordinal")
        if (
            not isinstance(ordinal_value, int)
            or isinstance(ordinal_value, bool)
            or ordinal_value != ordinal
            or not isinstance(rule_id, str)
            or re.fullmatch(r"[a-z0-9][a-z0-9-]*", rule_id) is None
            or rule_id in seen
            or row.get("patternType") not in ("bytes", "string")
            or not isinstance(encoded, str)
            or not isinstance(flags, int)
            or isinstance(flags, bool)
            or flags < 0
            or flags & ~_SECRET_RULE_FROZEN_FLAG_MASK
            or flags & _SECRET_RULE_FORBIDDEN_FLAGS
        ):
            raise AuditError("secret rule projection value drift")
        try:
            decoded = base64.b64decode(encoded, validate=True)
        except (ValueError, binascii.Error) as exc:
            raise AuditError("secret rule projection base64 drift") from exc
        if base64.b64encode(decoded).decode("ascii") != encoded:
            raise AuditError("secret rule projection base64 drift")
        if row["patternType"] == "string":
            try:
                decoded.decode("utf-8", "strict")
            except UnicodeDecodeError as exc:
                raise AuditError("secret rule projection Unicode drift") from exc
        if (
            (row["patternType"] == "bytes" and flags & 0x020)
            or (
                row["patternType"] == "string"
                and (
                    flags & 0x004
                    or not flags & (0x020 | 0x100)
                )
            )
            or (flags & 0x020 and flags & 0x100)
            or (flags & 0x004 and flags & 0x100)
        ):
            raise AuditError("secret rule projection flag/type drift")
        seen.add(rule_id)


def _secret_rule_set_digest_from_projection(
    value: Mapping[str, Any]
) -> str:
    version = value.get("ruleSetVersion")
    projection = value.get("ruleProjection")
    if version != "qinao.secret-scan.v1":
        raise AuditError("secret rule projection version drift")
    _validate_secret_rule_projection(projection)
    digest_rows: List[Dict[str, str]] = []
    for row in projection:
        pattern = base64.b64decode(row["patternB64"], validate=True)
        if row["patternType"] == "bytes":
            pattern_digest = _sha256(pattern)
        else:
            pattern_digest = _sha256(
                b"qinao-secret-regex-string\x00" + pattern
            )
        digest_rows.append({
            "id": row["ruleId"],
            "patternSha256": pattern_digest,
        })
    return _sha256(canonical_json_bytes({
        "version": version,
        "rules": digest_rows,
    }))


def _validate_persisted_secret_rule_authority(
    value: Mapping[str, Any]
) -> None:
    _require_lower_hex(
        value.get("ruleSetDigest"), 64,
        "persisted secret rule set digest",
    )
    if value.get("ruleSetDigest") != (
        _secret_rule_set_digest_from_projection(value)
    ):
        raise AuditError("persisted secret rule authority drift")


def _validate_secret_scan_binding_authority(
    reservation: Mapping[str, Any],
    identity: Mapping[str, Any],
    root: Path,
) -> Dict[str, Any]:
    binding = reservation.get("binding")
    rule_authority = _current_secret_rule_set_authority()
    root = _absolute_path_without_symlink_resolution(Path(root))
    expected_module = _absolute_path_without_symlink_resolution(
        Path(str(identity.get("repository", "")))
        / "scripts" / "qinao_convergence_audit.py"
    )
    runtime_module = _absolute_path_without_symlink_resolution(
        Path(__file__)
    )
    if (
        not isinstance(binding, Mapping)
        or binding.get("runId") != identity.get("runId")
        or binding.get("identityDigest") != identity.get("identityDigest")
        or binding.get("runRoot") != str(root)
        or binding.get("repository") != identity.get("repository")
        or reservation.get("repository") != identity.get("repository")
        or runtime_module != expected_module
        or binding.get("scannerModulePath") != str(runtime_module)
        or any(
            binding.get(field) != rule_authority[field]
            for field in (
                "ruleSetVersion", "ruleSetDigest", "ruleProjection"
            )
        )
    ):
        raise AuditError("secret scan authoritative identity drift")
    module_payload, module_observed = _read_ordinary_snapshot(
        runtime_module, maximum=8 * 1024 * 1024
    )
    if (
        binding.get("scannerModuleMode")
        != "%04o" % stat.S_IMODE(module_observed.st_mode)
        or binding.get("scannerModuleSize") != len(module_payload)
        or binding.get("scannerModuleSha256") != _sha256(module_payload)
    ):
        raise AuditError("secret scan executing module drift")
    return rule_authority


def _validate_secret_scan_reservation_shape(
    record: Mapping[str, Any]
) -> None:
    binding = record.get("binding")
    if not isinstance(binding, Mapping):
        raise AuditError("secret scan reservation binding drift")
    expected_binding_fields = {
        "schemaVersion", "runId", "identityDigest", "runRoot",
        "repository", "phase", "frontierId", "headOid", "headTreeOid",
        "indexTreeOid", "indexEntryMapDigest", "stagedPathDigest",
        "declaredPathDigest",
        "dirtyPathDigest", "selectedEntriesDigest", "scanEntriesDigest",
        "subjectDigest",
        "scannerModulePath", "scannerModuleMode", "scannerModuleSize",
        "scannerModuleSha256",
        "ruleSetVersion", "ruleSetDigest", "ruleProjection", "outputName",
        "bindingDigest",
    }
    corrected = binding.get("schemaVersion") == "qinao.secret-scan-capture-binding.v3"
    if corrected:
        expected_binding_fields.add("taskCorrectionRecordDigest")
        _require_lower_hex(binding.get("taskCorrectionRecordDigest"), 64, "scan correction record")
        if binding.get("phase") != "task3-correction-scan-1":
            raise AuditError("secret scan correction phase drift")
    if (
        set(binding) != expected_binding_fields
        or binding.get("schemaVersion")
        not in ("qinao.secret-scan-capture-binding.v2", "qinao.secret-scan-capture-binding.v3")
        or binding.get("outputName") != "secret-scan.json"
    ):
        raise AuditError("secret scan reservation binding shape drift")
    _validate_persisted_secret_rule_authority(binding)
    _verify_self_digest(binding, "bindingDigest")
    if binding.get("subjectDigest") != (
        _secret_scan_subject_digest_from_binding(binding)
    ):
        raise AuditError("secret scan subject digest drift")
    for field in (
        "identityDigest", "indexEntryMapDigest", "stagedPathDigest",
        "declaredPathDigest", "dirtyPathDigest", "selectedEntriesDigest",
        "scanEntriesDigest",
        "subjectDigest", "scannerModuleSha256", "ruleSetDigest",
        "bindingDigest",
    ):
        _require_lower_hex(
            binding.get(field), 64, "secret scan binding " + field
        )
    for field in ("runRoot", "repository"):
        value = binding.get(field)
        if not isinstance(value, str) or not Path(value).is_absolute():
            raise AuditError("secret scan binding path drift")
    module_path = binding.get("scannerModulePath")
    if (
        not isinstance(module_path, str)
        or not Path(module_path).is_absolute()
        or module_path
        != str(Path(binding["repository"]) / "scripts"
               / "qinao_convergence_audit.py")
        or re.fullmatch(r"0[0-7]{3}", str(binding.get("scannerModuleMode")))
        is None
        or not isinstance(binding.get("scannerModuleSize"), int)
        or isinstance(binding.get("scannerModuleSize"), bool)
        or binding.get("scannerModuleSize") < 1
    ):
        raise AuditError("secret scan executing module shape drift")
    for field in ("headOid", "headTreeOid", "indexTreeOid"):
        value = binding.get(field)
        if field != "indexTreeOid" and value == "unborn":
            continue
        if (
            not isinstance(value, str)
            or re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", value) is None
        ):
            raise AuditError("secret scan binding HEAD drift")
    if (binding.get("headOid") == "unborn") != (
        binding.get("headTreeOid") == "unborn"
    ):
        raise AuditError("secret scan binding unborn HEAD drift")
    for field in ("runId", "frontierId"):
        value = binding.get(field)
        if not isinstance(value, str) or re.fullmatch(
            r"[0-9a-f]{32}", value
        ) is None:
            raise AuditError("secret scan binding identity drift")
    phase = _safe_component(binding.get("phase"), "secret scan phase")
    recovery_key = record.get("recoveryKey")
    _require_lower_hex(recovery_key, 64, "secret scan recovery key")
    capture_id = record.get("captureId")
    if (
        not isinstance(capture_id, str)
        or re.fullmatch(r"[0-9a-f]{32}", capture_id) is None
        or capture_id
        != _sha256(
            b"qinao-secret-scan-capture\x00"
            + recovery_key.encode("ascii")
        )[:32]
    ):
        raise AuditError("secret scan deterministic capture ID drift")
    absolute = record.get("absolutePath")
    output = record.get("outputPath")
    expected_generation = "%016d-%s" % (
        record.get("sequence"), capture_id
    )
    if (
        recovery_key != _sha256(canonical_json_bytes(binding))
        or record.get("inputDigest") != recovery_key
        or record.get("bindingDigest") != binding.get("bindingDigest")
        or record.get("phase") != phase
        or record.get("frontierId") != binding.get("frontierId")
        or record.get("repository") != binding.get("repository")
        or record.get("outputName") != "secret-scan.json"
        or not isinstance(absolute, str)
        or not Path(absolute).is_absolute()
        or Path(absolute).name != expected_generation
        or output != str(Path(absolute) / "secret-scan.json")
    ):
        raise AuditError("secret scan reservation projection drift")


_SECRET_SCAN_EXECUTION_FIELDS = frozenset({
    "schemaVersion", "runId", "identityDigest", "runRoot", "repository",
    "captureId", "phase", "frontierId", "absolutePath", "outputName",
    "outputPath", "reservationRecordDigest",
    "materializationRecordDigest", "bindingDigest", "subjectDigest",
    "attemptId", "outerInvocationStartRecordDigest", "invocationDigest",
    "profile", "argv", "argvDigest", "runtimeDigest",
    "importInventoryDigest", "scannerModulePath", "scannerModuleMode",
    "scannerModuleSize", "scannerModuleSha256", "ruleSetVersion",
    "ruleSetDigest", "ruleProjection", "indexTreeOid",
    "scanEntriesDigest",
    "executionDigest",
})


def _validate_secret_scan_invocation_start_shape(
    record: Mapping[str, Any]
) -> None:
    execution = record.get("execution")
    if (
        not isinstance(execution, Mapping)
        or set(execution) != _SECRET_SCAN_EXECUTION_FIELDS
    ):
        raise AuditError("secret scan execution field drift")
    _verify_self_digest(execution, "executionDigest")
    if (
        execution.get("schemaVersion")
        != "qinao.secret-scan-execution.v2"
        or execution.get("profile") != "ledger"
    ):
        raise AuditError("secret scan execution contract drift")
    _validate_persisted_secret_rule_authority(execution)
    for field in (
        "runId", "captureId", "frontierId", "attemptId",
    ):
        _require_lower_hex(
            execution.get(field), 32, "secret scan execution " + field
        )
    for field in (
        "identityDigest", "reservationRecordDigest",
        "materializationRecordDigest", "bindingDigest", "subjectDigest",
        "outerInvocationStartRecordDigest", "invocationDigest",
        "argvDigest", "runtimeDigest", "importInventoryDigest",
        "scannerModuleSha256", "ruleSetDigest", "scanEntriesDigest",
        "executionDigest",
    ):
        _require_lower_hex(
            execution.get(field), 64, "secret scan execution " + field
        )
    if (
        not isinstance(execution.get("scannerModuleSize"), int)
        or isinstance(execution.get("scannerModuleSize"), bool)
        or execution.get("scannerModuleSize") < 1
        or re.fullmatch(
            r"0[0-7]{3}", str(execution.get("scannerModuleMode"))
        ) is None
    ):
        raise AuditError("secret scan execution numeric/mode drift")
    _validate_secret_rule_projection(execution.get("ruleProjection"))
    phase = _safe_component(
        execution.get("phase"), "secret scan execution phase"
    )
    for field in (
        "runRoot", "repository", "absolutePath", "outputPath",
        "scannerModulePath",
    ):
        value = execution.get(field)
        if (
            not isinstance(value, str)
            or not Path(value).is_absolute()
            or str(_absolute_path_without_symlink_resolution(Path(value)))
            != value
        ):
            raise AuditError("secret scan execution path drift")
    if (
        execution.get("phase") != phase
        or execution.get("outputName") != "secret-scan.json"
        or execution.get("outputPath")
        != str(Path(execution["absolutePath"]) / "secret-scan.json")
        or execution.get("scannerModulePath")
        != str(
            Path(execution["repository"])
            / "scripts" / "qinao_convergence_audit.py"
        )
    ):
        raise AuditError("secret scan execution path binding drift")
    argv = execution.get("argv")
    expected_argv = [
        "secret-scan-worktree",
        "--root",
        execution["runRoot"],
        "--repository",
        execution["repository"],
        "--phase",
        execution["phase"],
        "--frontier-id",
        execution["frontierId"],
    ]
    # Execution.v2 keeps its closed fields; only binding.v3 may authorize this
    # exact suffix in cold projection. Shape validation grants no generation.
    if isinstance(argv, list) and len(argv) == len(expected_argv) + 2:
        selector = argv[-1]
        if (argv[-2] != "--task-correction-record" or phase != "task3-correction-scan-1"
            or not isinstance(selector, str)
            or str(Path(selector)) != selector
            or Path(selector).parent != Path(execution["runRoot"]) / "ledger/records"
            or re.fullmatch(r"[0-9]{16}\.json", Path(selector).name) is None):
            raise AuditError("secret scan correction execution argv shape drift")
        expected_argv += ["--task-correction-record", selector]
    if (
        argv != expected_argv
        or execution.get("argvDigest")
        != _sha256(canonical_json_bytes(expected_argv))
    ):
        raise AuditError("secret scan execution argv drift")
    attempt_id = _sha256(
        b"qinao-secret-scan-attempt\x00"
        + execution["captureId"].encode("ascii")
        + b"\x00"
        + execution["outerInvocationStartRecordDigest"].encode("ascii")
    )[:32]
    if execution.get("attemptId") != attempt_id:
        raise AuditError("secret scan deterministic attempt drift")
    if re.fullmatch(
        r"[0-9a-f]{40}|[0-9a-f]{64}",
        str(execution.get("indexTreeOid")),
    ) is None:
        raise AuditError("secret scan execution index tree drift")
    mirrored = (
        "captureId", "attemptId", "reservationRecordDigest",
        "materializationRecordDigest", "outerInvocationStartRecordDigest",
        "invocationDigest", "bindingDigest",
    )
    if (
        any(record.get(field) != execution.get(field) for field in mirrored)
        or record.get("inputDigest") != execution.get("executionDigest")
    ):
        raise AuditError("secret scan invocation start projection drift")


def _validate_secret_scan_terminal_shape(
    record: Mapping[str, Any]
) -> None:
    for field, size in (
        ("captureId", 32), ("attemptId", 32),
        ("invocationStartRecordDigest", 64),
        ("outerInvocationStartRecordDigest", 64),
        ("invocationDigest", 64), ("executionDigest", 64),
        ("bindingDigest", 64), ("subjectDigest", 64),
        ("resultRecordDigest", 64), ("outputSha256", 64),
    ):
        _require_lower_hex(
            record.get(field), size, "secret scan terminal " + field
        )
    result = record.get("result")
    if not isinstance(result, Mapping):
        raise AuditError("secret scan terminal result drift")
    _verify_self_digest(result)
    if (
        result.get("schemaVersion") not in (
            "qinao.secret-scan-worktree.v1",
            "qinao.secret-scan-indeterminate.v1",
        )
        or record.get("resultRecordDigest") != result.get("recordDigest")
        or record.get("inputDigest") != result.get("recordDigest")
        or record.get("outputPath") is None
        or not isinstance(record.get("outputPath"), str)
        or not Path(record["outputPath"]).is_absolute()
        or record.get("outputMode") != "0600"
        or not isinstance(record.get("outputSize"), int)
        or isinstance(record.get("outputSize"), bool)
        or record.get("outputSize") < 1
        or record.get("outputSize")
        != len(canonical_json_bytes(result))
        or record.get("outputSha256")
        != _sha256(canonical_json_bytes(result))
    ):
        raise AuditError("secret scan terminal result/output drift")
    if result.get("schemaVersion") == "qinao.secret-scan-indeterminate.v1":
        if (
            set(result) != {"schemaVersion", "reasonCode", "recordDigest"}
            or result.get("reasonCode") not in (
                "durable-start-without-candidate",
                "conflicting-durable-candidates",
            )
            or record.get("completionState")
            != "secret-scan-indeterminate-no-replay"
        ):
            raise AuditError("secret scan indeterminate result drift")
        return
    result_binding = result.get("resultBinding")
    if (
        set(result) != _SECRET_SCAN_RESULT_FIELDS | {"resultBinding"}
        or not isinstance(result_binding, Mapping)
        or set(result_binding) != _SECRET_SCAN_RESULT_BINDING_FIELDS
        or result_binding.get("schemaVersion")
        != "qinao.secret-scan-result-binding.v1"
    ):
        raise AuditError("secret scan terminal result binding drift")
    _verify_self_digest(result_binding, "resultBindingDigest")
    for field in (
        "ruleCount", "scannedFileCount", "scannedByteCount",
        "findingCount",
    ):
        value = result.get(field)
        if (
            not isinstance(value, int)
            or isinstance(value, bool)
            or value < 0
        ):
            raise AuditError("secret scan terminal count drift")
    if (
        result.get("ruleCount", 0) < 1
        or result.get("scannedFileCount", 0) < 1
        or result.get("scannedByteCount", 0) < 1
        or not isinstance(result.get("ruleSetVersion"), str)
        or not result.get("ruleSetVersion")
        or result.get("ruleSetDigest")
        != result_binding.get("ruleSetDigest")
        or not isinstance(result.get("entries"), list)
        or len(result["entries"]) != result["scannedFileCount"]
        or not isinstance(result.get("findings"), list)
        or len(result["findings"]) != result["findingCount"]
    ):
        raise AuditError("secret scan terminal scan-result drift")
    expected_state = (
        "secret-scan-clean"
        if result["findingCount"] == 0
        else "secret-scan-findings-blocked"
    )
    if record.get("completionState") != expected_state:
        raise AuditError("secret scan terminal outcome drift")


def _validate_secret_scan_terminal_selection_shape(
    record: Mapping[str, Any],
) -> None:
    for field, size in (
        ("outerInvocationStartRecordDigest", 64),
        ("invocationDigest", 64), ("outerArgvDigest", 64),
        ("captureId", 32), ("attemptId", 32),
        ("frontierId", 32), ("terminalRecordDigest", 64),
        ("terminalResultRecordDigest", 64), ("selectionDigest", 64),
    ):
        _require_lower_hex(
            record.get(field), size, "secret scan selection " + field
        )
    state = record.get("terminalCompletionState")
    exit_code = record.get("terminalExitCode")
    expected_exit = {
        "secret-scan-clean": 0,
        "secret-scan-findings-blocked": 1,
        "secret-scan-indeterminate-no-replay": 2,
    }.get(state)
    selection_fields = {
        key: record[key]
        for key in (
            "selectionSchemaVersion",
            "outerInvocationStartRecordDigest", "invocationDigest",
            "outerArgvDigest", "captureId", "attemptId", "frontierId",
            "terminalRecordDigest", "terminalCompletionState",
            "terminalResultRecordDigest", "terminalExitCode",
        )
    }
    expected_selection = _self_digest_record(
        selection_fields, field="selectionDigest"
    )
    if (
        record.get("selectionSchemaVersion")
        != "qinao.secret-scan-terminal-selection.v1"
        or expected_exit is None
        or exit_code != expected_exit
        or record.get("inputDigest") != record.get("selectionDigest")
        or record.get("selectionDigest")
        != expected_selection["selectionDigest"]
    ):
        raise AuditError("secret scan terminal selection drift")


def _secret_scan_terminal_selection_payload(
    outer_start: Mapping[str, Any],
    reservation: Mapping[str, Any],
    invocation_start: Mapping[str, Any],
    terminal: Mapping[str, Any],
) -> Dict[str, Any]:
    invocation = outer_start.get("invocation")
    if not isinstance(invocation, Mapping):
        raise AuditError("secret scan selection outer invocation drift")
    payload = {
        "selectionSchemaVersion":
            "qinao.secret-scan-terminal-selection.v1",
        "outerInvocationStartRecordDigest": outer_start["recordDigest"],
        "invocationDigest": invocation["recordDigest"],
        "outerArgvDigest": _sha256(
            canonical_json_bytes(invocation["argv"])
        ),
        "captureId": reservation["captureId"],
        "attemptId": invocation_start["attemptId"],
        "frontierId": reservation["frontierId"],
        "terminalRecordDigest": terminal["recordDigest"],
        "terminalCompletionState": terminal["completionState"],
        "terminalResultRecordDigest": terminal["resultRecordDigest"],
        "terminalExitCode": _secret_scan_terminal_exit_code(terminal),
    }
    return _self_digest_record(payload, field="selectionDigest")


def _validate_linked_sterile_invocation(
    invocation: Mapping[str, Any],
) -> None:
    if set(invocation) != {
        "schemaVersion",
        "profile",
        "argv",
        "repository",
        "runtime",
        "flags",
        "sysPath",
        "importInventory",
        "recordDigest",
    }:
        raise AuditError("linked sterile invocation field drift")
    _verify_self_digest(invocation)
    if (
        invocation.get("schemaVersion")
        != "qinao.sterile-invocation.v1"
        or invocation.get("profile") != "ledger"
    ):
        raise AuditError("linked sterile invocation profile drift")
    _canonical_absolute_path(
        invocation.get("repository"),
        "linked sterile invocation repository",
    )
    argv = invocation.get("argv")
    if (
        not isinstance(argv, list)
        or not argv
        or any(not isinstance(value, str) for value in argv)
    ):
        raise AuditError("linked sterile invocation argv drift")


def _task_test_expected_tests_digest(values: Sequence[str]) -> str:
    return _sha256(
        b"qinao.task-test-expected-tests.v1\x00"
        + canonical_json_bytes(list(values))
    )


def _task_test_proof_key(subject: Mapping[str, Any]) -> str:
    fields = (
        "runId", "identityDigest", "repository", "branch",
        "resultHeadOid", "resultTreeOid", "indexTreeOid",
        "cleanStatusSha256", "localConfigDigest",
        "protectedWitnessDigest", "frontierId",
        "frontierStartRecordDigest", "expectedTestsDigest",
        "cleanScanTerminalRecordDigest", "cleanScanSubjectDigest",
        "moduleManifestDigest", "argvDigest", "runtimeDigest",
        "importInventoryDigest", "testPlanDigest",
    )
    values = {
        field: subject.get(field) for field in fields
    }
    version = subject.get("schemaVersion")
    if version in (
        "qinao.task-test-subject.v2",
        "qinao.task-test-subject.v3",
        "qinao.task-test-subject.v4",
        "qinao.task-test-subject.v5",
    ):
        values["captureContractVersion"] = subject.get(
            "captureContractVersion"
        )
        values["captureContractDigest"] = subject.get(
            "captureContractDigest"
        )
    if version in ("qinao.task-test-subject.v3", "qinao.task-test-subject.v4", "qinao.task-test-subject.v5"):
        values["executionContractVersion"] = subject.get(
            "executionContractVersion"
        )
        values["executionContractDigest"] = subject.get(
            "executionContractDigest"
        )
        if version == "qinao.task-test-subject.v5":
            values.update({
                "scanResultRelationDigest": subject.get("scanResultRelationDigest"),
                "outputContractVersion": subject.get("outputContractVersion"),
                "outputContractDigest": subject.get("outputContractDigest"),
            })
            return _sha256(
                b"qinao.task-test-proof-key.v5\x00" + canonical_json_bytes(values)
            )
        if version == "qinao.task-test-subject.v4":
            values["scanResultRelationDigest"] = subject.get("scanResultRelationDigest")
            return _sha256(
                b"qinao.task-test-proof-key.v4\x00" + canonical_json_bytes(values)
            )
        return _sha256(
            b"qinao.task-test-proof-key.v3\x00"
            + canonical_json_bytes(values)
        )
    if version == "qinao.task-test-subject.v2":
        return _sha256(
            b"qinao.task-test-proof-key.v2\x00"
            + canonical_json_bytes(values)
        )
    return _sha256(canonical_json_bytes(values))


def _validate_task_test_module_manifest(
    manifest: Any,
) -> None:
    if not isinstance(manifest, list) or len(manifest) != 2:
        raise AuditError("task test module manifest shape drift")
    expected_roles = ["production", "tests"]
    seen_paths = set()
    for ordinal, row in enumerate(manifest):
        if not isinstance(row, Mapping) or set(row) != {
            "role", "moduleName", "relativePath", "absolutePath",
            "mode", "size", "gitBlobOid", "sha256",
        }:
            raise AuditError("task test module manifest row drift")
        if (
            row.get("role") != expected_roles[ordinal]
            or not isinstance(row.get("moduleName"), str)
            or not row["moduleName"]
            or not isinstance(row.get("relativePath"), str)
            or not row["relativePath"]
            or not isinstance(row.get("absolutePath"), str)
            or not Path(row["absolutePath"]).is_absolute()
            or row["absolutePath"] in seen_paths
            or re.fullmatch(r"0[0-7]{3}", str(row.get("mode"))) is None
            or not isinstance(row.get("size"), int)
            or isinstance(row.get("size"), bool)
            or row["size"] <= 0
            or re.fullmatch(
                r"[0-9a-f]{40}|[0-9a-f]{64}",
                str(row.get("gitBlobOid")),
            ) is None
        ):
            raise AuditError("task test module manifest value drift")
        _require_lower_hex(
            row.get("sha256"), 64, "task test module SHA256"
        )
        seen_paths.add(row["absolutePath"])


def _task_test_domain_digest(domain: bytes, value: Any) -> str:
    if not isinstance(domain, bytes) or not domain:
        raise AuditError("task test digest domain drift")
    return _sha256(domain + b"\x00" + canonical_json_bytes(value))


def _validate_task_test_activation_witness(
    value: Any,
    module_manifest: Sequence[Mapping[str, Any]],
) -> Dict[str, Any]:
    if not isinstance(value, Mapping):
        raise AuditError("task test activation witness shape drift")
    witness = dict(value)
    if (
        set(witness) != {
            "schemaVersion", "loaderSchemaVersion", "moduleOrder",
            "modules", "witnessDigest",
        }
        or witness.get("schemaVersion")
        != "qinao.task-test-activation-witness.v1"
        or witness.get("loaderSchemaVersion")
        != "qinao.verified-source-loader.v1"
    ):
        raise AuditError("task test activation witness field drift")
    expected_modules = [
        {
            "role": row["role"],
            "moduleName": row["moduleName"],
            "absolutePath": row["absolutePath"],
            "size": row["size"],
            "sha256": row["sha256"],
        }
        for row in module_manifest
    ]
    if (
        witness.get("moduleOrder")
        != [row["moduleName"] for row in module_manifest]
        or witness.get("modules") != expected_modules
    ):
        raise AuditError("task test activation witness module drift")
    _require_lower_hex(
        witness.get("witnessDigest"), 64,
        "task test activation witness digest",
    )
    unsigned = dict(witness)
    unsigned.pop("witnessDigest")
    if witness["witnessDigest"] != _task_test_domain_digest(
        b"qinao.task-test-activation-witness.v1", unsigned
    ):
        raise AuditError("task test activation witness digest drift")
    return witness


def _validate_task_test_plan(
    value: Any,
    expected_tests: Sequence[str],
    module_manifest: Sequence[Mapping[str, Any]],
) -> Dict[str, Any]:
    if not isinstance(value, Mapping):
        raise AuditError("task test plan shape drift")
    plan = dict(value)
    if (
        set(plan) != {
            "schemaVersion", "groups", "flattenedTestIds",
            "flattenedTestIdsDigest", "activationWitness",
            "activationWitnessDigest", "planDigest",
        }
        or plan.get("schemaVersion") != "qinao.task-test-plan.v1"
    ):
        raise AuditError("task test plan field drift")
    groups = plan.get("groups")
    if not isinstance(groups, list) or len(groups) != len(expected_tests):
        raise AuditError("task test plan group count drift")
    flattened: List[str] = []
    global_ids = set()
    validated_groups = []
    for ordinal, (candidate, target) in enumerate(
        zip(groups, expected_tests)
    ):
        if not isinstance(candidate, Mapping):
            raise AuditError("task test plan group shape drift")
        group = dict(candidate)
        if set(group) != {
            "schemaVersion", "ordinal", "target", "moduleName",
            "className", "testIds", "testIdsDigest",
            "executionBindings", "executionBindingsDigest", "groupDigest",
        } or group.get("schemaVersion") != (
            "qinao.task-test-plan-group.v1"
        ):
            raise AuditError("task test plan group field drift")
        module_name, class_name = _parse_task_test_target(target)
        ids = group.get("testIds")
        prefix = module_name + "." + class_name + "."
        execution_bindings = group.get("executionBindings")
        if (
            group.get("ordinal") != ordinal
            or group.get("target") != target
            or group.get("moduleName") != module_name
            or group.get("className") != class_name
            or not isinstance(ids, list)
            or not ids
            or any(not isinstance(item, str) for item in ids)
            or ids != sorted(ids, key=lambda item: item.encode("utf-8"))
            or len(ids) != len(set(ids))
            or any(item in global_ids for item in ids)
            or any(
                re.fullmatch(
                    re.escape(prefix) + r"test[A-Za-z0-9_]+", item
                ) is None
                for item in ids
            )
            or group.get("testIdsDigest") != _task_test_domain_digest(
                b"qinao.task-test-ids.v1", ids
            )
            or not isinstance(execution_bindings, list)
            or [
                row.get("testId") if isinstance(row, Mapping) else None
                for row in execution_bindings
            ] != ids
            or any(
                not isinstance(row, Mapping)
                or set(row) != {
                    "testId", "classExpectedFailure",
                    "methodExpectedFailure", "setUpOwner",
                    "tearDownOwner", "failureExceptionOwner",
                    "cleanupPolicy", "unsupportedFixturePolicy",
                }
                or type(row.get("classExpectedFailure")) is not bool
                or type(row.get("methodExpectedFailure")) is not bool
                or row.get("cleanupPolicy")
                != "qinao.task-test-cleanup-capability.v1"
                or row.get("unsupportedFixturePolicy")
                != "qinao.task-test-no-module-or-class-fixtures.v1"
                or any(
                    type(row.get(key)) is not str or not row.get(key)
                    for key in (
                        "setUpOwner", "tearDownOwner",
                        "failureExceptionOwner",
                        "cleanupPolicy", "unsupportedFixturePolicy",
                    )
                )
                for row in execution_bindings
            )
            or group.get("executionBindingsDigest")
            != _task_test_domain_digest(
                b"qinao.task-test-execution-bindings.v1",
                execution_bindings,
            )
        ):
            raise AuditError("task test plan group identity drift")
        _require_lower_hex(
            group.get("groupDigest"), 64,
            "task test plan group digest",
        )
        unsigned_group = dict(group)
        unsigned_group.pop("groupDigest")
        if group["groupDigest"] != _task_test_domain_digest(
            b"qinao.task-test-plan-group.v1", unsigned_group
        ):
            raise AuditError("task test plan group digest drift")
        global_ids.update(ids)
        flattened.extend(ids)
        validated_groups.append(group)
    if (
        plan.get("flattenedTestIds") != flattened
        or plan.get("flattenedTestIdsDigest")
        != _task_test_domain_digest(
            b"qinao.task-test-flattened-ids.v1", flattened
        )
    ):
        raise AuditError("task test flattened plan drift")
    witness = _validate_task_test_activation_witness(
        plan.get("activationWitness"), module_manifest
    )
    if plan.get("activationWitnessDigest") != witness["witnessDigest"]:
        raise AuditError("task test plan activation digest drift")
    _require_lower_hex(
        plan.get("planDigest"), 64, "task test plan digest"
    )
    unsigned_plan = dict(plan)
    unsigned_plan.pop("planDigest")
    if plan["planDigest"] != _task_test_domain_digest(
        b"qinao.task-test-plan.v1", unsigned_plan
    ):
        raise AuditError("task test plan digest drift")
    plan["groups"] = validated_groups
    plan["activationWitness"] = witness
    return plan


def _validate_task_test_subject(subject: Any) -> Dict[str, Any]:
    if not isinstance(subject, Mapping):
        raise AuditError("task test subject shape drift")
    value = dict(subject)
    common_fields = {
        "schemaVersion", "runId", "identityDigest", "repository",
        "branch", "resultHeadOid", "resultTreeOid", "indexTreeOid",
        "cleanStatusSha256", "localConfigDigest",
        "protectedWitnessDigest", "frontierId",
        "frontierStartRecordDigest", "expectedTests",
        "expectedTestsDigest", "cleanScanTerminalRecordDigest",
        "cleanScanSubjectDigest", "outerInvocationStartRecordDigest",
        "invocationDigest", "argvDigest", "runtimeDigest",
        "importInventoryDigest", "moduleManifest",
        "moduleManifestDigest", "testPlan", "testPlanDigest",
        "subjectDigest",
    }
    version = value.get("schemaVersion")
    expected_fields = set(common_fields)
    if version in (
        "qinao.task-test-subject.v2",
        "qinao.task-test-subject.v3",
        "qinao.task-test-subject.v4",
        "qinao.task-test-subject.v5",
    ):
        expected_fields.update({
            "captureContractVersion", "captureContractDigest"
        })
    if version in ("qinao.task-test-subject.v3", "qinao.task-test-subject.v4", "qinao.task-test-subject.v5"):
        expected_fields.update({
            "executionContractVersion", "executionContractDigest"
        })
    if version in ("qinao.task-test-subject.v4", "qinao.task-test-subject.v5"):
        expected_fields.update({"scanResultRelation", "scanResultRelationDigest"})
    if version == "qinao.task-test-subject.v5":
        expected_fields.update({"outputContractVersion", "outputContractDigest"})
    if (
        version not in (
            "qinao.task-test-subject.v1",
            "qinao.task-test-subject.v2",
            "qinao.task-test-subject.v3",
            "qinao.task-test-subject.v4",
            "qinao.task-test-subject.v5",
        )
        or set(value) != expected_fields
        or not isinstance(value.get("repository"), str)
        or not Path(value["repository"]).is_absolute()
        or not isinstance(value.get("branch"), str)
        or not value["branch"].startswith("refs/heads/")
        or value.get("cleanStatusSha256") != _sha256(b"")
    ):
        raise AuditError("task test subject field drift")
    if version in (
        "qinao.task-test-subject.v2",
        "qinao.task-test-subject.v3",
        "qinao.task-test-subject.v4",
        "qinao.task-test-subject.v5",
    ) and (
        value.get("captureContractVersion") != 1
        or value.get("captureContractDigest")
        != _STRICT_PROCESS_FD_CAPTURE_CONTRACT_DIGEST
    ):
        raise AuditError("task test capture contract drift")
    if version in ("qinao.task-test-subject.v3", "qinao.task-test-subject.v4", "qinao.task-test-subject.v5") and (
        value.get("executionContractVersion") != {
            "qinao.task-test-subject.v3": 1,
            "qinao.task-test-subject.v4": 2,
            "qinao.task-test-subject.v5": 3,
        }[version]
        or not _task_execution_contract_matches(value)
    ):
        raise AuditError("task test execution contract drift")
    if version == "qinao.task-test-subject.v5" and (
        type(value.get("captureContractVersion")) is not int
        or type(value.get("outputContractVersion")) is not int
        or value["outputContractVersion"] != 1
        or value.get("outputContractDigest") != _TASK_TEST_OUTPUT_CONTRACT_DIGEST
    ):
        raise AuditError("task test subject output contract drift")
    _require_lower_hex(value.get("runId"), 32, "task test run ID")
    _require_lower_hex(value.get("frontierId"), 32, "task test frontier")
    for field in (
        "identityDigest", "localConfigDigest", "protectedWitnessDigest",
        "frontierStartRecordDigest", "expectedTestsDigest",
        "cleanScanTerminalRecordDigest", "cleanScanSubjectDigest",
        "invocationDigest", "argvDigest", "runtimeDigest",
        "importInventoryDigest", "moduleManifestDigest", "subjectDigest",
    ):
        _require_lower_hex(
            value.get(field), 64, "task test subject " + field
        )
    for field in ("resultHeadOid", "resultTreeOid", "indexTreeOid"):
        if re.fullmatch(
            r"[0-9a-f]{40}|[0-9a-f]{64}", str(value.get(field))
        ) is None:
            raise AuditError("task test Git subject drift")
    expected_tests = value.get("expectedTests")
    if (
        not isinstance(expected_tests, list)
        or not expected_tests
        or any(not isinstance(item, str) or not item for item in expected_tests)
        or len(expected_tests) != len(set(expected_tests))
        or value["expectedTestsDigest"]
        != _task_test_expected_tests_digest(expected_tests)
    ):
        raise AuditError("task test expected tests digest drift")
    _validate_task_test_module_manifest(value.get("moduleManifest"))
    if value["moduleManifestDigest"] != _sha256(
        canonical_json_bytes(value["moduleManifest"])
    ):
        raise AuditError("task test module manifest digest drift")
    plan = _validate_task_test_plan(
        value.get("testPlan"), expected_tests, value["moduleManifest"]
    )
    if value.get("testPlanDigest") != plan["planDigest"]:
        raise AuditError("task test subject plan digest drift")
    if version in ("qinao.task-test-subject.v4", "qinao.task-test-subject.v5"):
        relation = _validate_task_scan_result_relation_shape(value.get("scanResultRelation"))
        allowed_relations = (
            ("qinao.task-scan-result-relation.v3",)
            if version == "qinao.task-test-subject.v5"
            else ("qinao.task-scan-result-relation.v1", "qinao.task-scan-result-relation.v2")
        )
        if (
            relation["schemaVersion"] not in allowed_relations
            or value.get("scanResultRelationDigest") != relation["relationDigest"]
            or relation["resultCommitOid"] != value["resultHeadOid"]
            or relation["resultTreeOid"] != value["resultTreeOid"]
            or relation["scannedIndexTreeOid"] != value["indexTreeOid"]
            or relation["frontierStartRecordDigest"] != value["frontierStartRecordDigest"]
            or relation["scanTerminalRecordDigest"] != value["cleanScanTerminalRecordDigest"]
            or relation["scanSubjectDigest"] != value["cleanScanSubjectDigest"]
        ):
            raise AuditError("task subject scan/result relation drift")
    _verify_self_digest(value, "subjectDigest")
    return value


def _validate_task_test_capture_summary(
    value: Any, label: str, *, version: int = 1
) -> None:
    expected = {"byteCount", "sha256"}
    if version == 1:
        expected.add("captureComplete")
    if version not in (1, 2) or not isinstance(value, Mapping) or set(value) != expected:
        raise AuditError("task test " + label + " capture shape drift")
    if (
        not isinstance(value.get("byteCount"), int)
        or isinstance(value.get("byteCount"), bool)
        or value["byteCount"] < 0
        or value["byteCount"] > MAX_SAFE_INTEGER
        or (version == 1 and value.get("captureComplete") is not True)
    ):
        raise AuditError("task test " + label + " capture value drift")
    _require_lower_hex(
        value.get("sha256"), 64, "task test " + label + " digest"
    )


def _validate_task_test_target_result(value: Any) -> Dict[str, Any]:
    if not isinstance(value, Mapping):
        raise AuditError("task test target result shape drift")
    row = dict(value)
    version = row.get("schemaVersion")
    if set(row) != {
        "schemaVersion", "target", "testIds", "testIdsDigest",
        "startedTestIds", "finishedTestIds", "testsRun", "failures",
        "errors", "skips", "expectedFailures", "unexpectedSuccesses",
        "outcomes", "outcomesDigest", "stdout", "stderr",
        "successful", "targetResultDigest",
    } or version not in (
        "qinao.task-test-target-result.v1",
        "qinao.task-test-target-result.v2",
    ):
        raise AuditError("task test target result field drift")
    ids = row.get("testIds")
    target = row.get("target")
    if not isinstance(target, str):
        raise AuditError("task test target result selector drift")
    module_name, class_name = _parse_task_test_target(target)
    prefix = module_name + "." + class_name + "."
    if (
        not isinstance(ids, list)
        or not ids
        or any(not isinstance(item, str) or not item for item in ids)
        or len(ids) != len(set(ids))
        or ids != sorted(ids, key=lambda item: item.encode("utf-8"))
        or any(
            re.fullmatch(
                re.escape(prefix) + r"test[A-Za-z0-9_]+", item
            ) is None
            for item in ids
        )
        or row.get("startedTestIds") != ids
        or row.get("finishedTestIds") != ids
        or row.get("testsRun") != len(ids)
        or row.get("testIdsDigest") != _sha256(
            b"qinao.task-test-ids.v1\x00" + canonical_json_bytes(ids)
        )
    ):
        raise AuditError("task test target ID closure drift")
    outcomes = row.get("outcomes")
    if not isinstance(outcomes, list) or len(outcomes) != len(ids):
        raise AuditError("task test closed outcome count drift")
    validated_outcomes = []
    for identifier, candidate in zip(ids, outcomes):
        if (
            not isinstance(candidate, Mapping)
            or set(candidate) != {
                "schemaVersion", "testId", "closed", "category",
                "outcomeDigest",
            }
            or candidate.get("schemaVersion")
            != "qinao.task-test-outcome.v1"
            or candidate.get("testId") != identifier
            or candidate.get("closed") is not True
            or candidate.get("category")
            not in _TASK_TEST_OUTCOME_CATEGORIES
        ):
            raise AuditError("task test closed outcome identity drift")
        _require_lower_hex(
            candidate.get("outcomeDigest"), 64,
            "task test outcome digest",
        )
        _verify_self_digest(candidate, "outcomeDigest")
        validated_outcomes.append(dict(candidate))
    _require_lower_hex(
        row.get("outcomesDigest"), 64,
        "task test outcomes digest",
    )
    if row["outcomesDigest"] != _task_test_domain_digest(
        b"qinao.task-test-outcomes.v1", validated_outcomes
    ):
        raise AuditError("task test outcomes digest drift")
    derived = {
        field: [
            outcome["testId"]
            for outcome in validated_outcomes
            if outcome["category"] == category
        ]
        for field, category in (
            ("failures", "failure"),
            ("errors", "error"),
            ("skips", "skip"),
            ("expectedFailures", "expectedFailure"),
            ("unexpectedSuccesses", "unexpectedSuccess"),
        )
    }
    if any(row.get(field) != items for field, items in derived.items()):
        raise AuditError("task test outcome list derivation drift")
    successful = all(
        outcome["category"] in (
            "success", "skip", "expectedFailure"
        )
        for outcome in validated_outcomes
    )
    if row.get("successful") is not successful:
        raise AuditError("task test target success drift")
    capture_version = 2 if version.endswith(".v2") else 1
    _validate_task_test_capture_summary(
        row.get("stdout"), "stdout", version=capture_version
    )
    _validate_task_test_capture_summary(
        row.get("stderr"), "stderr", version=capture_version
    )
    _verify_self_digest(row, "targetResultDigest")
    return row


def _validate_task_test_terminal_result(value: Any) -> Dict[str, Any]:
    if not isinstance(value, Mapping):
        raise AuditError("task test terminal result shape drift")
    result = dict(value)
    version = result.get("schemaVersion")
    expected_fields = {
        "schemaVersion", "attemptId", "proofKeyDigest", "subjectDigest",
        "status", "reasonCode", "targetResults", "targetResultsDigest",
        "totalTestsRun", "resultDigest",
    }
    if version in (
        "qinao.task-test-result.v2",
        "qinao.task-test-result.v3",
        "qinao.task-test-result.v4",
        "qinao.task-test-result.v5",
    ):
        expected_fields.update({
            "captureContractVersion", "captureContractDigest",
            "captureEvidence", "captureEvidenceDigest",
        })
    if version in ("qinao.task-test-result.v3", "qinao.task-test-result.v4", "qinao.task-test-result.v5"):
        expected_fields.update({
            "executionContractVersion", "executionContractDigest",
            "terminalAuthority", "executionLeaseAcquiredRecordDigest",
        })
    if version in ("qinao.task-test-result.v4", "qinao.task-test-result.v5"):
        expected_fields.add("scanResultRelationDigest")
        _require_lower_hex(result.get("scanResultRelationDigest"), 64, "result relation")
    if version == "qinao.task-test-result.v5":
        expected_fields.update({
            "outputContractVersion", "outputContractDigest",
            "outputEvidence", "outputEvidenceDigest",
        })
    if set(result) != expected_fields or version not in (
        "qinao.task-test-result.v1", "qinao.task-test-result.v2",
        "qinao.task-test-result.v3",
        "qinao.task-test-result.v4",
        "qinao.task-test-result.v5",
    ):
        raise AuditError("task test terminal result field drift")
    _require_lower_hex(result.get("attemptId"), 32, "task test attempt")
    for field in ("proofKeyDigest", "subjectDigest", "targetResultsDigest"):
        _require_lower_hex(
            result.get(field), 64, "task test result " + field
        )
    rows = result.get("targetResults")
    if not isinstance(rows, list):
        raise AuditError("task test target results drift")
    validated = [_validate_task_test_target_result(row) for row in rows]
    expected_row_version = (
        "qinao.task-test-target-result.v2"
        if version in (
            "qinao.task-test-result.v2",
            "qinao.task-test-result.v3",
            "qinao.task-test-result.v4",
            "qinao.task-test-result.v5",
        ) else "qinao.task-test-target-result.v1"
    )
    if any(row.get("schemaVersion") != expected_row_version for row in validated):
        raise AuditError("task test result/row version mixing")
    if validated and any(
        row["stdout"] != validated[0]["stdout"]
        or row["stderr"] != validated[0]["stderr"]
        for row in validated
    ):
        raise AuditError("task test combined capture summary drift")
    if result["targetResultsDigest"] != _sha256(
        canonical_json_bytes(validated)
    ):
        raise AuditError("task test target results digest drift")
    total = sum(row["testsRun"] for row in validated)
    if result.get("totalTestsRun") != total:
        raise AuditError("task test total count drift")
    if version in (
        "qinao.task-test-result.v2",
        "qinao.task-test-result.v3",
        "qinao.task-test-result.v4",
        "qinao.task-test-result.v5",
    ):
        evidence = _validate_task_test_capture_evidence(
            result.get("captureEvidence")
        )
        if (
            result.get("captureContractVersion") != 1
            or result.get("captureContractDigest")
            != _STRICT_PROCESS_FD_CAPTURE_CONTRACT_DIGEST
            or result.get("captureEvidenceDigest")
            != evidence["captureEvidenceDigest"]
        ):
            raise AuditError("task test result capture binding drift")
        if validated and any(
            row["stdout"] != evidence["stdout"]
            or row["stderr"] != evidence["stderr"]
            for row in validated
        ):
            raise AuditError("task test row/capture evidence drift")
    if version in ("qinao.task-test-result.v3", "qinao.task-test-result.v4", "qinao.task-test-result.v5"):
        if (
            result.get("executionContractVersion") != {
                "qinao.task-test-result.v3": 1,
                "qinao.task-test-result.v4": 2,
                "qinao.task-test-result.v5": 3,
            }[version]
            or not _task_execution_contract_matches(result)
            or result.get("terminalAuthority") not in (
                "incumbent", "closedLeaseRecovery"
            )
        ):
            raise AuditError("task test result execution binding drift")
        _require_lower_hex(
            result.get("executionLeaseAcquiredRecordDigest"), 64,
            "task test result acquired lease",
        )
    status = result.get("status")
    reason = result.get("reasonCode")
    if status == "task-tests-success":
        if not validated or not all(row["successful"] for row in validated):
            raise AuditError("task test success result drift")
        if reason is not None:
            raise AuditError("task test success reason drift")
    elif status == "task-tests-failed":
        if not validated or all(row["successful"] for row in validated):
            raise AuditError("task test failed result drift")
        if reason != "test-failure":
            raise AuditError("task test failure reason drift")
    elif status == "task-tests-indeterminate-no-replay":
        allowed_reasons = (
            "durable-start-no-terminal", "subject-drift",
            "runner-indeterminate",
        )
        if version in (
            "qinao.task-test-result.v2",
            "qinao.task-test-result.v3",
            "qinao.task-test-result.v4",
            "qinao.task-test-result.v5",
        ):
            allowed_reasons += ("capture-incomplete",)
        retained_rows = (version == "qinao.task-test-result.v5"
                         and reason == "output-retention-incomplete")
        if retained_rows:
            if not validated or not total:
                raise AuditError("task test retention failure lacks observed rows")
        elif validated or total or reason not in allowed_reasons:
            raise AuditError("task test indeterminate result drift")
    else:
        raise AuditError("task test result status drift")
    if (
        version in (
            "qinao.task-test-result.v2",
            "qinao.task-test-result.v3",
            "qinao.task-test-result.v4",
            "qinao.task-test-result.v5",
        )
        and status in ("task-tests-success", "task-tests-failed")
        and result["captureEvidence"]["state"] != "SEALED"
    ):
        raise AuditError("task test completed without sealed capture")
    if version in (
        "qinao.task-test-result.v2",
        "qinao.task-test-result.v3",
        "qinao.task-test-result.v4",
        "qinao.task-test-result.v5",
    ):
        expected_evidence_state = {
            "task-tests-success": "SEALED",
            "task-tests-failed": "SEALED",
            "capture-incomplete": "INCOMPLETE",
            "durable-start-no-terminal": "UNAVAILABLE",
            "runner-indeterminate": "SEALED",
            "subject-drift": "SEALED",
            "output-retention-incomplete": "SEALED",
        }.get(reason if status == "task-tests-indeterminate-no-replay" else status)
        if evidence["state"] != expected_evidence_state:
            raise AuditError("task test reason/evidence state drift")
    if version == "qinao.task-test-result.v5":
        _validate_task_test_result_output(result)
    _verify_self_digest(result, "resultDigest")
    return result


def _validate_task_test_result_output(result: Mapping[str, Any]) -> None:
    """Check v5 retention metadata without substituting it for observation."""
    output = _validate_task_test_output_evidence(result.get("outputEvidence"))
    if (
        type(result.get("captureContractVersion")) is not int
        or type(result.get("outputContractVersion")) is not int
        or result["outputContractVersion"] != 1
        or result.get("outputContractDigest") != _TASK_TEST_OUTPUT_CONTRACT_DIGEST
        or output["outputContractDigest"] != result["outputContractDigest"]
        or result.get("outputEvidenceDigest") != output["outputEvidenceDigest"]
        or output["leaseAcquiredRecordDigest"]
        != result["executionLeaseAcquiredRecordDigest"]
        or output["captureEvidenceDigest"] != result["captureEvidenceDigest"]
    ):
        raise AuditError("task test result output contract drift")
    attempt = output["attempt"]
    if attempt is not None and any(
        attempt.get(field) != result.get(field)
        for field in ("attemptId", "subjectDigest", "proofKeyDigest")
    ):
        raise AuditError("task test result output attempt drift")
    complete = output["state"] == "SEALED_COMPLETE"
    if result["status"] in ("task-tests-success", "task-tests-failed") and not complete:
        raise AuditError("task test result lacks complete retained output")
    if result["reasonCode"] == "output-retention-incomplete" and complete:
        raise AuditError("task test retention failure has complete output")
    if complete:
        capture = result["captureEvidence"]
        if capture["state"] != "SEALED" or any(
            output["channels"][channel][field] != capture[channel][field]
            for channel in ("stdout", "stderr")
            for field in ("byteCount", "sha256")
        ):
            raise AuditError("task test retained/observed output drift")
    if result["terminalAuthority"] == "closedLeaseRecovery":
        if (
            result["status"] != "task-tests-indeterminate-no-replay"
            or result["reasonCode"] != "durable-start-no-terminal"
            or output["state"] != "UNAVAILABLE"
            or output["reasonCodes"] != ["capture-unavailable"]
            or output["ownerDigest"] is not None
            or output["attempt"] is not None
            or output["channels"] != {"stdout": None, "stderr": None}
            or output["sealedDigest"] is not None
        ):
            raise AuditError("closed lease recovery cannot adopt local output")
    elif result["reasonCode"] == "durable-start-no-terminal":
        raise AuditError("task test unavailable recovery lacks closed lease")


def _validate_task_test_attempt_start_shape(
    record: Mapping[str, Any],
) -> None:
    subject = _validate_task_test_subject(record.get("subject"))
    version = subject["schemaVersion"]
    capture_bound = version in (
        "qinao.task-test-subject.v2",
        "qinao.task-test-subject.v3",
        "qinao.task-test-subject.v4",
        "qinao.task-test-subject.v5",
    )
    for field, size in (
        ("attemptId", 32), ("frontierId", 32),
        ("frontierStartRecordDigest", 64),
        ("outerInvocationStartRecordDigest", 64),
        ("invocationDigest", 64), ("proofKeyDigest", 64),
        ("subjectDigest", 64), ("expectedTestsDigest", 64),
        ("testPlanDigest", 64),
    ):
        _require_lower_hex(record.get(field), size, "task test start " + field)
    if (
        record.get("inputDigest") != subject["subjectDigest"]
        or record.get("subjectDigest") != subject["subjectDigest"]
        or record.get("proofKeyDigest") != _task_test_proof_key(subject)
        or record.get("expectedTests") != subject["expectedTests"]
        or record.get("expectedTestsDigest")
        != subject["expectedTestsDigest"]
        or record.get("testPlanDigest") != subject["testPlanDigest"]
        or any(
            record.get(field) != subject.get(field)
            for field in (
                "frontierId", "frontierStartRecordDigest",
                "outerInvocationStartRecordDigest", "invocationDigest",
            )
        )
    ):
        raise AuditError("task test start binding drift")
    if capture_bound:
        if (
            record.get("captureContractVersion") != 1
            or record.get("captureContractDigest")
            != subject["captureContractDigest"]
        ):
            raise AuditError("task test v2 start capture drift")
    elif any(field in record for field in (
        "captureContractVersion", "captureContractDigest"
    )):
        raise AuditError("task test v1 start has v2 capture fields")
    if version in ("qinao.task-test-subject.v3", "qinao.task-test-subject.v4", "qinao.task-test-subject.v5"):
        _require_lower_hex(
            record.get("executionLeaseAcquiredRecordDigest"), 64,
            "task test start acquired lease",
        )
    elif "executionLeaseAcquiredRecordDigest" in record:
        raise AuditError("legacy task test start has lease authority")
    output_fields = ("outputContractVersion", "outputContractDigest")
    if version == "qinao.task-test-subject.v5":
        if (
            type(record.get("captureContractVersion")) is not int
            or type(record.get("outputContractVersion")) is not int
            or any(record.get(field) != subject[field] for field in output_fields)
        ):
            raise AuditError("task test start output contract drift")
    elif any(field in record for field in output_fields):
        raise AuditError("legacy task test start has output contract")


def _validate_task_test_attempt_terminal_shape(
    record: Mapping[str, Any],
) -> None:
    result = _validate_task_test_terminal_result(record.get("result"))
    version = result["schemaVersion"]
    capture_bound = version in (
        "qinao.task-test-result.v2",
        "qinao.task-test-result.v3",
        "qinao.task-test-result.v4",
        "qinao.task-test-result.v5",
    )
    for field, size in (
        ("attemptId", 32), ("invocationStartRecordDigest", 64),
        ("frontierId", 32), ("frontierStartRecordDigest", 64),
        ("outerInvocationStartRecordDigest", 64),
        ("invocationDigest", 64), ("proofKeyDigest", 64),
        ("subjectDigest", 64), ("resultRecordDigest", 64),
    ):
        _require_lower_hex(
            record.get(field), size, "task test terminal " + field
        )
    expected_exit = {
        "task-tests-success": 0,
        "task-tests-failed": 1,
        "task-tests-indeterminate-no-replay": 2,
    }[record["completionState"]]
    if (
        record.get("inputDigest") != result["resultDigest"]
        or record.get("resultRecordDigest") != result["resultDigest"]
        or record.get("attemptId") != result["attemptId"]
        or record.get("proofKeyDigest") != result["proofKeyDigest"]
        or record.get("subjectDigest") != result["subjectDigest"]
        or record.get("targetResults") != result["targetResults"]
        or record.get("totalTestsRun") != result["totalTestsRun"]
        or record.get("completionState") != result["status"]
        or record.get("exitCode") != expected_exit
    ):
        raise AuditError("task test terminal binding drift")
    if capture_bound:
        evidence = _validate_task_test_capture_evidence(
            record.get("captureEvidence")
        )
        if (
            record.get("captureContractVersion") != 1
            or record.get("captureContractDigest")
            != result["captureContractDigest"]
            or record.get("captureEvidenceDigest")
            != evidence["captureEvidenceDigest"]
            or record.get("captureEvidence") != result["captureEvidence"]
        ):
            raise AuditError("task test v2 terminal capture drift")
    elif any(field in record for field in (
        "captureContractVersion", "captureContractDigest",
        "captureEvidence", "captureEvidenceDigest",
    )):
        raise AuditError("task test v1 terminal has v2 capture fields")
    if version in ("qinao.task-test-result.v3", "qinao.task-test-result.v4", "qinao.task-test-result.v5"):
        if (
            record.get("terminalAuthority")
            != result.get("terminalAuthority")
            or record.get("executionLeaseAcquiredRecordDigest")
            != result.get("executionLeaseAcquiredRecordDigest")
        ):
            raise AuditError("task test terminal lease authority drift")
    elif any(field in record for field in (
        "terminalAuthority", "executionLeaseAcquiredRecordDigest",
    )):
        raise AuditError("legacy task test terminal has lease authority")
    output_fields = (
        "outputContractVersion", "outputContractDigest",
        "outputEvidence", "outputEvidenceDigest",
    )
    if version == "qinao.task-test-result.v5":
        if (
            type(record.get("captureContractVersion")) is not int
            or type(record.get("outputContractVersion")) is not int
            or any(record.get(field) != result[field] for field in output_fields)
        ):
            raise AuditError("task test terminal output binding drift")
    elif any(field in record for field in output_fields):
        raise AuditError("legacy task test terminal has retained output")


_TASK_TEST_EXECUTION_LEASE_ACQUIRED_FIELDS = (
    "executionContractVersion", "executionContractDigest", "leaseId",
    "holderId", "generation", "frontierId",
    "frontierStartRecordDigest", "outerInvocationStartRecordDigest",
    "invocationDigest", "expectedTestsDigest",
    "predecessorLeaseTerminalRecordDigest", "lockName", "lockIdentity",
    "lockIdentityDigest", "releaseRule", "authorityScope",
)
_TASK_TEST_EXECUTION_LEASE_TERMINAL_FIELDS = (
    "executionContractVersion", "executionContractDigest", "leaseId",
    "holderId", "generation", "frontierId",
    "frontierStartRecordDigest", "leaseAcquiredRecordDigest",
    "lockIdentityDigest", "disposition", "attemptBinding",
    "attemptStartRecordDigest", "taskTestTerminalRecordDigest",
)


def _validate_task_test_execution_lease_acquired_shape(
    record: Mapping[str, Any],
) -> None:
    if (
        not _task_execution_contract_matches(record)
        or record.get("lockName") != "ledger/identity.json"
        or record.get("releaseRule") != "darwin-flock-close-only-v1"
        or record.get("authorityScope")
        != "cooperative-canonical-root-v1"
        or not isinstance(record.get("generation"), int)
        or isinstance(record.get("generation"), bool)
        or record["generation"] < 1
    ):
        raise AuditError("task test execution lease acquisition drift")
    for field in ("leaseId", "holderId"):
        value = record.get(field)
        if type(value) is not str or re.fullmatch(
            r"[0-9a-f]{32}|[0-9a-f]{64}", value
        ) is None:
            raise AuditError("task test execution lease identity drift")
    _require_lower_hex(
        record.get("frontierId"), 32,
        "task test execution lease frontier",
    )
    for field in (
        "frontierStartRecordDigest", "outerInvocationStartRecordDigest",
        "invocationDigest", "expectedTestsDigest",
        "executionContractDigest", "lockIdentityDigest",
    ):
        _require_lower_hex(
            record.get(field), 64,
            "task test execution lease " + field,
        )
    predecessor = record.get("predecessorLeaseTerminalRecordDigest")
    if predecessor is not None:
        _require_lower_hex(
            predecessor, 64,
            "task test execution lease predecessor",
        )
    lock_identity = record.get("lockIdentity")
    if (
        not isinstance(lock_identity, Mapping)
        or set(lock_identity) != {
            "device", "inode", "mode", "linkCount", "identityDigest",
        }
        or type(lock_identity.get("device")) is not str
        or re.fullmatch(
            r"0|[1-9][0-9]*", lock_identity["device"]
        ) is None
        or type(lock_identity.get("inode")) is not str
        or re.fullmatch(
            r"0|[1-9][0-9]*", lock_identity["inode"]
        ) is None
        or lock_identity.get("mode") != "0600"
        or lock_identity.get("linkCount") != 1
    ):
        raise AuditError("task test execution lease lock identity drift")
    _require_lower_hex(
        lock_identity.get("identityDigest"), 64,
        "task test execution root identity",
    )
    if record.get("lockIdentityDigest") != _sha256(
        canonical_json_bytes(dict(lock_identity))
    ):
        raise AuditError("task test execution lock digest drift")
    acquisition_input = {
        "schemaVersion": _task_lease_input_schema("acquisition", record),
        **{
            field: record.get(field)
            for field in _TASK_TEST_EXECUTION_LEASE_ACQUIRED_FIELDS
        },
    }
    if record.get("inputDigest") != _sha256(
        canonical_json_bytes(acquisition_input)
    ):
        raise AuditError("task test execution lease input drift")


def _validate_task_test_execution_lease_terminal_shape(
    record: Mapping[str, Any],
) -> None:
    if (
        not _task_execution_contract_matches(record)
        or not isinstance(record.get("generation"), int)
        or isinstance(record.get("generation"), bool)
        or record["generation"] < 1
        or record.get("disposition") not in (
            "completed", "reused-success", "preactivation-failed",
            "owner-unwound", "owner-lost",
        )
        or record.get("attemptBinding") not in (
            "absent", "running", "terminal", "reused",
        )
    ):
        raise AuditError("task test execution lease terminal drift")
    for field in ("leaseId", "holderId"):
        value = record.get(field)
        if type(value) is not str or re.fullmatch(
            r"[0-9a-f]{32}|[0-9a-f]{64}", value
        ) is None:
            raise AuditError("task test execution lease identity drift")
    _require_lower_hex(
        record.get("frontierId"), 32,
        "task test execution lease frontier",
    )
    for field in (
        "executionContractDigest", "frontierStartRecordDigest",
        "leaseAcquiredRecordDigest", "lockIdentityDigest",
    ):
        _require_lower_hex(
            record.get(field), 64,
            "task test execution lease terminal " + field,
        )
    start_digest = record.get("attemptStartRecordDigest")
    terminal_digest = record.get("taskTestTerminalRecordDigest")
    if start_digest is not None:
        _require_lower_hex(
            start_digest, 64,
            "task test execution attempt start",
        )
    if terminal_digest is not None:
        _require_lower_hex(
            terminal_digest, 64,
            "task test execution attempt terminal",
        )
    binding = record["attemptBinding"]
    expected_shapes = {
        "absent": (False, False),
        "running": (True, False),
        "terminal": (True, True),
        "reused": (True, True),
    }
    if expected_shapes[binding] != (
        start_digest is not None, terminal_digest is not None
    ):
        raise AuditError("task test execution attempt binding drift")
    disposition = record["disposition"]
    allowed_bindings = {
        "completed": {"terminal"},
        "reused-success": {"reused"},
        "preactivation-failed": {"absent"},
        "owner-unwound": {"running"},
        "owner-lost": {"absent", "running", "terminal"},
    }
    if binding not in allowed_bindings[disposition]:
        raise AuditError("task test execution disposition drift")
    terminal_input = {
        "schemaVersion": _task_lease_input_schema("terminal", record),
        **{
            field: record.get(field)
            for field in _TASK_TEST_EXECUTION_LEASE_TERMINAL_FIELDS
        },
    }
    if record.get("inputDigest") != _sha256(
        canonical_json_bytes(terminal_input)
    ):
        raise AuditError("task test execution lease terminal input drift")


_GIT_CAPSULE_PREPARATION_FIELDS = frozenset(
    {
        "schemaVersion", "preparationId", "intentDigest", "generation",
        "profile", "preflightRecordDigest", "stableProjectionDigest",
        "repository", "sourceOid", "predecessorTerminalRecordDigest",
        "lockName", "lockIdentity", "lockIdentityDigest", "releaseRule",
    }
)


def _git_capsule_preparation_intent(
    profile: str,
    preflight_record_digest: str,
    stable_projection_digest: Optional[str],
    repository: str,
    source_oid: Optional[str],
) -> Dict[str, Any]:
    return {
        "schemaVersion": "qinao.git-execution-capsule-preparation-intent.v1",
        "profile": profile,
        "preflightRecordDigest": preflight_record_digest,
        "stableProjectionDigest": stable_projection_digest,
        "repository": repository,
        "sourceOid": source_oid,
    }


def _validate_git_capsule_preparation(value: Any) -> Dict[str, Any]:
    if not isinstance(value, Mapping):
        raise AuditError("Git execution capsule preparation shape drift")
    preparation = dict(value)
    if (
        set(preparation) != _GIT_CAPSULE_PREPARATION_FIELDS
        or preparation.get("schemaVersion")
        != "qinao.git-execution-capsule-preparation.v1"
        or preparation.get("profile")
        not in {
            "credential-read", "ls-remote-read",
            "fetch-quarantine", "push-outbound",
        }
        or not isinstance(preparation.get("generation"), int)
        or isinstance(preparation.get("generation"), bool)
        or preparation["generation"] < 1
        or preparation.get("lockName") != "preparation.lock"
        or preparation.get("releaseRule")
        != "darwin-flock-close-only-v1"
    ):
        raise AuditError("Git execution capsule preparation shape drift")
    _require_lower_hex(
        preparation.get("preparationId"), 32,
        "Git execution capsule preparation ID",
    )
    for field in (
        "intentDigest", "preflightRecordDigest", "lockIdentityDigest",
    ):
        _require_lower_hex(
            preparation.get(field), 64,
            "Git execution capsule preparation " + field,
        )
    stable = preparation.get("stableProjectionDigest")
    if stable is not None:
        _require_lower_hex(
            stable, 64, "Git execution capsule stable projection"
        )
    predecessor = preparation.get("predecessorTerminalRecordDigest")
    if predecessor is not None:
        _require_lower_hex(
            predecessor, 64,
            "Git execution capsule preparation predecessor",
        )
    repository = preparation.get("repository")
    if (
        not isinstance(repository, str)
        or not Path(repository).is_absolute()
    ):
        raise AuditError("Git execution capsule preparation repository drift")
    source_oid = preparation.get("sourceOid")
    if source_oid is not None and (
        not isinstance(source_oid, str)
        or re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", source_oid)
        is None
    ):
        raise AuditError("Git execution capsule preparation source drift")
    if (preparation["profile"] == "push-outbound") != (
        source_oid is not None
    ):
        raise AuditError("Git execution capsule preparation source/profile drift")
    if (preparation["profile"] == "credential-read") != (stable is None):
        raise AuditError(
            "Git execution capsule preparation projection/profile drift"
        )
    lock_identity = preparation.get("lockIdentity")
    if (
        not isinstance(lock_identity, Mapping)
        or set(lock_identity) != {
            "device", "inode", "mode", "linkCount"
        }
        or not isinstance(lock_identity.get("device"), str)
        or re.fullmatch(r"0|[1-9][0-9]*", lock_identity["device"])
        is None
        or not isinstance(lock_identity.get("inode"), str)
        or re.fullmatch(r"0|[1-9][0-9]*", lock_identity["inode"])
        is None
        or lock_identity.get("mode") != "0600"
        or lock_identity.get("linkCount") != 1
        or preparation["lockIdentityDigest"]
        != _sha256(canonical_json_bytes(dict(lock_identity)))
    ):
        raise AuditError("Git execution capsule preparation lock drift")
    expected_intent = _git_capsule_preparation_intent(
        preparation["profile"],
        preparation["preflightRecordDigest"],
        stable,
        repository,
        source_oid,
    )
    if preparation["intentDigest"] != _sha256(
        canonical_json_bytes(expected_intent)
    ):
        raise AuditError("Git execution capsule preparation intent drift")
    return preparation


def _validate_git_capsule_preparation_terminal_shape(
    record: Mapping[str, Any],
) -> None:
    _require_lower_hex(
        record.get("resourceId"), 32,
        "Git execution capsule preparation resource",
    )
    _require_lower_hex(
        record.get("preparationId"), 32,
        "Git execution capsule preparation ID",
    )
    for field in (
        "intentDigest", "allocationRecordDigest", "snapshotDigest",
        "snapshotRecordDigest",
    ):
        _require_lower_hex(
            record.get(field), 64,
            "Git execution capsule preparation terminal " + field,
        )
    generation = record.get("generation")
    disposition = record.get("disposition")
    capsule_digest = record.get("capsuleRecordDigest")
    if (
        not isinstance(generation, int)
        or isinstance(generation, bool)
        or generation < 1
        or disposition not in {
            "prepared", "owner-lost-preserved",
            "owner-unwound-preserved",
        }
        or record.get("completionState")
        != (
            "prepared"
            if disposition == "prepared"
            else "preserved-incomplete"
        )
    ):
        raise AuditError("Git execution capsule preparation terminal drift")
    if disposition == "prepared":
        _require_lower_hex(
            capsule_digest, 64,
            "Git execution capsule prepared descriptor",
        )
    elif capsule_digest is not None:
        raise AuditError("incomplete Git execution capsule was promoted")
    terminal_input = {
        "schemaVersion": "qinao.git-execution-capsule-preparation-terminal-input.v1",
        **{
            field: record.get(field)
            for field in (
                "resourceId", "preparationId", "intentDigest",
                "generation", "allocationRecordDigest", "disposition",
                "snapshotDigest", "snapshotRecordDigest",
                "capsuleRecordDigest",
            )
        },
    }
    if record.get("inputDigest") != _sha256(
        canonical_json_bytes(terminal_input)
    ):
        raise AuditError("Git execution capsule terminal input drift")


_NETWORK_PREFLIGHT_FAILURE_CLASSES = frozenset(
    {
        "LiveProjectionDrift",
        "CredentialUnavailable",
        "CredentialIdentityDrift",
        "CredentialGenerationDrift",
        "ExecutionCapsuleUnavailable",
        "BrokerBindingDrift",
        "InterruptedBeforeNetworkAttempt",
    }
)


def _validate_network_execution_reservation_shape(
    record: Mapping[str, Any],
) -> None:
    for field, size in (
        ("useKey", 64),
        ("frontierId", 32),
        ("argvDigest", 64),
        ("preflightRecordDigest", 64),
        ("stableProjectionDigest", 64),
        ("manifestRecordDigest", 64),
        ("requestId", 64),
        ("rowDigest", 64),
    ):
        _require_lower_hex(
            record.get(field), size, "network execution reservation " + field
        )
    try:
        specification = _network_operation_contract(record.get("operation"))
    except AuditError as exc:
        raise AuditError("network execution reservation operation drift") from exc
    lock_identity = record.get("lockIdentity")
    if (
        record.get("inputDigest") != record.get("useKey")
        or record.get("manifestSchemaVersion")
        != "qinao.network-request-manifest.v2"
        or record.get("wrapper") != specification.get("wrapper")
        or not isinstance(record.get("requestSequence"), int)
        or isinstance(record.get("requestSequence"), bool)
        or record["requestSequence"] < 1
        or record.get("maximumUses") != 1
        or record.get("lockName") != "ledger/identity.json"
        or record.get("releaseRule")
        != "darwin-flock-close-only-v1"
        or not isinstance(lock_identity, Mapping)
        or set(lock_identity) != {
            "device", "inode", "mode", "linkCount", "identityDigest",
        }
        or record.get("lockIdentityDigest")
        != _sha256(canonical_json_bytes(dict(lock_identity)))
        or record.get("useKey")
        != _network_request_use_key(
            record["manifestRecordDigest"], record["requestId"], 1
        )
    ):
        raise AuditError("network execution reservation binding drift")
    _require_lower_hex(
        record.get("lockIdentityDigest"),
        64,
        "network execution reservation lock identity",
    )
    if (
        type(lock_identity.get("device")) is not str
        or re.fullmatch(r"0|[1-9][0-9]*", lock_identity["device"])
        is None
        or type(lock_identity.get("inode")) is not str
        or re.fullmatch(r"0|[1-9][0-9]*", lock_identity["inode"])
        is None
        or lock_identity.get("mode") != "0600"
        or lock_identity.get("linkCount") != 1
    ):
        raise AuditError("network execution reservation lock drift")
    _require_lower_hex(
        lock_identity.get("identityDigest"),
        64,
        "network execution reservation root identity",
    )


def _validate_network_preflight_terminal_shape(
    record: Mapping[str, Any],
) -> None:
    _require_lower_hex(
        record.get("useKey"), 64, "network preflight terminal use key"
    )
    _require_lower_hex(
        record.get("reservationRecordDigest"),
        64,
        "network preflight reservation record",
    )
    if (
        record.get("inputDigest")
        != record.get("reservationRecordDigest")
        or record.get("networkAttempted") is not False
        or record.get("failureClass")
        not in _NETWORK_PREFLIGHT_FAILURE_CLASSES
    ):
        raise AuditError("network preflight terminal binding drift")


def _validate_risk_completed_shape(record: Mapping[str, Any]) -> None:
    result = record.get("riskResult")
    if not isinstance(result, Mapping):
        raise AuditError("risk completed result shape drift")
    _verify_self_digest(result)
    schema = result.get("schemaVersion")
    required = {
        "schemaVersion",
        "sourceIdentityDigest",
        "rawDiffSha256",
        "rawManifestDigest",
        "rawEntryCount",
        "contentObservationDigest",
        "effectiveClass",
        "reasonCodes",
        "recordDigest",
    }
    if schema == "qinao.risk-result.v2":
        required.add("classifierBindingDigest")
    elif schema != "qinao.risk-result.v1":
        raise AuditError("risk completed result schema drift")
    optional = {"B", "H", "T", "V", "prBodySha256"}
    if set(result) - required - optional or not required.issubset(result):
        raise AuditError("risk completed result field drift")
    for field in (
        "sourceIdentityDigest",
        "rawDiffSha256",
        "rawManifestDigest",
        "contentObservationDigest",
        "recordDigest",
    ):
        _require_lower_hex(result.get(field), 64, "risk result " + field)
    if schema == "qinao.risk-result.v2":
        _require_lower_hex(
            result.get("classifierBindingDigest"),
            64,
            "risk result classifier binding",
        )
    for field in ("B", "H", "T"):
        if field in result:
            _require_lower_hex(result[field], 40, "risk result " + field)
    for field in ("V", "prBodySha256"):
        if field in result:
            _require_lower_hex(result[field], 64, "risk result " + field)
    reasons = result.get("reasonCodes")
    if (
        type(result.get("rawEntryCount")) is not int
        or result["rawEntryCount"] < 0
        or result.get("effectiveClass") not in ("routine", "high")
        or not isinstance(reasons, list)
        or any(type(reason) is not str or not reason for reason in reasons)
        or reasons != sorted(set(reasons))
        or record.get("inputDigest") != result.get("recordDigest")
        or record.get("sourceIdentityDigest")
        != result.get("sourceIdentityDigest")
        or record.get("contentObservationDigest")
        != result.get("contentObservationDigest")
    ):
        raise AuditError("risk completed result binding drift")


def _validate_ledger_record_shape(record: Mapping[str, Any]) -> None:
    if not isinstance(record, Mapping):
        raise AuditError("ledger record must be an object")
    if record.get("schemaVersion") != "qinao.ledger-record.v1":
        raise AuditError("ledger record schema drift")
    kind = record.get("operationKind")
    registry = _LEDGER_OPERATION_FIELDS.get(kind)
    if registry is None:
        raise AuditError("unknown ledger operation kind")
    required, optional, completion_states = registry
    fields_set = set(record)
    if not (_LEDGER_BASE_FIELDS | required).issubset(fields_set):
        raise AuditError("ledger operation omitted required field")
    if fields_set - (_LEDGER_BASE_FIELDS | required | optional):
        raise AuditError("ledger operation has unknown field")
    if record.get("completionState") not in completion_states:
        raise AuditError("ledger operation completion-state drift")
    _require_lower_hex(record.get("inputDigest"), 64, "ledger input digest")
    _require_lower_hex(record.get("previousRecordDigest"), 64, "previous record")
    _require_lower_hex(record.get("recordDigest"), 64, "record digest")
    record_id = record.get("recordId")
    if not isinstance(record_id, str) or re.fullmatch(r"[0-9a-f]{32}", record_id) is None:
        raise AuditError("ledger record ID drift")
    declared = record.get("declaredFilenames")
    if (
        not isinstance(declared, list)
        or any(not isinstance(name, str) or "\x00" in name for name in declared)
        or len(declared) != len(set(declared))
    ):
        raise AuditError("ledger declared filename drift")
    if kind == "frontier-start" and record.get("declaredPaths") != declared:
        raise AuditError("frontier declared filename/path drift")
    if kind in _CLEANUP_KINDS:
        disposition = _validate_cleanup_disposition(record.get("cleanupDisposition"))
        if (declared or disposition["ownerKind"] != _CLEANUP_KINDS[kind]
                or record.get("inputDigest") != disposition["recordDigest"]):
            raise AuditError("cleanup record envelope drift")
    if kind in (
        "sterile-invocation-started",
        "sterile-invocation-started-linked",
    ):
        invocation = record.get("invocation")
        if not isinstance(invocation, Mapping):
            raise AuditError("sterile invocation start shape drift")
        if kind == "sterile-invocation-started-linked":
            _validate_linked_sterile_invocation(invocation)
        else:
            _verify_self_digest(invocation)
        if (
            invocation.get("schemaVersion")
            != "qinao.sterile-invocation.v1"
            or record.get("inputDigest")
            != invocation.get("recordDigest")
        ):
            raise AuditError("sterile invocation start digest drift")
    elif kind in (
        "sterile-invocation-completed",
        "sterile-invocation-completed-linked",
    ):
        invocation_digest = record.get("invocationDigest")
        exit_code = record.get("exitCode")
        _require_lower_hex(
            invocation_digest, 64, "sterile invocation digest"
        )
        if (
            not isinstance(exit_code, int)
            or isinstance(exit_code, bool)
            or exit_code not in (0, 1, 2)
            or (
                record.get("completionState")
                != ("complete" if exit_code == 0 else "failed")
            )
        ):
            raise AuditError("sterile invocation exit/state drift")
        if kind == "sterile-invocation-completed":
            if record.get("inputDigest") != invocation_digest:
                raise AuditError(
                    "legacy sterile invocation input digest drift"
                )
        else:
            start_digest = record.get(
                "invocationStartRecordDigest"
            )
            _require_lower_hex(
                start_digest,
                64,
                "sterile invocation start record digest",
            )
            if record.get("inputDigest") != start_digest:
                raise AuditError(
                    "linked sterile invocation input digest drift"
                )
    if kind == "secret-scan-capture-reserved":
        _validate_secret_scan_reservation_shape(record)
    elif kind == "secret-scan-capture-materialized":
        for field, size in (
            ("captureId", 32), ("frontierId", 32),
            ("recoveryKey", 64), ("bindingDigest", 64),
            ("reservationRecordDigest", 64),
        ):
            _require_lower_hex(
                record.get(field), size, "secret scan materialization " + field
            )
        absolute = record.get("absolutePath")
        if (
            record.get("inputDigest") != record.get("recoveryKey")
            or record.get("outputName") != "secret-scan.json"
            or not isinstance(record.get("repository"), str)
            or not Path(record["repository"]).is_absolute()
            or not isinstance(absolute, str)
            or not Path(absolute).is_absolute()
            or record.get("outputPath")
            != str(Path(absolute) / "secret-scan.json")
        ):
            raise AuditError("secret scan materialization projection drift")
    elif kind == "secret-scan-invocation-started":
        _validate_secret_scan_invocation_start_shape(record)
    elif kind == "secret-scan-terminal":
        _validate_secret_scan_terminal_shape(record)
    elif kind == "secret-scan-terminal-selected":
        _validate_secret_scan_terminal_selection_shape(record)
    elif kind == "task-test-attempt-started":
        _validate_task_test_attempt_start_shape(record)
    elif kind == "task-test-attempt-terminal":
        _validate_task_test_attempt_terminal_shape(record)
    elif kind == "task-test-execution-lease-acquired":
        _validate_task_test_execution_lease_acquired_shape(record)
    elif kind == "task-test-execution-lease-terminal":
        _validate_task_test_execution_lease_terminal_shape(record)
    elif kind == "resource-allocated":
        preparation = record.get("preparation")
        if preparation is None:
            if record.get("inputDigest") != _sha256(
                (
                    str(record.get("resourceKind")) + "\0"
                    + str(record.get("resourceId"))
                ).encode("ascii")
            ):
                raise AuditError("resource allocation input drift")
        else:
            if record.get("resourceKind") != "git-execution-capsule":
                raise AuditError("non-capsule resource has preparation")
            validated = _validate_git_capsule_preparation(preparation)
            allocation_input = {
                "schemaVersion": "qinao.git-execution-capsule-allocation-input.v1",
                "resourceId": record.get("resourceId"),
                "resourceKind": record.get("resourceKind"),
                "absolutePath": record.get("absolutePath"),
                "preparation": validated,
            }
            if record.get("inputDigest") != _sha256(
                canonical_json_bytes(allocation_input)
            ):
                raise AuditError("Git execution capsule allocation input drift")
    elif kind == "git-execution-capsule-preparation-terminal":
        _validate_git_capsule_preparation_terminal_shape(record)
    elif kind == "network-execution-reserved":
        _validate_network_execution_reservation_shape(record)
    elif kind == "network-preflight-terminal":
        _validate_network_preflight_terminal_shape(record)
    elif kind == "risk-completed":
        _validate_risk_completed_shape(record)
    if kind in ("capture-sealed", "content-observation-sealed"):
        if not declared:
            raise AuditError("capture seal declared filename drift")
    elif kind not in ("frontier-start", "frontier-complete", "task-resumption", "task-correction") and declared:
        raise AuditError("unexpected ledger declared filenames")


_KNOWN_CHAIN_TERMINALS = frozenset({
    "task-correction",
    "task-resumption",
    "policy-capture-prepared", "policy-capture-started",
    "policy-capture-completed", "policy-capture-failed",
    "bootstrap-completed", "frontier-start", "frontier-complete",
    "capture-allocated", "capture-sealed",
    "content-observation-allocated", "content-observation-sealed",
    "secret-scan-capture-reserved", "secret-scan-capture-materialized",
    "secret-scan-invocation-started", "secret-scan-terminal",
    "secret-scan-terminal-selected",
    "task-test-attempt-started", "task-test-attempt-terminal",
    "task-test-execution-lease-acquired",
    "task-test-execution-lease-terminal",
    "risk-completed", "capture-forensic-incomplete",
    "resource-allocated", "resource-snapshot",
    "git-execution-capsule-preparation-terminal",
    "git-capsule-cleanup-settled", "network-cleanup-settled",
    "git-execution-capsule-consumed", "git-execution-capsule-tainted",
    "git-state-snapshot",
    "sterile-invocation-started",
    "sterile-invocation-started-linked",
    "sterile-invocation-completed",
    "sterile-invocation-completed-linked",
    "network-execution-reserved", "network-preflight-terminal",
    "network-attempt", "network-observation", "network-terminal",
})


def _validate_recovered_record_chain(
    identity: Mapping[str, Any],
    named_records: Sequence[Tuple[str, Mapping[str, Any]]],
) -> List[Dict[str, Any]]:
    records: List[Dict[str, Any]] = []
    previous = identity["identityDigest"]
    seen_ids = set()
    for expected, (name, candidate) in enumerate(named_records, 1):
        if name != "%016d.json" % expected:
            raise AuditError("record sequence gap or unexpected filename")
        record = dict(candidate)
        _verify_self_digest(record)
        _validate_ledger_record_shape(record)
        if (
            record.get("sequence") != expected
            or record.get("runId") != identity.get("runId")
        ):
            raise AuditError("record identity or sequence mismatch")
        if record.get("previousRecordDigest") != previous:
            raise AuditError("record chain fork")
        record_id = record.get("recordId")
        if not isinstance(record_id, str) or record_id in seen_ids:
            raise AuditError("duplicate record ID")
        seen_ids.add(record_id)
        previous = record["recordDigest"]
        records.append(record)
    if (
        not records
        or records[-1].get("operationKind") not in _KNOWN_CHAIN_TERMINALS
    ):
        raise AuditError("terminal chain state unknown")
    return records


def _recover_records_fd(
    transaction: LedgerTransaction,
) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    identity = transaction.read_canonical_at(
        transaction._fds["ledger"], "identity.json"
    )
    _verify_self_digest(identity, "identityDigest")
    names = transaction.list_directory(
        transaction.directory_fd("records")
    )
    named_records = [
        (
            name,
            transaction.read_canonical_at(
                transaction.directory_fd("records"), name
            ),
        )
        for name in names
    ]
    return identity, _validate_recovered_record_chain(
        identity, named_records
    )


def _resource_manifest_fd(
    transaction: LedgerTransaction, resource_fd: _ChildFdOwnerSlot
) -> List[Dict[str, Any]]:
    entries: List[Dict[str, Any]] = []
    files: List[Tuple[int, _ChildFdOwnerSlot, str, os.stat_result]] = []
    aggregate_bytes = 0

    def discover(
        directory_fd: _ChildFdOwnerSlot, prefix: Tuple[str, ...]
    ) -> None:
        nonlocal aggregate_bytes
        for name in transaction.list_directory(directory_fd):
            relative_parts = prefix + (name,)
            if len(relative_parts) > MAX_RESOURCE_DEPTH:
                raise AuditError("resource depth exceeds bound")
            relative = b"/".join(
                os.fsencode(component) for component in relative_parts
            )
            if len(relative) > MAX_RESOURCE_PATH_BYTES:
                raise AuditError("resource path exceeds bound")
            if len(entries) >= MAX_RESOURCE_ENTRIES:
                raise AuditError("resource entry count exceeds bound")
            observed = _fd_at(directory_fd, os.stat, name, follow_symlinks=False)
            row: Dict[str, Any] = {
                "pathB64": base64.b64encode(relative).decode("ascii"),
                "mode": "%04o" % stat.S_IMODE(observed.st_mode),
                "size": 0,
                "sha256": None,
            }
            if stat.S_ISDIR(observed.st_mode):
                row["type"] = "directory"
                entries.append(row)
                child_fd = transaction.open_directory_at(
                    directory_fd, name, expected_mode=None
                )
                discover(child_fd, relative_parts)
                continue
            if not stat.S_ISREG(observed.st_mode):
                raise AuditError("resource symlink or special file")
            if observed.st_nlink != 1:
                raise AuditError("resource hard link surprise")
            aggregate_bytes += observed.st_size
            if aggregate_bytes > MAX_RESOURCE_BYTES:
                raise AuditError("aggregate resource bytes exceed bound")
            row["type"] = "file"
            row["size"] = observed.st_size
            index = len(entries)
            entries.append(row)
            files.append((index, directory_fd, name, observed))

    discover(resource_fd, ())
    flags = (
        os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
        | getattr(os, "O_CLOEXEC", 0)
    )
    stable = lambda value: (
        value.st_dev, value.st_ino, value.st_mode, value.st_nlink,
        value.st_size, value.st_mtime_ns,
    )
    for index, parent_fd, name, expected in files:
        descriptor = transaction._open_member_at(parent_fd, name, flags)
        primary: Optional[BaseException] = None
        try:
            before = _fd_call(descriptor, os.fstat)
            visible = _fd_at(parent_fd, os.stat, name, follow_symlinks=False)
            if (
                not stat.S_ISREG(before.st_mode)
                or before.st_nlink != 1
                or stable(before) != stable(expected)
                or stable(before) != stable(visible)
            ):
                raise AuditError("resource file changed before hash")
            digest = hashlib.sha256()
            byte_count = 0
            while True:
                chunk = _fd_call(descriptor, os.read, 1024 * 1024)
                if not chunk:
                    break
                byte_count += len(chunk)
                if byte_count > expected.st_size:
                    raise AuditError("resource file grew during hash")
                digest.update(chunk)
            after = _fd_call(descriptor, os.fstat)
            visible_after = _fd_at(parent_fd, os.stat, name, follow_symlinks=False)
            if (
                byte_count != expected.st_size
                or stable(before) != stable(after)
                or stable(before) != stable(visible_after)
            ):
                raise AuditError("resource file changed during hash")
            entries[index]["sha256"] = digest.hexdigest()
        except BaseException as exc:
            primary = exc
            raise
        finally:
            _close_fd_slots([descriptor], primary)
    transaction.revalidate()
    entries.sort(key=lambda row: base64.b64decode(row["pathB64"]))
    return entries


def _recover_records_at(ledger: Path) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    ledger = Path(ledger)
    _ordinary_directory(ledger, 0o700)
    identity = _read_canonical_file(ledger / "identity.json")
    _verify_self_digest(identity, "identityDigest")
    _ordinary_file(ledger / "lock", expected_mode=0o600)
    records_dir = ledger / "records"
    _ordinary_directory(records_dir, 0o700)
    names = sorted(path.name for path in records_dir.iterdir())
    named_records = [
        (name, _read_canonical_file(records_dir / name)) for name in names
    ]
    return identity, _validate_recovered_record_chain(
        identity, named_records
    )


def _recover_records(root: Path) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    root = _absolute_path_without_symlink_resolution(Path(root))
    with LedgerTransaction(
        root, operation_kind="ledger-record-recovery"
    ) as transaction:
        return _recover_records_fd(transaction)


def _validate_frontier_kind(frontier_kind: Any) -> str:
    if (
        not isinstance(frontier_kind, str)
        or frontier_kind not in SUPPORTED_FRONTIER_KINDS
    ):
        raise AuditError("unknown frontier kind")
    return frontier_kind


def _validate_current_task_publication(
    transaction: LedgerTransaction, record: Mapping[str, Any]
) -> None:
    """Raw publication is a new write, never historical read/adoption."""
    if record.get("operationKind") == "task-correction":
        _validate_ledger_record_shape(record)
        state = transaction.recover()
        if (record.get("sequence") != state["nextSequence"]
            or record.get("previousRecordDigest") != state["records"][-1]["recordDigest"]):
            raise AuditError("task correction publication lineage drift")
        _validate_task3_correction(transaction, state, record, live=True)
        return
    if record.get("operationKind") == "task-resumption":
        _validate_ledger_record_shape(record)
        state = transaction.recover()
        if (record.get("sequence") != state["nextSequence"]
            or record.get("previousRecordDigest") != state["records"][-1]["recordDigest"]):
            raise AuditError("task resumption publication lineage drift")
        _validate_task3_resumption(transaction, state, record, live=True)
        return
    if record.get("frontierKind") != "task" or record.get("operationKind") not in (
        "frontier-start", "frontier-complete"
    ):
        return
    _validate_ledger_record_shape(record)
    state = transaction.recover()
    if (
        record.get("sequence") != state["nextSequence"]
        or record.get("previousRecordDigest") != state["records"][-1]["recordDigest"]
        or record.get("runId") != state["identity"]["runId"]
    ):
        raise AuditError("current task raw publication lineage drift")
    if record["operationKind"] == "frontier-start":
        baseline = _validate_task_start(record, state["identity"])
        if baseline != _observe_task_start(
            state["identity"], baseline["taskNumber"],
            record["declaredPaths"], record["expectedTests"],
        ):
            raise AuditError("current task raw baseline drift")
        if record.get("parentFrontierId") is not None or any(
            row.get("parentFrontierId") is None for row in state["openFrontiers"]
        ):
            raise AuditError("current task raw start has an open peer or parent")
    else:
        starts = [row for row in state["openFrontiers"]
                  if row["frontierId"] == record.get("frontierId")]
        proof = record.get("taskCompletion")
        if (
            len(starts) != 1 or not isinstance(proof, Mapping)
            or record.get("completionState") != "completed"
            or record.get("inputDigest") != starts[0]["inputDigest"]
            or record.get("declaredFilenames") != starts[0]["declaredPaths"]
            or any(row.get("parentFrontierId") == starts[0]["frontierId"]
                   for row in state["openFrontiers"])
        ):
            raise AuditError("current task raw completion authority absent")
        if proof != _ordinary_task_completion(
            starts[0], state, proof.get("resultCommitOid"),
            completion_sequence=record["sequence"], live=True,
            task_correction_record_digest=proof.get("taskCorrectionRecordDigest"),
        ):
            raise AuditError("current task raw completion proof drift")


