            (b"classification", b"exact-live-clean-4a-no-sequencer"),
            (b"config_raw_sha256", FROZEN_RAW_CONFIG_DIGEST.encode("ascii")),
            (b"config_canonical_sha256", FROZEN_CONFIG_DIGEST.encode("ascii")),
