def _network_raw_bytes(
    value: Any, label: str, maximum: int, *, allow_empty: bool = False
) -> bytes:
    if (
        not isinstance(value, bytes)
        or (not value and not allow_empty)
        or len(value) > maximum
    ):
        raise AuditError(label + " raw bytes drift")
    return value


def _network_redacted_value(
    domain: str, value: bytes
) -> Dict[str, Any]:
    digest = hashlib.sha256()
    digest.update(b"qinao.network-redaction.v1\x00")
    digest.update(domain.encode("ascii", "strict"))
    digest.update(b"\x00")
    digest.update(value)
    return {"byteCount": len(value), "valueDigest": digest.hexdigest()}


def _network_environment_name_is_forbidden(name: str) -> bool:
    return name in _NETWORK_FORBIDDEN_ENVIRONMENT_EXACT or any(
        name.startswith(prefix)
        for prefix in _NETWORK_FORBIDDEN_ENVIRONMENT_PREFIXES
    )


def _network_config_key_is_forbidden(
    key: str, scope: str, value: bytes
) -> bool:
    if key == "http.followredirects":
        return not (
            scope == "command" and value.lower() in (b"false", b"never")
        )
    if key == "include.path" or re.fullmatch(
        r"includeif\..+\.path", key
    ):
        return True
    if key == "credential.helper":
        return not (scope == "system" and value == b"osxkeychain")
    if key.startswith("credential."):
        return True
    if re.fullmatch(
        r"remote\.[^.]+\.(?:pushurl|push|mirror|uploadpack|receivepack|proxy|"
        r"lfsurl|lfspushurl|promisor|partialclonefilter)",
        key,
    ):
        return True
    if re.fullmatch(r"url\..+\.(?:insteadof|pushinsteadof)", key):
        return True
    if key == "remote.pushdefault" or key.startswith("push."):
        return True
    if re.fullmatch(r"branch\.[^.]+\.pushremote", key):
        return True
    if key in {
        "lfs.url", "lfs.pushurl", "core.gitproxy", "core.sshcommand",
        "core.alternaterefscommand", "core.askpass",
    }:
        return True
    if key in {"protocol.allow", "protocol.version", "extensions.partialclone"}:
        return True
    if re.fullmatch(r"protocol\.[^.]+\.allow", key):
        return True
    if re.fullmatch(
        r"http(?:\..+)?\.(?:proxy|extraheader|sslverify|sslcert|sslkey|"
        r"sslcainfo|sslcapath|followredirects|curloptresolve|cookiefile|"
        r"savecookies|pinnedpubkey|sslbackend|proxyauthmethod)",
        key,
    ):
        return True
    return False


def _validate_network_egress_surface(
    raw: Mapping[str, Any],
) -> Dict[str, Any]:
    """Close and redact one ephemeral network-egress observation.

    Raw config, environment, tool, LFS, and CA bytes are deliberately accepted
    only at this boundary.  The returned value is JSON-safe and contains no raw
    caller value; every value-bearing row is domain-separated before hashing.
    """

    raw = _require_mapping(raw, "network egress raw surface")
    if (
        set(raw) != _NETWORK_RAW_SURFACE_FIELDS
        or raw.get("schemaVersion") != "qinao.network-egress-raw-surface.v1"
    ):
        raise AuditError("network egress raw surface field drift")
    repository = raw.get("repository")
    if not isinstance(repository, str) or not repository.startswith("/"):
        raise AuditError("network egress repository must be absolute")
    if raw.get("remoteName") != "origin":
        raise AuditError("network egress remote name drift")

    config_rows_value = raw.get("configRows")
    if not isinstance(config_rows_value, list) or not config_rows_value:
        raise AuditError("network egress config rows are absent")
    config_rows: List[Dict[str, Any]] = []
    for expected_sequence, row_value in enumerate(config_rows_value, 1):
        row = _require_mapping(row_value, "network config row")
        if set(row) != {"sequence", "scope", "originRole", "key", "value"}:
            raise AuditError("network config row field drift")
        scope = row.get("scope")
        origin_role = row.get("originRole")
        key = row.get("key")
        if (
            row.get("sequence") != expected_sequence
            or scope not in _NETWORK_CONFIG_ORIGIN_FOR_SCOPE
            or origin_role != _NETWORK_CONFIG_ORIGIN_FOR_SCOPE.get(scope)
            or not isinstance(key, str)
            or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9./:-]*", key) is None
        ):
            raise AuditError("network config row identity drift")
        value = _network_raw_bytes(
            row.get("value"),
            "network config value",
            1024 * 1024,
            allow_empty=True,
        )
        normalized_key = key.lower()
        if _network_config_key_is_forbidden(normalized_key, scope, value):
            raise AuditError("network config contains a forbidden routing key")
        if normalized_key == "remote.origin.url" and value != _NETWORK_GIT_ENDPOINT.encode("ascii"):
            raise AuditError("network config fetch endpoint drift")
        config_rows.append(
            {
                "sequence": expected_sequence,
                "scope": scope,
                "originRole": origin_role,
                "key": key,
                **_network_redacted_value("config:" + key, value),
            }
        )

    config_files_value = _require_mapping(
        raw.get("configFiles"), "network config files"
    )
    if set(config_files_value) != _NETWORK_CONFIG_FILE_NAMES:
        raise AuditError("network config file field drift")
    config_files = []
    for name in sorted(_NETWORK_CONFIG_FILE_NAMES):
        value = config_files_value.get(name)
        if value is None:
            config_files.append({"name": name, "state": "absent"})
            continue
        payload = _network_raw_bytes(
            value,
            "network config file",
            16 * 1024 * 1024,
            allow_empty=True,
        )
        config_files.append(
            {
                "name": name,
                "state": "present",
                "byteCount": len(payload),
                "sha256": _sha256(payload),
            }
        )
    tracked_lfs = config_files_value.get("trackedLfsConfig")
    worktree_lfs = config_files_value.get("worktreeLfsConfig")
    if tracked_lfs != worktree_lfs:
        raise AuditError("tracked and worktree LFS config drift")
    if (
        isinstance(tracked_lfs, bytes)
        and _sha256(tracked_lfs) not in _NETWORK_REVIEWED_LFS_CONFIG_DIGESTS
    ):
        raise AuditError("unreviewed LFS config")

    urls = _require_mapping(raw.get("resolvedUrls"), "resolved network URLs")
    if set(urls) != {"fetch", "push", "lfs", "github"}:
        raise AuditError("resolved network URL field drift")
    if (
        urls.get("fetch") != [_NETWORK_GIT_ENDPOINT]
        or urls.get("push") != [_NETWORK_GIT_ENDPOINT]
        or urls.get("lfs") != _NETWORK_LFS_ENDPOINT
        or urls.get("github") != _NETWORK_GITHUB_ENDPOINT
    ):
        raise AuditError("resolved network destination drift")

    lfs_value = _require_mapping(raw.get("lfs"), "network LFS surface")
    if set(lfs_value) != {"versionBytes", "environmentRows"}:
        raise AuditError("network LFS surface field drift")
    lfs_version = _network_raw_bytes(
        lfs_value.get("versionBytes"), "git-lfs version", 64 * 1024
    )
    if re.fullmatch(rb"git-lfs/[0-9]+(?:\.[0-9]+){1,3}[^\r\n]*\n", lfs_version) is None:
        raise AuditError("git-lfs version framing drift")
    lfs_rows_value = lfs_value.get("environmentRows")
    if not isinstance(lfs_rows_value, list) or not lfs_rows_value:
        raise AuditError("git-lfs environment is absent")
    lfs_rows = []
    lfs_names = set()
    for row_value in lfs_rows_value:
        row = _require_mapping(row_value, "git-lfs environment row")
        if set(row) != {"name", "value"}:
            raise AuditError("git-lfs environment row field drift")
        name = row.get("name")
        if (
            not isinstance(name, str)
            or re.fullmatch(r"[A-Za-z][A-Za-z0-9]+", name) is None
            or name in lfs_names
        ):
            raise AuditError("git-lfs environment row identity drift")
        lfs_names.add(name)
        value = _network_raw_bytes(
            row.get("value"),
            "git-lfs environment value",
            1024 * 1024,
            allow_empty=True,
        )
        if name.lower().endswith("endpoint"):
            expected_endpoint = _NETWORK_LFS_ENDPOINT.encode("ascii")
            if not (
                value == expected_endpoint
                or value.startswith(expected_endpoint + b" (auth=")
                and value.endswith(b")")
            ):
                raise AuditError("git-lfs environment endpoint drift")
        lfs_rows.append(
            {"name": name, **_network_redacted_value("lfs:" + name, value)}
        )
    if "Endpoint" not in lfs_names:
        raise AuditError("git-lfs endpoint observation is absent")

    environment_value = _require_mapping(
        raw.get("environment"), "network process environment"
    )
    environment_rows = []
    for name in sorted(environment_value):
        value = environment_value[name]
        if (
            not isinstance(name, str)
            or re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name) is None
            or not isinstance(value, str)
            or "\x00" in value
        ):
            raise AuditError("forbidden network process environment surface")
        if (
            _network_environment_name_is_forbidden(name)
            and _NETWORK_SAFE_FORCED_ENVIRONMENT.get(name) != value
        ):
            raise AuditError("forbidden network process environment surface")
        encoded = value.encode("utf-8", "strict")
        if len(encoded) > 1024 * 1024:
            raise AuditError("network process environment value exceeds bound")
        environment_rows.append(
            {"name": name}
        )

    tools_value = _require_mapping(raw.get("tools"), "network tool surface")
    if set(tools_value) != _NETWORK_TOOL_NAMES:
        raise AuditError("network tool surface field drift")
    tool_rows = []
    version_patterns = {
        "git": rb"git version ([0-9]+(?:\.[0-9]+){1,3})[^\r\n]*\n",
        "git-lfs": rb"git-lfs/([0-9]+(?:\.[0-9]+){1,3})[^\r\n]*\n",
        "gh": rb"gh version ([0-9]+(?:\.[0-9]+){1,3})[^\r\n]*\n",
        "python": rb"Python ([0-9]+(?:\.[0-9]+){1,3})[^\r\n]*\n",
    }
    for name in sorted(_NETWORK_TOOL_NAMES):
        tool = _require_mapping(tools_value[name], "network tool identity")
        expected_tool_fields = {"absolutePath", "fileBytes", "versionBytes"}
        if name == "git-credential-osxkeychain":
            expected_tool_fields.add("fileMode")
        if set(tool) != expected_tool_fields:
            raise AuditError("network tool identity field drift")
        path = tool.get("absolutePath")
        if not isinstance(path, str) or not path.startswith("/") or "\x00" in path:
            raise AuditError("network tool path drift")
        if name == "sh" and path != _NETWORK_GIT_SUPERVISOR_EXECUTABLE:
            raise AuditError("network supervisor interpreter path drift")
        file_mode: Optional[int] = None
        if name == "git-credential-osxkeychain":
            file_mode = tool.get("fileMode")
            if (
                not isinstance(file_mode, int)
                or isinstance(file_mode, bool)
                or file_mode != stat.S_IMODE(file_mode)
                or not file_mode & stat.S_IXUSR
                or Path(path).name != "git-credential-osxkeychain"
            ):
                raise AuditError("network credential helper identity drift")
        file_bytes = _network_raw_bytes(
            tool.get("fileBytes"), "network tool file", 256 * 1024 * 1024
        )
        version_bytes = _network_raw_bytes(
            tool.get("versionBytes"), "network tool version", 64 * 1024,
            allow_empty=name == "sh",
        )
        if name == "sh" and version_bytes != b"":
            raise AuditError("network supervisor version observation must be empty")
        parsed_version: Optional[str] = None
        pattern = version_patterns.get(name)
        if pattern is not None:
            match = re.fullmatch(pattern, version_bytes)
            if match is None:
                raise AuditError("network tool version framing drift")
            parsed_version = match.group(1).decode("ascii", "strict")
        row = {
            "name": name,
            "absolutePathDigest": _network_redacted_value(
                "tool-path:" + name, path.encode("utf-8", "strict")
            )["valueDigest"],
            "fileByteCount": len(file_bytes),
            "fileSha256": _sha256(file_bytes),
            "versionByteCount": len(version_bytes),
            "versionSha256": _sha256(version_bytes),
            "parsedVersion": parsed_version,
        }
        if name == "git-credential-osxkeychain":
            row["absolutePath"] = path
            row["fileMode"] = file_mode
        elif name == "sh":
            row["absolutePath"] = path
        tool_rows.append(row)

    capabilities = raw.get("gitCapabilities")
    if capabilities != list(_NETWORK_GIT_CAPABILITIES):
        raise AuditError("network Git capability surface drift")

    tls_value = _require_mapping(raw.get("tls"), "network TLS surface")
    if set(tls_value) != {
        "stdlibFiles", "sslModuleBytes", "opensslVersion", "defaultCABytes"
    }:
        raise AuditError("network TLS surface field drift")
    stdlib_value = _require_mapping(tls_value.get("stdlibFiles"), "TLS stdlib files")
    if not stdlib_value:
        raise AuditError("TLS stdlib file surface is absent")
    stdlib_rows = []
    for name in sorted(stdlib_value):
        if (
            not isinstance(name, str)
            or not name
            or "/" in name
            or "\x00" in name
        ):
            raise AuditError("TLS stdlib file identity drift")
        payload = _network_raw_bytes(
            stdlib_value[name], "TLS stdlib file", 64 * 1024 * 1024
        )
        stdlib_rows.append(
            {"name": name, "byteCount": len(payload), "sha256": _sha256(payload)}
        )
    ssl_module = _network_raw_bytes(
        tls_value.get("sslModuleBytes"), "TLS ssl module", 256 * 1024 * 1024
    )
    ca_bytes = _network_raw_bytes(
        tls_value.get("defaultCABytes"), "TLS default CA", 64 * 1024 * 1024
    )
    openssl_version = tls_value.get("opensslVersion")
    if (
        not isinstance(openssl_version, str)
        or re.fullmatch(
            r"(?:OpenSSL|LibreSSL) [A-Za-z0-9 ._+-]+", openssl_version
        ) is None
    ):
        raise AuditError("OpenSSL version drift")

    risk_value = _require_mapping(
        raw.get("transportRisk"), "network transport risk surface"
    )
    if set(risk_value) != {
        "ordinaryObjects", "replacementRefs", "alternates", "promisorRemotes"
    }:
        raise AuditError("network transport risk field drift")
    ordinary_objects = risk_value.get("ordinaryObjects")
    if (
        not isinstance(ordinary_objects, list)
        or len(set(ordinary_objects)) != len(ordinary_objects)
        or any(
            not isinstance(oid, str)
            or re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", oid) is None
            for oid in ordinary_objects
        )
    ):
        raise AuditError("ordinary object observation drift")
    stable_risk = {}
    for name in ("replacementRefs", "alternates", "promisorRemotes"):
        rows = risk_value.get(name)
        if not isinstance(rows, list):
            raise AuditError("network redirection risk row drift")
        try:
            payload = canonical_json_bytes(rows)
        except (AuditError, TypeError, ValueError) as exc:
            raise AuditError("network redirection risk row drift") from exc
        stable_risk[name + "Count"] = len(rows)
        stable_risk[name + "Digest"] = _sha256(payload)

    return {
        "schemaVersion": "qinao.network-egress-validated-surface.v1",
        "repository": repository,
        "remoteName": "origin",
        "config": {"rows": config_rows, "files": config_files},
        "resolvedUrls": dict(urls),
        "lfs": {
            "versionByteCount": len(lfs_version),
            "versionSha256": _sha256(lfs_version),
            "environmentRows": lfs_rows,
        },
        "environmentRows": environment_rows,
        "tools": tool_rows,
        "gitCapabilities": list(capabilities),
        "tls": {
            "stdlibFiles": stdlib_rows,
            "sslModuleByteCount": len(ssl_module),
            "sslModuleSha256": _sha256(ssl_module),
            "opensslVersion": openssl_version,
            "defaultCAByteCount": len(ca_bytes),
            "defaultCASha256": _sha256(ca_bytes),
        },
        "transportRisk": {
            "ordinaryObjectCount": len(ordinary_objects),
            "ordinaryObjectStateDigest": _sha256(
                canonical_json_bytes(ordinary_objects)
            ),
            **stable_risk,
        },
        "forbiddenSurfaceCount": 0,
    }


def _validate_network_egress_double_read(
    first_raw: Mapping[str, Any], second_raw: Mapping[str, Any]
) -> Dict[str, Any]:
    """Validate both ephemeral reads and return only the redacted surface."""

    first_validated = _validate_network_egress_surface(first_raw)
    _validate_network_egress_surface(second_raw)
    if first_raw != second_raw:
        raise AuditError("concurrent network egress observation drift")
    return first_validated


def _network_projection_count(value: Any, label: str) -> int:
    if (
        not isinstance(value, int)
        or isinstance(value, bool)
        or value < 0
        or value > 256 * 1024 * 1024
    ):
        raise AuditError(label + " count drift")
    return value


def _network_projection_digest(value: Any, label: str) -> str:
    return _require_lower_hex(value, 64, label)


def _validate_network_validated_projection_shape(
    validated: Mapping[str, Any],
    *, _tool_mode: str = "current",
) -> Dict[str, Any]:
    """Reopen every nested field of a redacted egress projection.

    A self-digest proves only that bytes are internally consistent.  This
    validator supplies the missing type authority: no caller-defined nested
    field, raw byte value, or secret-looking string is admitted by re-signing.
    """

    validated = _require_mapping(validated, "validated network egress surface")
    required = {
        "schemaVersion", "repository", "remoteName", "config", "resolvedUrls",
        "lfs", "environmentRows", "tools", "gitCapabilities", "tls",
        "transportRisk", "forbiddenSurfaceCount",
    }
    if (
        set(validated) != required
        or validated.get("schemaVersion")
        != "qinao.network-egress-validated-surface.v1"
    ):
        raise AuditError("validated network egress surface field drift")
    repository = validated.get("repository")
    if (
        not isinstance(repository, str)
        or not repository.startswith("/")
        or "\x00" in repository
        or len(repository.encode("utf-8", "strict")) > 16 * 1024
        or validated.get("remoteName") != "origin"
        or validated.get("forbiddenSurfaceCount") != 0
    ):
        raise AuditError("validated network egress identity drift")

    config = _require_mapping(validated.get("config"), "network config projection")
    if set(config) != {"rows", "files"}:
        raise AuditError("network config projection field drift")
    config_rows = config.get("rows")
    if not isinstance(config_rows, list) or not config_rows:
        raise AuditError("network config projection rows are absent")
    origin_url_count = 0
    for sequence, row_value in enumerate(config_rows, 1):
        row = _require_mapping(row_value, "network config projection row")
        if set(row) != {
            "sequence", "scope", "originRole", "key", "byteCount",
            "valueDigest",
        }:
            raise AuditError("network config projection row field drift")
        scope = row.get("scope")
        key = row.get("key")
        if (
            row.get("sequence") != sequence
            or scope not in _NETWORK_CONFIG_ORIGIN_FOR_SCOPE
            or row.get("originRole")
            != _NETWORK_CONFIG_ORIGIN_FOR_SCOPE.get(scope)
            or not isinstance(key, str)
            or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9./:-]*", key) is None
        ):
            raise AuditError("network config projection row identity drift")
        byte_count = _network_projection_count(
            row.get("byteCount"), "network config projection value"
        )
        value_digest = _network_projection_digest(
            row.get("valueDigest"), "network config projection value"
        )
        normalized_key = key.lower()
        redacted_value = {
            "byteCount": byte_count, "valueDigest": value_digest,
        }
        if normalized_key == "credential.helper":
            if (
                scope != "system"
                or redacted_value != _network_redacted_value(
                    "config:" + key, b"osxkeychain"
                )
            ):
                raise AuditError(
                    "network config projection contains a routing key"
                )
        elif _network_config_key_is_forbidden(
            normalized_key, scope, b"false"
        ):
            raise AuditError("network config projection contains a routing key")
        if normalized_key == "remote.origin.url":
            origin_url_count += 1
            expected = _network_redacted_value(
                "config:" + key, _NETWORK_GIT_ENDPOINT.encode("ascii")
            )
            if redacted_value != expected:
                raise AuditError("network config projection endpoint drift")
        if normalized_key == "http.followredirects":
            admitted = {
                tuple(sorted(_network_redacted_value(
                    "config:" + key, value
                ).items()))
                for value in (b"false", b"never")
            }
            if tuple(sorted(redacted_value.items())) not in admitted:
                raise AuditError("network redirect projection drift")
    if origin_url_count != 1:
        raise AuditError("network config projection origin endpoint drift")

    config_files = config.get("files")
    if not isinstance(config_files, list) or len(config_files) != len(
        _NETWORK_CONFIG_FILE_NAMES
    ):
        raise AuditError("network config file projection drift")
    for expected_name, row_value in zip(
        sorted(_NETWORK_CONFIG_FILE_NAMES), config_files
    ):
        row = _require_mapping(row_value, "network config file projection")
        state = row.get("state")
        expected_fields = (
            {"name", "state"}
            if state == "absent"
            else {"name", "state", "byteCount", "sha256"}
        )
        if (
            set(row) != expected_fields
            or row.get("name") != expected_name
            or state not in ("absent", "present")
        ):
            raise AuditError("network config file projection field drift")
        if state == "present":
            _network_projection_count(
                row.get("byteCount"), "network config file projection"
            )
            _network_projection_digest(
                row.get("sha256"), "network config file projection"
            )

    urls = _require_mapping(validated.get("resolvedUrls"), "resolved network URLs")
    if set(urls) != {"fetch", "push", "lfs", "github"} or dict(urls) != {
        "fetch": [_NETWORK_GIT_ENDPOINT],
        "push": [_NETWORK_GIT_ENDPOINT],
        "lfs": _NETWORK_LFS_ENDPOINT,
        "github": _NETWORK_GITHUB_ENDPOINT,
    }:
        raise AuditError("resolved network destination projection drift")

    lfs = _require_mapping(validated.get("lfs"), "network LFS projection")
    if set(lfs) != {"versionByteCount", "versionSha256", "environmentRows"}:
        raise AuditError("network LFS projection field drift")
    _network_projection_count(lfs.get("versionByteCount"), "network LFS version")
    _network_projection_digest(lfs.get("versionSha256"), "network LFS version")
    lfs_rows = lfs.get("environmentRows")
    if not isinstance(lfs_rows, list) or not lfs_rows:
        raise AuditError("network LFS environment projection is absent")
    lfs_names = set()
    for row_value in lfs_rows:
        row = _require_mapping(row_value, "network LFS environment projection row")
        if set(row) != {"name", "byteCount", "valueDigest"}:
            raise AuditError("network LFS environment projection field drift")
        name = row.get("name")
        if (
            not isinstance(name, str)
            or re.fullmatch(r"[A-Za-z][A-Za-z0-9]+", name) is None
            or name in lfs_names
        ):
            raise AuditError("network LFS environment projection identity drift")
        lfs_names.add(name)
        _network_projection_count(
            row.get("byteCount"), "network LFS environment projection"
        )
        _network_projection_digest(
            row.get("valueDigest"), "network LFS environment projection"
        )
    if "Endpoint" not in lfs_names:
        raise AuditError("network LFS endpoint projection is absent")

    environment_rows = validated.get("environmentRows")
    if not isinstance(environment_rows, list):
        raise AuditError("network environment projection drift")
    environment_names = []
    for row_value in environment_rows:
        row = _require_mapping(row_value, "network environment projection row")
        name = row.get("name")
        if (
            set(row) != {"name"}
            or not isinstance(name, str)
            or re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name) is None
            or (
                _network_environment_name_is_forbidden(name)
                and name not in _NETWORK_SAFE_FORCED_ENVIRONMENT
            )
        ):
            raise AuditError("network environment projection identity drift")
        environment_names.append(name)
    if environment_names != sorted(set(environment_names)):
        raise AuditError("network environment projection ordering drift")

    tools = validated.get("tools")
    tool_names = _network_projection_tool_names(_tool_mode)
    if not isinstance(tools, list) or len(tools) != len(tool_names):
        raise AuditError("network tool projection drift")
    for expected_name, row_value in zip(sorted(tool_names), tools):
        row = _require_mapping(row_value, "network tool projection row")
        expected_tool_fields = {
            "name", "absolutePathDigest", "fileByteCount", "fileSha256",
            "versionByteCount", "versionSha256", "parsedVersion",
        }
        if expected_name == "git-credential-osxkeychain":
            expected_tool_fields.update({"absolutePath", "fileMode"})
        elif expected_name == "sh":
            expected_tool_fields.add("absolutePath")
        if set(row) != expected_tool_fields or row.get("name") != expected_name:
            raise AuditError("network tool projection field drift")
        _network_projection_digest(
            row.get("absolutePathDigest"), "network tool path"
        )
        _network_projection_count(row.get("fileByteCount"), "network tool file")
        _network_projection_digest(row.get("fileSha256"), "network tool file")
        _network_projection_count(
            row.get("versionByteCount"), "network tool version"
        )
        _network_projection_digest(
            row.get("versionSha256"), "network tool version"
        )
        version = row.get("parsedVersion")
        if expected_name in {"git", "git-lfs", "gh", "python"}:
            if (
                not isinstance(version, str)
                or re.fullmatch(r"[0-9]+(?:\.[0-9]+){1,3}", version) is None
            ):
                raise AuditError("network tool parsed version drift")
        elif version is not None:
            raise AuditError("network tool unparsed version drift")
        if expected_name == "sh" and (
            row.get("absolutePath") != _NETWORK_GIT_SUPERVISOR_EXECUTABLE
            or row.get("absolutePathDigest") != _network_redacted_value(
                "tool-path:sh", _NETWORK_GIT_SUPERVISOR_EXECUTABLE.encode("utf-8", "strict")
            )["valueDigest"]
            or row.get("fileByteCount") == 0
            or row.get("versionByteCount") != 0
            or row.get("versionSha256") != _sha256(b"")
        ):
            raise AuditError("network supervisor interpreter projection drift")
        if expected_name == "git-credential-osxkeychain":
            helper_path = row.get("absolutePath")
            helper_mode = row.get("fileMode")
            if (
                not isinstance(helper_path, str)
                or not helper_path.startswith("/")
                or "\x00" in helper_path
                or Path(helper_path).name != "git-credential-osxkeychain"
                or row.get("absolutePathDigest")
                != _network_redacted_value(
                    "tool-path:git-credential-osxkeychain",
                    helper_path.encode("utf-8", "strict"),
                )["valueDigest"]
                or not isinstance(helper_mode, int)
                or isinstance(helper_mode, bool)
                or helper_mode != stat.S_IMODE(helper_mode)
                or not helper_mode & stat.S_IXUSR
            ):
                raise AuditError("network credential helper projection drift")

    if validated.get("gitCapabilities") != list(_NETWORK_GIT_CAPABILITIES):
        raise AuditError("network Git capability projection drift")

    tls = _require_mapping(validated.get("tls"), "network TLS projection")
    if set(tls) != {
        "stdlibFiles", "sslModuleByteCount", "sslModuleSha256",
        "opensslVersion", "defaultCAByteCount", "defaultCASha256",
    }:
        raise AuditError("network TLS projection field drift")
    stdlib_files = tls.get("stdlibFiles")
    if not isinstance(stdlib_files, list) or not stdlib_files:
        raise AuditError("network TLS stdlib projection is absent")
    stdlib_names = []
    for row_value in stdlib_files:
        row = _require_mapping(row_value, "network TLS stdlib projection row")
        name = row.get("name")
        if (
            set(row) != {"name", "byteCount", "sha256"}
            or not isinstance(name, str)
            or not name
            or "/" in name
            or "\x00" in name
        ):
            raise AuditError("network TLS stdlib projection identity drift")
        stdlib_names.append(name)
        _network_projection_count(row.get("byteCount"), "network TLS stdlib")
        _network_projection_digest(row.get("sha256"), "network TLS stdlib")
    if stdlib_names != sorted(set(stdlib_names)):
        raise AuditError("network TLS stdlib projection ordering drift")
    for count_name, digest_name in (
        ("sslModuleByteCount", "sslModuleSha256"),
        ("defaultCAByteCount", "defaultCASha256"),
    ):
        _network_projection_count(tls.get(count_name), "network TLS material")
        _network_projection_digest(tls.get(digest_name), "network TLS material")
    openssl_version = tls.get("opensslVersion")
    if (
        not isinstance(openssl_version, str)
        or re.fullmatch(r"(?:OpenSSL|LibreSSL) [A-Za-z0-9 ._+-]+", openssl_version)
        is None
    ):
        raise AuditError("network TLS version projection drift")

    risk = _require_mapping(
        validated.get("transportRisk"), "network transport risk projection"
    )
    risk_fields = {
        "ordinaryObjectCount", "ordinaryObjectStateDigest",
        "replacementRefsCount", "replacementRefsDigest", "alternatesCount",
        "alternatesDigest", "promisorRemotesCount", "promisorRemotesDigest",
    }
    if set(risk) != risk_fields:
        raise AuditError("network transport risk projection field drift")
    for count_name, digest_name in (
        ("ordinaryObjectCount", "ordinaryObjectStateDigest"),
        ("replacementRefsCount", "replacementRefsDigest"),
        ("alternatesCount", "alternatesDigest"),
        ("promisorRemotesCount", "promisorRemotesDigest"),
    ):
        _network_projection_count(risk.get(count_name), "network transport risk")
        _network_projection_digest(risk.get(digest_name), "network transport risk")

    try:
        payload = canonical_json_bytes(dict(validated))
    except (AuditError, TypeError, ValueError, UnicodeError) as exc:
        raise AuditError("validated network egress surface is not canonical JSON") from exc
    secret_scan_objects({"network-local-projection": payload})
    return dict(validated)


def _network_stable_surface(validated: Mapping[str, Any]) -> Dict[str, Any]:
    stable = dict(validated)
    risk = dict(_require_mapping(stable["transportRisk"], "network risk projection"))
    risk.pop("ordinaryObjectCount", None)
    risk.pop("ordinaryObjectStateDigest", None)
    stable["transportRisk"] = risk
    return stable


def _project_network_egress_surface(
    validated: Mapping[str, Any]
) -> Dict[str, Any]:
    """Project validated facts; fail closed on every transport redirection."""

    validated = _validate_network_validated_projection_shape(validated)
    risk = _require_mapping(validated.get("transportRisk"), "network transport risk")
    for count_name in (
        "replacementRefsCount", "alternatesCount", "promisorRemotesCount"
    ):
        if risk.get(count_name) != 0:
            raise AuditError("network transport redirection surface is nonempty")
    local_digest = _digest_projection(_network_stable_surface(validated))
    result = dict(validated)
    result["schemaVersion"] = "qinao.network-egress-local-projection.v1"
    result["localConfigProjectionDigest"] = local_digest
    return _self_digest_record(result)


def _validate_network_local_projection(
    projection: Mapping[str, Any], *, _tool_mode: str = "current",
) -> Dict[str, Any]:
    projection = _require_mapping(projection, "network local projection")
    required = {
        "schemaVersion", "repository", "remoteName", "config", "resolvedUrls",
        "lfs", "environmentRows", "tools", "gitCapabilities", "tls",
        "transportRisk", "forbiddenSurfaceCount", "localConfigProjectionDigest",
        "recordDigest",
    }
    if (
        set(projection) != required
        or projection.get("schemaVersion")
        != "qinao.network-egress-local-projection.v1"
    ):
        raise AuditError("network local projection field drift")
    _verify_self_digest(projection)
    local_digest = _require_lower_hex(
        projection.get("localConfigProjectionDigest"),
        64,
        "network local projection",
    )
    validated = dict(projection)
    validated.pop("recordDigest")
    validated.pop("localConfigProjectionDigest")
    validated["schemaVersion"] = "qinao.network-egress-validated-surface.v1"
    _validate_network_validated_projection_shape(validated, _tool_mode=_tool_mode)
    if local_digest != _digest_projection(_network_stable_surface(validated)):
        raise AuditError("network local projection digest drift")
    if projection.get("forbiddenSurfaceCount") != 0:
        raise AuditError("network forbidden surface drift")
    risk = _require_mapping(projection.get("transportRisk"), "network transport risk")
    if any(
        risk.get(name) != 0
        for name in (
            "replacementRefsCount", "alternatesCount", "promisorRemotesCount"
        )
    ):
        raise AuditError("network transport redirection surface is nonempty")
    return dict(projection)


def _network_full_stable_projection(
    record: Mapping[str, Any]
) -> Dict[str, Any]:
    return {
        "localConfigProjectionDigest": record["localConfigProjectionDigest"],
        "gitEndpoint": record["gitEndpoint"],
        "lfsEndpoint": record["lfsEndpoint"],
        "githubEndpoint": record["githubEndpoint"],
        "fetchPolicyDigest": record["fetchPolicyDigest"],
        "gitCredentialIdentityDigest": record["gitCredentialIdentityDigest"],
        "gitCredentialGenerationDigest": record[
            "gitCredentialGenerationDigest"
        ],
        "ghCredentialIdentityDigest": record["ghCredentialIdentityDigest"],
        "ghCredentialGenerationDigest": record[
            "ghCredentialGenerationDigest"
        ],
    }


def build_network_egress_preflight(
    local: Mapping[str, Any],
    *,
    local_only: bool,
    destination: Optional[Mapping[str, Any]] = None,
    git_credential: Optional[Mapping[str, Any]] = None,
    gh_credential: Optional[Mapping[str, Any]] = None,
    fetch_policy: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    local_projection = _validate_network_local_projection(local)
    repository = local_projection["repository"]
    local_digest = local_projection["localConfigProjectionDigest"]
    base = {
        "schemaVersion": "qinao.network-egress.v1",
        "profile": "local-only" if local_only else "full",
        "repository": repository,
        "localProjection": dict(local_projection),
        "localConfigProjectionDigest": local_digest,
        "forbiddenSurfaceCount": 0,
    }
    if local_only:
        if any(value is not None for value in (destination, git_credential, gh_credential, fetch_policy)):
            raise AuditError("local-only preflight cannot bind network authority")
        return _self_digest_record(base)
    destination = _require_mapping(destination, "network destination")
    git_credential = _require_mapping(git_credential, "Git credential projection")
    gh_credential = _require_mapping(gh_credential, "GitHub credential projection")
    fetch_policy = _require_mapping(fetch_policy, "fetch policy")
    if set(destination) != {"git"}:
        raise AuditError("network destination field drift")
    git_url = destination.get("git")
    if git_url != _NETWORK_GIT_ENDPOINT:
        raise AuditError("network destination drift")
    credential_fields = {"identityDigest", "generationDigest"}
    for label, credential in (("Git", git_credential), ("GitHub", gh_credential)):
        if set(credential) != credential_fields:
            raise AuditError(label + " credential projection field drift")
        _require_lower_hex(credential.get("identityDigest"), 64, label + " credential identity")
        _require_lower_hex(credential.get("generationDigest"), 64, label + " credential generation")
    fetch_policy_digest = _digest_projection(fetch_policy)
    base.update(
        {
            "gitEndpoint": git_url,
            "lfsEndpoint": _NETWORK_LFS_ENDPOINT,
            "githubEndpoint": _NETWORK_GITHUB_ENDPOINT,
            "fetchPolicyDigest": fetch_policy_digest,
            "gitCredentialIdentityDigest": git_credential["identityDigest"],
            "gitCredentialGenerationDigest": git_credential["generationDigest"],
            "ghCredentialIdentityDigest": gh_credential["identityDigest"],
            "ghCredentialGenerationDigest": gh_credential["generationDigest"],
        }
    )
    base["stableProjectionDigest"] = _digest_projection(
        _network_full_stable_projection(base)
    )
    return _self_digest_record(base)


def _validate_argv(argv: Sequence[str]) -> List[str]:
    if not isinstance(argv, (list, tuple)) or not argv:
        raise AuditError("network argv must be a nonempty sequence")
    normalized = []
    for argument in argv:
        if not isinstance(argument, str) or not argument or "\x00" in argument:
            raise AuditError("unsafe network argv")
        if any(ord(character) < 0x20 for character in argument):
            raise AuditError("control byte in network argv")
        normalized.append(argument)
    return normalized


_NETWORK_OPERATION_FIELDS = frozenset(
    {
        "wrapper", "parserFamily", "method", "bodySchema",
        "executorFamily", "credentialKind", "recoveryClass",
        "responseProfile", "responseSchema",
    }
)


def _network_operation_contract(operation: str) -> Dict[str, Any]:
    """Return one closed operation row after validating all linked roles."""

    if not isinstance(operation, str) or not operation:
        raise AuditError("unknown network operation")
    specification = NETWORK_OPERATION_SPEC.get(operation)
    if not isinstance(specification, Mapping):
        raise AuditError("unknown network operation")
    row = dict(specification)
    if set(row) != _NETWORK_OPERATION_FIELDS:
        raise AuditError("network operation contract field drift")
    wrapper = row["wrapper"]
    parser_family = row["parserFamily"]
    executor_family = row["executorFamily"]
    credential_kind = row["credentialKind"]
    recovery_class = row["recoveryClass"]
    method = row["method"]
    body_schema = row["bodySchema"]
    response_profile = row["responseProfile"]
    response_schema = row["responseSchema"]
    if recovery_class != "unknown-no-replay":
        raise AuditError("network operation recovery contract drift")
    if not (
        isinstance(response_schema, str) and response_schema
    ) and not (
        isinstance(response_schema, tuple)
        and len(response_schema) >= 3
        and response_schema[0] == "one-of"
        and all(
            (
                isinstance(descriptor, str) and descriptor
            ) or (
                isinstance(descriptor, tuple)
                and len(descriptor) == 2
                and descriptor[0] == "array"
                and isinstance(descriptor[1], str)
                and descriptor[1]
            )
            for descriptor in response_schema[1:]
        )
    ):
        raise AuditError("network operation response contract drift")
    if wrapper == "network-git":
        if (
            parser_family not in {
                "git-ls-remote", "git-fetch-empty",
                "git-fetch-known", "git-push",
            }
            or executor_family != "git-child"
            or credential_kind != "git"
            or method is not None
            or body_schema is not None
            or response_profile != "git-transport"
            or response_schema != "git-transport-v1"
        ):
            raise AuditError("network Git parser/executor contract drift")
    elif wrapper == "network-gh":
        read_families = {"github-read", "github-job-log"}
        mutation_families = {
            "github-pr-create", "github-pr-update",
            "github-comment-create", "github-merge",
        }
        if parser_family not in read_families | mutation_families:
            raise AuditError("network GitHub parser contract drift")
        if credential_kind != "gh" or method not in {
            "GET", "POST", "PATCH", "PUT",
        }:
            raise AuditError("network GitHub method/credential contract drift")
        if parser_family in read_families:
            if method != "GET" or body_schema is not None:
                raise AuditError("network GitHub read contract drift")
        elif (
            method == "GET"
            or not isinstance(body_schema, tuple)
            or not body_schema
            or tuple(sorted(set(body_schema))) != body_schema
            or any(
                not isinstance(field, str) or not field
                for field in body_schema
            )
        ):
            raise AuditError("network GitHub mutation body contract drift")
        expected_executor = (
            "github-job-log"
            if parser_family == "github-job-log"
            else "github-pages"
        )
        if executor_family != expected_executor:
            raise AuditError("network GitHub executor contract drift")
        expected_profile = (
            "job-log" if executor_family == "github-job-log"
            else "github-rest"
        )
        if response_profile != expected_profile:
            raise AuditError("network GitHub response profile drift")
    elif wrapper == "lfs-batch":
        if (
            parser_family != "lfs-batch"
            or executor_family != "lfs-batch"
            or credential_kind != "git"
            or method != "POST"
            or body_schema != "qinao.lfs-batch-request.v1"
            or response_profile != "lfs-batch"
            or response_schema != "qinao.lfs-batch-response.v1"
        ):
            raise AuditError("LFS parser/executor contract drift")
    else:
        raise AuditError("network operation wrapper contract drift")
    return row


def _network_operations_for_wrapper(wrapper: str) -> frozenset[str]:
    if wrapper not in ("network-git", "network-gh", "lfs-batch"):
        raise AuditError("unknown network wrapper")
    selected = frozenset(
        operation
        for operation in NETWORK_OPERATION_SPEC
        if _network_operation_contract(operation)["wrapper"] == wrapper
    )
    if not selected:
        raise AuditError("network wrapper has no operation")
    return selected


def _network_executor_family(operation: str) -> str:
    return str(_network_operation_contract(operation)["executorFamily"])


def _network_recovery_class(operation: str) -> str:
    return str(_network_operation_contract(operation)["recoveryClass"])


def _network_response_contract(operation: str) -> Tuple[str, Any]:
    row = _network_operation_contract(operation)
    return str(row["responseProfile"]), row["responseSchema"]


def _sole_network_operation(wrapper: str) -> str:
    selected = _network_operations_for_wrapper(wrapper)
    if len(selected) != 1:
        raise AuditError("network wrapper operation is ambiguous")
    return next(iter(selected))


def _network_operation_for_parser_family(parser_family: str) -> str:
    selected = [
        operation
        for operation in NETWORK_OPERATION_SPEC
        if _network_operation_contract(operation)["parserFamily"]
        == parser_family
    ]
    if len(selected) != 1:
        raise AuditError("network parser family operation is ambiguous")
    return selected[0]


def _network_git_ref(value: Any, *, allow_tag: bool) -> str:
    namespace = r"(?:heads|tags)" if allow_tag else r"heads"
    if (
        not isinstance(value, str)
        or len(value) > 1024
        or re.fullmatch(
            r"refs/" + namespace + r"/[A-Za-z0-9][A-Za-z0-9._/-]*",
            value,
        ) is None
    ):
        raise AuditError("network Git ref drift")
    suffix = value.split("/", 2)[2]
    components = suffix.split("/")
    if (
        any(
            not component
            or component.startswith(".")
            or component.endswith(".")
            or component.endswith(".lock")
            for component in components
        )
        or ".." in value
        or "@{" in value
        or any(character in value for character in "\\~^:?*[")
    ):
        raise AuditError("unsafe network Git ref")
    return value


def _network_git_oid(value: Any, label: str, *, allow_empty: bool = False) -> str:
    if allow_empty and value == "":
        return ""
    if (
        not isinstance(value, str)
        or re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", value) is None
        or set(value) == {"0"}
    ):
        raise AuditError(label + " OID drift")
    return value


def _parse_network_git_argv(
    operation: str, argv: Sequence[str]
) -> Dict[str, Any]:
    """Admit one exact Git transport grammar with a literal destination."""

    specification = _network_operation_contract(operation)
    if specification["wrapper"] != "network-git":
        raise AuditError("operation is not a network Git operation")
    parser_family = specification["parserFamily"]
    normalized = _validate_argv(argv)
    result: Dict[str, Any] = {
        "schemaVersion": "qinao.network-git-argv-binding.v1",
        "operation": operation,
        "parserFamily": parser_family,
        "endpoint": _NETWORK_GIT_ENDPOINT,
        "argv": normalized,
    }
    if parser_family == "git-ls-remote":
        listing_forms = (
            [
                "ls-remote", "--refs", "--branches", "--tags",
                _NETWORK_GIT_ENDPOINT,
            ],
            ["ls-remote", "--refs", "--branches", _NETWORK_GIT_ENDPOINT],
        )
        if normalized in listing_forms:
            result["mode"] = "listing"
            return _self_digest_record(result, field="bindingDigest")
        exact_prefixes = (
            ["ls-remote", "--refs", _NETWORK_GIT_ENDPOINT],
            ["ls-remote", "--exit-code", "--refs", _NETWORK_GIT_ENDPOINT],
        )
        for prefix in exact_prefixes:
            if len(normalized) == len(prefix) + 1 and normalized[:-1] == prefix:
                result["mode"] = "exact-ref"
                result["remoteRef"] = _network_git_ref(
                    normalized[-1], allow_tag=True
                )
                return _self_digest_record(result, field="bindingDigest")
        raise AuditError("network Git ls-remote argv drift")

    fetch_prefix = [
        "fetch", "--no-auto-maintenance", "--no-write-commit-graph",
        "--no-recurse-submodules", "--no-write-fetch-head", "--no-tags",
    ]
    if parser_family == "git-fetch-empty":
        if (
            len(normalized) != len(fetch_prefix) + 2
            or normalized[:len(fetch_prefix)] != fetch_prefix
            or normalized[-2] != _NETWORK_GIT_ENDPOINT
            or normalized[-1].count(":") != 1
        ):
            raise AuditError("network Git empty fetch argv drift")
        remote_ref, local_ref = normalized[-1].split(":", 1)
        if local_ref != _NETWORK_FETCH_LOCAL_REF:
            raise AuditError("network Git empty fetch local ref drift")
        result["remoteRef"] = _network_git_ref(remote_ref, allow_tag=True)
        result["localRef"] = local_ref
        result["refspec"] = normalized[-1]
        result["negotiationTips"] = []
        return _self_digest_record(result, field="bindingDigest")
    if parser_family == "git-fetch-known":
        if (
            len(normalized) != len(fetch_prefix) + 3
            or normalized[:len(fetch_prefix)] != fetch_prefix
            or not normalized[len(fetch_prefix)].startswith("--negotiation-tip=")
            or normalized[-2] != _NETWORK_GIT_ENDPOINT
            or normalized[-1].count(":") != 1
        ):
            raise AuditError("network Git known fetch argv drift")
        tip = _network_git_oid(
            normalized[len(fetch_prefix)].split("=", 1)[1],
            "network Git negotiation tip",
        )
        remote_ref, local_ref = normalized[-1].split(":", 1)
        if local_ref != _NETWORK_FETCH_LOCAL_REF:
            raise AuditError("network Git known fetch local ref drift")
        result["remoteRef"] = _network_git_ref(remote_ref, allow_tag=True)
        result["localRef"] = local_ref
        result["refspec"] = normalized[-1]
        result["negotiationTips"] = [tip]
        return _self_digest_record(result, field="bindingDigest")
    if parser_family == "git-push":
        prefix = [
            "push", "--porcelain", "--recurse-submodules=no",
            "--no-follow-tags", "--no-signed", "--no-force-if-includes",
        ]
        if (
            len(normalized) != 9
            or normalized[:6] != prefix
            or not normalized[6].startswith("--force-with-lease=")
            or normalized[7] != _NETWORK_GIT_ENDPOINT
            or normalized[8].count(":") != 1
        ):
            raise AuditError("network Git push argv drift")
        lease = normalized[6].split("=", 1)[1]
        if lease.count(":") != 1:
            raise AuditError("network Git push lease drift")
        lease_ref, expected_oid = lease.split(":", 1)
        source_oid, destination_ref = normalized[8].split(":", 1)
        destination_ref = _network_git_ref(destination_ref, allow_tag=False)
        if _network_git_ref(lease_ref, allow_tag=False) != destination_ref:
            raise AuditError("network Git push destination drift")
        source_oid = _network_git_oid(source_oid, "network Git push source")
        expected_oid = _network_git_oid(
            expected_oid, "network Git push expected", allow_empty=True
        )
        if expected_oid and len(expected_oid) != len(source_oid):
            raise AuditError("network Git push object format drift")
        result.update(
            {
                "sourceOid": source_oid,
                "expectedOid": expected_oid,
                "destinationRef": destination_ref,
            }
        )
        return _self_digest_record(result, field="bindingDigest")
    raise AuditError("unknown network Git parser family")


def seal_network_request_manifest(
    operation: str,
    argv: Sequence[str],
    preflight: Mapping[str, Any],
    *,
    request_body_record: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    request: Dict[str, Any] = {"operation": operation, "argv": list(argv)}
    if request_body_record is not None:
        request["requestBodyRecord"] = request_body_record
    return seal_network_request_manifest_rows(
        [request], preflight
    )


_NETWORK_REQUEST_MANIFEST_V2_FIELDS = frozenset(
    {
        "schemaVersion", "manifestKind", "preflightRecordDigest",
        "stableProjectionDigest", "parentObservationRecordDigest",
        "rowCount", "rows", "rowsDigest", "recordDigest",
    }
)
_NETWORK_REQUEST_ROW_V2_FIELDS = frozenset(
    {
        "schemaVersion", "sequence", "requestId", "maximumUses",
        "operation", "wrapper", "recoveryClass", "argv", "argvDigest",
        "preflightRecordDigest", "stableProjectionDigest", "gitBinding",
        "requestBodyRecordDigest", "requestBodySha256",
        "requestBodyByteCount", "rowDigest",
    }
)
_NETWORK_MUTATION_PARSER_FAMILIES = frozenset(
    {
        "git-push", "github-pr-create", "github-pr-update",
        "github-comment-create", "github-merge",
    }
)


def _network_request_row_v2(
    operation: str,
    argv: Sequence[str],
    preflight: Mapping[str, Any],
    sequence: int,
    *,
    request_body_record: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    if not isinstance(sequence, int) or isinstance(sequence, bool) or sequence < 1:
        raise AuditError("network request row sequence drift")
    specification = _network_operation_contract(operation)
    normalized = _validate_argv(argv)
    git_binding = (
        _parse_network_git_argv(operation, normalized)
        if specification["wrapper"] == "network-git"
        else None
    )
    body_digest = None
    body_sha256 = None
    body_byte_count = 0
    if request_body_record is not None:
        body_record = validate_network_gh_request_body(
            request_body_record, operation
        )
        body_digest = body_record["recordDigest"]
        body_sha256 = body_record["canonicalBodySha256"]
        body_byte_count = body_record["canonicalBodyByteCount"]
    row: Dict[str, Any] = {
        "schemaVersion": "qinao.network-request-row.v2",
        "sequence": sequence,
        "maximumUses": 1,
        "operation": operation,
        "wrapper": specification["wrapper"],
        "recoveryClass": specification["recoveryClass"],
        "argv": normalized,
        "argvDigest": _sha256(canonical_json_bytes(normalized)),
        "preflightRecordDigest": preflight["recordDigest"],
        "stableProjectionDigest": preflight["stableProjectionDigest"],
        "gitBinding": git_binding,
        "requestBodyRecordDigest": body_digest,
        "requestBodySha256": body_sha256,
        "requestBodyByteCount": body_byte_count,
    }
    row["requestId"] = _digest_projection(
        {
            "schemaVersion": "qinao.network-request-id.v1",
            "row": row,
        }
    )
    return _self_digest_record(row, field="rowDigest")


def seal_network_request_manifest_rows(
    requests: Sequence[Mapping[str, Any]],
    preflight: Mapping[str, Any],
    parent_observation: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Seal one ordered, closed, single-use network request batch."""

    try:
        preflight = validate_network_egress_record(preflight)
    except AuditError as exc:
        raise AuditError("network preflight validation failed") from exc
    if preflight.get("profile") != "full":
        raise AuditError("network preflight is not full")
    if (
        not isinstance(requests, (list, tuple))
        or not requests
        or len(requests) > 64
    ):
        raise AuditError("network request manifest row count drift")
    parent_digest = None
    if parent_observation is not None:
        parent = _require_mapping(
            parent_observation, "network parent observation"
        )
        _verify_self_digest(parent)
        parent_digest = parent["recordDigest"]
    rows = []
    mutation_count = 0
    for sequence, raw_request in enumerate(requests, 1):
        request = _require_mapping(raw_request, "network request row")
        allowed = {"operation", "argv", "requestBodyRecord"}
        if not set(request).issubset(allowed) or not {
            "operation", "argv"
        }.issubset(request):
            raise AuditError("network request input field drift")
        specification = _network_operation_contract(request["operation"])
        if specification["parserFamily"] in _NETWORK_MUTATION_PARSER_FAMILIES:
            mutation_count += 1
        rows.append(
            _network_request_row_v2(
                request["operation"],
                request["argv"],
                preflight,
                sequence,
                request_body_record=request.get("requestBodyRecord"),
            )
        )
    if mutation_count and (mutation_count != 1 or len(rows) != 1):
        raise AuditError("network mutation manifest must contain one row")
    return _self_digest_record(
        {
            "schemaVersion": "qinao.network-request-manifest.v2",
            "manifestKind": "network-request",
            "preflightRecordDigest": preflight["recordDigest"],
            "stableProjectionDigest": preflight["stableProjectionDigest"],
            "parentObservationRecordDigest": parent_digest,
            "rowCount": len(rows),
            "rows": rows,
            "rowsDigest": _sha256(canonical_json_bytes(rows)),
        }
    )


def _validate_network_request_manifest_v2(
    manifest: Mapping[str, Any], preflight: Mapping[str, Any],
    *, _tool_mode: str = "current",
) -> Dict[str, Any]:
    manifest = _require_mapping(manifest, "network request manifest v2")
    if (
        set(manifest) != _NETWORK_REQUEST_MANIFEST_V2_FIELDS
        or manifest.get("schemaVersion")
        != "qinao.network-request-manifest.v2"
        or manifest.get("manifestKind") != "network-request"
    ):
        raise AuditError("network request manifest v2 field drift")
    _verify_self_digest(manifest)
    try:
        preflight = _validate_network_egress_record(preflight, _tool_mode=_tool_mode)
    except AuditError as exc:
        raise AuditError("network preflight validation failed") from exc
    if preflight.get("profile") != "full":
        raise AuditError("network preflight is not full")
    if (
        manifest.get("preflightRecordDigest") != preflight["recordDigest"]
        or manifest.get("stableProjectionDigest")
        != preflight["stableProjectionDigest"]
    ):
        raise AuditError("network manifest v2 preflight binding drift")
    parent_digest = manifest.get("parentObservationRecordDigest")
    if parent_digest is not None:
        _require_lower_hex(parent_digest, 64, "network parent observation")
    rows = manifest.get("rows")
    row_count = manifest.get("rowCount")
    if (
        not isinstance(row_count, int)
        or isinstance(row_count, bool)
        or not isinstance(rows, list)
        or not rows
        or len(rows) > 64
        or row_count != len(rows)
        or manifest.get("rowsDigest")
        != _sha256(canonical_json_bytes(rows))
    ):
        raise AuditError("network manifest v2 rows drift")
    request_ids = set()
    row_digests = set()
    mutation_count = 0
    validated_rows = []
    for expected_sequence, raw_row in enumerate(rows, 1):
        row = _require_mapping(raw_row, "network request manifest row")
        if (
            set(row) != _NETWORK_REQUEST_ROW_V2_FIELDS
            or row.get("schemaVersion") != "qinao.network-request-row.v2"
            or row.get("sequence") != expected_sequence
            or not isinstance(row.get("sequence"), int)
            or isinstance(row.get("sequence"), bool)
            or row.get("maximumUses") != 1
            or not isinstance(row.get("maximumUses"), int)
            or isinstance(row.get("maximumUses"), bool)
        ):
            raise AuditError("network request manifest row field drift")
        _verify_self_digest(row, field="rowDigest")
        specification = _network_operation_contract(row.get("operation"))
        argv = _validate_argv(row.get("argv"))
        if (
            row.get("wrapper") != specification["wrapper"]
            or row.get("recoveryClass") != specification["recoveryClass"]
            or row.get("argvDigest")
            != _sha256(canonical_json_bytes(argv))
            or row.get("preflightRecordDigest") != preflight["recordDigest"]
            or row.get("stableProjectionDigest")
            != preflight["stableProjectionDigest"]
        ):
            raise AuditError("network request manifest row binding drift")
        expected_git_binding = (
            _parse_network_git_argv(row["operation"], argv)
            if specification["wrapper"] == "network-git"
            else None
        )
        if row.get("gitBinding") != expected_git_binding:
            raise AuditError("network request nested Git binding drift")
        body_digest = row.get("requestBodyRecordDigest")
        body_sha256 = row.get("requestBodySha256")
        body_byte_count = row.get("requestBodyByteCount")
        if body_digest is None:
            if body_sha256 is not None or body_byte_count != 0:
                raise AuditError("network request body binding drift")
        else:
            _require_lower_hex(body_digest, 64, "network request body record")
            _require_lower_hex(body_sha256, 64, "network request body")
            if (
                not isinstance(body_byte_count, int)
                or isinstance(body_byte_count, bool)
                or body_byte_count < 1
            ):
                raise AuditError("network request body byte count drift")
        identity_projection = dict(row)
        request_id = identity_projection.pop("requestId", None)
        identity_projection.pop("rowDigest", None)
        expected_request_id = _digest_projection(
            {
                "schemaVersion": "qinao.network-request-id.v1",
                "row": identity_projection,
            }
        )
        if request_id != expected_request_id:
            raise AuditError("network request identity drift")
        row_digest = row["rowDigest"]
        if request_id in request_ids or row_digest in row_digests:
            raise AuditError("duplicate network request identity")
        request_ids.add(request_id)
        row_digests.add(row_digest)
        if specification["parserFamily"] in _NETWORK_MUTATION_PARSER_FAMILIES:
            mutation_count += 1
        validated_rows.append(dict(row))
    if mutation_count and (mutation_count != 1 or len(validated_rows) != 1):
        raise AuditError("network mutation manifest must contain one row")
    return dict(manifest)


def select_network_request_row(
    manifest: Mapping[str, Any],
    operation: str,
    argv: Sequence[str],
    preflight: Mapping[str, Any],
    *,
    request_body_record: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    return _select_network_request_row(
        manifest, operation, argv, preflight,
        request_body_record=request_body_record, _tool_mode="current",
    )


def _select_network_request_row(
    manifest: Mapping[str, Any], operation: str, argv: Sequence[str],
    preflight: Mapping[str, Any], *,
    request_body_record: Optional[Mapping[str, Any]] = None,
    _tool_mode: str,
) -> Dict[str, Any]:
    validated = _validate_network_request_manifest_v2(manifest, preflight, _tool_mode=_tool_mode)
    normalized = _validate_argv(argv)
    body_digest = None
    body_sha256 = None
    body_byte_count = 0
    if request_body_record is not None:
        body = validate_network_gh_request_body(
            request_body_record, operation
        )
        body_digest = body["recordDigest"]
        body_sha256 = body["canonicalBodySha256"]
        body_byte_count = body["canonicalBodyByteCount"]
    matches = [
        row for row in validated["rows"]
        if row["operation"] == operation
        and row["argv"] == normalized
        and row["requestBodyRecordDigest"] == body_digest
        and row["requestBodySha256"] == body_sha256
        and row["requestBodyByteCount"] == body_byte_count
    ]
    if len(matches) != 1:
        raise AuditError("network request manifest selection is not unique")
    return dict(matches[0])


def _network_request_use_key(
    manifest_record_digest: str, request_id: str, ordinal: int
) -> str:
    _require_lower_hex(
        manifest_record_digest, 64, "network manifest record"
    )
    if (
        not isinstance(request_id, str)
        or not request_id
        or len(request_id.encode("utf-8", "strict")) > 1024
        or "\x00" in request_id
        or any(ord(character) < 0x20 for character in request_id)
    ):
        raise AuditError("network request identity drift")
    if not isinstance(ordinal, int) or isinstance(ordinal, bool) or ordinal != 1:
        raise AuditError("network request use ordinal drift")
    return _digest_projection(
        {
            "manifestRecordDigest": manifest_record_digest,
            "requestId": request_id,
            "useOrdinal": 1,
        }
    )


def build_network_gh_request_body(
    operation: str, body: Mapping[str, Any]
) -> Dict[str, Any]:
    """Build the one reviewed canonical mutation body bound by an intent."""

    specification = _network_operation_contract(operation)
    if (
        specification["wrapper"] != "network-gh"
        or specification["bodySchema"] is None
    ):
        raise AuditError("GitHub request body operation drift")
    body = dict(_require_mapping(body, "GitHub request body"))
    if set(body) != set(specification["bodySchema"]):
        raise AuditError("GitHub request body field drift")
    for field_name, value in body.items():
        if (
            not isinstance(value, str)
            or not value
            or "\x00" in value
            or len(value.encode("utf-8", "strict")) > 256 * 1024
        ):
            raise AuditError("GitHub request body value drift")
    if specification["parserFamily"] == "github-pr-create":
        if body["base"] != "main" or re.fullmatch(
            r"[A-Za-z0-9._/-]+", body["head"]
        ) is None:
            raise AuditError("GitHub pull request body ref drift")
    if specification["parserFamily"] == "github-merge":
        if (
            body["merge_method"] not in ("merge", "squash", "rebase")
            or re.fullmatch(r"[0-9a-f]{40}", body["sha"]) is None
        ):
            raise AuditError("GitHub merge body drift")
    canonical_body = canonical_json_bytes(body)
    return _self_digest_record(
        {
            "schemaVersion": "qinao.network-gh-request-body.v1",
            "operation": operation,
            "body": body,
            "canonicalBodyByteCount": len(canonical_body),
            "canonicalBodySha256": _sha256(canonical_body),
        }
    )


def validate_network_gh_request_body(
    record: Mapping[str, Any], operation: str
) -> Dict[str, Any]:
    record = _require_mapping(record, "GitHub request body record")
    if set(record) != {
        "schemaVersion", "operation", "body", "canonicalBodyByteCount",
        "canonicalBodySha256", "recordDigest",
    } or record.get("schemaVersion") != "qinao.network-gh-request-body.v1":
        raise AuditError("GitHub request body record field drift")
    _verify_self_digest(record)
    expected = build_network_gh_request_body(
        operation,
        _require_mapping(record.get("body"), "GitHub request body payload"),
    )
    if dict(record) != expected:
        raise AuditError("GitHub request body record drift")
    return dict(record)


def _project_response_headers(
    value: Any, profile: Optional[str] = None
) -> Dict[str, str]:
    """Validate the bounded wire surface before selecting evidence fields.

    The admitted grammar is deliberately narrower than general HTTP. Even
    discarded metadata must satisfy it; duplicates are detected before loss.
    """
    profiles = {
        "credential": {"content-type", "x-oauth-scopes"},
        "github-page": {"content-type", "x-github-request-id", "x-ratelimit-limit",
                        "x-ratelimit-remaining", "x-ratelimit-reset", "link"},
        "job-redirect": {"location", "x-github-request-id", "x-ratelimit-limit",
                         "x-ratelimit-remaining", "x-ratelimit-reset"},
        "signed-log": {"content-type"},
        "lfs": {"content-type"},
    }
    if profile is not None and profile not in profiles:
        raise AuditError("HTTPS response header profile drift")
    if isinstance(value, Mapping):
        pairs = value.items()
    elif isinstance(value, (list, tuple)):
        pairs = value
    else:
        raise AuditError("HTTPS response header pairs type drift")
    normalized: Dict[str, str] = {}
    total = 0
    for count, pair in enumerate(pairs, 1):
        if count > 100:
            raise AuditError("HTTPS response header count exceeds bound")
        if not isinstance(pair, (tuple, list)) or len(pair) != 2:
            raise AuditError("HTTPS response header pair shape drift")
        name, field = pair
        if not isinstance(name, str) or not isinstance(field, str):
            raise AuditError("HTTPS response header type drift")
        if (
            not name or len(name) > 256
            or re.fullmatch(r"[!#$%&'*+.^_`|~0-9A-Za-z-]+", name) is None
        ):
            raise AuditError("HTTPS response header name drift")
        if len(field) > 16384:
            raise AuditError("HTTPS response header value exceeds bound")
        try:
            field_bytes = field.encode("latin-1", "strict")
        except UnicodeEncodeError as exc:
            raise AuditError("HTTPS response header encoding drift") from exc
        if any(byte < 32 or byte == 127 for byte in field_bytes):
            raise AuditError("HTTPS response header control/injection")
        total += len(name) + len(field_bytes)
        if total > 65536:
            raise AuditError("HTTPS response header aggregate exceeds bound")
        lowered = name.lower()
        if lowered in normalized:
            raise AuditError("HTTPS response duplicate header")
        normalized[lowered] = field
    if profile is None:
        return normalized
    return {name: field for name, field in normalized.items() if name in profiles[profile]}


def validate_network_gh_response(
    operation: str,
    argv: Sequence[str],
    preflight: Mapping[str, Any],
    manifest: Mapping[str, Any],
    status: int,
    headers: Mapping[str, str],
    chunks: Iterable[bytes],
) -> Dict[str, Any]:
    specification = _network_operation_contract(operation)
    if specification["wrapper"] != "network-gh":
        raise AuditError("unknown GitHub operation")
    select_network_request_row(manifest, operation, argv, preflight)
    if not isinstance(status, int) or isinstance(status, bool):
        raise AuditError("GitHub response status type drift")
    if 300 <= status < 400:
        raise AuditError("GitHub redirect is forbidden")
    if status < 200 or status >= 300:
        raise AuditError("GitHub response is not successful")
    if not isinstance(headers, Mapping):
        raise AuditError("GitHub response headers type drift")
    normalized_headers = _project_response_headers(headers, "github-page")
    _method, endpoint, _paginate = _parse_network_gh_request(
        operation, argv
    )
    response_profile, response_schema = _network_response_contract(operation)
    captured = safe_capture(
        chunks,
        profile=response_profile,
        endpoint=endpoint,
        response_schema=response_schema,
    )
    return _self_digest_record(
        {
            "schemaVersion": "qinao.network-gh-observation.v1",
            "operation": operation,
            "status": status,
            "headerNames": sorted(normalized_headers),
            "headerProjectionDigest": _digest_projection(normalized_headers),
            "preflightRecordDigest": preflight["recordDigest"],
            "manifestRecordDigest": manifest["recordDigest"],
            "safeCaptureDigest": captured["recordDigest"],
            "responseSha256": captured["rawSha256"],
            "responseByteCount": captured["rawByteCount"],
            "redirectCount": 0,
        }
    )


def _parse_network_gh_request(
    operation: str, argv: Sequence[str]
) -> Tuple[str, str, bool]:
    specification = _network_operation_contract(operation)
    if specification["wrapper"] != "network-gh":
        raise AuditError("unknown GitHub operation")
    normalized = _validate_argv(argv)
    if not normalized or normalized[0] != "api":
        raise AuditError("network-gh requires the sealed api syntax")
    if specification["bodySchema"] is None:
        if normalized[1:3] == ["--paginate", "--slurp"]:
            paginate = True
            remainder = normalized[3:]
        else:
            paginate = False
            remainder = normalized[1:]
        if len(remainder) != 1:
            raise AuditError("network-gh read argv shape drift")
        method = specification["method"]
        path = remainder[0]
        if paginate and specification["executorFamily"] != "github-pages":
            raise AuditError("network-gh executor forbids pagination")
    else:
        if len(normalized) not in (4, 6) or normalized[1] != "--method":
            raise AuditError("network-gh mutation argv shape drift")
        method = normalized[2]
        path = normalized[3]
        if len(normalized) == 6 and normalized[4:6] != ["--input", "-"]:
            raise AuditError("network-gh mutation input syntax drift")
        paginate = False
    if specification["method"] != method:
        raise AuditError("network-gh operation/method drift")
    if (
        not path.startswith("/")
        or path.startswith("//")
        or "#" in path
        or "\x00" in path
        or any(segment in (".", "..") for segment in path.split("?", 1)[0].split("/"))
    ):
        raise AuditError("network-gh path drift")
    if path not in ("/user", "/rate_limit") and not path.startswith(
        "/repos/ChangGeng01/ProjectSix/"
    ):
        raise AuditError("network-gh path is outside the closed repository")
    return method, path, paginate


def _read_bounded_chunks(
    chunks: Iterable[bytes], *, maximum: int, label: str
) -> bytes:
    accumulator = bytearray()
    for chunk in chunks:
        if not isinstance(chunk, bytes):
            raise AuditError(label + " chunk type drift")
        if len(accumulator) + len(chunk) > maximum:
            raise AuditError(label + " exceeds bound")
        accumulator.extend(chunk)
    return bytes(accumulator)


def _owned_bearer_authorization(token: memoryview) -> OwnedSecretBuffer:
    if not isinstance(token, memoryview) or not token:
        raise AuditError("Bearer token owner drift")
    owner = bytearray(b"Bearer ")
    owner.extend(token)
    return OwnedSecretBuffer.take(owner)


def _github_next_link(value: Optional[str], seen_paths: Sequence[str]) -> Optional[str]:
    if value is None:
        return None
    if not isinstance(value, str) or not value or "\r" in value or "\n" in value:
        raise AuditError("GitHub pagination Link framing drift")
    relations: Dict[str, str] = {}
    for component in value.split(","):
        match = re.fullmatch(
            r'\s*<([^<>]+)>;\s*rel="(next|prev|first|last)"\s*',
            component,
        )
        if match is None or match.group(2) in relations:
            raise AuditError("GitHub pagination Link syntax drift")
        relations[match.group(2)] = match.group(1)
    next_url = relations.get("next")
    if next_url is None:
        return None
    try:
        parsed = urlsplit(next_url)
    except ValueError as exc:
        raise AuditError("GitHub pagination URL drift") from exc
    if (
        parsed.scheme != "https"
        or parsed.hostname != "api.github.com"
        or parsed.port not in (None, 443)
        or parsed.username is not None
        or parsed.password is not None
        or parsed.fragment
        or not parsed.path.startswith("/repos/ChangGeng01/ProjectSix/")
    ):
        raise AuditError("GitHub pagination changed authority")
    next_path = parsed.path + (("?" + parsed.query) if parsed.query else "")
    if next_path in set(seen_paths):
        raise AuditError("GitHub pagination Link loop")
    return next_path


def _execute_network_gh_pages(
    adapter: Any,
    operation: str,
    argv: Sequence[str],
    preflight: Mapping[str, Any],
    manifest: Mapping[str, Any],
    token: memoryview,
    *,
    request_body_record: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    specification = _network_operation_contract(operation)
    if specification["wrapper"] != "network-gh":
        raise AuditError("unknown GitHub operation")
    selected_row = select_network_request_row(
        manifest,
        operation,
        argv,
        preflight,
        request_body_record=request_body_record,
    )
    method, path, paginate = _parse_network_gh_request(operation, argv)
    body = b""
    if specification["bodySchema"] is not None:
        if request_body_record is None:
            raise AuditError("network-gh mutation body is not sealed")
        body_record = validate_network_gh_request_body(
            request_body_record, operation
        )
        body = canonical_json_bytes(body_record["body"])
        if (
            _sha256(body) != selected_row["requestBodySha256"]
            or len(body) != selected_row["requestBodyByteCount"]
        ):
            raise AuditError("network-gh mutation body digest drift")
    if specification["executorFamily"] == "github-job-log":
        return _execute_network_gh_job_log(
            adapter, operation, path, preflight, manifest, token
        )
    if specification["executorFamily"] != "github-pages":
        raise AuditError("network GitHub executor family drift")
    response_profile, response_schema = _network_response_contract(operation)
    pages = []
    seen_paths: List[str] = []
    aggregate = hashlib.sha256()
    total_bytes = 0
    while True:
        if len(pages) >= 100 or path in seen_paths:
            raise AuditError("GitHub pagination exceeds closed bound")
        seen_paths.append(path)
        authorization = _owned_bearer_authorization(token)
        try:
            result = adapter.https_request(
                authority="gh",
                method=method,
                host="api.github.com",
                path=path,
                headers={
                    "accept": "application/vnd.github+json",
                    "authorization": authorization.view(),
                    "user-agent": "qinao-convergence-audit/1",
                    "x-github-api-version": "2022-11-28",
                },
                body=body,
            )
        finally:
            authorization.release()
        result = _require_mapping(result, "GitHub page response")
        if set(result) != {"status", "headers", "bodyChunks"}:
            raise AuditError("GitHub page response shape drift")
        status = result.get("status")
        if (
            not isinstance(status, int)
            or isinstance(status, bool)
            or status < 200
            or status >= 300
        ):
            raise AuditError("GitHub page response is not successful")
        raw_headers = _require_mapping(result.get("headers"), "GitHub page headers")
        headers = _project_response_headers(raw_headers, "github-page")
        if headers.get("content-type", "").split(";", 1)[0] != "application/json":
            raise AuditError("GitHub page media type drift")
        payload = _read_bounded_chunks(
            result["bodyChunks"], maximum=4 * 1024 * 1024,
            label="GitHub page body",
        )
        total_bytes += len(payload)
        if total_bytes > 16 * 1024 * 1024:
            raise AuditError("GitHub paginated response exceeds aggregate bound")
        safe = safe_capture(
            [payload],
            profile=response_profile,
            endpoint=path,
            response_schema=response_schema,
        )
        parsed = _parse_json_response(payload, maximum=4 * 1024 * 1024)
        if not isinstance(parsed, (dict, list)):
            raise AuditError("GitHub page JSON shape drift")
        aggregate.update(bytes.fromhex(safe["rawSha256"]))
        pages.append(
            {
                "page": len(pages) + 1,
                "status": status,
                "headerNames": sorted(headers),
                "headerProjectionDigest": _digest_projection(headers),
                "responseByteCount": len(payload),
                "responseSha256": safe["rawSha256"],
                "safeCaptureDigest": safe["recordDigest"],
            }
        )
        next_path = _github_next_link(headers.get("link"), seen_paths)
        if next_path is None:
            break
        if method != "GET":
            raise AuditError("GitHub mutation returned pagination")
        if not paginate:
            raise AuditError("GitHub unpaginated request returned a next page")
        path = next_path
    return _self_digest_record(
        {
            "schemaVersion": "qinao.network-gh-observation.v1",
            "operation": operation,
            "status": 200,
            "pageCount": len(pages),
            "pages": pages,
            "preflightRecordDigest": preflight["recordDigest"],
            "manifestRecordDigest": manifest["recordDigest"],
            "responseByteCount": total_bytes,
            "responseSha256": aggregate.hexdigest(),
            "redirectCount": 0,
        }
    )


def _normalize_public_addresses(values: Any) -> List[str]:
    if not isinstance(values, (list, tuple)) or not values:
        raise AuditError("signed-log DNS result is empty")
    normalized: List[str] = []
    for raw_value in values:
        if not isinstance(raw_value, str) or raw_value in normalized:
            raise AuditError("signed-log DNS result drift")
        try:
            address = ipaddress.ip_address(raw_value)
        except ValueError as exc:
            raise AuditError("signed-log DNS address drift") from exc
        if any(
            (
                address.is_private,
                address.is_loopback,
                address.is_link_local,
                address.is_multicast,
                address.is_reserved,
                address.is_unspecified,
            )
        ):
            raise AuditError("signed-log DNS address is not public")
        normalized.append(address.compressed)
    return sorted(normalized)


def _execute_network_gh_job_log(
    adapter: Any,
    operation: str,
    endpoint: str,
    preflight: Mapping[str, Any],
    manifest: Mapping[str, Any],
    token: memoryview,
) -> Dict[str, Any]:
    response_profile, response_schema = _network_response_contract(operation)
    if response_profile != "job-log":
        raise AuditError("GitHub job-log response profile drift")
    authorization = _owned_bearer_authorization(token)
    try:
        first_value = adapter.https_request(
            authority="gh",
            method="GET",
            host="api.github.com",
            path=endpoint,
            headers={
                "accept": "application/vnd.github+json",
                "authorization": authorization.view(),
                "user-agent": "qinao-convergence-audit/1",
                "x-github-api-version": "2022-11-28",
            },
            body=b"",
        )
    finally:
        authorization.release()
    first = _require_mapping(
        first_value, "GitHub job-log redirect response",
    )
    if set(first) != {"status", "headers", "bodyChunks"} or first.get(
        "status"
    ) != 302:
        raise AuditError("GitHub job-log initial redirect drift")
    if list(first.get("bodyChunks", [])):
        raise AuditError("GitHub job-log redirect body drift")
    raw_headers = _require_mapping(
        first.get("headers"), "GitHub job-log redirect headers"
    )
    headers = _project_response_headers(raw_headers, "job-redirect")
    location = headers.get("location")
    if location is None:
        raise AuditError("GitHub job-log redirect Location is absent")
    try:
        parsed = urlsplit(location)
        host = parsed.hostname
        port = parsed.port
    except ValueError as exc:
        raise AuditError("GitHub job-log signed URL drift") from exc
    host_allowed = bool(
        isinstance(host, str)
        and (
            re.fullmatch(r"[a-z0-9-]+\.actions\.githubusercontent\.com", host)
            or re.fullmatch(
                r"productionresultssa[0-9]+\.blob\.core\.windows\.net",
                host,
            )
        )
    )
    if (
        parsed.scheme != "https"
        or not host_allowed
        or port not in (None, 443)
        or parsed.username is not None
        or parsed.password is not None
        or parsed.fragment
        or not parsed.query
        or not parsed.path.startswith("/")
        or ".." in parsed.path.split("/")
    ):
        raise AuditError("GitHub job-log signed URL authority drift")
    if not hasattr(adapter, "resolve_public_addresses"):
        raise AuditError("GitHub job-log DNS binder is unavailable")
    addresses = _normalize_public_addresses(
        adapter.resolve_public_addresses(host)
    )
    second = _require_mapping(
        adapter.https_request(
            authority="job-log",
            method="GET",
            host=host,
            path=parsed.path + "?" + parsed.query,
            headers={
                "accept": "text/plain",
                "user-agent": "qinao-convergence-audit/1",
            },
            body=b"",
            resolvedAddresses=addresses,
        ),
        "GitHub signed job-log response",
    )
    if set(second) != {"status", "headers", "bodyChunks"}:
        raise AuditError("GitHub signed job-log response shape drift")
    status = second.get("status")
    if (
        not isinstance(status, int)
        or isinstance(status, bool)
        or status < 200
        or status >= 300
    ):
        raise AuditError("GitHub signed job-log response is not successful")
    second_headers = _require_mapping(
        second.get("headers"), "GitHub signed job-log headers"
    )
    normalized_headers = _project_response_headers(second_headers, "signed-log")
    if normalized_headers.get("content-type", "").split(";", 1)[0] != (
        "text/plain"
    ):
        raise AuditError("GitHub signed job-log media type drift")
    payload = _read_bounded_chunks(
        second["bodyChunks"], maximum=MAX_SAFE_CAPTURE_BYTES,
        label="GitHub signed job-log body",
    )
    captured = safe_capture(
        [payload],
        profile=response_profile,
        endpoint=endpoint,
        response_schema=response_schema,
    )
    redirect_projection = {
        "scheme": "https",
        "host": host,
        "pathSha256": _sha256(parsed.path.encode("utf-8", "strict")),
        "wholeLocationSha256": _sha256(location.encode("ascii", "strict")),
        "resolvedAddressDigest": _sha256(canonical_json_bytes(addresses)),
    }
    return _self_digest_record(
        {
            "schemaVersion": "qinao.network-gh-observation.v1",
            "operation": operation,
            "status": status,
            "pageCount": 1,
            "pages": [
                {
                    "page": 1,
                    "status": status,
                    "headerNames": sorted(normalized_headers),
                    "headerProjectionDigest": _digest_projection(
                        normalized_headers
                    ),
                    "responseByteCount": len(payload),
                    "responseSha256": captured["rawSha256"],
                    "safeCaptureDigest": captured["recordDigest"],
                }
            ],
            "preflightRecordDigest": preflight["recordDigest"],
            "manifestRecordDigest": manifest["recordDigest"],
            "responseByteCount": len(payload),
            "responseSha256": captured["rawSha256"],
            "redirectCount": 1,
            "redirectProjectionDigest": _digest_projection(
                redirect_projection
            ),
        }
    )


class _NetworkGhDirectTransport:
    def __init__(
        self,
        adapter: Any,
        token: memoryview,
        request_body_record: Optional[Mapping[str, Any]] = None,
    ):
        self._adapter = adapter
        self._token = token
        self._request_body_record = request_body_record

    def execute(self, **request: Any) -> Dict[str, Any]:
        if (
            request.get("wrapper") != "network-gh"
            or request.get("credentialBroker") is not None
        ):
            raise AuditError("network-gh direct transport request drift")
        return {
            "observation": _execute_network_gh_pages(
                self._adapter,
                request["operation"],
                request["argv"],
                request["preflight"],
                request["manifest"],
                self._token,
                request_body_record=self._request_body_record,
            )
        }


_CREDENTIAL_BROKER_SOURCE = b'''import posix as _p,sys as _s
_response=bytearray()
_request=bytearray()
_status=0
_fd=-1
try:
 if len(_s.argv)!=4 or _s.argv[0]!="-c" or _s.argv[1]!="--read-fd" or _s.argv[3] not in ("get","store","erase"):_status=70
 elif not _s.argv[2].isdigit() or (_s.argv[2]!="0" and _s.argv[2].startswith("0")):_status=70
 else:
  _fd=int(_s.argv[2])
  if _fd<3:_status=70
 if _status==0:
  _raw=_s.stdin.buffer.read(65537)
  if not isinstance(_raw,bytes) or len(_raw)>65536:_status=70
  else:_request.extend(_raw)
 if _status==0:
  if not _request or _request[-1:]!=b"\\n" or _request[-2:]==b"\\n\\n":_status=70
  else:
   _fields={}
   for _line in _request[:-1].split(b"\\n"):
    if _line.count(b"=")!=1:_status=70;break
    _key,_value=_line.split(b"=",1);_key=bytes(_key)
    if _key in _fields or _key not in (b"protocol",b"host",b"path",b"username") or not _value or b"\\x00" in _value or b"\\r" in _value or b"\\n" in _value:_status=70;break
    _fields[_key]=_value
   if _status==0 and (_fields.get(b"protocol")!=b"https" or _fields.get(b"host")!=b"github.com" or _fields.get(b"path")!=b"ChangGeng01/ProjectSix.git"):_status=70
 if _status==0 and _s.argv[3]=="get":
  while len(_response)<=65536:
   _chunk=_p.read(_fd,min(4096,65537-len(_response)))
   if not _chunk:break
   _response.extend(_chunk)
  if len(_response)>65536 or len(_response)<2 or _response[-2:]!=b"\\n\\n":_status=70
  else:
   _secret_fields={}
   for _line in _response[:-2].split(b"\\n"):
    if _line.count(b"=")!=1:_status=70;break
    _key,_value=_line.split(b"=",1);_key=bytes(_key)
    if _key in _secret_fields or _key not in (b"protocol",b"host",b"path",b"username",b"password") or not _value or b"\\x00" in _value or b"\\r" in _value or b"\\n" in _value:_status=70;break
    _secret_fields[_key]=_value
   if _status==0 and (set(_secret_fields)!={b"protocol",b"host",b"path",b"username",b"password"} or _secret_fields[b"protocol"]!=b"https" or _secret_fields[b"host"]!=b"github.com" or _secret_fields[b"path"]!=b"ChangGeng01/ProjectSix.git"):_status=70
  if _status==0:
   _s.stdout.buffer.write(_response)
   _s.stdout.buffer.flush()
except BaseException:
 _status=70
finally:
 if _fd>=3:
  try:_p.close(_fd)
  except BaseException:pass
 for _owned in (_response,_request):
  for _index in range(len(_owned)):_owned[_index]=0
if _status:_p._exit(_status)
'''
_CREDENTIAL_BROKER_SOURCE_TEXT = _CREDENTIAL_BROKER_SOURCE.decode(
    "ascii", "strict"
)
_CREDENTIAL_BROKER_BOOTSTRAP = (
    "exec(" + repr(_CREDENTIAL_BROKER_SOURCE_TEXT) + ")"
)


def _canonical_shell_argv(argv: Sequence[str]) -> str:
    quoted = []
    for value in argv:
        if not isinstance(value, str) or not value:
            raise AuditError("credential helper shell argv drift")
        try:
            value.encode("ascii", "strict")
        except UnicodeEncodeError as exc:
            raise AuditError("credential helper shell encoding drift") from exc
        if any(marker in value for marker in ("\x00", "\r", "\n")):
            raise AuditError("credential helper shell framing drift")
        quoted.append("'" + value.replace("'", "'\"'\"'") + "'")
    return " ".join(quoted)


_NATIVE_FORK_RLOCK_TYPE = type(threading.RLock())
_NATIVE_FORK_RLOCK_REPR = _NATIVE_FORK_RLOCK_TYPE.__repr__


def _fork_rlock_current_depth(lock: Any) -> int:
    """Read depth without unlocking on the frozen CPython 3.9 runtime.

    That runtime lacks _recursion_count. Its native repr reads owner/count
    together under the GIL. This deliberately is not a portable lock protocol:
    reject wrappers and every representation/identity inconsistency.
    """

    if type(lock) is not _NATIVE_FORK_RLOCK_TYPE:
        raise AuditError("fork lock is not the native RLock")
    representation = _NATIVE_FORK_RLOCK_REPR(lock)
    match = re.fullmatch(
        r"<(locked|unlocked) _thread\.RLock object owner=([0-9]+) "
        r"count=([0-9]+) at (0x[0-9a-f]+)>", representation,
    )
    if match is None:
        raise AuditError("fork lock depth representation is unavailable")
    state, owner_text, count_text, address = match.groups()
    owner, count = int(owner_text), int(count_text)
    if (
        int(address, 16) != id(lock)
        or (state == "unlocked" and (owner != 0 or count != 0))
        or (state == "locked" and (owner == 0 or count == 0))
    ):
        raise AuditError("fork lock depth representation drift")
    return count if owner == threading.get_ident() else 0


class _ForkLockAcquisition:
    """Own exactly one recursive level, including interrupted acquire/release."""

    def __init__(self, lock: Any) -> None:
        self.lock = lock
        self._pid = os.getpid()
        self._thread_ident = threading.get_ident()
        self._thread_object = threading.current_thread()
        self.baseline = _fork_rlock_current_depth(lock)
        self.settled = False

    def acquire(self) -> None:
        # Never wait through an inverted outer caller's ownership order.
        if not self.lock.acquire(blocking=False):
            raise AuditError("fork lock acquisition failed")

    def settle(self) -> None:
        # Depth zero is relative to the observing thread, not proof that a
        # different thread's retained callback level has been released.
        if (
            self._pid != os.getpid()
            or self._thread_ident != threading.get_ident()
            or self._thread_object is not threading.current_thread()
        ):
            raise AuditError("fork lock settlement owner drift")
        primary: Optional[BaseException] = None
        # A release interrupted before taking effect gets only one retry.
        # Read exact depth first: a post-release interruption is not retried.
        for attempt in range(3):
            try:
                depth = _fork_rlock_current_depth(self.lock)
            except BaseException as exc:
                if primary is None:
                    primary = exc
                else:
                    _retain_git_cleanup_error(primary, exc)
                # Failed observation cannot authorize any release/retry.
                break
            if depth == self.baseline:
                self.settled = True
                break
            if depth != self.baseline + 1 or attempt == 2:
                uncertainty = AuditError("fork lock settlement is uncertain")
                if primary is None:
                    primary = uncertainty
                else:
                    _retain_git_cleanup_error(primary, uncertainty)
                break
            try:
                self.lock.release()
            except BaseException as exc:
                if primary is None:
                    primary = exc
                else:
                    _retain_git_cleanup_error(primary, exc)
        if primary is not None:
            raise primary


_CREDENTIAL_BROKERS_LOCK = threading.RLock()
_CREDENTIAL_BROKERS: Any = weakref.WeakValueDictionary()
_CREDENTIAL_BROKER_INFLIGHT: Dict[int, Any] = {}
_CREDENTIAL_BROKER_POISONED: Dict[int, Any] = {}
_CREDENTIAL_BROKERS_FORK_MUST_EXIT = True
_CREDENTIAL_BROKERS_FORK_ACQUISITION: Any = None


class OneShotCredentialBroker:
    """Scope-bound one-shot helper backed by an inherited anonymous pipe."""

    def __init__(
        self,
        helper_response: OwnedSecretBuffer,
        *,
        generation_digest: Optional[str] = None,
    ):
        self._protocol = b""
        self._host = b""
        self._path = b""
        self._keys: Tuple[str, ...] = ()
        self._response = bytearray()
        self._response_length = 0
        self._consumed = False
        self._consumption_count = 0
        self._generation_digest = generation_digest
        self._read_slot: Optional[_ChildFdOwnerSlot] = None
        self._write_slot: Optional[_ChildFdOwnerSlot] = None
        self._pipe_slots: List[_ChildFdOwnerSlot] = []
        self._construction_uncertain = False
        self._destruction_uncertain = False
        self._lifecycle_lock = threading.RLock()
        # One immutable publication couples phase, exact claim, retained
        # lifecycle acquisition and offset. Claims are never renewed here.
        self._feed_state: Tuple[Any, ...] = ("idle", None, None, 0)
        self._response_mac_key = bytearray()
        self._response_mac = b""
        self._program: Dict[str, Any] = {}
        try:
            with _CREDENTIAL_BROKERS_LOCK:
                _CREDENTIAL_BROKER_INFLIGHT[id(self)] = self
                # Retain the same backing before even parsing: an interrupted
                # incoming-owner release must not orphan its partial wipe.
                if isinstance(helper_response, OwnedSecretBuffer):
                    self._response = helper_response.owner()
            fields = _parse_owned_credential_helper(helper_response)
            if generation_digest is not None:
                _require_lower_hex(
                    generation_digest, 64, "credential broker generation"
                )
            self._protocol = bytes(fields.view("protocol"))
            self._host = bytes(fields.view("host"))
            self._path = bytes(fields.view("path"))
            self._keys = tuple(fields.names)
            interpreter = Path(sys.executable).resolve(strict=True)
            interpreter_bytes, interpreter_stat = _read_ordinary_snapshot(
                interpreter,
                maximum=256 * 1024 * 1024,
                single_link=False,
            )
            self._program = _self_digest_record(
                {
                    "schemaVersion": "qinao.credential-broker-program.v1",
                    "interpreterPath": str(interpreter),
                    "interpreterByteCount": len(interpreter_bytes),
                    "interpreterFileSha256": _sha256(interpreter_bytes),
                    "interpreterMode": format(
                        stat.S_IMODE(interpreter_stat.st_mode), "04o"
                    ),
                    "flags": ["-I", "-S", "-B"],
                    "sourceByteCount": len(_CREDENTIAL_BROKER_SOURCE),
                    "sourceSha256": _sha256(_CREDENTIAL_BROKER_SOURCE),
                    "bootstrapSha256": _sha256(
                        _CREDENTIAL_BROKER_BOOTSTRAP.encode(
                            "ascii", "strict"
                        )
                    ),
                    "shellRendererVersion": "single-quote-v1",
                }
            )
            with _CREDENTIAL_BROKERS_LOCK:
                # Keep the mutable owner discoverable even if move_owner
                # transfers successfully and is interrupted before returning.
                self._response = helper_response.owner()
                if helper_response.move_owner() is not self._response:
                    raise AuditError("credential broker secret owner drift")
                self._response_length = len(self._response)
                self._response_mac_key = bytearray(secrets.token_bytes(32))
                self._response_mac = hmac.digest(
                    self._response_mac_key,
                    memoryview(self._response),
                    "sha256",
                )
                # A syscall/slot-registration gap has no safe raw-close
                # authority. Retain this published owner if interrupted;
                # cleanup still consumes every registered permanent slot.
                self._construction_uncertain = True
                read_fd, write_fd = os.pipe()
                read_slot = self._own_pipe_fd(read_fd)
                write_slot = self._own_pipe_fd(write_fd)
                self._read_slot = self._normalize_pipe_slot(read_slot)
                self._write_slot = self._normalize_pipe_slot(write_slot)
                self._construction_uncertain = False
                _CREDENTIAL_BROKERS[id(self)] = self
                _CREDENTIAL_BROKER_INFLIGHT.pop(id(self), None)
        except BaseException as primary:
            try:
                helper_response.release()
            except BaseException as cleanup:
                _retain_git_cleanup_error(primary, cleanup)
            try:
                self._fail_closed(primary_error=primary)
            except BaseException as cleanup:
                _retain_git_cleanup_error(primary, cleanup)
            raise

    def _own_pipe_fd(self, descriptor: int) -> "_ChildFdOwnerSlot":
        slot = _ChildFdOwnerSlot(descriptor, "credential broker pipe")
        self._pipe_slots.append(slot)
        return slot

    def _normalize_pipe_slot(self, slot: "_ChildFdOwnerSlot") -> "_ChildFdOwnerSlot":
        if slot.descriptor() >= 3:
            slot._operate(os.set_inheritable, False)
            return slot
        duplicate = self._own_pipe_fd(
            slot._operate(fcntl.fcntl, fcntl.F_DUPFD_CLOEXEC, 3)
        )
        slot.close()
        return duplicate

    @property
    def _read_fd(self) -> int:
        # Compatibility projections are instantaneous borrows, never owners.
        slot = self._read_slot
        return slot.descriptor() if slot is not None and slot.phase == "owned" else -1

    @property
    def _write_fd(self) -> int:
        slot = self._write_slot
        return slot.descriptor() if slot is not None and slot.phase == "owned" else -1

    @property
    def _feed_active(self) -> bool:
        return self._feed_state[0] in (
            "acquiring", "cancelled-acquire", "acquired", "active", "settling"
        )

    @property
    def _feed_lock_held(self) -> bool:
        acquisition = self._feed_state[2]
        return acquisition is not None and not acquisition.settled

    def __enter__(self) -> "OneShotCredentialBroker":
        return self

    def __exit__(self, exc_type: Any, exc: Any, traceback: Any) -> bool:
        del exc_type, exc, traceback
        self.close()
        return False

    def __del__(self) -> None:
        try:
            self.close()
        except BaseException:
            pass

    def _unregister(self) -> None:
        with _CREDENTIAL_BROKERS_LOCK:
            if _CREDENTIAL_BROKERS.get(id(self)) is self:
                _CREDENTIAL_BROKERS.pop(id(self), None)
            if _CREDENTIAL_BROKER_POISONED.get(id(self)) is self:
                _CREDENTIAL_BROKER_POISONED.pop(id(self), None)
            if _CREDENTIAL_BROKER_INFLIGHT.get(id(self)) is self:
                _CREDENTIAL_BROKER_INFLIGHT.pop(id(self), None)

    def _wipe_response(self) -> None:
        for index in range(len(self._response)):
            self._response[index] = 0

    def _wipe_mac_key(self) -> None:
        for index in range(len(self._response_mac_key)):
            self._response_mac_key[index] = 0

    def _close_owned_fd(self, attribute: str, label: str) -> None:
        del label
        slot = {"_read_fd": self._read_slot, "_write_fd": self._write_slot}[attribute]
        if slot is not None:
            slot.close()

    def _assert_response_integrity(self) -> None:
        if (
            len(self._response) != self._response_length
            or not self._response_mac_key
            or not hmac.compare_digest(
                self._response_mac,
                hmac.digest(
                    self._response_mac_key,
                    memoryview(self._response),
                    "sha256",
                ),
            )
        ):
            raise AuditError("credential broker response integrity drift")

    def assert_credential_binding(
        self, root: Path, preflight: Mapping[str, Any]
    ) -> Dict[str, str]:
        """Re-derive the credential authority from the still-owned bytes."""

        with self._lifecycle_lock:
            try:
                if self._consumed or self._feed_active:
                    raise AuditError(
                        "credential broker binding is no longer fresh"
                    )
                self._assert_response_integrity()
                fields = _parse_credential_helper_owner(self._response)
                source_identity = _git_credential_source_identity(
                    fields.view("username")
                )
                identity_digest = _digest_projection(source_identity)
                generation_digest = _credential_generation_digest(
                    Path(root), "git", fields.view("password")
                )
                if (
                    identity_digest
                    != preflight.get("gitCredentialIdentityDigest")
                ):
                    raise AuditError(
                        "credential broker identity binding drift"
                    )
                if (
                    generation_digest
                    != preflight.get("gitCredentialGenerationDigest")
                    or self._generation_digest != generation_digest
                ):
                    raise AuditError(
                        "credential broker generation binding drift"
                    )
                return {
                    "identityDigest": identity_digest,
                    "generationDigest": generation_digest,
                }
            except BaseException as primary:
                self._fail_closed(primary_error=primary)
                raise

    def _fail_closed(
        self, *, unregister: bool = True, raise_on_close_error: bool = False,
        primary_error: Optional[BaseException] = None,
    ) -> None:
        first_error = primary_error

        def retain(error: BaseException) -> None:
            nonlocal first_error
            if first_error is None:
                first_error = error
            else:
                _retain_git_cleanup_error(first_error, error)

        with self._lifecycle_lock:
            self._consumed = True
            destruction_uncertain = False
            for backing, wipe in (
                (self._response, self._wipe_response),
                (self._response_mac_key, self._wipe_mac_key),
            ):
                try:
                    wipe()
                except BaseException as exc:
                    retain(exc)
                    try:
                        # One finite same-object fallback, also wiping retained
                        # views/traceback aliases. Never resize or retry an
                        # arbitrary failing wipe callback.
                        backing[:] = b"\x00" * len(backing)
                    except BaseException as fallback_error:
                        destruction_uncertain = True
                        retain(fallback_error)
            self._destruction_uncertain = destruction_uncertain
            for slot in reversed(self._pipe_slots):
                try:
                    slot.close()
                except BaseException as exc:
                    retain(exc)
        unresolved = self._construction_uncertain or self._destruction_uncertain or any(
            slot.phase != "closed" for slot in self._pipe_slots
        )
        if unresolved:
            with _CREDENTIAL_BROKERS_LOCK:
                _CREDENTIAL_BROKER_POISONED[id(self)] = self
                _CREDENTIAL_BROKER_INFLIGHT.pop(id(self), None)
        elif unregister and not self._feed_active:
            self._unregister()
        if first_error is not None and raise_on_close_error:
            raise first_error
        if self._construction_uncertain and raise_on_close_error:
            raise AuditError("credential broker construction acquisition is uncertain")

    @property
    def read_fd(self) -> int:
        with self._lifecycle_lock:
            if self._read_fd < 3:
                raise AuditError("credential broker pipe is closed")
            return self._read_fd

    def broker_argv(self) -> Tuple[str, ...]:
        return (
            self._program["interpreterPath"], "-I", "-S", "-B",
            "-c", _CREDENTIAL_BROKER_BOOTSTRAP,
            "--read-fd",
            str(self.read_fd),
        )

    def broker_shell_command(self) -> str:
        return _canonical_shell_argv(self.broker_argv())

    def program_projection(
        self, preflight: Mapping[str, Any]
    ) -> Dict[str, Any]:
        rows = [
            row
            for row in _require_mapping(
                preflight.get("localProjection"),
                "credential broker local projection",
            ).get("tools", [])
            if isinstance(row, Mapping) and row.get("name") == "python"
        ]
        if len(rows) != 1:
            raise AuditError("credential broker interpreter row drift")
        row = rows[0]
        if (
            row.get("absolutePathDigest")
            != _network_redacted_value(
                "tool-path:python",
                self._program["interpreterPath"].encode("utf-8", "strict"),
            )["valueDigest"]
            or row.get("fileByteCount")
            != self._program["interpreterByteCount"]
            or row.get("fileSha256")
            != self._program["interpreterFileSha256"]
        ):
            raise AuditError("credential broker interpreter identity drift")
        return dict(self._program)

    def consume(
        self, action: str, protocol: str, host: str, path: str
    ) -> Optional[OwnedSecretBuffer]:
        try:
            with self._lifecycle_lock:
                if action in ("store", "erase"):
                    return None
                if action != "get":
                    raise AuditError("credential broker action drift")
                if self._consumed or self._feed_active:
                    raise AuditError("credential broker replay")
                try:
                    scope = (
                        protocol.encode("ascii", "strict"),
                        host.encode("ascii", "strict"),
                        path.encode("ascii", "strict"),
                    )
                except UnicodeEncodeError as exc:
                    raise AuditError("credential broker scope encoding") from exc
                if scope != (self._protocol, self._host, self._path):
                    raise AuditError("credential broker scope drift")
                self._assert_response_integrity()
                owner = self._response
                for attribute in ("_write_fd", "_read_fd"):
                    self._close_owned_fd(
                        attribute, "credential broker consume pipe"
                    )
                self._consumed = True
                self._consumption_count = 1
                self._wipe_mac_key()
                self._unregister()
                result = OwnedSecretBuffer.take(owner)
                self._response = bytearray()
        except BaseException as primary:
            self._fail_closed(primary_error=primary)
            raise
        return result

    def prime_for_child(self) -> None:
        """Test-seam-only bounded feed; production uses selector pumping."""

        claim = self._new_child_feed_claim()
        try:
            self._begin_child_feed(claim)
            while not self._pump_child_feed(claim):
                raise AuditError(
                    "credential broker test seam feed would block"
                )
            self._complete_child_feed(claim)
        except BaseException as primary:
            try:
                self._abort_child_feed(claim)
            except BaseException as cleanup:
                _retain_git_cleanup_error(primary, cleanup)
            raise

    def _new_child_feed_claim(self) -> Tuple[Any, ...]:
        # Allocation acquires no resource; a runner records this exact tuple
        # before begin publishes ownership and acquires its lifecycle level.
        return (os.getpid(), threading.get_ident(), threading.current_thread(), object())

    def _validate_child_feed_claim(self, claim: Any, phases: Tuple[str, ...]) -> Tuple[Any, ...]:
        state = self._feed_state
        if (
            type(claim) is not tuple or len(claim) != 4
            or state[1] is not claim or state[0] not in phases
            or claim[0] != os.getpid()
            or claim[1] != threading.get_ident()
            or claim[2] is not threading.current_thread()
        ):
            raise AuditError("credential broker child feed ownership drift")
        return state

    def _begin_child_feed(self, claim: Any = None) -> Tuple[Any, ...]:
        if claim is None:
            claim = self._new_child_feed_claim()
        acquisition: Optional[_ForkLockAcquisition] = None

        def finish_acquire_attempt() -> None:
            # This local continuation runs only after acquire has returned or
            # its call path has unwound. Publish that fact, not new cleanup
            # authority: every eventual settlement still validates the exact
            # PID/thread/claim and the original native depth token.
            state = self._feed_state
            if state[1] is not claim or state[2] is not acquisition:
                raise AuditError("credential broker child feed acquisition drift")
            if state[0] in ("acquiring", "cancelled-acquire"):
                self._feed_state = ("acquired", claim, acquisition, state[3])

        try:
            with _CREDENTIAL_BROKERS_LOCK:
                if (
                    type(claim) is not tuple or len(claim) != 4
                    or claim[0] != os.getpid()
                    or claim[1] != threading.get_ident()
                    or claim[2] is not threading.current_thread()
                    or self._feed_state[0] != "idle" or self._consumed
                ):
                    # Losing/stale callers never acquire, wipe or release the
                    # incumbent claim's resources.
                    raise AuditError("credential broker child feed is unavailable")
                acquisition = _ForkLockAcquisition(self._lifecycle_lock)
                self._feed_state = ("acquiring", claim, acquisition, 0)
            try:
                acquisition.acquire()
            finally:
                finish_acquire_attempt()
            if (
                self._consumed
                or self._write_fd < 3
                or self._read_fd < 3
            ):
                raise AuditError(
                    "credential broker child feed is unavailable"
                )
            self._assert_response_integrity()
            self._write_slot._operate(os.set_blocking, False)
            self._validate_child_feed_claim(claim, ("acquired",))
            self._feed_state = ("active", claim, acquisition, 0)
            return claim
        except BaseException as primary:
            if (
                acquisition is not None
                and self._feed_state[1] is claim
                and self._feed_state[2] is acquisition
            ):
                try:
                    # Also covers interruption after claim publication but
                    # before entering the inner acquire/finally scope.
                    finish_acquire_attempt()
                    self._abort_child_feed(claim)
                except BaseException as cleanup:
                    _retain_git_cleanup_error(primary, cleanup)
            raise

    def _child_feed_fd(self, claim: Any) -> int:
        self._validate_child_feed_claim(claim, ("active",))
        return self._write_slot.descriptor()

    def _pump_child_feed(self, claim: Any) -> bool:
        state = self._validate_child_feed_claim(claim, ("active",))
        offset = state[3]
        self._assert_response_integrity()
        if offset == self._response_length:
            return True
        try:
            written = self._write_slot._operate(
                os.write,
                memoryview(self._response)[
                    offset : offset + 64 * 1024
                ],
            )
        except BlockingIOError:
            return False
        except OSError as exc:
            raise AuditError("credential broker child pipe failure") from exc
        if written <= 0:
            raise AuditError("credential broker child feed short write")
        if self._feed_state is not state:
            raise AuditError("credential broker child feed claim changed during write")
        self._feed_state = ("active", claim, state[2], offset + written)
        return offset + written == self._response_length

    def _settle_child_feed(self, claim: Any) -> None:
        state = self._validate_child_feed_claim(
            claim, ("acquiring", "cancelled-acquire", "acquired", "active", "settling", "closed")
        )
        if state[0] == "closed":
            return
        acquisition = state[2]
        if state[0] in ("acquiring", "cancelled-acquire"):
            # A same-thread close can run before the native syscall and that
            # syscall can still resume afterward. Keep its exact token live;
            # only begin's acquire-return/unwind continuation may settle it.
            self._feed_state = ("cancelled-acquire", claim, acquisition, state[3])
            return
        self._feed_state = ("settling", claim, acquisition, state[3])
        try:
            acquisition.settle()
        finally:
            if acquisition.settled:
                self._feed_state = ("closed", claim, acquisition, state[3])
                if not self._construction_uncertain and not self._destruction_uncertain and all(
                    slot.phase == "closed" for slot in self._pipe_slots
                ):
                    self._unregister()

    def _complete_child_feed(self, claim: Any) -> None:
        state = self._validate_child_feed_claim(claim, ("active",))
        primary: Optional[BaseException] = None
        try:
            if state[3] != self._response_length:
                raise AuditError(
                    "credential broker child feed completion drift"
                )
            self._close_owned_fd(
                "_write_fd", "credential broker child feed pipe"
            )
            self._wipe_response()
            self._wipe_mac_key()
        except BaseException as exc:
            primary = exc
            self._fail_closed(primary_error=primary)
            raise
        finally:
            try:
                self._settle_child_feed(claim)
            except BaseException as cleanup:
                if primary is None:
                    raise
                _retain_git_cleanup_error(primary, cleanup)

    def _abort_child_feed(self, claim: Any) -> None:
        state = self._validate_child_feed_claim(
            claim, ("acquiring", "cancelled-acquire", "acquired", "active", "settling", "closed")
        )
        if state[0] == "closed":
            return
        primary: Optional[BaseException] = None
        try:
            self._fail_closed(raise_on_close_error=True)
        except BaseException as exc:
            primary = exc
            raise
        finally:
            try:
                self._settle_child_feed(claim)
            except BaseException as cleanup:
                if primary is None:
                    raise
                _retain_git_cleanup_error(primary, cleanup)

    def finalize_child_consumption(self) -> None:
        with self._lifecycle_lock:
            if self._read_fd < 3 or self._write_fd >= 0 or self._feed_active:
                raise AuditError(
                    "credential broker child feed was not finalized"
                )
            self._read_slot._operate(os.set_blocking, False)
            remainder = bytearray(self._response_length + 1)
            observed = 0
            try:
                while True:
                    try:
                        count = self._read_slot._operate(
                            os.readv,
                            [memoryview(remainder)[observed:]],
                        )
                    except BlockingIOError:
                        raise AuditError(
                            "credential broker child is still live"
                        )
                    if count == 0:
                        break
                    observed += count
                    if observed > self._response_length:
                        raise AuditError("credential broker child pipe drift")
                if observed:
                    raise AuditError(
                        "credential broker child did not consume response"
                    )
                self._consumed = True
                self._consumption_count = 1
            finally:
                for index in range(len(remainder)):
                    remainder[index] = 0
                self._wipe_response()

    def close(self) -> None:
        if self._feed_active:
            self._abort_child_feed(self._feed_state[1])
        self._fail_closed(raise_on_close_error=True)

    def _close_after_fork_child(self) -> None:
        self._wipe_response()
        self._wipe_mac_key()
        self._consumed = True
        # A broker carrying endpoint state may not touch inherited slot locks.
        # The composite normally exits before reaching this clean-child hook.
        if self._pipe_slots or self._construction_uncertain or self._destruction_uncertain:
            os._exit(70)
        self._lifecycle_lock = threading.RLock()
        self._feed_state = ("idle", None, None, 0)

    def projection(self) -> Dict[str, Any]:
        return {
            "schemaVersion": "qinao.one-shot-credential-broker.v1",
            "protocol": self._protocol.decode("ascii"),
            "host": self._host.decode("ascii"),
            "path": self._path.decode("ascii"),
            "responseKeyNames": list(self._keys),
            "generationDigest": self._generation_digest,
            "consumed": self._consumed,
            "consumptionCount": self._consumption_count,
            "transport": "anonymous-pipe",
            "programDigest": self._program["recordDigest"],
        }


def _credential_brokers_before_fork() -> bool:
    global _CREDENTIAL_BROKERS_FORK_MUST_EXIT
    global _CREDENTIAL_BROKERS_FORK_ACQUISITION
    _CREDENTIAL_BROKERS_FORK_MUST_EXIT = True
    if _CREDENTIAL_BROKERS_FORK_ACQUISITION is not None:
        raise AuditError("credential fork lock settlement is pending")
    _CREDENTIAL_BROKERS_FORK_ACQUISITION = _ForkLockAcquisition(_CREDENTIAL_BROKERS_LOCK)
    _CREDENTIAL_BROKERS_FORK_ACQUISITION.acquire()
    _CREDENTIAL_BROKERS_FORK_MUST_EXIT = bool(
        _CREDENTIAL_BROKERS or _CREDENTIAL_BROKER_POISONED
        or _CREDENTIAL_BROKER_INFLIGHT
    )
    return _CREDENTIAL_BROKERS_FORK_MUST_EXIT


def _credential_brokers_after_fork_parent() -> None:
    global _CREDENTIAL_BROKERS_FORK_MUST_EXIT
    global _CREDENTIAL_BROKERS_FORK_ACQUISITION
    _CREDENTIAL_BROKERS_FORK_MUST_EXIT = True
    acquisition = _CREDENTIAL_BROKERS_FORK_ACQUISITION
    if acquisition is not None:
        try:
            acquisition.settle()
        finally:
            if acquisition.settled:
                _CREDENTIAL_BROKERS_FORK_ACQUISITION = None


def _credential_brokers_after_fork_child() -> None:
    global _CREDENTIAL_BROKERS_LOCK
    global _CREDENTIAL_BROKERS
    global _CREDENTIAL_BROKER_POISONED
    global _CREDENTIAL_BROKER_INFLIGHT
    global _CREDENTIAL_BROKERS_FORK_MUST_EXIT
    global _CREDENTIAL_BROKERS_FORK_ACQUISITION
    must_exit = _CREDENTIAL_BROKERS_FORK_MUST_EXIT
    if must_exit:
        os._exit(70)
    try:
        inherited_by_id = {
            id(broker): broker for broker in _CREDENTIAL_BROKERS.values()
        }
        inherited_by_id.update(_CREDENTIAL_BROKER_POISONED)
        inherited_by_id.update(_CREDENTIAL_BROKER_INFLIGHT)
        for broker in tuple(inherited_by_id.values()):
            try:
                broker._close_after_fork_child()
            except BaseException:
                os._exit(70)
    finally:
        _CREDENTIAL_BROKERS = weakref.WeakValueDictionary()
        _CREDENTIAL_BROKER_POISONED = {}
        _CREDENTIAL_BROKER_INFLIGHT = {}
        _CREDENTIAL_BROKERS_LOCK = threading.RLock()
        _CREDENTIAL_BROKERS_FORK_MUST_EXIT = True
        _CREDENTIAL_BROKERS_FORK_ACQUISITION = None


def _network_git_child_command(
    operation: str,
    argv: Sequence[str],
    broker: OneShotCredentialBroker,
) -> List[str]:
    """Construct the sole reviewed Git child command projection."""

    specification = _network_operation_contract(operation)
    if specification["wrapper"] != "network-git":
        raise AuditError("runtime Git transport operation drift")
    child_argv = _parse_network_git_argv(operation, argv)["argv"]
    if type(broker) is not OneShotCredentialBroker:
        raise AuditError("runtime Git transport broker drift")
    broker_argv = broker.broker_argv()
    helper_command = "!" + broker.broker_shell_command()
    if helper_command != "!" + _canonical_shell_argv(broker_argv):
        raise AuditError("runtime Git helper shell drift")
    command = [
        "/usr/bin/git", "--no-pager", "--no-optional-locks",
        "--no-replace-objects",
        "-c", "core.hooksPath=/dev/null",
        "-c", "core.fsmonitor=false",
        "-c", "http.followRedirects=false",
        "-c", "credential.useHttpPath=true",
        "-c", "credential.helper=",
        "-c", "credential.helper=" + helper_command,
    ]
    if specification["parserFamily"] == "git-push":
        command.extend(
            [
                "-c", "remote.origin.mirror=false",
                "-c", "push.followTags=false",
                "-c", "push.pushOption=",
                "-c", "push.gpgSign=false",
                "-c", "push.useForceIfIncludes=false",
            ]
        )
    command.extend(child_argv)
    return command


def _git_child_fd_identity(descriptor: int, label: str) -> Dict[str, str]:
    if not isinstance(descriptor, int) or descriptor < 0:
        raise AuditError(label + " descriptor drift")
    try:
        observed = os.fstat(descriptor)
    except OSError as exc:
        raise AuditError(label + " descriptor is unavailable") from exc
    return {
        "device": str(observed.st_dev),
        "inode": str(observed.st_ino),
        "mode": "%04o" % stat.S_IMODE(observed.st_mode),
        "fileType": str(stat.S_IFMT(observed.st_mode)),
    }


def _git_child_read_pipe_binding(
    descriptor: int, label: str
) -> Dict[str, Any]:
    identity = _git_child_fd_identity(descriptor, label)
    try:
        descriptor_flags = fcntl.fcntl(descriptor, fcntl.F_GETFD)
        status_flags = fcntl.fcntl(descriptor, fcntl.F_GETFL)
    except OSError as exc:
        raise AuditError(label + " flags are unavailable") from exc
    if (
        int(identity["fileType"]) != stat.S_IFIFO
        or status_flags & os.O_ACCMODE != os.O_RDONLY
        or descriptor_flags & fcntl.FD_CLOEXEC == 0
        or os.get_inheritable(descriptor)
    ):
        raise AuditError(label + " policy drift")
    return {
        "identity": identity,
        "descriptorFlags": descriptor_flags,
        "statusFlags": status_flags,
        "accessMode": "read-only",
        "closeOnExec": True,
    }


def _git_child_execution_binding(
    *,
    root: Path,
    attempt: Mapping[str, Any],
    consumption: Mapping[str, Any],
    operation: str,
    argv: Sequence[str],
    preflight: Mapping[str, Any],
    manifest: Mapping[str, Any],
    capsule: Mapping[str, Any],
    snapshot: Mapping[str, Any],
    broker: OneShotCredentialBroker,
    cwd_identity: Mapping[str, str],
) -> Dict[str, Any]:
    """Seal durable history and the exact imminent child invocation."""

    attempt_value = dict(_require_mapping(attempt, "network Git attempt"))
    consumption_value = dict(
        _require_mapping(consumption, "network Git capsule consumption")
    )
    preflight_value = dict(
        _require_mapping(preflight, "network Git grant preflight")
    )
    manifest_value = dict(
        _require_mapping(manifest, "network Git grant manifest")
    )
    capsule_value = dict(
        _require_mapping(capsule, "network Git grant capsule")
    )
    snapshot_value = dict(
        _require_mapping(snapshot, "network Git grant snapshot")
    )
    for value in (
        attempt_value,
        consumption_value,
        preflight_value,
        manifest_value,
        capsule_value,
    ):
        _verify_self_digest(value)
    normalized = _validate_argv(argv)
    selected = select_network_request_row(
        manifest_value, operation, normalized, preflight_value
    )
    specification = _network_operation_contract(operation)
    expected_profile = {
        "git-ls-remote": "ls-remote-read",
        "git-fetch-empty": "fetch-quarantine",
        "git-fetch-known": "fetch-quarantine",
        "git-push": "push-outbound",
    }.get(specification["parserFamily"])
    if expected_profile is None:
        raise AuditError("network Git execution grant profile drift")
    if (
        attempt_value.get("operationKind") != "network-attempt"
        or attempt_value.get("completionState") != "attempted"
        or attempt_value.get("wrapper") != "network-git"
        or attempt_value.get("operation") != operation
        or attempt_value.get("argvDigest")
        != _sha256(canonical_json_bytes(normalized))
        or attempt_value.get("preflightRecordDigest")
        != preflight_value.get("recordDigest")
        or attempt_value.get("stableProjectionDigest")
        != preflight_value.get("stableProjectionDigest")
        or attempt_value.get("manifestRecordDigest")
        != manifest_value.get("recordDigest")
        or attempt_value.get("requestId") != selected.get("requestId")
        or attempt_value.get("rowDigest") != selected.get("rowDigest")
        or attempt_value.get("useKey") != attempt_value.get("logicalKey")
        or attempt_value.get("maximumUses") != 1
        or attempt_value.get("capsuleProfile") != expected_profile
        or attempt_value.get("capsuleResourceId")
        != capsule_value.get("resourceId")
        or attempt_value.get("capsuleRecordDigest")
        != capsule_value.get("recordDigest")
        or attempt_value.get("capsuleSnapshotDigest")
        != snapshot_value.get("snapshotDigest")
        or attempt_value.get("capsuleSnapshotRecordDigest")
        != snapshot_value.get("recordDigest")
    ):
        raise AuditError("network Git execution grant attempt drift")
    if (
        consumption_value.get("operationKind")
        != "git-execution-capsule-consumed"
        or consumption_value.get("completionState") != "consumed"
        or consumption_value.get("resourceId")
        != capsule_value.get("resourceId")
        or consumption_value.get("profile") != expected_profile
        or consumption_value.get("capsuleRecordDigest")
        != capsule_value.get("recordDigest")
        or consumption_value.get("snapshotDigest")
        != snapshot_value.get("snapshotDigest")
        or consumption_value.get("snapshotRecordDigest")
        != snapshot_value.get("recordDigest")
        or consumption_value.get("preflightRecordDigest")
        != preflight_value.get("recordDigest")
    ):
        raise AuditError("network Git execution grant consumption drift")
    if type(broker) is not OneShotCredentialBroker:
        raise AuditError("network Git execution grant broker type drift")
    credential_binding = broker.assert_credential_binding(
        Path(root), preflight_value
    )
    broker_projection = broker.projection()
    if (
        broker_projection.get("consumed") is not False
        or broker_projection.get("consumptionCount") != 0
    ):
        raise AuditError("network Git execution grant broker is not fresh")
    read_fd = broker.read_fd
    read_fd_binding = _git_child_read_pipe_binding(
        read_fd, "network Git broker"
    )
    cwd_projection = dict(
        _require_mapping(cwd_identity, "network Git cwd anchor")
    )
    if set(cwd_projection) != {"device", "inode", "mode", "fileType"}:
        raise AuditError("network Git cwd anchor shape drift")
    supervisor_row = next(
        row for row in preflight_value["localProjection"]["tools"]
        if row["name"] == "sh"
    )
    supervisor_observation = _capture_network_supervisor_identity()
    if (
        supervisor_observation["absolutePath"] != supervisor_row["absolutePath"]
        or len(supervisor_observation["fileBytes"]) != supervisor_row["fileByteCount"]
        or _sha256(supervisor_observation["fileBytes"]) != supervisor_row["fileSha256"]
    ):
        raise AuditError("network Git supervisor interpreter identity drift")
    supervisor_identity = {
        field: supervisor_row[field]
        for field in ("absolutePath", "fileByteCount", "fileSha256")
    }
    command = _network_git_child_command(operation, normalized, broker)
    broker_program = broker.program_projection(preflight_value)
    broker_argv = list(broker.broker_argv())
    broker_shell = broker.broker_shell_command()
    return _self_digest_record(
        {
            "schemaVersion": "qinao.network-git-child-binding.v1",
            "attemptRecordDigest": attempt_value["recordDigest"],
            "capsuleConsumptionRecordDigest": consumption_value[
                "recordDigest"
            ],
            "logicalKey": attempt_value["logicalKey"],
            "reservationRecordDigest": attempt_value[
                "reservationRecordDigest"
            ],
            "operation": operation,
            "argvDigest": _sha256(canonical_json_bytes(normalized)),
            "commandDigest": _sha256(canonical_json_bytes(command)),
            "supervisorEnvelopeVersion": (
                _NETWORK_GIT_SUPERVISOR_VERSION
            ),
            "supervisorExecutable": (
                supervisor_identity["absolutePath"]
            ),
            "supervisorInterpreter": supervisor_identity,
            "supervisorPolicyDigest": _sha256(
                _NETWORK_GIT_SUPERVISOR_POLICY.encode(
                    "ascii", "strict"
                )
            ),
            "supervisorArgvForwarding": "positional-dollar-at",
            "supervisorReadinessProof": "anonymous-pipe-exact-Q",
            "supervisorParentDeathPolicy": "pipe-eof-kill-process-group",
            "childLifetimeQuiescenceProof": "anonymous-pipe-eof",
            "environmentDigest": _sha256(
                canonical_json_bytes(dict(_NETWORK_CHILD_ENVIRONMENT))
            ),
            "preflightRecordDigest": preflight_value["recordDigest"],
            "manifestRecordDigest": manifest_value["recordDigest"],
            "requestId": selected["requestId"],
            "rowDigest": selected["rowDigest"],
            "capsuleResourceId": capsule_value["resourceId"],
            "capsuleRecordDigest": capsule_value["recordDigest"],
            "capsuleSnapshotDigest": snapshot_value["snapshotDigest"],
            "capsuleSnapshotRecordDigest": snapshot_value["recordDigest"],
            "brokerProjectionDigest": _sha256(
                canonical_json_bytes(broker_projection)
            ),
            "brokerCredentialIdentityDigest": credential_binding[
                "identityDigest"
            ],
            "brokerCredentialGenerationDigest": credential_binding[
                "generationDigest"
            ],
            "brokerProgramDigest": broker_program["recordDigest"],
            "brokerArgvDigest": _sha256(
                canonical_json_bytes(broker_argv)
            ),
            "brokerShellCommandDigest": _sha256(
                broker_shell.encode("ascii", "strict")
            ),
            "brokerReadFd": read_fd,
            "brokerReadFdBinding": read_fd_binding,
            "cwdAnchorIdentity": cwd_projection,
        }
    )


def _retain_git_cleanup_error(primary: BaseException, cleanup: BaseException) -> None:
    """Keep ordered cleanup evidence without replacing the original failure."""
    if cleanup is not primary:
        primary.__dict__.setdefault("cleanup_errors", []).append(cleanup)


_CLEANUP_KINDS = {
    "git-capsule-cleanup-settled": "git-capsule-preparation",
    "network-cleanup-settled": "lfs-network-attempt",
}
_CLEANUP_ACTIONS = {
    "git-capsule-preparation": ("capsule-preservation", "capsule-release"),
    "lfs-network-attempt": ("helper-release", "helper-fallback", "authorization-release", "authorization-fallback"),
}
_CLEANUP_CATEGORIES = frozenset({"audit", "os", "interrupt", "exit", "memory", "other"})
_CLEANUP_DIAGNOSTIC_CONTEXTS: Dict[int, Dict[str, Any]] = {}
_CLEANUP_DIAGNOSTIC_LOCK = threading.RLock()


def _cleanup_diagnostics_after_fork_child() -> None:
    # A clean child inherits neither publication identity nor a usable lock.
    # Do not acquire a lock that may have belonged to another parent thread.
    global _CLEANUP_DIAGNOSTIC_CONTEXTS, _CLEANUP_DIAGNOSTIC_LOCK
    _CLEANUP_DIAGNOSTIC_CONTEXTS = {}
    _CLEANUP_DIAGNOSTIC_LOCK = threading.RLock()


class _CleanupDiagnosticContext:
    """Identity-only permission to publish one diagnostic, never to execute."""
    __slots__ = ()


def _cleanup_category(error: BaseException) -> str:
    for kind, label in ((AuditError, "audit"), (KeyboardInterrupt, "interrupt"),
                        (SystemExit, "exit"), (MemoryError, "memory"), (OSError, "os")):
        if isinstance(error, kind):
            return label
    return "other"


def _validate_cleanup_disposition(value: Any) -> Dict[str, Any]:
    value = dict(_require_mapping(value, "cleanup disposition"))
    if set(value) != {"schemaVersion", "runId", "ownerKind", "ownerId", "ownerRecordDigest",
            "ownerContextDigest", "terminalRecordDigest", "primaryAction", "primaryCategory", "errors", "owners", "recordDigest"}:
        raise AuditError("cleanup disposition field drift")
    if (value["schemaVersion"] != "qinao.cleanup-disposition.v1" or type(value["ownerKind"]) is not str
            or value["ownerKind"] not in _CLEANUP_ACTIONS):
        raise AuditError("cleanup disposition schema/owner drift")
    _verify_self_digest(value)
    for field in ("ownerRecordDigest", "ownerContextDigest"):
        _require_lower_hex(value[field], 64, "cleanup " + field)
    for field in ("runId", "ownerId"):
        _require_lower_hex(value[field], 32, "cleanup " + field)
    if value["terminalRecordDigest"] is not None:
        _require_lower_hex(value["terminalRecordDigest"], 64, "cleanup terminal")
    actions = _CLEANUP_ACTIONS[value["ownerKind"]]
    body_action = "capsule-body" if value["ownerKind"] == "git-capsule-preparation" else "lfs-body"
    errors = value["errors"]
    if not isinstance(errors, list) or len(errors) > min(8, len(actions)):
        raise AuditError("cleanup error row bound drift")
    positions = []
    for sequence, row in enumerate(errors, 1):
        if (not isinstance(row, Mapping) or set(row) != {"sequence", "action", "category"}
                or type(row["sequence"]) is not int or row["sequence"] != sequence
                or type(row["action"]) is not str or type(row["category"]) is not str
                or row["action"] not in actions or row["category"] not in _CLEANUP_CATEGORIES):
            raise AuditError("cleanup error row drift")
        positions.append(actions.index(row["action"]))
    if positions != sorted(set(positions)):
        raise AuditError("cleanup error action order drift")
    if (type(value["primaryCategory"]) is not str or type(value["primaryAction"]) is not str
            or value["primaryCategory"] not in _CLEANUP_CATEGORIES or value["primaryAction"] not in (body_action,) + actions):
        raise AuditError("cleanup primary drift")
    if value["primaryAction"] != body_action and (not errors or
            (value["primaryAction"], value["primaryCategory"]) != (errors[0]["action"], errors[0]["category"])):
        raise AuditError("cleanup primary/first error drift")
    owners = value["owners"]
    names = ["preparation-lock"] if body_action == "capsule-body" else ["helper", "authorization"]
    if (not isinstance(owners, list) or not owners or len(owners) > len(names)
            or any(not isinstance(row, Mapping) or set(row) != {"name", "state"}
                or row["name"] != names[index] or row["state"] not in ("released", "uncertain")
                for index, row in enumerate(owners))):
        raise AuditError("cleanup owner state drift")
    if body_action == "lfs-body" and len(owners) == 1 and any(row["action"].startswith("authorization-") for row in errors):
        raise AuditError("cleanup action without acquired owner")
    return value


def _cleanup_projected_owner(disposition: Mapping[str, Any], resources: Mapping[str, Any], attempts: Mapping[str, Any]) -> Dict[str, Any]:
    if disposition["ownerKind"] == "git-capsule-preparation":
        owner = resources.get(disposition["ownerId"])
        record = owner.get("allocation") if isinstance(owner, Mapping) else None
        preparation = record.get("preparation") if isinstance(record, Mapping) else None
        if (not isinstance(preparation, Mapping) or record.get("resourceKind") != "git-execution-capsule"
                or _sha256(canonical_json_bytes(preparation)) != disposition["ownerContextDigest"]):
            raise AuditError("cleanup capsule owner binding drift")
    else:
        owner = attempts.get(disposition["ownerId"])
        record = owner.get("attempt") if isinstance(owner, Mapping) else None
        if (not isinstance(record, Mapping) or record.get("wrapper") != "lfs-batch"
                or record.get("reservationRecordDigest") != disposition["ownerContextDigest"]):
            raise AuditError("cleanup network owner binding drift")
    if not isinstance(owner, dict) or record.get("recordDigest") != disposition["ownerRecordDigest"] or record.get("runId") != disposition["runId"]:
        raise AuditError("cleanup owner lineage drift")
    return owner


def _project_cleanup_record(record: Mapping[str, Any], resources: Mapping[str, Any], attempts: Mapping[str, Any]) -> None:
    disposition = _validate_cleanup_disposition(record.get("cleanupDisposition"))
    owner = _cleanup_projected_owner(disposition, resources, attempts)
    owner_record = owner["allocation"] if disposition["ownerKind"] == "git-capsule-preparation" else owner["attempt"]
    terminal = owner.get("preparationTerminal") if disposition["ownerKind"] == "git-capsule-preparation" else owner.get("terminal")
    if (record.get("runId") != disposition["runId"] or record.get("sequence", 0) <= owner_record["sequence"]
            or owner.get("cleanupDiagnostic") is not None
            or disposition["terminalRecordDigest"] != (terminal.get("recordDigest") if isinstance(terminal, Mapping) else None)
            or (isinstance(terminal, Mapping) and terminal["sequence"] >= record["sequence"])):
        raise AuditError("cleanup terminal/order/duplicate drift")
    owner["cleanupDiagnostic"] = dict(record)


def _cleanup_owner_uncertain(resource: Mapping[str, Any]) -> bool:
    return any(row["state"] == "uncertain" for row in resource.get("cleanupDiagnostic", {}).get("cleanupDisposition", {}).get("owners", []))


def _capture_cleanup_diagnostic_context(root: Path, owner_kind: str, owner: Any, owner_record: Mapping[str, Any]) -> Any:
    root = _absolute_path_without_symlink_resolution(Path(root))
    if owner_kind == "git-capsule-preparation":
        if type(owner) is not _GitCapsulePreparationGuard or owner.root != root:
            raise AuditError("cleanup live capsule owner drift")
        owner.revalidate()
        if owner_record.get("preparation") != owner.preparation:
            raise AuditError("cleanup capsule preparation drift")
        owner_id = owner_record["resourceId"]
        context_digest = _sha256(canonical_json_bytes(owner.preparation))
    elif owner_kind == "lfs-network-attempt":
        recovered = recover_run_state(root)
        reservations = [row for row in recovered.get("networkReservations", [])
                        if row.get("reservation", {}).get("recordDigest") == owner_record.get("reservationRecordDigest")]
        if len(reservations) != 1 or type(owner) is not _NetworkExecutionReservationGuard:
            raise AuditError("cleanup live network owner drift")
        owner.require_reservation(reservations[0]["reservation"])
        if _network_execution_guard(root, reservations[0]["reservation"]) is not owner:
            raise AuditError("cleanup registered network owner drift")
        owner_id, context_digest = owner_record["attemptId"], owner_record["reservationRecordDigest"]
    else:
        raise AuditError("cleanup context kind drift")
    binding = {"runId": owner_record["runId"], "ownerKind": owner_kind, "ownerId": owner_id,
        "ownerRecordDigest": owner_record["recordDigest"], "ownerContextDigest": context_digest}
    recovered = recover_run_state(root)
    attempts = {row["attempt"]["attemptId"]: row for row in recovered.get("networkAttempts", [])}
    projected = _cleanup_projected_owner(binding, recovered.get("resources", {}), attempts)
    if projected.get("cleanupDiagnostic") is not None:
        raise AuditError("cleanup context already terminal")
    context = _CleanupDiagnosticContext()
    with _CLEANUP_DIAGNOSTIC_LOCK:
        _CLEANUP_DIAGNOSTIC_CONTEXTS[id(context)] = {"context": context, "root": root, "pid": os.getpid(),
            "thread": threading.current_thread(), "binding": binding, "payload": None}
    return context


def _cleanup_context_entry(context: Any, root: Optional[Path] = None) -> Dict[str, Any]:
    with _CLEANUP_DIAGNOSTIC_LOCK:
        entry = _CLEANUP_DIAGNOSTIC_CONTEXTS.get(id(context))
        if (type(context) is not _CleanupDiagnosticContext or entry is None or entry["context"] is not context
                or entry["pid"] != os.getpid() or entry["thread"] is not threading.current_thread()
                or (root is not None and entry["root"] != root)):
            raise AuditError("cleanup publication lacks live diagnostic owner")
        return entry


def _drop_cleanup_diagnostic_context(context: Any) -> None:
    if context is not None:
        _cleanup_context_entry(context)
        with _CLEANUP_DIAGNOSTIC_LOCK:
            _CLEANUP_DIAGNOSTIC_CONTEXTS.pop(id(context))


def _validate_cleanup_publication(transaction: LedgerTransaction, record: Mapping[str, Any]) -> None:
    if record.get("operationKind") not in _CLEANUP_KINDS:
        return
    entry = _cleanup_context_entry(getattr(transaction, "_cleanup_diagnostic_context", None), transaction.root)
    if record.get("cleanupDisposition") != entry["payload"] or entry["payload"] is None:
        raise AuditError("cleanup publication payload drift")
    _identity, records = _recover_records_fd(transaction)
    _project_state(transaction.root, tuple(records) + (record,), transaction=transaction)


def _publish_cleanup_disposition(context: Any, primary: BaseException, primary_action: str,
                                 events: Sequence[Tuple[str, BaseException]], owners: Sequence[Mapping[str, str]]) -> Optional[Dict[str, Any]]:
    if context is None:
        return None
    entry = _cleanup_context_entry(context)
    root, binding = entry["root"], entry["binding"]
    kind = next(kind for kind, owner_kind in _CLEANUP_KINDS.items() if owner_kind == binding["ownerKind"])
    if entry["payload"] is None:
        recovered = recover_run_state(root)
        if recovered.get("classification") != "complete":
            raise AuditError("cleanup publication owner projection is indeterminate")
        attempts = {row["attempt"]["attemptId"]: row for row in recovered["networkAttempts"]}
        owner = _cleanup_projected_owner(binding, recovered["resources"], attempts)
        terminal = owner.get("preparationTerminal") if binding["ownerKind"] == "git-capsule-preparation" else owner.get("terminal")
        entry["payload"] = _validate_cleanup_disposition(_self_digest_record({
            "schemaVersion": "qinao.cleanup-disposition.v1", **binding,
            "terminalRecordDigest": terminal.get("recordDigest") if isinstance(terminal, Mapping) else None,
            "primaryAction": primary_action, "primaryCategory": _cleanup_category(primary),
            "errors": [{"sequence": index, "action": action, "category": _cleanup_category(error)}
                       for index, (action, error) in enumerate(events, 1)], "owners": list(owners)}))
    def publish(transaction: LedgerTransaction):
        recovered = transaction.recover()
        attempts = {row["attempt"]["attemptId"]: row for row in recovered["networkAttempts"]}
        owner = _cleanup_projected_owner(binding, recovered["resources"], attempts)
        existing = owner.get("cleanupDiagnostic")
        if existing is not None:
            if existing.get("cleanupDisposition") != entry["payload"]:
                raise AuditError("cleanup diagnostic conflict")
            return existing
        transaction._cleanup_diagnostic_context = context
        return transaction.append_record(recovered, kind, entry["payload"]["recordDigest"], [], "diagnostic-only",
            {"cleanupDisposition": entry["payload"]})
    try:
        record = _execute_ledger_transaction(root, operation_kind=kind, body=publish)
    except BaseException as publication_error:
        _retain_git_cleanup_error(primary, publication_error)
        try:
            recovered = recover_run_state(root)
            matches = [row for row in recovered.get("records", []) if row.get("operationKind") == kind
                       and row.get("cleanupDisposition") == entry["payload"] and entry["payload"] is not None]
            if len(matches) != 1:
                raise AuditError("cleanup publication remains incomplete")
            record = matches[0]
        except BaseException as observation_error:
            _retain_git_cleanup_error(primary, observation_error)
            primary.__dict__["cleanup_publication_uncertain"] = context
            return None
    _drop_cleanup_diagnostic_context(context)
    return record


def _settle_cleanup_diagnostic(context: Any, primary: BaseException, primary_action: str,
                               events: Sequence[Tuple[str, BaseException]], owners: Sequence[Mapping[str, str]]) -> None:
    try:
        _publish_cleanup_disposition(context, primary, primary_action, events, owners)
    except BaseException as publication_error:
        _retain_git_cleanup_error(primary, publication_error)
        primary.__dict__["cleanup_publication_uncertain"] = context


def _make_git_child_execution_grant_authority() -> Tuple[Any, ...]:
    """Create process-local MintPermit, grant, and anchor-lease authority.

    Durable records prove what happened; they deliberately cannot recreate
    permission to start a child.  That permission originates only from the
    normal return of the exact attempt append in this process and thread.
    """

    class GitChildExecutionMintPermit:
        __slots__ = ()

    class GitChildExecutionGrant:
        __slots__ = ()

    registry_lock = threading.RLock()
    root_slots: Dict[str, Dict[str, Any]] = {}
    permits: Dict[int, Dict[str, Any]] = {}
    grants: Dict[int, Dict[str, Any]] = {}
    live_entries: Dict[int, Dict[str, Any]] = {}
    fork_must_exit = True
    fork_acquisition: Any = None

    def root_value_for(root: Path) -> Path:
        return _absolute_path_without_symlink_resolution(Path(root))

    def slot_for(root_value: Path) -> Dict[str, Any]:
        key = str(root_value)
        with registry_lock:
            slot = root_slots.get(key)
            if slot is None:
                slot = {
                    "root": root_value,
                    "lock": threading.RLock(),
                    "entriesByAttempt": {},
                    "entriesByResource": {},
                    "poisoned": False,
                    "poisonReason": None,
                }
                root_slots[key] = slot
            return slot

    def fd_identity_from_stat(observed: os.stat_result) -> Dict[str, str]:
        return {
            "device": str(observed.st_dev),
            "inode": str(observed.st_ino),
            "mode": "%04o" % stat.S_IMODE(observed.st_mode),
            "fileType": str(stat.S_IFMT(observed.st_mode)),
        }

    def owner_is_current(owner: Mapping[str, Any]) -> bool:
        return (
            owner.get("pid") == os.getpid()
            and owner.get("thread") == threading.get_ident()
            and owner.get("threadObject") is threading.current_thread()
        )

    def slot_has_close_barrier(slot: Mapping[str, Any]) -> bool:
        """Derive the barrier from tombstones; never maintain a counter."""

        entries = slot.get("entriesByAttempt", {})
        if not isinstance(entries, Mapping):
            return True
        return any(
            isinstance(owner, Mapping)
            and owner.get("closeState")
            in ("closing", "close-uncertain")
            for owner in entries.values()
        )

    def remove_live_entry(owner: Dict[str, Any]) -> None:
        with registry_lock:
            permit = owner.get("permit")
            grant = owner.get("grant")
            live_entries.pop(id(owner), None)
            if permits.get(id(permit)) is owner:
                permits.pop(id(permit), None)
            if grants.get(id(grant)) is owner:
                grants.pop(id(grant), None)

    def retire_clean_entry(owner: Dict[str, Any]) -> None:
        """Drop only confirmed-clean live indexes; poison stays forever."""

        slot = owner["slot"]
        with slot["lock"]:
            if (
                owner.get("state") not in ("cancelled", "revoked")
                or owner.get("closeState") != "closed"
            ):
                raise AuditError(
                    "network Git execution grant retirement drift"
                )
            attempt_digest = owner.get("attemptDigest")
            resource_id = owner.get("resourceId")
            if slot["entriesByAttempt"].get(attempt_digest) is owner:
                slot["entriesByAttempt"].pop(attempt_digest, None)
            if slot["entriesByResource"].get(resource_id) is owner:
                slot["entriesByResource"].pop(resource_id, None)
        remove_live_entry(owner)

    def poison_entry(
        owner: Dict[str, Any],
        reason: str,
        *,
        detach_descriptor: bool,
    ) -> AuditError:
        slot = owner["slot"]
        with slot["lock"]:
            if detach_descriptor:
                owner["cwdFd"] = None
            owner["state"] = "poisoned"
            owner["closeState"] = "close-uncertain"
            owner["closeError"] = reason
            slot["poisoned"] = True
            if slot.get("poisonReason") is None:
                slot["poisonReason"] = reason
        return AuditError(
            "network Git execution grant anchor close is uncertain: "
            + reason
        )

    def close_anchor_once(owner: Dict[str, Any]) -> None:
        """Retire the exact anchor owner once; uncertainty permanently poisons."""
        slot = owner["slot"]
        with slot["lock"]:
            if owner.get("state") == "poisoned":
                raise AuditError("network Git execution grant root is poisoned")
            if owner.get("closeState") == "closed":
                owner["state"] = "revoked"
                return
            descriptor = owner.get("cwdFd")
            arena = owner.get("cwdArena")
            if descriptor is None and arena is None:
                owner["closeState"] = "closed"
                owner["state"] = "revoked"
                return
            if descriptor is not None and not isinstance(descriptor, _ChildFdOwnerSlot):
                raise AuditError("network Git anchor owner drift")
            if arena is not None and not isinstance(arena, _FdAcquisitionArena):
                raise AuditError("network Git traversal owner drift")
            if owner.get("closeState") != "open":
                raise poison_entry(owner, "close-reentry", detach_descriptor=False)
            owner["state"] = "revoking"
            owner["closeState"] = "closing"
        try:
            _close_fd_slots(reversed(arena.slots) if arena is not None else (descriptor,))
            if arena is not None and not arena.settled():
                raise AuditError("network Git anchor acquisition is unresolved")
        except BaseException as caught:
            # This call owns the exact slot close boundary. Preserve its
            # original OS failure, not the slot's diagnostic normalization.
            primary = (caught.__cause__
                       if isinstance(caught, AuditError)
                       and isinstance(caught.__cause__, OSError) else caught)
            if primary is not caught:
                _retain_git_cleanup_error(primary, caught)
            uncertainty = poison_entry(
                owner, "anchor-close-not-confirmed", detach_descriptor=False
            )
            _retain_git_cleanup_error(primary, uncertainty)
            raise primary
        with slot["lock"]:
            owner["cwdFd"] = None
            owner["closeState"] = "closed"
            owner["state"] = "revoked"

    def fail_and_close(owner: Dict[str, Any], *, claim: Any = None) -> None:
        slot = owner["slot"]
        with owner["spawnGate"]:
            with slot["lock"]:
                if claim is not None:
                    if owner.get("consumeClaim") is not claim:
                        return
                    allowed = ("issued", "validating-consume", "leased")
                else:
                    allowed = ("validating-issue", "publishing-grant", "issued")
                    if owner.get("consumeClaim") is not None:
                        return
                if owner.get("state") not in allowed:
                    if owner.get("state") == "poisoned":
                        raise AuditError("network Git execution grant root is poisoned")
                    return
                owner["cancelRequested"] = True
                owner["state"] = "revoking"
            close_and_retire(owner, claim=claim)

    def close_and_retire(owner: Dict[str, Any], *, claim: Any = None) -> None:
        with owner["spawnGate"]:
            slot = owner["slot"]
            with slot["lock"]:
                if claim is not None and owner.get("consumeClaim") is not claim:
                    return
                if owner.get("state") not in ("revoking", "revoked"):
                    raise AuditError("network Git execution grant close authority drift")
            primary: Optional[BaseException] = None
            try:
                close_anchor_once(owner)
            except BaseException as exc:
                primary = exc
            try:
                with slot["lock"]:
                    clean = owner.get("state") == "revoked" and owner.get("closeState") == "closed"
                if clean:
                    # Keep the arena canonical even if interruption splits the
                    # individual index removals. Publication cannot observe the
                    # partial retirement before its poison tombstone is restored.
                    with registry_lock:
                        try:
                            retire_clean_entry(owner)
                        except BaseException:
                            with slot["lock"]:
                                owner["state"] = "poisoned"
                                owner["closeError"] = "clean-anchor-retirement-was-interrupted"
                                slot["poisoned"] = True
                                if slot.get("poisonReason") is None:
                                    slot["poisonReason"] = owner["closeError"]
                                slot["entriesByAttempt"][owner["attemptDigest"]] = owner
                                slot["entriesByResource"][owner["resourceId"]] = owner
                                live_entries[id(owner)] = owner
                                if owner.get("grant") is not None:
                                    grants[id(owner["grant"])] = owner
                                else:
                                    permits[id(owner["permit"])] = owner
                            raise
            except BaseException as cleanup:
                if primary is None:
                    primary = cleanup
                else:
                    _retain_git_cleanup_error(primary, cleanup)
            if primary is not None:
                raise primary

    def publish_permit(
        root_value: Path,
        attempt_value: Dict[str, Any],
        reservation_value: Dict[str, Any],
    ) -> Any:
        _verify_self_digest(attempt_value)
        _verify_self_digest(reservation_value)
        attempt_digest = attempt_value.get("recordDigest")
        resource_id = attempt_value.get("capsuleResourceId")
        if (
            attempt_value.get("operationKind") != "network-attempt"
            or attempt_value.get("completionState") != "attempted"
            or attempt_value.get("wrapper") != "network-git"
            or not isinstance(attempt_digest, str)
            or not isinstance(resource_id, str)
            or attempt_value.get("reservationRecordDigest")
            != reservation_value.get("recordDigest")
        ):
            raise AuditError("network Git mint permit attempt drift")
        slot = slot_for(root_value)
        permit = GitChildExecutionMintPermit()
        owner = {
            "permit": permit,
            "grant": None,
            "state": "minted",
            "pid": os.getpid(),
            "thread": threading.get_ident(),
            "threadObject": threading.current_thread(),
            "root": root_value,
            "slot": slot,
            "attempt": attempt_value,
            "reservation": reservation_value,
            "consumption": None,
            "attemptDigest": attempt_digest,
            "resourceId": resource_id,
            "reservationDigest": reservation_value["recordDigest"],
            "binding": None,
            "broker": None,
            "cwdPath": None,
            "cwdFd": None,
            "cwdIdentity": None,
            "closeState": "closed",
            "closeError": None,
            "cancelRequested": False,
            "spawnGate": threading.RLock(),
        }
        try:
            with registry_lock:
                with slot["lock"]:
                    if (
                        slot.get("poisoned")
                        or slot_has_close_barrier(slot)
                    ):
                        raise AuditError(
                            "network Git execution grant root is poisoned"
                        )
                    if (
                        attempt_digest in slot["entriesByAttempt"]
                        or resource_id in slot["entriesByResource"]
                    ):
                        raise AuditError(
                            "network Git execution grant lineage is active"
                        )
                    slot["entriesByAttempt"][attempt_digest] = owner
                    slot["entriesByResource"][resource_id] = owner
                    permits[id(permit)] = owner
                    live_entries[id(owner)] = owner
        except BaseException:
            with registry_lock:
                permits.pop(id(permit), None)
                live_entries.pop(id(owner), None)
            with slot["lock"]:
                if slot["entriesByAttempt"].get(attempt_digest) is owner:
                    slot["entriesByAttempt"].pop(attempt_digest, None)
                if slot["entriesByResource"].get(resource_id) is owner:
                    slot["entriesByResource"].pop(resource_id, None)
                owner["state"] = "cancelled"
            raise
        return permit

    def append_attempt_and_mint(
        root: Path,
        manifest_record_digest: str,
        attempt_payload: Mapping[str, Any],
        *,
        reservation: Mapping[str, Any],
        state_validator: Any,
        permit_sink: List[Any],
        recovery_scope: Any,
        recovery_permit_sink: List[Any],
        _faults: Optional[DurabilityFaults],
    ) -> Dict[str, Any]:
        if type(permit_sink) is not list or permit_sink:
            raise AuditError("network Git mint permit sink drift")
        root_value = root_value_for(root)
        reservation_value = dict(
            _require_mapping(
                reservation, "network Git mint permit reservation"
            )
        )
        attempt = _append_record(
            root_value,
            "network-attempt",
            manifest_record_digest,
            [],
            "attempted",
            dict(
                _require_mapping(
                    attempt_payload, "network Git attempt payload"
                )
            ),
            state_validator=state_validator,
            _faults=_faults,
        )
        permit: Any = None
        try:
            _mint_network_attempt_recovery_permit(
                recovery_scope, recovery_permit_sink, root_value,
                attempt, reservation_value,
            )
            permit = publish_permit(
                root_value, dict(attempt), reservation_value
            )
            permit_sink.append(permit)
            return attempt
        except BaseException as primary:
            if permit is not None:
                try:
                    revoke_permit(permit)
                except BaseException as cleanup:
                    _retain_git_cleanup_error(primary, cleanup)
            permit_sink.clear()
            raise

    def revoke_permit(permit: Any) -> None:
        with registry_lock:
            owner = permits.get(id(permit))
            if owner is None:
                return
            if (
                type(permit) is not GitChildExecutionMintPermit
                or owner.get("permit") is not permit
            ):
                raise AuditError("network Git mint permit drift")
            slot = owner["slot"]
            with slot["lock"]:
                state = owner.get("state")
                if state == "minted":
                    owner["state"] = "cancelled"
                    state = "cancelled"
                if state == "cancelled":
                    attempt_digest = owner.get("attemptDigest")
                    resource_id = owner.get("resourceId")
                    if (
                        slot["entriesByAttempt"].get(attempt_digest)
                        is owner
                    ):
                        slot["entriesByAttempt"].pop(
                            attempt_digest, None
                        )
                    if (
                        slot["entriesByResource"].get(resource_id)
                        is owner
                    ):
                        slot["entriesByResource"].pop(resource_id, None)
                    live_entries.pop(id(owner), None)
                    permits.pop(id(permit), None)
                    return
                if state in ("validating-issue", "publishing-grant"):
                    owner["cancelRequested"] = True
                    return
                if state == "issued":
                    owner["cancelRequested"] = True
                    permits.pop(id(permit), None)
                    return

    def cancel_unstarted_owner(owner: Dict[str, Any]) -> None:
        slot = owner["slot"]
        with slot["lock"]:
            if owner.get("cwdFd") is not None:
                owner["cancelRequested"] = True
                return
            owner["state"] = "cancelled"
            owner["closeState"] = "closed"
        retire_clean_entry(owner)

    def begin_issue(
        mint_permit: Any,
        root_value: Path,
        attempt_value: Mapping[str, Any],
        resource_id: Any,
        owner_sink: List[Dict[str, Any]],
    ) -> Dict[str, Any]:
        if type(owner_sink) is not list or owner_sink:
            raise AuditError("network Git issue owner sink drift")
        owner: Optional[Dict[str, Any]] = None
        try:
            with registry_lock:
                owner = permits.get(id(mint_permit))
                if (
                    type(mint_permit) is not GitChildExecutionMintPermit
                    or owner is None
                    or owner.get("permit") is not mint_permit
                ):
                    raise AuditError("network Git mint permit is required")
                slot = owner["slot"]
                with slot["lock"]:
                    valid = (
                        owner.get("state") == "minted"
                        and not slot.get("poisoned")
                        and not slot_has_close_barrier(slot)
                        and owner_is_current(owner)
                        and owner.get("root") == root_value
                        and owner.get("attempt") == attempt_value
                        and owner.get("resourceId") == resource_id
                        and slot["entriesByAttempt"].get(
                            owner.get("attemptDigest")
                        ) is owner
                        and slot["entriesByResource"].get(resource_id)
                        is owner
                    )
                    if not valid:
                        raise AuditError(
                            "network Git mint permit scope drift"
                        )
                    # The cleanup handle is published before validation state;
                    # interruption during function return remains recoverable
                    # by the caller and by the original permit capability.
                    owner_sink.append(owner)
                    owner["state"] = "validating-issue"
                    owner["cancelRequested"] = False
                    return owner
        except BaseException as primary:
            if owner is not None:
                try:
                    cancel_unstarted_owner(owner)
                except BaseException as cleanup:
                    _retain_git_cleanup_error(primary, cleanup)
            raise

    def issue(
        root: Path,
        *,
        mint_permit: Any,
        attempt: Mapping[str, Any],
        consumption: Mapping[str, Any],
        operation: str,
        argv: Sequence[str],
        preflight: Mapping[str, Any],
        manifest: Mapping[str, Any],
        capsule: Mapping[str, Any],
        snapshot: Mapping[str, Any],
        broker: OneShotCredentialBroker,
    ) -> Any:
        try:
            root_value = root_value_for(root)
            attempt_value = dict(
                _require_mapping(attempt, "network Git attempt")
            )
            consumption_value = dict(
                _require_mapping(
                    consumption, "network Git capsule consumption"
                )
            )
            capsule_value = dict(
                _require_mapping(capsule, "network Git grant capsule")
            )
            resource_id = capsule_value.get("resourceId")
        except BaseException as primary:
            try:
                revoke_permit(mint_permit)
            except BaseException as cleanup:
                _retain_git_cleanup_error(primary, cleanup)
            raise
        owner: Optional[Dict[str, Any]] = None
        owner_sink: List[Dict[str, Any]] = []
        cwd_fd_sink: List[_ChildFdOwnerSlot] = []
        try:
            owner = begin_issue(
                mint_permit,
                root_value,
                attempt_value,
                resource_id,
                owner_sink,
            )
            slot = owner["slot"]
            working_directory = _absolute_path_without_symlink_resolution(
                Path(capsule_value.get("workingDirectory", ""))
            )
            attempt_digest = attempt_value.get("recordDigest")
            recovered = recover_run_state(root_value)
            projected_attempts = [
                value
                for value in recovered.get("networkAttempts", [])
                if value.get("attempt", {}).get("recordDigest")
                == attempt_digest
            ]
            resource = recovered.get("resources", {}).get(resource_id)
            if (
                recovered.get("classification") != "complete"
                or len(projected_attempts) != 1
                or projected_attempts[0].get("attempt") != attempt_value
                or projected_attempts[0].get("state")
                != "attempted-unknown"
                or projected_attempts[0].get("terminal") is not None
                or not isinstance(resource, Mapping)
                or resource.get("consumption") != consumption_value
                or resource.get("taint") is not None
            ):
                raise AuditError(
                    "network Git execution grant durable lineage drift"
                )
            # Publish the entire traversal before its first acquisition, not
            # only the final cwd descriptor returned by the callee.
            with slot["lock"]:
                owner["cwdArena"] = _FdAcquisitionArena()
                owner["closeState"] = "open"
            cwd_fd, reopened, observed = _open_directory_fd(
                working_directory, descriptor_sink=cwd_fd_sink,
                ownership_arena=owner["cwdArena"],
            )
            cwd_identity = fd_identity_from_stat(observed)
            with slot["lock"]:
                owner["cwdIdentity"] = cwd_identity
                owner["cwdPath"] = working_directory
                owner["closeState"] = "open"
                # Descriptor assignment is the adoption commit and therefore
                # happens after all metadata needed by fail-closed cleanup.
                owner["cwdFd"] = cwd_fd
            cwd_fd_sink.clear()
            visible = os.stat(working_directory, follow_symlinks=False)
            if (
                reopened != working_directory
                or not stat.S_ISDIR(observed.st_mode)
                or stat.S_IMODE(observed.st_mode) != 0o700
                or _directory_identity(visible)
                != _directory_identity(observed)
                or _fd_call(cwd_fd, os.get_inheritable)
                or _fd_call(
                    cwd_fd, _git_child_fd_identity, "network Git cwd anchor"
                )
                != cwd_identity
            ):
                raise AuditError(
                    "network Git execution grant cwd anchor drift"
                )
            binding = _git_child_execution_binding(
                root=root_value,
                attempt=attempt_value,
                consumption=consumption_value,
                operation=operation,
                argv=argv,
                preflight=preflight,
                manifest=manifest,
                capsule=capsule_value,
                snapshot=snapshot,
                broker=broker,
                cwd_identity=cwd_identity,
            )
            grant = GitChildExecutionGrant()
            with registry_lock:
                with slot["lock"]:
                    if (
                        owner.get("state") != "validating-issue"
                        or owner.get("cancelRequested")
                        or slot.get("poisoned")
                        or slot_has_close_barrier(slot)
                        or slot["entriesByAttempt"].get(
                            owner.get("attemptDigest")
                        ) is not owner
                        or slot["entriesByResource"].get(resource_id)
                        is not owner
                    ):
                        raise AuditError(
                            "network Git execution grant issue was cancelled"
                        )
                    owner.update(
                        {
                            "grant": grant,
                            "state": "publishing-grant",
                            "consumption": consumption_value,
                            "binding": binding,
                            "broker": broker,
                        }
                    )
                    grants[id(grant)] = owner
                    owner["state"] = "issued"
                    if owner.get("cancelRequested"):
                        raise AuditError(
                            "network Git execution grant issue was cancelled"
                        )
                    permits.pop(id(mint_permit), None)
            return grant
        except BaseException as primary:
            if owner is None and owner_sink:
                owner = owner_sink[0]
            if owner is None:
                raise
            # The prepublished arena owns the exact final slot even when the
            # return/adoption assignment was interrupted. No numeric lookup
            # or second owner is needed for the pending handoff.
            cwd_fd_sink.clear()
            try:
                fail_and_close(owner)
            except BaseException as cleanup_error:
                _retain_git_cleanup_error(primary, cleanup_error)
            raise primary

    def grant_owner(grant: Any) -> Dict[str, Any]:
        with registry_lock:
            owner = grants.get(id(grant))
        if (
            type(grant) is not GitChildExecutionGrant
            or owner is None
            or owner.get("grant") is not grant
        ):
            raise AuditError(
                "network Git child execution grant is required"
            )
        return owner

    def consume(
        grant: Any,
        root: Path,
        *,
        operation: str,
        argv: Sequence[str],
        preflight: Mapping[str, Any],
        manifest: Mapping[str, Any],
        capsule: Mapping[str, Any],
        snapshot: Mapping[str, Any],
        broker: OneShotCredentialBroker,
        _claim_sink: Optional[List[Any]] = None,
        _supervisor_sink: Optional[List[Any]] = None,
    ) -> Tuple[_ChildFdOwnerSlot, Path, Dict[str, str]]:
        owner = grant_owner(grant)
        slot = owner["slot"]
        root_value = root_value_for(root)
        # Immutable owner/scope losers must fail even while spawnGate is held
        # by a live child. They never acquire cancellation/cleanup authority.
        if (
            not owner_is_current(owner)
            or owner.get("root") != root_value
            or owner.get("broker") is not broker
        ):
            raise AuditError("network Git child execution grant owner/scope drift")
        if _claim_sink is not None and (type(_claim_sink) is not list or _claim_sink):
            raise AuditError("network Git consume claim sink drift")
        if _supervisor_sink is not None and (type(_supervisor_sink) is not list or _supervisor_sink):
            raise AuditError("network Git consume supervisor sink drift")
        claim = object()

        def enter_validation() -> None:
            with owner["spawnGate"], slot["lock"]:
                if (
                    owner.get("state") != "issued"
                    or owner.get("consumeClaim") is not None
                    or owner.get("cancelRequested")
                    or slot.get("poisoned")
                    or slot_has_close_barrier(slot)
                    or slot["entriesByAttempt"].get(owner["attemptDigest"]) is not owner
                    or slot["entriesByResource"].get(owner["resourceId"]) is not owner
                ):
                    raise AuditError(
                        "network Git child execution grant replay"
                    )
                # setdefault is the one-shot claim commit, including same-thread
                # signal/reentry between validation and publication. Local claim
                # cleanup covers interruption before the caller's sink is filled.
                if owner.setdefault("consumeClaim", claim) is not claim:
                    raise AuditError("network Git child execution grant replay")
                if _claim_sink is not None:
                    _claim_sink.append(claim)
                if owner.get("state") != "issued" or owner.get("cancelRequested"):
                    raise AuditError("network Git child execution grant consume was cancelled")
                owner["state"] = "validating-consume"

        try:
            enter_validation()
            descriptor = owner.get("cwdFd")
            if not isinstance(descriptor, _ChildFdOwnerSlot):
                raise AuditError(
                    "network Git child execution grant anchor drift"
                )
            visible_fd_identity = _fd_call(
                descriptor, _git_child_fd_identity, "network Git cwd anchor"
            )
            cwd_path = owner.get("cwdPath")
            if not isinstance(cwd_path, Path):
                raise AuditError(
                    "network Git child execution grant cwd drift"
                )
            try:
                visible = os.stat(cwd_path, follow_symlinks=False)
            except OSError as exc:
                raise AuditError(
                    "network Git child execution grant cwd disappeared"
                ) from exc
            if (
                visible_fd_identity != owner.get("cwdIdentity")
                or _directory_identity(visible)
                != (
                    int(visible_fd_identity["device"]),
                    int(visible_fd_identity["inode"]),
                    stat.S_IFDIR | int(visible_fd_identity["mode"], 8),
                )
            ):
                raise AuditError(
                    "network Git child execution grant cwd replacement"
                )
            recovered = recover_run_state(root_value)
            attempts = [
                value
                for value in recovered.get("networkAttempts", [])
                if value.get("attempt", {}).get("recordDigest")
                == owner["attempt"].get("recordDigest")
            ]
            capsule_value = dict(
                _require_mapping(capsule, "network Git grant capsule")
            )
            resource = recovered.get("resources", {}).get(
                capsule_value.get("resourceId")
            )
            if (
                recovered.get("classification") != "complete"
                or len(attempts) != 1
                or attempts[0].get("attempt") != owner["attempt"]
                or attempts[0].get("state") != "attempted-unknown"
                or attempts[0].get("terminal") is not None
                or not isinstance(resource, Mapping)
                or resource.get("consumption") != owner["consumption"]
                or resource.get("taint") is not None
            ):
                raise AuditError(
                    "network Git child execution grant durable lineage drift"
                )
            binding = _git_child_execution_binding(
                root=root_value,
                attempt=owner["attempt"],
                consumption=owner["consumption"],
                operation=operation,
                argv=argv,
                preflight=preflight,
                manifest=manifest,
                capsule=capsule_value,
                snapshot=snapshot,
                broker=broker,
                cwd_identity=visible_fd_identity,
            )
            with owner["spawnGate"], slot["lock"]:
                if (
                    owner.get("state") != "validating-consume"
                    or owner.get("consumeClaim") is not claim
                    or owner.get("cancelRequested")
                    or slot.get("poisoned")
                    or slot_has_close_barrier(slot)
                    or binding != owner.get("binding")
                ):
                    raise AuditError(
                        "network Git child execution grant consume was cancelled"
                    )
                if _supervisor_sink is not None:
                    supervisor = binding["supervisorInterpreter"]
                    _supervisor_sink.append((
                        supervisor["absolutePath"], supervisor["fileByteCount"], supervisor["fileSha256"],
                    ))
                owner["state"] = "leased"
            return descriptor, cwd_path, dict(visible_fd_identity)
        except BaseException as primary:
            try:
                fail_and_close(owner, claim=claim)
            except BaseException as cleanup_error:
                _retain_git_cleanup_error(primary, cleanup_error)
            raise primary

    def run_child(grant: Any, runner: Any) -> Any:
        """Own admission through proved child quiescence in one scope."""

        if not callable(runner):
            raise AuditError("network Git child runner drift")
        owner = grant_owner(grant)
        if not owner_is_current(owner):
            raise AuditError("network Git child execution lease owner drift")
        slot = owner["slot"]
        spawn_gate = owner["spawnGate"]
        quiescent = False
        may_have_child = False
        run_claim = object()

        def mark_quiescent() -> None:
            nonlocal quiescent
            quiescent = True

        with spawn_gate:
            try:
                with slot["lock"]:
                    if (
                        owner.get("state") != "leased"
                        or owner.get("consumeClaim") is None
                        or owner.get("runClaim") is not None
                        or owner.get("cancelRequested")
                        or slot.get("poisoned")
                        or slot_has_close_barrier(slot)
                    ):
                        raise AuditError("network Git child execution lease cancelled")
                    if owner.setdefault("runClaim", run_claim) is not run_claim:
                        raise AuditError("network Git child execution lease cancelled")
                    if owner.get("state") != "leased" or owner.get("cancelRequested"):
                        raise AuditError("network Git child execution lease cancelled")
                    owner["state"] = "validating-run"
                descriptor = owner.get("cwdFd")
                if (
                    not isinstance(descriptor, _ChildFdOwnerSlot)
                    or _fd_call(
                        descriptor, _git_child_fd_identity, "network Git leased cwd anchor"
                    ) != owner.get("cwdIdentity")
                ):
                    raise AuditError("network Git leased anchor drift")
                reservation = owner.get("reservation")
                if not isinstance(reservation, Mapping):
                    raise AuditError(
                        "network Git child reservation drift"
                    )
                guard = _network_execution_guard(
                    owner["root"], reservation
                )
                lease_fd = guard.child_lifetime_lease_fd(
                    reservation, owner["attempt"]
                )
                with slot["lock"]:
                    if (
                        not owner_is_current(owner)
                        or owner.get("state") != "validating-run"
                        or owner.get("runClaim") is not run_claim
                        or owner.get("cancelRequested")
                        or slot.get("poisoned")
                        or slot_has_close_barrier(slot)
                    ):
                        raise AuditError(
                            "network Git child execution lease cancelled"
                        )
                    # Conservative before the external boundary: from here
                    # until a trusted runner proves quiescence, a child may
                    # exist even if Python control flow is interrupted.
                    may_have_child = True
                    owner["state"] = "child-maybe"
                result = runner(mark_quiescent, lease_fd)
                if not quiescent:
                    raise AuditError(
                        "network Git child quiescence was not proved"
                    )
                with slot["lock"]:
                    owner["state"] = "child-quiescent"
                    cancelled = bool(owner.get("cancelRequested"))
                if cancelled:
                    raise AuditError(
                        "network Git child execution was cancelled"
                    )
                return result
            except BaseException as primary:
                with slot["lock"]:
                    if owner.get("runClaim") is not run_claim:
                        raise
                    if not may_have_child:
                        # Winning a token does not revive a source state that
                        # reentrant revoke retired/poisoned before registration.
                        if owner.get("state") not in ("leased", "validating-run"):
                            raise
                        quiescent = True
                        owner["state"] = "child-quiescent"
                    elif quiescent:
                        owner["state"] = "child-quiescent"
                    else:
                        owner["state"] = "poisoned"
                        owner["closeError"] = (
                            "child-lifecycle-was-not-proved-quiescent"
                        )
                        slot["poisoned"] = True
                        if slot.get("poisonReason") is None:
                            slot["poisonReason"] = owner["closeError"]
                if not quiescent:
                    _retain_git_cleanup_error(primary, AuditError(
                        "network Git child lifecycle is uncertain; "
                        "root poisoned"
                    ))
                raise

    def finish_child_use(grant: Any, *, _expected_claim: Any = None) -> None:
        with registry_lock:
            owner = grants.get(id(grant))
        if owner is None:
            return
        if (
            type(grant) is not GitChildExecutionGrant
            or owner.get("grant") is not grant
        ):
            raise AuditError("network Git child execution grant drift")
        slot = owner["slot"]
        spawn_gate = owner["spawnGate"]
        with spawn_gate:
            with slot["lock"]:
                if _expected_claim is not None and owner.get("consumeClaim") is not _expected_claim:
                    return
                if not owner_is_current(owner):
                    owner["cancelRequested"] = True
                    return
                if owner.get("state") == "poisoned":
                    raise AuditError(
                        "network Git execution grant root is poisoned"
                    )
                if owner.get("state") not in (
                    "leased", "child-quiescent"
                ):
                    return
                if owner.get("state") == "leased" and owner.get("runClaim") is not None:
                    return
                owner["state"] = "revoking"
            close_and_retire(owner, claim=_expected_claim)

    def revoke(grant: Any, *, _expected_claim: Any = None) -> None:
        with registry_lock:
            owner = grants.get(id(grant))
        if owner is None:
            return
        if (
            type(grant) is not GitChildExecutionGrant
            or owner.get("grant") is not grant
        ):
            raise AuditError("network Git child execution grant drift")
        slot = owner["slot"]
        spawn_gate = owner["spawnGate"]
        with spawn_gate:
            with slot["lock"]:
                if _expected_claim is not None and owner.get("consumeClaim") is not _expected_claim:
                    return
                state = owner.get("state")
                if state == "poisoned":
                    raise AuditError(
                        "network Git execution grant root is poisoned: "
                        + str(owner.get("closeError"))
                    )
                if state in (
                    "validating-consume",
                    "validating-run",
                    "child-maybe",
                ) or (state == "issued" and owner.get("consumeClaim") is not None) or (
                    state == "leased" and owner.get("runClaim") is not None
                ):
                    owner["cancelRequested"] = True
                    return
                if state in ("leased", "child-quiescent"):
                    if not owner_is_current(owner):
                        owner["cancelRequested"] = True
                        return
                    owner["state"] = "revoking"
                elif state == "revoking" or (
                    state == "revoked"
                    and owner.get("closeState") == "closed"
                ):
                    pass
                elif state != "issued":
                    return
                else:
                    owner["state"] = "revoking"
            close_and_retire(owner, claim=_expected_claim)

    def current_thread_grants() -> Tuple[Any, ...]:
        current = threading.current_thread()
        pid = os.getpid()
        with registry_lock:
            return tuple(
                owner["grant"]
                for owner in grants.values()
                if owner.get("pid") == pid
                and owner.get("threadObject") is current
            )

    def revoke_grants_since(initial: Sequence[Any]) -> None:
        initial_ids = {id(grant) for grant in initial}
        first_error: Optional[BaseException] = None
        for grant in current_thread_grants():
            if id(grant) in initial_ids:
                continue
            try:
                revoke(grant)
            except BaseException as exc:
                if first_error is None:
                    first_error = exc
                else:
                    _retain_git_cleanup_error(first_error, exc)
        if first_error is not None:
            raise first_error

    def current_thread_permits() -> Tuple[Any, ...]:
        current = threading.current_thread()
        pid = os.getpid()
        with registry_lock:
            return tuple(
                owner["permit"]
                for owner in permits.values()
                if owner.get("pid") == pid
                and owner.get("threadObject") is current
            )

    def revoke_permits_since(initial: Sequence[Any]) -> None:
        initial_ids = {id(permit) for permit in initial}
        primary: Optional[BaseException] = None
        for permit in current_thread_permits():
            if id(permit) not in initial_ids:
                try:
                    revoke_permit(permit)
                except BaseException as exc:
                    if primary is None:
                        primary = exc
                    else:
                        _retain_git_cleanup_error(primary, exc)
        if primary is not None:
            raise primary

    def assert_attempt_quiescent(
        root: Path, attempt_record_digest: str
    ) -> None:
        """Prove that this attempt retains no child-start authority."""

        root_value = root_value_for(root)
        _require_lower_hex(
            attempt_record_digest,
            64,
            "network Git quiescent attempt record",
        )
        key = str(root_value)
        with registry_lock:
            if any(
                owner.get("root") == root_value
                and owner.get("attemptDigest")
                == attempt_record_digest
                for owner in live_entries.values()
            ):
                raise AuditError(
                    "network Git child authority is not quiescent"
                )
            slot = root_slots.get(key)
            if slot is None:
                return
            with slot["lock"]:
                if (
                    slot.get("poisoned")
                    or slot_has_close_barrier(slot)
                    or slot["entriesByAttempt"].get(
                        attempt_record_digest
                    ) is not None
                ):
                    raise AuditError(
                        "network Git child authority is not quiescent"
                    )

    def before_fork() -> bool:
        nonlocal fork_must_exit, fork_acquisition
        fork_must_exit = True
        if fork_acquisition is not None:
            raise AuditError("Git grant fork lock settlement is pending")
        fork_acquisition = _ForkLockAcquisition(registry_lock)
        fork_acquisition.acquire()
        fork_must_exit = bool(
            live_entries
            or any(
                slot.get("poisoned")
                or slot_has_close_barrier(slot)
                or bool(slot.get("entriesByAttempt"))
                or bool(slot.get("entriesByResource"))
                for slot in root_slots.values()
            )
        )
        return fork_must_exit

    def after_fork_parent() -> None:
        nonlocal fork_must_exit, fork_acquisition
        fork_must_exit = True
        if fork_acquisition is not None:
            try:
                fork_acquisition.settle()
            finally:
                if fork_acquisition.settled:
                    fork_acquisition = None

    def after_fork_child() -> None:
        nonlocal registry_lock, root_slots, permits, grants
        nonlocal live_entries, fork_must_exit, fork_acquisition
        if fork_must_exit:
            os._exit(70)
        root_slots = {}
        permits = {}
        grants = {}
        live_entries = {}
        fork_must_exit = True
        fork_acquisition = None
        registry_lock = threading.RLock()

    return (
        append_attempt_and_mint,
        issue,
        consume,
        run_child,
        finish_child_use,
        revoke,
        current_thread_grants,
        revoke_grants_since,
        revoke_permit,
        current_thread_permits,
        revoke_permits_since,
        assert_attempt_quiescent,
        before_fork,
        after_fork_parent,
        after_fork_child,
    )


(
    _append_network_git_attempt_and_mint,
    _issue_git_child_execution_grant,
    _consume_git_child_execution_grant,
    _run_git_child_execution,
    _finish_git_child_execution_use,
    _revoke_git_child_execution_grant,
    _current_thread_git_child_execution_grants,
    _revoke_git_child_execution_grants_since,
    _revoke_git_child_execution_mint_permit,
    _current_thread_git_child_execution_mint_permits,
    _revoke_git_child_execution_mint_permits_since,
    _assert_git_child_execution_attempt_quiescent,
    _git_child_execution_grant_before_fork,
    _git_child_execution_grant_after_fork_parent,
    _git_child_execution_grant_after_fork_child,
) = _make_git_child_execution_grant_authority()


def _make_network_attempt_recovery_permit_authority() -> Tuple[Any, ...]:
    """Create one-shot, process-local authority for live-owner recovery."""

    class NetworkAttemptRecoveryPermit:
        __slots__ = ()

    class NetworkAttemptRecoveryScope:
        __slots__ = ()

    authority_lock = threading.RLock()
    owners: Dict[int, Dict[str, Any]] = {}
    owners_by_guard: Dict[int, Dict[str, Any]] = {}
    fork_must_exit = True
    fork_acquisition: Any = None

    def mint(
        scope: Any,
        permit_sink: List[Any],
        root: Path,
        attempt: Mapping[str, Any],
        reservation: Mapping[str, Any],
    ) -> Any:
        if (
            type(scope) is not NetworkAttemptRecoveryScope
            or type(permit_sink) is not list
            or permit_sink
        ):
            raise AuditError("network recovery scope/sink drift")
        root_value = _absolute_path_without_symlink_resolution(Path(root))
        attempt_value = dict(
            _require_mapping(attempt, "network recovery attempt")
        )
        reservation_value = dict(
            _require_mapping(
                reservation, "network recovery reservation"
            )
        )
        _verify_self_digest(attempt_value)
        _verify_self_digest(reservation_value)
        logical_key = _require_lower_hex(
            attempt_value.get("logicalKey"),
            64,
            "network recovery logical key",
        )
        attempt_digest = _require_lower_hex(
            attempt_value.get("recordDigest"),
            64,
            "network recovery attempt record",
        )
        if (
            attempt_value.get("operationKind") != "network-attempt"
            or attempt_value.get("completionState") != "attempted"
            or attempt_value.get("reservationRecordDigest")
            != reservation_value.get("recordDigest")
            or attempt_value.get("useKey") != logical_key
            or reservation_value.get("useKey") != logical_key
        ):
            raise AuditError("network recovery permit lineage drift")
        guard = _network_execution_guard(root_value, reservation_value)
        permit = NetworkAttemptRecoveryPermit()
        owner = {
            "permit": permit,
            "scope": scope,
            "pid": os.getpid(),
            "thread": threading.get_ident(),
            "threadObject": threading.current_thread(),
            "root": root_value,
            "attempt": attempt_value,
            "attemptDigest": attempt_digest,
            "logicalKey": logical_key,
            "reservation": reservation_value,
            "guard": guard,
            "state": "arming",
            "cancelRequested": False,
        }
        with authority_lock:
            if id(guard) in owners_by_guard or any(
                current.get("guard") is guard for current in owners.values()
            ):
                raise AuditError("network recovery arm is already live")
            # Primary publication is the cleanup commit, not caller delivery.
            # Scope rediscovery must retain this entry on every interruption.
            owners[id(permit)] = owner
            owners_by_guard[id(guard)] = owner
            permit_sink.append(permit)
        # Reservation lifecycle precedes recovery/Git authority in lock order.
        guard.mark_attempt_live(reservation_value, attempt_value)
        with authority_lock:
            if owner.get("cancelRequested"):
                raise AuditError("network recovery arming was cancelled")
            owner["state"] = "dormant"
        return permit

    def owner_for(permit: Any) -> Dict[str, Any]:
        with authority_lock:
            owner = owners.get(id(permit))
        if (
            type(permit) is not NetworkAttemptRecoveryPermit
            or owner is None
            or owner.get("permit") is not permit
        ):
            raise AuditError("network recovery permit is required")
        return owner

    def begin(
        permit: Any,
        scope: Any,
        root: Path,
        logical_key: str,
        attempt: Mapping[str, Any],
        reservation: Mapping[str, Any],
    ) -> "_NetworkExecutionReservationGuard":
        root_value = _absolute_path_without_symlink_resolution(Path(root))
        logical_key = _require_lower_hex(
            logical_key, 64, "network recovery logical key"
        )
        attempt_value = dict(
            _require_mapping(attempt, "network recovery attempt")
        )
        reservation_value = dict(
            _require_mapping(
                reservation, "network recovery reservation"
            )
        )
        owner = owner_for(permit)
        claim = object()
        try:
            with authority_lock:
                if (
                    type(scope) is not NetworkAttemptRecoveryScope
                    or owner.get("scope") is not scope
                    or owner.get("state") != "dormant"
                    or owner.get("beginClaim") is not None
                    or owner.get("cancelRequested")
                    or owner.get("pid") != os.getpid()
                    or owner.get("thread") != threading.get_ident()
                    or owner.get("threadObject")
                    is not threading.current_thread()
                    or owner.get("root") != root_value
                    or owner.get("logicalKey") != logical_key
                    or owner.get("attempt") != attempt_value
                    or owner.get("reservation") != reservation_value
                ):
                    raise AuditError(
                        "network recovery permit scope drift"
                    )
                # Register the cleanup claim before lifecycle publication.
                # Even an interrupted assignment/return is recognized by the
                # local claim, rather than a post-publication Boolean.
                if owner.setdefault("beginClaim", claim) is not claim:
                    raise AuditError("network recovery validation is already claimed")
                owner["state"] = "validating"
            if attempt_value.get("wrapper") == "network-git":
                _assert_git_child_execution_attempt_quiescent(
                    root_value, owner["attemptDigest"]
                )
            guard = owner.get("guard")
            if not isinstance(guard, _NetworkExecutionReservationGuard):
                raise AuditError("network recovery guard drift")
            guard.require_reservation(reservation_value)
            guard.begin_settlement(reservation_value)
            with authority_lock:
                if (
                    owners.get(id(permit)) is not owner
                    or owner.get("state") != "validating"
                    or owner.get("cancelRequested")
                ):
                    raise AuditError(
                        "network recovery permit was cancelled"
                    )
                owner["state"] = "settling"
            return guard
        except BaseException:
            with authority_lock:
                if owner.get("beginClaim") is claim and owners.get(id(permit)) is owner:
                    owner["state"] = "failed"
            raise

    def revoke(permit: Any, *, _scope_cleanup: bool = False) -> None:
        with authority_lock:
            owner = owners.get(id(permit))
            if owner is None:
                return
            if (
                type(permit) is not NetworkAttemptRecoveryPermit
                or owner.get("permit") is not permit
            ):
                raise AuditError("network recovery permit drift")
            if not _scope_cleanup and owner.get("state") in ("arming", "validating"):
                owner["cancelRequested"] = True
                return
        guard = owner["guard"]
        if _scope_cleanup:
            # Never hold recovery/Git locks across reservation lifecycle. A
            # still-live child fails the trusted check and leaves this owner
            # discoverable, rather than granting false cold-recovery safety.
            if owner["attempt"].get("wrapper") == "network-git":
                _assert_git_child_execution_attempt_quiescent(
                    owner["root"], owner["attemptDigest"]
                )
            with guard._lifecycle_lock:
                if guard._phase == "attempt-live":
                    guard.begin_settlement(owner["reservation"])
        else:
            with guard._lifecycle_lock:
                if guard._phase == "attempt-live":
                    # Failed validation has not established child quiescence.
                    # Retain this recovery capability for scope reconciliation
                    # rather than orphaning a still-live reservation owner.
                    with authority_lock:
                        owner["cancelRequested"] = True
                    return
        with authority_lock:
            if owners.get(id(permit)) is not owner:
                return
            owner["state"] = "retired"
            guard = owner.get("guard")
            if owners_by_guard.get(id(guard)) is owner:
                owners_by_guard.pop(id(guard), None)
            # The registry entry is the capability and is removed last so a
            # partially interrupted retirement remains discoverable/retriable.
            owners.pop(id(permit), None)

    def scope_decorator(function: Any) -> Any:
        def scoped(*args: Any, **kwargs: Any) -> Any:
            hidden = {
                "_network_recovery_scope",
                "_network_recovery_permit_sink",
            }
            if hidden.intersection(kwargs):
                raise AuditError("network recovery scope injection")
            scope = NetworkAttemptRecoveryScope()
            permit_sink: List[Any] = []
            kwargs["_network_recovery_scope"] = scope
            kwargs["_network_recovery_permit_sink"] = permit_sink
            initial_permits = _current_thread_git_child_execution_mint_permits()
            initial_grants = _current_thread_git_child_execution_grants()
            primary: Optional[BaseException] = None
            try:
                return function(*args, **kwargs)
            except BaseException as exc:
                primary = exc
                raise
            finally:
                cleanup_primary = primary
                for cleanup in (
                    lambda: _revoke_git_child_execution_mint_permits_since(initial_permits),
                    lambda: _revoke_git_child_execution_grants_since(initial_grants),
                ):
                    try:
                        cleanup()
                    except BaseException as exc:
                        if cleanup_primary is None:
                            cleanup_primary = exc
                        else:
                            _retain_git_cleanup_error(cleanup_primary, exc)
                with authority_lock:
                    pending = tuple(
                        owner["permit"] for owner in owners.values()
                        if owner.get("scope") is scope
                        and owner.get("pid") == os.getpid()
                        and owner.get("threadObject") is threading.current_thread()
                    )
                # Sink delivery and secondary retirement can both be
                # interrupted; the primary owner registry is authoritative.
                for permit in pending:
                    try:
                        revoke(permit, _scope_cleanup=True)
                    except BaseException as exc:
                        if cleanup_primary is None:
                            cleanup_primary = exc
                        else:
                            _retain_git_cleanup_error(cleanup_primary, exc)
                if primary is None and cleanup_primary is not None:
                    raise cleanup_primary

        scoped.__name__ = function.__name__
        scoped.__qualname__ = function.__qualname__
        scoped.__doc__ = function.__doc__
        scoped.__wrapped__ = function
        return scoped

    def before_fork() -> bool:
        nonlocal fork_must_exit, fork_acquisition
        fork_must_exit = True
        if fork_acquisition is not None:
            raise AuditError("recovery fork lock settlement is pending")
        fork_acquisition = _ForkLockAcquisition(authority_lock)
        fork_acquisition.acquire()
        fork_must_exit = bool(owners)
        return fork_must_exit

    def after_fork_parent() -> None:
        nonlocal fork_must_exit, fork_acquisition
        fork_must_exit = True
        if fork_acquisition is not None:
            try:
                fork_acquisition.settle()
            finally:
                if fork_acquisition.settled:
                    fork_acquisition = None

    def after_fork_child() -> None:
        nonlocal authority_lock, owners, owners_by_guard, fork_must_exit
        nonlocal fork_acquisition
        if fork_must_exit:
            os._exit(70)
        owners = {}
        owners_by_guard = {}
        fork_must_exit = True
        fork_acquisition = None
        authority_lock = threading.RLock()

    return (
        scope_decorator,
        mint,
        begin,
        revoke,
        before_fork,
        after_fork_parent,
        after_fork_child,
    )


(
    _network_attempt_recovery_scope,
    _mint_network_attempt_recovery_permit,
    _begin_network_attempt_recovery,
    _revoke_network_attempt_recovery_permit,
    _network_attempt_recovery_permit_before_fork,
    _network_attempt_recovery_permit_after_fork_parent,
    _network_attempt_recovery_permit_after_fork_child,
) = _make_network_attempt_recovery_permit_authority()


def _git_child_mint_permit_scope(function: Any) -> Any:
    """Revoke every permit minted by one wrapper call on every unwind."""

    def scoped(*args: Any, **kwargs: Any) -> Any:
        initial = _current_thread_git_child_execution_mint_permits()
        initial_network_guards = (
            _current_thread_network_execution_guards()
        )
        primary: Optional[BaseException] = None
        try:
            return function(*args, **kwargs)
        except BaseException as exc:
            primary = exc
            raise
        finally:
            cleanup_primary = primary
            for cleanup in (
                lambda: _revoke_git_child_execution_mint_permits_since(initial),
                lambda: _close_network_execution_guards_since(initial_network_guards),
            ):
                try:
                    cleanup()
                except BaseException as exc:
                    if cleanup_primary is None:
                        cleanup_primary = exc
                    else:
                        _retain_git_cleanup_error(cleanup_primary, exc)
            if primary is None and cleanup_primary is not None:
                raise cleanup_primary

    scoped.__name__ = function.__name__
    scoped.__qualname__ = function.__qualname__
    scoped.__doc__ = function.__doc__
    scoped.__wrapped__ = function
    return scoped


_NETWORK_CHILD_ENVIRONMENT = MappingProxyType({
    "HOME": "/nonexistent",
    "LANG": "C",
    "LC_ALL": "C",
    "PATH": "/usr/bin:/bin",
    "GIT_ALLOW_PROTOCOL": "https",
    "GIT_ATTR_NOSYSTEM": "1",
    "GIT_CONFIG_GLOBAL": "/dev/null",
    "GIT_CONFIG_NOSYSTEM": "1",
    "GIT_CONFIG_SYSTEM": "/dev/null",
    "GIT_NO_REPLACE_OBJECTS": "1",
    "GIT_NO_LAZY_FETCH": "1",
    "GIT_OPTIONAL_LOCKS": "0",
    "GIT_PROTOCOL_FROM_USER": "0",
    "GIT_TERMINAL_PROMPT": "0",
    "GIT_LFS_SKIP_SMUDGE": "1",
})

_NETWORK_GIT_SUPERVISOR_VERSION = "qinao.git-child-supervisor.v1"
_NETWORK_GIT_SUPERVISOR_EXECUTABLE = "/bin/sh"
_NETWORK_GIT_SUPERVISOR_POLICY = (
    ": <&__LEASE_FD__ || exit 125\n"
    "( exec \"$@\" ) 0<&0 __ACK_FD__>&- __PARENT_DEATH_FD__>&- &\n"
    "qinao_git_pid=$!\n"
    "( IFS= read -r _ <&__PARENT_DEATH_FD__; kill -KILL 0 ) "
    "__ACK_FD__>&- &\n"
    "qinao_parent_watchdog_pid=$!\n"
    "trap '' PIPE\n"
    "if ! printf Q >&__ACK_FD__; then kill -KILL 0; exit 125; fi\n"
    "trap - PIPE\n"
    "wait \"$qinao_git_pid\"\n"
    "qinao_status=$?\n"
    "kill -KILL \"$qinao_parent_watchdog_pid\" 2>/dev/null || :\n"
    "wait \"$qinao_parent_watchdog_pid\" 2>/dev/null || :\n"
    "exit \"$qinao_status\""
)


def _network_git_supervisor_command(
    command: Sequence[str], lease_fd: int, ack_fd: int,
    parent_death_fd: int,
    *, supervisor_executable: Optional[str] = None,
) -> List[str]:
    executable = (_NETWORK_GIT_SUPERVISOR_EXECUTABLE
                  if supervisor_executable is None else supervisor_executable)
    if not isinstance(executable, str) or not executable.startswith("/") or "\x00" in executable:
        raise AuditError("network Git supervisor executable drift")
    if (
        not isinstance(lease_fd, int)
        or not isinstance(ack_fd, int)
        or lease_fd < 3
        or ack_fd < 3
        or not isinstance(parent_death_fd, int)
        or parent_death_fd < 3
        or len({lease_fd, ack_fd, parent_death_fd}) != 3
    ):
        raise AuditError("network Git supervisor descriptor drift")
    normalized = _validate_argv(command)
    template = _NETWORK_GIT_SUPERVISOR_POLICY.replace(
        "__LEASE_FD__", str(lease_fd)
    ).replace("__ACK_FD__", str(ack_fd)).replace(
        "__PARENT_DEATH_FD__", str(parent_death_fd)
    )
    if any(
        marker in template
        for marker in (
            "__LEASE_FD__", "__ACK_FD__", "__PARENT_DEATH_FD__"
        )
    ):
        raise AuditError("network Git supervisor rendering drift")
    required_fragments = (
        ": <&" + str(lease_fd) + " || exit 125",
        '( exec "$@" ) 0<&0 ',
        str(ack_fd) + ">&- " + str(parent_death_fd) + ">&- &",
        "read -r _ <&" + str(parent_death_fd),
        "printf Q >&" + str(ack_fd),
    )
    if any(fragment not in template for fragment in required_fragments):
        raise AuditError("network Git supervisor redirection drift")
    return [
        executable,
        "-c",
        template,
        "qinao-git-supervisor",
        *normalized,
    ]


def _network_run_root_from_member(member_path: str) -> Path:
    path = Path(_canonical_absolute_path(member_path, "network member"))
    candidates = []
    for parent in path.parents:
        identity_path = parent / "ledger" / "identity.json"
        if identity_path.is_file() and not identity_path.is_symlink():
            relative = path.relative_to(parent)
            if relative.parts[:2] == ("ledger", "captures"):
                candidates.append(parent)
    if len(candidates) != 1:
        raise AuditError("network member run root is absent or ambiguous")
    return candidates[0]


def _reopen_sealed_network_member(
    member_path: str, schema_version: str
) -> Tuple[Path, Dict[str, Any], str, Dict[str, Any]]:
    root = _network_run_root_from_member(member_path)
    recovered = recover_run_state(root)
    if recovered.get("classification") != "complete":
        raise AuditError("network member ledger is indeterminate")
    capture, value = _reopen_sealed_capture_member(
        recovered, member_path
    )
    if value.get("schemaVersion") != schema_version:
        raise AuditError("sealed network member schema drift")
    seal = capture.get("seal")
    if not isinstance(seal, Mapping):
        raise AuditError("sealed network member terminal is absent")
    seal_path = _ledger_record_path(root, seal)
    reopened = reopen_sealed_named_record(
        root, seal_path, Path(member_path).name
    )
    if reopened != value:
        raise AuditError("sealed network member reopened bytes drift")
    return root, value, seal_path, capture


def _network_logical_key(
    wrapper: str,
    frontier_id: str,
    operation: str,
    argv: Sequence[str],
    preflight: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> str:
    del frontier_id
    validated = _validate_network_request_manifest_v2(
        manifest, preflight
    )
    normalized = _validate_argv(argv)
    matches = [
        row for row in validated["rows"]
        if row["operation"] == operation and row["argv"] == normalized
    ]
    if len(matches) != 1 or matches[0]["wrapper"] != wrapper:
        raise AuditError("network logical request selection drift")
    return _network_request_use_key(
        validated["recordDigest"], matches[0]["requestId"], 1
    )


def _network_cold_preflight_mode(preflight: Mapping[str, Any]) -> str:
    """Classify one exact old shape, never fall back from a validation error."""
    value = _require_mapping(preflight, "network cold preflight")
    projection = _require_mapping(value.get("localProjection"), "network cold projection")
    rows = projection.get("tools")
    names = ([row.get("name") if isinstance(row, Mapping) else None for row in rows]
             if isinstance(rows, list) else [])
    mode = ("historical-seven" if names == sorted(_NETWORK_HISTORICAL_TOOL_NAMES) else "current")
    _validate_network_egress_record(value, _tool_mode=mode)
    return mode


def _select_network_cold_use_key(
    root: Path, frontier_id: str, wrapper: str, operation: str,
    argv: Sequence[str], preflight: Mapping[str, Any], manifest: Mapping[str, Any],
    *, request_body_record: Optional[Mapping[str, Any]] = None,
) -> str:
    """Yield only an exact request key; historical proof cannot start a use."""
    mode = _network_cold_preflight_mode(preflight)
    selected = _select_network_request_row(
        manifest, operation, argv, preflight,
        request_body_record=request_body_record, _tool_mode=mode,
    )
    if selected["wrapper"] != wrapper:
        raise AuditError("network cold request wrapper drift")
    key = _network_request_use_key(manifest["recordDigest"], selected["requestId"], 1)
    if mode == "historical-seven":
        recovered = recover_run_state(root)
        matches = [entry for entry in recovered.get("networkAttempts", [])
                   if entry.get("logicalKey") == key]
        expected = {
            "frontierId": frontier_id, "wrapper": wrapper, "operation": operation,
            "logicalKey": key, "useKey": key,
            "argvDigest": _sha256(canonical_json_bytes(_validate_argv(argv))),
            "preflightRecordDigest": preflight["recordDigest"],
            "stableProjectionDigest": preflight["stableProjectionDigest"],
            "manifestRecordDigest": manifest["recordDigest"],
            "requestId": selected["requestId"], "rowDigest": selected["rowDigest"],
        }
        if (recovered.get("classification") != "complete" or len(matches) != 1
                or not isinstance(matches[0].get("attempt"), Mapping)
                or any(matches[0]["attempt"].get(field) != value for field, value in expected.items())):
            # No old recorded use is a current authority route.
            validate_network_egress_record(preflight)
            raise AuditError("historical network request has no exact recorded attempt")
    return key


def _network_execution_reservation_binding(
    wrapper: str,
    frontier_id: str,
    operation: str,
    argv: Sequence[str],
    preflight: Mapping[str, Any],
    manifest: Mapping[str, Any],
    *,
    request_body_record: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    normalized = _validate_argv(argv)
    selected = select_network_request_row(
        manifest,
        operation,
        normalized,
        preflight,
        request_body_record=request_body_record,
    )
    if selected.get("wrapper") != wrapper:
        raise AuditError("network execution reservation wrapper drift")
    use_key = _network_request_use_key(
        manifest["recordDigest"], selected["requestId"], 1
    )
    return {
        "useKey": use_key,
        "frontierId": frontier_id,
        "wrapper": wrapper,
        "operation": operation,
        "argvDigest": _sha256(canonical_json_bytes(normalized)),
        "preflightRecordDigest": preflight["recordDigest"],
        "stableProjectionDigest": preflight["stableProjectionDigest"],
        "manifestRecordDigest": manifest["recordDigest"],
        "manifestSchemaVersion": manifest["schemaVersion"],
        "requestId": selected["requestId"],
        "requestSequence": selected["sequence"],
        "rowDigest": selected["rowDigest"],
        "maximumUses": selected["maximumUses"],
    }


_NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK = threading.RLock()
_NETWORK_EXECUTION_RESERVATION_GUARDS: Dict[
    str, "_NetworkExecutionReservationGuard"
] = {}
_NETWORK_EXECUTION_RESERVATION_PHYSICAL_GUARDS: Dict[
    Tuple[int, int, int], "_NetworkExecutionReservationGuard"
] = {}
_NETWORK_EXECUTION_RESERVATION_ACQUISITIONS_INFLIGHT = 0
_NETWORK_EXECUTION_RESERVATION_ACQUISITION_POISONED = False
_NETWORK_EXECUTION_RESERVATION_FORK_MUST_EXIT = True
_NETWORK_EXECUTION_RESERVATION_FORK_ACQUISITION: Any = None


class _NetworkExecutionReservationGuard:
    """Per-root retained-inode owner for one pre-network reservation."""

    def __init__(
        self,
        root: Path,
        use_key: str,
        root_fd: _ChildFdOwnerSlot,
        ledger_fd: _ChildFdOwnerSlot,
        identity_fd: _ChildFdOwnerSlot,
        root_identity: Tuple[int, int, int],
        ledger_identity: Tuple[int, int, int],
        identity_stat: os.stat_result,
        identity_bytes: bytes,
        identity: Mapping[str, Any],
    ) -> None:
        self.root = root
        self.use_key = use_key
        self._root_fd: Optional[_ChildFdOwnerSlot] = root_fd
        self._ledger_fd: Optional[_ChildFdOwnerSlot] = ledger_fd
        self._identity_fd: Optional[_ChildFdOwnerSlot] = identity_fd
        self._root_identity = root_identity
        self._ledger_identity = ledger_identity
        self._identity_stat = identity_stat
        self._identity_bytes = identity_bytes
        self._path_key = str(root)
        self._physical_key = root_identity
        self._owner_pid = os.getpid()
        self._owner_thread = threading.get_ident()
        self._owner_thread_object = threading.current_thread()
        self._lifecycle_lock = threading.RLock()
        self._closed = False
        self._quarantined = False
        self._teardown_started = False
        self._closing_descriptor: Optional[str] = None
        self._phase = "reserved"
        self._attempt_record_digest: Optional[str] = None
        self._terminal_record_digest: Optional[str] = None
        self._reservation_record_digest: Optional[str] = None
        self._reservation: Optional[Dict[str, Any]] = None
        self.lock_identity = {
            "device": str(identity_stat.st_dev),
            "inode": str(identity_stat.st_ino),
            "mode": "0600",
            "linkCount": 1,
            "identityDigest": identity["identityDigest"],
        }
        self.lock_identity_digest = _sha256(
            canonical_json_bytes(self.lock_identity)
        )

    def _abort_acquisition_locked(self) -> None:
        """Identity-bound abort for a partially published guard."""

        try:
            _close_named_fd_slots(self, ("_root_fd", "_ledger_fd"))
            _close_named_fd_slots(self, ("_identity_fd",))
        except BaseException:
            self._quarantined = True
            os._exit(70)
        if any(
            descriptor is not None
            for descriptor in (
                self._root_fd,
                self._ledger_fd,
                self._identity_fd,
            )
        ):
            os._exit(70)
        if (
            _NETWORK_EXECUTION_RESERVATION_PHYSICAL_GUARDS.get(
                self._physical_key
            ) is self
        ):
            del _NETWORK_EXECUTION_RESERVATION_PHYSICAL_GUARDS[
                self._physical_key
            ]
        if (
            _NETWORK_EXECUTION_RESERVATION_GUARDS.get(self._path_key)
            is self
        ):
            del _NETWORK_EXECUTION_RESERVATION_GUARDS[self._path_key]
        self._closed = True
        self._phase = "closed"

    @classmethod
    def acquire_nonblocking(
        cls, root: Path, use_key: str
    ) -> "_NetworkExecutionReservationGuard":
        global _NETWORK_EXECUTION_RESERVATION_ACQUISITIONS_INFLIGHT
        global _NETWORK_EXECUTION_RESERVATION_ACQUISITION_POISONED

        _require_lower_hex(
            use_key, 64, "network execution reservation use key"
        )
        root_fd = ledger_fd = identity_fd = None
        guard: Optional[_NetworkExecutionReservationGuard] = None
        flock_succeeded = False
        transaction_finished = False
        with _NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK:
            if (
                _NETWORK_EXECUTION_RESERVATION_ACQUISITION_POISONED
                or _NETWORK_EXECUTION_RESERVATION_ACQUISITIONS_INFLIGHT
            ):
                raise AuditError(
                    "network execution reservation acquisition is active"
                )
            _NETWORK_EXECUTION_RESERVATION_ACQUISITIONS_INFLIGHT = 1
            try:
                absolute = _absolute_path_without_symlink_resolution(
                    Path(root)
                )
                root_fd, reopened, root_stat = _open_directory_fd(absolute)
                root_identity = _directory_identity(root_stat)
                if (
                    reopened != absolute
                    or stat.S_IMODE(root_stat.st_mode) != 0o700
                    or str(absolute)
                    in _NETWORK_EXECUTION_RESERVATION_GUARDS
                    or root_identity
                    in _NETWORK_EXECUTION_RESERVATION_PHYSICAL_GUARDS
                ):
                    raise AuditError(
                        "network execution reservation is active"
                    )
                ledger_fd = _open_owned_at(root_fd, "ledger", _DIRECTORY_OPEN_FLAGS)
                ledger_stat = _fd_call(ledger_fd, os.fstat)
                if (
                    not stat.S_ISDIR(ledger_stat.st_mode)
                    or stat.S_IMODE(ledger_stat.st_mode) != 0o700
                ):
                    raise AuditError(
                        "network execution ledger anchor drift"
                    )
                identity_fd = _open_owned_at(ledger_fd, "identity.json", os.O_RDONLY
                    | getattr(os, "O_NOFOLLOW", 0)
                    | getattr(os, "O_CLOEXEC", 0))
                identity_stat = _fd_call(identity_fd, os.fstat)
                visible_identity = _fd_at(ledger_fd, os.stat, "identity.json", follow_symlinks=False)
                if (
                    not stat.S_ISREG(identity_stat.st_mode)
                    or stat.S_IMODE(identity_stat.st_mode) != 0o600
                    or identity_stat.st_nlink != 1
                    or _stat_identity(visible_identity)
                    != _stat_identity(identity_stat)
                    or _fd_call(identity_fd, os.get_inheritable)
                ):
                    raise AuditError(
                        "network execution identity anchor drift"
                    )
                _fd_call(identity_fd, os.lseek, 0, os.SEEK_SET)
                chunks: List[bytes] = []
                total = 0
                while True:
                    chunk = _fd_call(identity_fd, os.read, 65536)
                    if not chunk:
                        break
                    total += len(chunk)
                    if total > MAX_JSON_BYTES:
                        raise AuditError(
                            "network execution identity exceeds bound"
                        )
                    chunks.append(chunk)
                identity_bytes = b"".join(chunks)
                identity = parse_canonical_json(identity_bytes)
                if not isinstance(identity, Mapping):
                    raise AuditError(
                        "network execution identity shape drift"
                    )
                _verify_self_digest(identity, "identityDigest")
                try:
                    _fd_call(identity_fd, fcntl.flock, fcntl.LOCK_EX | fcntl.LOCK_NB)
                except OSError as exc:
                    if exc.errno in (errno.EACCES, errno.EAGAIN):
                        raise AuditError(
                            "network execution reservation is active"
                        ) from exc
                    raise
                flock_succeeded = True
                guard = cls(
                    absolute,
                    use_key,
                    root_fd,
                    ledger_fd,
                    identity_fd,
                    root_identity,
                    _directory_identity(ledger_stat),
                    identity_stat,
                    identity_bytes,
                    identity,
                )
                # Secondary index first; the path index is the cleanup
                # capability and is published last.
                _NETWORK_EXECUTION_RESERVATION_PHYSICAL_GUARDS[
                    guard._physical_key
                ] = guard
                _NETWORK_EXECUTION_RESERVATION_GUARDS[
                    guard._path_key
                ] = guard
                root_fd = ledger_fd = identity_fd = None
                guard.revalidate()
                transaction_finished = True
                return guard
            except BaseException as primary:
                cleanup_complete = True
                if guard is not None:
                    try:
                        guard._abort_acquisition_locked()
                    except BaseException as cleanup:
                        _retain_git_cleanup_error(primary, cleanup)
                        cleanup_complete = False
                else:
                    failure: Optional[BaseException] = None
                    try:
                        _close_fd_slots((ledger_fd, root_fd))
                    except BaseException as cleanup:
                        failure = cleanup
                    if failure is None:
                        try:
                            _close_fd_slots((identity_fd,))
                        except BaseException as cleanup:
                            failure = cleanup
                    cleanup_complete = failure is None
                    if failure is not None:
                        _retain_git_cleanup_error(primary, failure)
                transaction_finished = cleanup_complete
                if flock_succeeded and not cleanup_complete:
                    _NETWORK_EXECUTION_RESERVATION_ACQUISITION_POISONED = True
                raise
            finally:
                if transaction_finished:
                    _NETWORK_EXECUTION_RESERVATION_ACQUISITIONS_INFLIGHT = 0
                else:
                    _NETWORK_EXECUTION_RESERVATION_ACQUISITION_POISONED = True

    def _require_owner_thread_locked(self) -> None:
        if (
            os.getpid() != self._owner_pid
            or threading.get_ident() != self._owner_thread
            or threading.current_thread() is not self._owner_thread_object
        ):
            raise AuditError(
                "network execution reservation owner thread drift"
            )

    def revalidate(self) -> None:
        with self._lifecycle_lock:
            self._require_owner_thread_locked()
            if self._closed or self._quarantined:
                raise AuditError(
                    "network execution reservation guard is not active"
                )
            with _NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK:
                if (
                    _NETWORK_EXECUTION_RESERVATION_GUARDS.get(
                        self._path_key
                    ) is not self
                    or _NETWORK_EXECUTION_RESERVATION_PHYSICAL_GUARDS.get(
                        self._physical_key
                    ) is not self
                ):
                    raise AuditError(
                        "network execution reservation owner drift"
                    )
            if any(
                descriptor is None
                for descriptor in (
                    self._root_fd,
                    self._ledger_fd,
                    self._identity_fd,
                )
            ):
                raise AuditError(
                    "network execution reservation descriptor drift"
                )
            assert self._root_fd is not None
            assert self._ledger_fd is not None
            assert self._identity_fd is not None
            root_stat = _fd_call(self._root_fd, os.fstat)
            ledger_stat = _fd_call(self._ledger_fd, os.fstat)
            identity_stat = _fd_call(self._identity_fd, os.fstat)
            visible_root = os.stat(self.root, follow_symlinks=False)
            visible_ledger = _fd_at(self._root_fd, os.stat, "ledger", follow_symlinks=False)
            visible_identity = _fd_at(self._ledger_fd, os.stat, "identity.json", follow_symlinks=False)
            if (
                _directory_identity(root_stat) != self._root_identity
                or _directory_identity(visible_root)
                != self._root_identity
                or _directory_identity(ledger_stat)
                != self._ledger_identity
                or _directory_identity(visible_ledger)
                != self._ledger_identity
                or _stat_identity(identity_stat)
                != _stat_identity(self._identity_stat)
                or _stat_identity(visible_identity)
                != _stat_identity(self._identity_stat)
            ):
                raise AuditError(
                    "network execution reservation anchor drift"
                )
            _fd_call(self._identity_fd, os.lseek, 0, os.SEEK_SET)
            chunks = []
            total = 0
            while True:
                chunk = _fd_call(self._identity_fd, os.read, 65536)
                if not chunk:
                    break
                total += len(chunk)
                if total > MAX_JSON_BYTES:
                    raise AuditError(
                        "network execution identity exceeds bound"
                    )
                chunks.append(chunk)
            if b"".join(chunks) != self._identity_bytes:
                raise AuditError(
                    "network execution reservation identity content drift"
                )

    def bind_reservation(self, reservation: Mapping[str, Any]) -> None:
        value = dict(
            _require_mapping(
                reservation, "network execution reservation"
            )
        )
        _verify_self_digest(value)
        with self._lifecycle_lock:
            self.revalidate()
            digest = value.get("recordDigest")
            if (
                value.get("operationKind")
                != "network-execution-reserved"
                or value.get("useKey") != self.use_key
                or value.get("lockIdentity") != self.lock_identity
                or value.get("lockIdentityDigest")
                != self.lock_identity_digest
                or not isinstance(digest, str)
            ):
                raise AuditError(
                    "network execution reservation guard binding drift"
                )
            if (
                self._reservation_record_digest is not None
                and self._reservation_record_digest != digest
            ):
                raise AuditError(
                    "network execution reservation guard rebound"
                )
            self._reservation_record_digest = digest
            self._reservation = value

    def bound_reservation(self) -> Optional[Dict[str, Any]]:
        with self._lifecycle_lock:
            self._require_owner_thread_locked()
            return (
                None
                if self._reservation is None
                else dict(self._reservation)
            )

    def require_reservation(
        self, reservation: Mapping[str, Any]
    ) -> None:
        value = _require_mapping(
            reservation, "network execution reservation"
        )
        with self._lifecycle_lock:
            self.revalidate()
            if (
                value.get("useKey") != self.use_key
                or value.get("recordDigest")
                != self._reservation_record_digest
                or value.get("lockIdentity") != self.lock_identity
                or value.get("lockIdentityDigest")
                != self.lock_identity_digest
            ):
                raise AuditError(
                    "network execution reservation guard drift"
                )

    def require_execution_reservation(
        self, reservation: Mapping[str, Any]
    ) -> None:
        with self._lifecycle_lock:
            self.require_reservation(reservation)
            if self._phase not in ("reserved", "attempt-live"):
                raise AuditError(
                    "network execution reservation is settling"
                )

    def child_lifetime_lease_fd(
        self,
        reservation: Mapping[str, Any],
        attempt: Mapping[str, Any],
    ) -> _ChildFdOwnerSlot:
        """Borrow the exact flock fd for one sealed Darwin child lifetime."""

        attempt_value = dict(
            _require_mapping(attempt, "network child lease attempt")
        )
        _verify_self_digest(attempt_value)
        attempt_digest = _require_lower_hex(
            attempt_value.get("recordDigest"),
            64,
            "network child lease attempt record",
        )
        with self._lifecycle_lock:
            self.require_reservation(reservation)
            if (
                self._phase != "attempt-live"
                or self._attempt_record_digest != attempt_digest
                or attempt_value.get("completionState") != "attempted"
                or attempt_value.get("logicalKey") != self.use_key
                or attempt_value.get("reservationRecordDigest")
                != self._reservation_record_digest
            ):
                raise AuditError("network child lifetime lease drift")
            descriptor = self._identity_fd
            if not isinstance(descriptor, _ChildFdOwnerSlot):
                raise AuditError(
                    "network child lifetime lease is unavailable"
                )
            try:
                descriptor_flags = _fd_call(descriptor, fcntl.fcntl, fcntl.F_GETFD)
                observed = _fd_call(descriptor, os.fstat)
                _fd_call(descriptor, fcntl.flock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except OSError as exc:
                raise AuditError(
                    "network child lifetime lease ownership drift"
                ) from exc
            if (
                _stat_identity(observed)
                != _stat_identity(self._identity_stat)
                or stat.S_IMODE(observed.st_mode) != 0o600
                or observed.st_nlink != 1
                or descriptor_flags & fcntl.FD_CLOEXEC == 0
                or _fd_call(descriptor, os.get_inheritable)
            ):
                raise AuditError(
                    "network child lifetime lease policy drift"
                )
            return descriptor

    def mark_attempt_live(
        self,
        reservation: Mapping[str, Any],
        attempt: Mapping[str, Any],
    ) -> None:
        attempt_value = dict(
            _require_mapping(attempt, "network live attempt")
        )
        _verify_self_digest(attempt_value)
        digest = _require_lower_hex(
            attempt_value.get("recordDigest"),
            64,
            "network live attempt record",
        )
        with self._lifecycle_lock:
            self.require_reservation(reservation)
            if (
                attempt_value.get("operationKind") != "network-attempt"
                or attempt_value.get("completionState") != "attempted"
                or attempt_value.get("logicalKey") != self.use_key
                or attempt_value.get("reservationRecordDigest")
                != self._reservation_record_digest
            ):
                raise AuditError("network live attempt lineage drift")
            if self._phase == "attempt-live":
                if self._attempt_record_digest != digest:
                    raise AuditError("network live attempt rebound")
                return
            if self._phase != "reserved":
                raise AuditError("network live attempt phase drift")
            self._attempt_record_digest = digest
            self._phase = "attempt-live"

    def begin_settlement(
        self, reservation: Mapping[str, Any]
    ) -> None:
        with self._lifecycle_lock:
            self.require_reservation(reservation)
            if self._phase == "terminal":
                return
            if self._phase != "attempt-live":
                raise AuditError(
                    "network execution settlement replay"
                )
            # Child authority has already been proved quiescent before this
            # transition.  From here a failed/interrupted ledger settlement
            # may safely release the physical owner: a later cold recovery can
            # resume from durable history without racing a live child.
            self._phase = "recovery-sealed"

    def mark_terminal(
        self,
        reservation: Mapping[str, Any],
        terminal: Mapping[str, Any],
    ) -> None:
        terminal_value = dict(
            _require_mapping(terminal, "network execution terminal")
        )
        _verify_self_digest(terminal_value)
        terminal_digest = _require_lower_hex(
            terminal_value.get("recordDigest"),
            64,
            "network execution terminal record",
        )
        with self._lifecycle_lock:
            self.require_reservation(reservation)
            if self._phase == "terminal":
                if self._terminal_record_digest != terminal_digest:
                    raise AuditError(
                        "network execution terminal rebound"
                    )
                return
            if (
                terminal_value.get("operationKind")
                not in ("network-terminal", "network-preflight-terminal")
                or terminal_value.get("useKey", self.use_key)
                != self.use_key
                or self._phase
                not in ("reserved", "attempt-live", "recovery-sealed")
            ):
                raise AuditError("network execution terminal phase drift")
            if terminal_value.get("operationKind") == "network-terminal":
                attempt_digest = terminal_value.get(
                    "attemptRecordDigest"
                )
                if (
                    self._attempt_record_digest is not None
                    and attempt_digest != self._attempt_record_digest
                ):
                    raise AuditError(
                        "network execution terminal attempt drift"
                    )
            self._terminal_record_digest = terminal_digest
            self._phase = "terminal"

    @staticmethod
    def _close_descriptor(descriptor: _ChildFdOwnerSlot) -> bool:
        try:
            descriptor._close_after_fork_child()
            return True
        except BaseException:
            return False

    def _descriptor_has_expected_identity_locked(
        self, name: str, descriptor: _ChildFdOwnerSlot
    ) -> bool:
        try:
            observed = _fd_call(descriptor, os.fstat)
        except (OSError, AuditError):
            return False
        if name == "_root_fd":
            return _directory_identity(observed) == self._root_identity
        if name == "_ledger_fd":
            return _directory_identity(observed) == self._ledger_identity
        if name == "_identity_fd":
            return _stat_identity(observed) == _stat_identity(
                self._identity_stat
            )
        raise AuditError(
            "network execution reservation descriptor name drift"
        )

    def _reconcile_interrupted_close_locked(self) -> bool:
        """Only the permanent slot's successful close commit proves detach."""
        name = self._closing_descriptor
        if name is None:
            return True
        descriptor = getattr(self, name)
        if descriptor is None or descriptor.phase == "closed":
            setattr(self, name, None)
            self._closing_descriptor = None
            return True
        self._quarantined = True
        return False

    def _retire_indexes_after_detach_locked(self) -> None:
        if any(
            descriptor is not None
            for descriptor in (
                self._root_fd,
                self._ledger_fd,
                self._identity_fd,
            )
        ):
            raise AuditError(
                "network execution reservation retirement before detach"
            )
        self._phase = "retiring"
        with _NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK:
            if (
                _NETWORK_EXECUTION_RESERVATION_PHYSICAL_GUARDS.get(
                    self._physical_key
                ) is self
            ):
                del _NETWORK_EXECUTION_RESERVATION_PHYSICAL_GUARDS[
                    self._physical_key
                ]
            if (
                _NETWORK_EXECUTION_RESERVATION_GUARDS.get(
                    self._path_key
                ) is self
            ):
                del _NETWORK_EXECUTION_RESERVATION_GUARDS[
                    self._path_key
                ]
        self._closed = True
        self._phase = "closed"

    def close(self) -> None:
        with self._lifecycle_lock:
            if self._closed:
                self._retire_indexes_after_detach_locked()
                return
            self._require_owner_thread_locked()
            if self._closing_descriptor is not None:
                if not self._reconcile_interrupted_close_locked():
                    raise AuditError(
                        "network execution reservation close is uncertain"
                    )
            if all(
                descriptor is None
                for descriptor in (
                    self._root_fd,
                    self._ledger_fd,
                    self._identity_fd,
                )
            ):
                self._retire_indexes_after_detach_locked()
                return
            if self._quarantined:
                raise AuditError(
                    "network execution reservation is quarantined"
                )
            if self._phase not in (
                "reserved", "recovery-sealed", "terminal"
            ):
                self._quarantined = True
                raise AuditError(
                    "network execution owner is not safe to close"
                )
            if not self._teardown_started:
                # Detect an fd ABA before teardown begins.  Re-taking the
                # nonblocking flock proves physical exclusion immediately
                # before any descriptor is detached.
                self.revalidate()
                assert self._identity_fd is not None
                try:
                    _fd_call(self._identity_fd, fcntl.flock, fcntl.LOCK_EX | fcntl.LOCK_NB)
                except OSError as exc:
                    self._quarantined = True
                    raise AuditError(
                        "network execution reservation flock ownership drift"
                    ) from exc
                self._teardown_started = True
            # Identity is dependent exclusion. Independent root/ledger
            # retirement continues after the first failure, but the flock is
            # retained until both predecessors have positively detached.
            try:
                _close_named_fd_slots(self, ("_root_fd", "_ledger_fd"))
                _close_named_fd_slots(self, ("_identity_fd",))
            except BaseException:
                self._quarantined = True
                raise
            self._retire_indexes_after_detach_locked()

    def _close_after_fork_child(self) -> None:
        if self._closed:
            return
        if self._quarantined or self._closing_descriptor is not None:
            os._exit(70)
        for name in ("_root_fd", "_ledger_fd", "_identity_fd"):
            descriptor = getattr(self, name)
            if descriptor is not None:
                if not self._close_descriptor(descriptor):
                    os._exit(70)
                setattr(self, name, None)
        self._closed = True
        self._lifecycle_lock = threading.RLock()


def _network_execution_reservation_before_fork() -> bool:
    global _NETWORK_EXECUTION_RESERVATION_FORK_MUST_EXIT
    global _NETWORK_EXECUTION_RESERVATION_FORK_ACQUISITION
    _NETWORK_EXECUTION_RESERVATION_FORK_MUST_EXIT = True
    if _NETWORK_EXECUTION_RESERVATION_FORK_ACQUISITION is not None:
        raise AuditError("reservation fork lock settlement is pending")
    _NETWORK_EXECUTION_RESERVATION_FORK_ACQUISITION = _ForkLockAcquisition(
        _NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK
    )
    _NETWORK_EXECUTION_RESERVATION_FORK_ACQUISITION.acquire()
    _NETWORK_EXECUTION_RESERVATION_FORK_MUST_EXIT = bool(
        _NETWORK_EXECUTION_RESERVATION_ACQUISITIONS_INFLIGHT
        or _NETWORK_EXECUTION_RESERVATION_ACQUISITION_POISONED
        or _NETWORK_EXECUTION_RESERVATION_GUARDS
        or _NETWORK_EXECUTION_RESERVATION_PHYSICAL_GUARDS
    )
    return _NETWORK_EXECUTION_RESERVATION_FORK_MUST_EXIT


def _network_execution_reservation_after_fork_parent() -> None:
    global _NETWORK_EXECUTION_RESERVATION_FORK_MUST_EXIT
    global _NETWORK_EXECUTION_RESERVATION_FORK_ACQUISITION
    _NETWORK_EXECUTION_RESERVATION_FORK_MUST_EXIT = True
    acquisition = _NETWORK_EXECUTION_RESERVATION_FORK_ACQUISITION
    if acquisition is not None:
        try:
            acquisition.settle()
        finally:
            if acquisition.settled:
                _NETWORK_EXECUTION_RESERVATION_FORK_ACQUISITION = None


def _network_execution_reservation_after_fork_child() -> None:
    global _NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK
    global _NETWORK_EXECUTION_RESERVATION_GUARDS
    global _NETWORK_EXECUTION_RESERVATION_PHYSICAL_GUARDS
    global _NETWORK_EXECUTION_RESERVATION_ACQUISITIONS_INFLIGHT
    global _NETWORK_EXECUTION_RESERVATION_ACQUISITION_POISONED
    global _NETWORK_EXECUTION_RESERVATION_FORK_MUST_EXIT
    global _NETWORK_EXECUTION_RESERVATION_FORK_ACQUISITION
    must_exit = _NETWORK_EXECUTION_RESERVATION_FORK_MUST_EXIT
    if must_exit:
        # Kernel process teardown closes every inherited descriptor.  Exit
        # before any interruptible Python cleanup can let the forked child
        # continue with a split guard acquisition/owner.
        os._exit(70)
    guards = tuple({
        id(guard): guard
        for guard in (
            *_NETWORK_EXECUTION_RESERVATION_GUARDS.values(),
            *_NETWORK_EXECUTION_RESERVATION_PHYSICAL_GUARDS.values(),
        )
    }.values())
    for guard in guards:
        guard._close_after_fork_child()
    _NETWORK_EXECUTION_RESERVATION_GUARDS = {}
    _NETWORK_EXECUTION_RESERVATION_PHYSICAL_GUARDS = {}
    _NETWORK_EXECUTION_RESERVATION_ACQUISITIONS_INFLIGHT = 0
    _NETWORK_EXECUTION_RESERVATION_ACQUISITION_POISONED = False
    _NETWORK_EXECUTION_RESERVATION_FORK_MUST_EXIT = True
    _NETWORK_EXECUTION_RESERVATION_FORK_ACQUISITION = None
    _NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK = threading.RLock()


def _network_execution_guard(
    root: Path, reservation: Mapping[str, Any]
) -> _NetworkExecutionReservationGuard:
    key = str(_absolute_path_without_symlink_resolution(Path(root)))
    with _NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK:
        guard = _NETWORK_EXECUTION_RESERVATION_GUARDS.get(key)
    if guard is None:
        raise AuditError("network execution reservation owner is absent")
    guard.require_execution_reservation(reservation)
    return guard


def _network_attempt_recovery_guard(
    root: Path, use_key: str
) -> Tuple[_NetworkExecutionReservationGuard, bool]:
    """Acquire a cold physical owner; never reuse live execution authority."""

    key = str(_absolute_path_without_symlink_resolution(Path(root)))
    with _NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK:
        existing = _NETWORK_EXECUTION_RESERVATION_GUARDS.get(key)
    if existing is not None:
        raise AuditError(
            "network attempt recovery is blocked by live execution"
        )
    return (
        _NetworkExecutionReservationGuard.acquire_nonblocking(
            Path(root), use_key
        ),
        True,
    )


def _release_network_execution_guard(
    root: Path, reservation: Mapping[str, Any]
) -> None:
    key = str(_absolute_path_without_symlink_resolution(Path(root)))
    with _NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK:
        guard = _NETWORK_EXECUTION_RESERVATION_GUARDS.get(key)
    if guard is None:
        return
    guard.require_reservation(reservation)
    guard.close()


def _current_thread_network_execution_guards(
) -> Tuple[_NetworkExecutionReservationGuard, ...]:
    owner_pid = os.getpid()
    owner = threading.get_ident()
    owner_object = threading.current_thread()
    with _NETWORK_EXECUTION_RESERVATION_GUARDS_LOCK:
        return tuple(
            guard
            for guard in _NETWORK_EXECUTION_RESERVATION_GUARDS.values()
            if guard._owner_pid == owner_pid
            and guard._owner_thread == owner
            and guard._owner_thread_object is owner_object
        )


def _close_network_execution_guards_since(
    initial: Sequence[_NetworkExecutionReservationGuard],
) -> None:
    initial_guards = set(initial)
    pending = tuple(
        guard
        for guard in _current_thread_network_execution_guards()
        if guard not in initial_guards
    )
    primary: Optional[BaseException] = None
    for guard in pending:
        try:
            reservation = guard.bound_reservation()
            if reservation is None or guard._phase in ("terminal", "recovery-sealed"):
                guard.close()
            else:
                _terminalize_network_preflight_no_network(
                    guard.root,
                    reservation,
                    "InterruptedBeforeNetworkAttempt",
                )
        except BaseException as exc:
            if primary is None:
                primary = exc
            else:
                _retain_git_cleanup_error(primary, exc)
    if primary is not None:
        raise primary


def _selected_network_reservation(
    recovered: Mapping[str, Any], use_key: str
) -> Optional[Dict[str, Any]]:
    matches = [
        value
        for value in recovered.get("networkReservations", [])
        if value.get("useKey") == use_key
    ]
    if len(matches) > 1:
        raise AuditError("network execution reservation is ambiguous")
    return None if not matches else dict(matches[0])


def _require_network_reservation_binding(
    projected: Mapping[str, Any], binding: Mapping[str, Any]
) -> Dict[str, Any]:
    reservation = projected.get("reservation")
    if not isinstance(reservation, Mapping) or any(
        reservation.get(field) != expected
        for field, expected in binding.items()
    ):
        raise AuditError("network execution reservation binding drift")
    return dict(reservation)


def _terminalize_network_preflight_no_network(
    root: Path,
    reservation: Mapping[str, Any],
    failure_class: str,
) -> Optional[Dict[str, Any]]:
    if failure_class not in _NETWORK_PREFLIGHT_FAILURE_CLASSES:
        raise AuditError("network preflight failure class drift")
    reservation = dict(
        _require_mapping(reservation, "network execution reservation")
    )
    use_key = reservation.get("useKey")
    _require_lower_hex(use_key, 64, "network execution reservation use key")

    def current() -> Dict[str, Any]:
        recovered = recover_run_state(root)
        if recovered.get("classification") != "complete":
            raise AuditError("network preflight ledger is indeterminate")
        selected = _selected_network_reservation(recovered, use_key)
        if selected is None:
            raise AuditError("network preflight reservation is absent")
        if selected.get("reservation") != reservation:
            raise AuditError("network preflight reservation changed")
        return selected

    def mark_terminal(
        terminal: Mapping[str, Any]
    ) -> Dict[str, Any]:
        value = dict(
            _require_mapping(
                terminal, "network preflight terminal"
            )
        )
        _network_execution_guard(
            root, reservation
        ).mark_terminal(reservation, value)
        return value

    terminalization_primary: Optional[BaseException] = None
    try:
        selected = current()
        if selected.get("state") == "preflight-failed-no-network":
            terminal = selected.get("terminal")
            if not isinstance(terminal, Mapping):
                raise AuditError("network preflight terminal is absent")
            return mark_terminal(terminal)
        if selected.get("state") == "attempted":
            return None
        if selected.get("state") != "reserved":
            raise AuditError("network preflight reservation state drift")
        _network_execution_guard(root, reservation)

        def validate(recovered: Mapping[str, Any]) -> None:
            value = _selected_network_reservation(recovered, use_key)
            if (
                value is None
                or value.get("state") != "reserved"
                or value.get("reservation") != reservation
            ):
                raise AuditError(
                    "network preflight terminal predecessor drift"
                )

        try:
            terminal = _append_record(
                root,
                "network-preflight-terminal",
                reservation["recordDigest"],
                [],
                "preflight-failed-no-network",
                {
                    "useKey": use_key,
                    "reservationRecordDigest": reservation[
                        "recordDigest"
                    ],
                    "networkAttempted": False,
                    "failureClass": failure_class,
                },
                state_validator=validate,
            )
            return mark_terminal(terminal)
        except AuditError:
            # An attempt can win the race after the first projection.  It is
            # then the sole no-replay authority and a preflight terminal must
            # not fork the lineage.
            selected = current()
            if selected.get("state") == "attempted":
                return None
            terminal = selected.get("terminal")
            if (
                selected.get("state")
                == "preflight-failed-no-network"
                and isinstance(terminal, Mapping)
            ):
                return mark_terminal(terminal)
            raise
    except BaseException as primary:
        terminalization_primary = primary
        raise
    finally:
        # Once a live owner reaches terminalization, every exit path releases
        # or quarantines that exact physical root.  Durable state remains the
        # sole cold-recovery authority.
        try:
            _release_network_execution_guard(root, reservation)
        except BaseException as cleanup:
            if terminalization_primary is None:
                raise
            _retain_git_cleanup_error(terminalization_primary, cleanup)


def reserve_network_execution_no_live_work(
    root: Path,
    frontier_id: str,
    *,
    wrapper: str,
    operation: str,
    argv: Sequence[str],
    preflight: Mapping[str, Any],
    manifest: Mapping[str, Any],
    request_body_record: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    """Reserve one sealed V2 use before projection, credentials, or runtime."""

    root = _absolute_path_without_symlink_resolution(Path(root))
    binding = _network_execution_reservation_binding(
        wrapper,
        frontier_id,
        operation,
        argv,
        preflight,
        manifest,
        request_body_record=request_body_record,
    )
    recovered = recover_run_state(root)
    if recovered.get("classification") != "complete":
        raise AuditError("network reservation ledger is indeterminate")
    selected = _selected_network_reservation(recovered, binding["useKey"])
    if selected is not None:
        reservation = _require_network_reservation_binding(
            selected, binding
        )
        if selected.get("state") == "reserved":
            guard = _NetworkExecutionReservationGuard.acquire_nonblocking(
                root, binding["useKey"]
            )
            reservation_primary: Optional[BaseException] = None
            try:
                if (
                    guard.lock_identity != reservation.get("lockIdentity")
                    or guard.lock_identity_digest
                    != reservation.get("lockIdentityDigest")
                ):
                    raise AuditError(
                        "network execution reservation lock identity drift"
                    )
                guard.bind_reservation(reservation)
                _terminalize_network_preflight_no_network(
                    root, reservation, "InterruptedBeforeNetworkAttempt"
                )
            except BaseException as primary:
                reservation_primary = primary
                raise
            finally:
                try:
                    guard.close()
                except BaseException as cleanup:
                    if reservation_primary is None:
                        raise
                    _retain_git_cleanup_error(reservation_primary, cleanup)
        raise AuditError(
            "network execution reservation is already terminal or abandoned"
        )

    guard = _NetworkExecutionReservationGuard.acquire_nonblocking(
        root, binding["useKey"]
    )
    binding.update(
        {
            "lockName": "ledger/identity.json",
            "lockIdentity": dict(guard.lock_identity),
            "lockIdentityDigest": guard.lock_identity_digest,
            "releaseRule": "darwin-flock-close-only-v1",
        }
    )

    def validate(current: Mapping[str, Any]) -> None:
        if _selected_network_reservation(
            current, binding["useKey"]
        ) is not None or any(
            value.get("logicalKey") == binding["useKey"]
            for value in current.get("networkAttempts", [])
        ):
            raise AuditError("network request use is already reserved")
        frontiers = [
            value
            for value in current.get("openFrontiers", [])
            if value.get("frontierId") == frontier_id
            and value.get("frontierKind")
            in ("remote-mutation", "local-resource")
        ]
        if len(frontiers) != 1:
            raise AuditError("network reservation frontier is unavailable")

    try:
        reservation = _append_record(
            root,
            "network-execution-reserved",
            binding["useKey"],
            [],
            "reserved",
            binding,
            state_validator=validate,
        )
        guard.bind_reservation(reservation)
        return reservation
    except BaseException as primary:
        try:
            guard.close()
        except BaseException as cleanup:
            _retain_git_cleanup_error(primary, cleanup)
        raise


def reopen_network_execution_reservation_no_live_work(
    root: Path,
    reservation: Mapping[str, Any],
    *,
    wrapper: str,
    frontier_id: str,
    operation: str,
    argv: Sequence[str],
    preflight: Mapping[str, Any],
    manifest: Mapping[str, Any],
    request_body_record: Optional[Mapping[str, Any]] = None,
) -> Dict[str, Any]:
    binding = _network_execution_reservation_binding(
        wrapper,
        frontier_id,
        operation,
        argv,
        preflight,
        manifest,
        request_body_record=request_body_record,
    )
    supplied = dict(
        _require_mapping(reservation, "network execution reservation")
    )
    recovered = recover_run_state(root)
    if recovered.get("classification") != "complete":
        raise AuditError("network reservation ledger is indeterminate")
    selected = _selected_network_reservation(recovered, binding["useKey"])
    if (
        selected is None
        or selected.get("state") != "reserved"
        or _require_network_reservation_binding(selected, binding)
        != supplied
    ):
        raise AuditError("network execution reservation is not open")
    _network_execution_guard(root, supplied)
    return supplied


def _run_reserved_network_preflight_step(
    root: Path,
    reservation: Mapping[str, Any],
    failure_class: str,
    operation: Any,
) -> Any:
    try:
        if not callable(operation):
            raise AuditError("network preflight step is not callable")
        return operation()
    except BaseException as exc:
        try:
            _terminalize_network_preflight_no_network(
                root,
                reservation,
                (
                    failure_class
                    if isinstance(exc, AuditError)
                    else "InterruptedBeforeNetworkAttempt"
                ),
            )
        except BaseException as cleanup:
            _retain_git_cleanup_error(exc, cleanup)
        raise


def _run_reserved_network_attempt_step(
    root: Path,
    reservation: Mapping[str, Any],
    operation: Any,
) -> Any:
    """Require a successful wrapper call to durably consume its reservation."""

    try:
        if not callable(operation):
            raise AuditError("network attempt step is not callable")
        result = operation()
        recovered = recover_run_state(root)
        selected = _selected_network_reservation(
            recovered, reservation.get("useKey")
        )
        if (
            recovered.get("classification") != "complete"
            or selected is None
            or selected.get("reservation") != reservation
            or selected.get("state") != "attempted"
        ):
            raise AuditError(
                "network wrapper returned without durable attempt handoff"
            )
        return result
    except BaseException as exc:
        try:
            _terminalize_network_preflight_no_network(
                root,
                reservation,
                (
                    "BrokerBindingDrift"
                    if isinstance(exc, AuditError)
                    else "InterruptedBeforeNetworkAttempt"
                ),
            )
        except BaseException as cleanup_error:
            _retain_git_cleanup_error(exc, cleanup_error)
        raise


def _raise_reserved_network_preflight_failure(
    root: Path,
    reservation: Mapping[str, Any],
    failure_class: str,
    message: str,
) -> None:
    _terminalize_network_preflight_no_network(
        root, reservation, failure_class
    )
    raise AuditError(message)


def _recover_network_logical_key(
    recovered: Mapping[str, Any], logical_key: str
) -> Optional[Dict[str, Any]]:
    matches = [
        row for row in recovered.get("networkAttempts", [])
        if row.get("logicalKey") == logical_key
    ]
    if not matches:
        return None
    if len(matches) != 1:
        raise AuditError("network logical key is ambiguous")
    selected = matches[0]
    if selected.get("state") in ("completed", "unknown-no-replay"):
        terminal = selected.get("terminal")
        if not isinstance(terminal, Mapping):
            raise AuditError("network terminal is absent")
        return dict(terminal)
    raise AuditError("network request is attempted and cannot be replayed")


def _recover_network_logical_key_locked(
    root: Path, logical_key: str
) -> Optional[Dict[str, Any]]:
    """Cold-reopen a network terminal while holding the durable ledger lock."""

    def reopen(transaction: LedgerTransaction) -> Optional[Dict[str, Any]]:
        recovered = transaction.recover()
        return _recover_network_logical_key(recovered, logical_key)

    return _execute_ledger_transaction(
        root,
        operation_kind="network-terminal-reopen",
        body=reopen,
    )


def recover_or_reopen_network_logical_key_no_network(
    root: Path, logical_key: str
) -> Optional[Dict[str, Any]]:
    """Cold-reopen or terminalize one exact request before any live work."""

    root = _absolute_path_without_symlink_resolution(Path(root))
    _require_lower_hex(logical_key, 64, "network logical key")

    def probe(transaction: LedgerTransaction) -> bool:
        _identity, records = _recover_records_fd(transaction)
        matches = [
            record for record in records
            if record.get("operationKind") == "network-attempt"
            and record.get("logicalKey") == logical_key
        ]
        if len(matches) > 1:
            raise AuditError("network logical key is ambiguous")
        return bool(matches)

    exists = _execute_ledger_transaction(
        root,
        operation_kind="network-attempt-cold-probe",
        body=probe,
    )
    if not exists:
        return None
    return recover_network_attempt_no_network(root, logical_key)


def recover_network_observation_no_network(
    root: Path, logical_key: str
) -> Dict[str, Any]:
    """Terminalize one durable observation without replaying transport."""

    root = _absolute_path_without_symlink_resolution(Path(root))
    _require_lower_hex(logical_key, 64, "network logical key")

    def terminalize(transaction: LedgerTransaction) -> Dict[str, Any]:
        _identity, records = _recover_records_fd(transaction)
        raw_attempts = [
            record for record in records
            if record.get("operationKind") == "network-attempt"
            and record.get("logicalKey") == logical_key
        ]
        if len(raw_attempts) != 1:
            raise AuditError(
                "network observation recovery key is absent or ambiguous"
            )
        frontier_id = raw_attempts[0].get("frontierId")
        frontiers = [
            record for record in records
            if record.get("operationKind") == "frontier-start"
            and record.get("frontierId") == frontier_id
        ]
        if len(frontiers) != 1:
            raise AuditError("network observation recovery frontier drift")
        resource_id = frontiers[0].get("resourceId")
        if resource_id is not None and not isinstance(resource_id, str):
            raise AuditError("network observation recovery resource drift")

        recovered = transaction.recover(
            allow_resource_drift_id=resource_id
        )
        matches = [
            value for value in recovered.get("networkAttempts", [])
            if value.get("logicalKey") == logical_key
        ]
        if len(matches) != 1:
            raise AuditError(
                "network observation recovery key is absent or ambiguous"
            )
        selected = matches[0]
        if selected.get("state") == "completed":
            terminal = selected.get("terminal")
            if not isinstance(terminal, Mapping):
                raise AuditError("completed network terminal is absent")
            return dict(terminal)
        if selected.get("state") != "observed":
            raise AuditError(
                "network request has no replay-free durable observation"
            )
        attempt = selected.get("attempt")
        observation = selected.get("observation")
        if not isinstance(attempt, Mapping) or not isinstance(
            observation, Mapping
        ):
            raise AuditError("network observation recovery lineage drift")

        terminal = transaction.append_record(
            recovered,
            "network-terminal",
            observation["recordDigest"],
            [],
            "completed",
            {
                "attemptId": attempt["attemptId"],
                "attemptRecordDigest": attempt["recordDigest"],
                "observationRecordDigest": observation["recordDigest"],
                "logicalKey": logical_key,
                "outcome": "completed",
            },
        )
        reopened = transaction.recover(
            allow_resource_drift_id=resource_id
        )
        recovered_terminal = _recover_network_logical_key(
            reopened, logical_key
        )
        if recovered_terminal != terminal:
            raise AuditError("network observation recovery terminal drift")
        return terminal

    return _execute_ledger_transaction(
        root,
        operation_kind="network-observation-recovery",
        body=terminalize,
    )


def _recover_network_attempt_no_network_with_guard(
    root: Path,
    logical_key: str,
    recovery_guard: _NetworkExecutionReservationGuard,
    owns_recovery_guard: bool,
) -> Dict[str, Any]:
    """Close one interrupted network attempt without replaying transport.

    A durable attempt proves only that transport *may* have started.  With no
    durable observation, recovery therefore burns any bound execution capsule
    before publishing ``unknown-no-replay``.  An already durable observation
    is never downgraded: it is terminalized as completed using its exact bytes.
    """

    root = _absolute_path_without_symlink_resolution(Path(root))
    _require_lower_hex(logical_key, 64, "network logical key")
    if not isinstance(
        recovery_guard, _NetworkExecutionReservationGuard
    ) or not isinstance(owns_recovery_guard, bool):
        raise AuditError("network attempt recovery guard drift")

    def recover_attempt(transaction: LedgerTransaction) -> Dict[str, Any]:
        _identity, records = _recover_records_fd(transaction)
        raw_attempts = [
            record for record in records
            if record.get("operationKind") == "network-attempt"
            and record.get("logicalKey") == logical_key
        ]
        if len(raw_attempts) != 1:
            raise AuditError(
                "network attempt recovery key is absent or ambiguous"
            )
        raw_attempt = raw_attempts[0]
        raw_reservations = [
            record for record in records
            if record.get("operationKind")
            == "network-execution-reserved"
            and record.get("useKey") == logical_key
            and record.get("recordDigest")
            == raw_attempt.get("reservationRecordDigest")
        ]
        if len(raw_reservations) != 1:
            raise AuditError(
                "network attempt recovery reservation is absent or ambiguous"
            )
        recovery_guard.bind_reservation(raw_reservations[0])
        recovery_guard.require_reservation(raw_reservations[0])
        if owns_recovery_guard:
            recovery_guard.mark_attempt_live(
                raw_reservations[0], raw_attempt
            )
            recovery_guard.begin_settlement(raw_reservations[0])
        resource_id = raw_attempt.get("capsuleResourceId")
        if resource_id is not None and not isinstance(resource_id, str):
            raise AuditError("network attempt capsule resource drift")

        capsule_drift = False
        if resource_id is None:
            recovered = transaction.recover()
        else:
            try:
                recovered = transaction.recover()
            except (AuditError, OSError, ValueError, KeyError, TypeError):
                # The second projection changes exactly one rule: it admits
                # byte drift for this attempt's sealed capsule.  If it still
                # fails, the ledger has a structural fault, not recoverable
                # child drift.
                recovered = transaction.recover(
                    allow_resource_drift_id=resource_id
                )
                capsule_drift = True

        def selected_attempt(
            value: Mapping[str, Any]
        ) -> Dict[str, Any]:
            matches = [
                projected
                for projected in value.get("networkAttempts", [])
                if projected.get("logicalKey") == logical_key
            ]
            if len(matches) != 1:
                raise AuditError(
                    "network attempt recovery key is absent or ambiguous"
                )
            return dict(matches[0])

        selected = selected_attempt(recovered)
        state = selected.get("state")
        if state in ("completed", "unknown-no-replay"):
            terminal = selected.get("terminal")
            if not isinstance(terminal, Mapping):
                raise AuditError("network recovery terminal is absent")
            return dict(terminal)

        attempt = selected.get("attempt")
        if not isinstance(attempt, Mapping) or attempt != raw_attempt:
            raise AuditError("network attempt recovery lineage drift")

        if state == "observed":
            observation = selected.get("observation")
            if not isinstance(observation, Mapping):
                raise AuditError("network recovery observation is absent")
            terminal = transaction.append_record(
                recovered,
                "network-terminal",
                observation["recordDigest"],
                [],
                "completed",
                {
                    "attemptId": attempt["attemptId"],
                    "attemptRecordDigest": attempt["recordDigest"],
                    "observationRecordDigest": observation[
                        "recordDigest"
                    ],
                    "logicalKey": logical_key,
                    "outcome": "completed",
                },
            )
            reopened = transaction.recover(
                allow_resource_drift_id=resource_id
            )
            terminalized = selected_attempt(reopened)
            if (
                terminalized.get("state") != "completed"
                or terminalized.get("terminal") != terminal
            ):
                raise AuditError("network observation recovery terminal drift")
            return terminal

        if state != "attempted-unknown":
            raise AuditError("network attempt recovery state drift")

        if resource_id is not None:
            resource = recovered.get("resources", {}).get(resource_id)
            snapshots = (
                resource.get("snapshots", [])
                if isinstance(resource, Mapping) else []
            )
            latest = snapshots[-1] if snapshots else None
            consumption = (
                resource.get("consumption")
                if isinstance(resource, Mapping) else None
            )
            taint = (
                resource.get("taint")
                if isinstance(resource, Mapping) else None
            )
            capsule_fields = {
                "capsuleProfile", "capsuleResourceId",
                "capsuleRecordDigest", "capsuleSnapshotDigest",
                "capsuleSnapshotRecordDigest",
            }
            if (
                not capsule_fields.issubset(attempt)
                or not isinstance(resource, Mapping)
                or resource.get("allocation", {}).get("resourceKind")
                != "git-execution-capsule"
                or not isinstance(latest, Mapping)
                or latest.get("snapshotDigest")
                != attempt.get("capsuleSnapshotDigest")
                or latest.get("recordDigest")
                != attempt.get("capsuleSnapshotRecordDigest")
            ):
                raise AuditError("network attempt capsule lineage drift")
            if consumption is None:
                if capsule_drift:
                    # A production child cannot mutate before its durable
                    # consume record.  Do not fabricate ordering authority or
                    # bless the changed bytes.
                    raise AuditError(
                        "unconsumed network capsule has byte drift"
                    )
                transaction.append_record(
                    recovered,
                    "git-execution-capsule-consumed",
                    attempt["capsuleRecordDigest"],
                    [],
                    "consumed",
                    {
                        "resourceId": resource_id,
                        "profile": attempt["capsuleProfile"],
                        "capsuleRecordDigest": attempt[
                            "capsuleRecordDigest"
                        ],
                        "snapshotDigest": attempt[
                            "capsuleSnapshotDigest"
                        ],
                        "snapshotRecordDigest": attempt[
                            "capsuleSnapshotRecordDigest"
                        ],
                        "preflightRecordDigest": attempt[
                            "preflightRecordDigest"
                        ],
                    },
                )
                recovered = transaction.recover()
                resource = recovered["resources"][resource_id]
                consumption = resource.get("consumption")
                if not isinstance(consumption, Mapping):
                    raise AuditError(
                        "network recovery capsule consumption drift"
                    )
            elif (
                consumption.get("capsuleRecordDigest")
                != attempt.get("capsuleRecordDigest")
                or consumption.get("snapshotDigest")
                != attempt.get("capsuleSnapshotDigest")
                or consumption.get("snapshotRecordDigest")
                != attempt.get("capsuleSnapshotRecordDigest")
                or consumption.get("preflightRecordDigest")
                != attempt.get("preflightRecordDigest")
            ):
                raise AuditError("network recovery capsule consumption drift")

            if (
                capsule_drift
                and taint is None
                and attempt.get("capsuleProfile")
                in {"ls-remote-read", "push-outbound"}
            ):
                transaction.append_record(
                    recovered,
                    "git-execution-capsule-tainted",
                    attempt["capsuleRecordDigest"],
                    [],
                    "tainted-preserved",
                    {
                        "resourceId": resource_id,
                        "profile": attempt["capsuleProfile"],
                        "capsuleRecordDigest": attempt[
                            "capsuleRecordDigest"
                        ],
                        "snapshotDigest": attempt[
                            "capsuleSnapshotDigest"
                        ],
                        "snapshotRecordDigest": attempt[
                            "capsuleSnapshotRecordDigest"
                        ],
                        "reasonCode": "child-failure-resource-drift",
                    },
                )
                recovered = transaction.recover()
            elif capsule_drift and taint is None:
                # A fetch capsule is deliberately mutable.  Its quarantine
                # owner must snapshot and terminalize that resource frontier;
                # this API only closes the no-replay network attempt.
                recovered = transaction.recover(
                    allow_resource_drift_id=resource_id
                )

        terminal = transaction.append_record(
            recovered,
            "network-terminal",
            attempt["recordDigest"],
            [],
            "unknown-no-replay",
            {
                "attemptId": attempt["attemptId"],
                "attemptRecordDigest": attempt["recordDigest"],
                "observationRecordDigest": None,
                "logicalKey": logical_key,
                "outcome": "unknown-no-replay",
                "failureClass": "InterruptedBeforeDurableObservation",
            },
        )
        reopened = transaction.recover(
            allow_resource_drift_id=resource_id
        )
        terminalized = selected_attempt(reopened)
        if (
            terminalized.get("state") != "unknown-no-replay"
            or terminalized.get("terminal") != terminal
        ):
            raise AuditError("network attempt recovery terminal drift")
        return terminal

    try:
        terminal = _execute_ledger_transaction(
            root,
            operation_kind="network-attempt-recovery",
            body=recover_attempt,
        )
        bound_reservation = recovery_guard.bound_reservation()
        if bound_reservation is None:
            raise AuditError(
                "network attempt recovery reservation was not bound"
            )
        recovery_guard.mark_terminal(bound_reservation, terminal)
        return terminal
    finally:
        if owns_recovery_guard:
            recovery_guard.close()


def recover_network_attempt_no_network(
    root: Path, logical_key: str
) -> Dict[str, Any]:
    """Cold-recover an attempt only when no live execution owner exists."""

    root_value = _absolute_path_without_symlink_resolution(Path(root))
    logical_key = _require_lower_hex(
        logical_key, 64, "network logical key"
    )
    recovery_guard, owns_recovery_guard = (
        _network_attempt_recovery_guard(root_value, logical_key)
    )
    return _recover_network_attempt_no_network_with_guard(
        root_value,
        logical_key,
        recovery_guard,
        owns_recovery_guard,
    )


def _recover_live_network_attempt_no_network(
    root: Path,
    logical_key: str,
    *,
    recovery_permit: Any,
    recovery_scope: Any,
    attempt: Mapping[str, Any],
    reservation: Mapping[str, Any],
) -> Dict[str, Any]:
    """Settle a live owner's attempt through its one-shot capability."""

    root_value = _absolute_path_without_symlink_resolution(Path(root))
    logical_key = _require_lower_hex(
        logical_key, 64, "network logical key"
    )
    primary: Optional[BaseException] = None
    try:
        recovery_guard = _begin_network_attempt_recovery(
            recovery_permit,
            recovery_scope,
            root_value,
            logical_key,
            attempt,
            reservation,
        )
        return _recover_network_attempt_no_network_with_guard(
            root_value,
            logical_key,
            recovery_guard,
            False,
        )
    except BaseException as exc:
        primary = exc
        raise
    finally:
        try:
            _revoke_network_attempt_recovery_permit(recovery_permit)
        except BaseException as cleanup:
            if primary is None:
                raise
            _retain_git_cleanup_error(primary, cleanup)


def _network_git_result_bytes(value: Any, label: str) -> bytes:
    if not isinstance(value, (bytes, bytearray, memoryview)):
        raise AuditError("network Git " + label + " result type drift")
    if len(value) > 8 * 1024 * 1024:
        raise AuditError("network Git " + label + " result exceeds bound")
    return bytes(value)


def _parse_network_git_result(
    binding: Mapping[str, Any],
    exit_code: int,
    stdout_bytes: Any,
    stderr_bytes: Any,
) -> Dict[str, Any]:
    """Turn one exact Git child result into a closed semantic record."""

    binding = _require_mapping(binding, "network Git argv binding")
    try:
        _verify_self_digest(binding, field="bindingDigest")
        expected_binding = _parse_network_git_argv(
            binding.get("operation"), binding.get("argv")
        )
    except AuditError as exc:
        raise AuditError("network Git result binding drift") from exc
    if dict(binding) != expected_binding:
        raise AuditError("network Git result binding/argv drift")
    if (
        not isinstance(exit_code, int)
        or isinstance(exit_code, bool)
        or exit_code != 0
    ):
        raise AuditError("network Git result exit status is not complete")
    stdout = _network_git_result_bytes(stdout_bytes, "stdout")
    stderr = _network_git_result_bytes(stderr_bytes, "stderr")
    if len(stdout) + len(stderr) > 16 * 1024 * 1024:
        raise AuditError("network Git result exceeds aggregate bound")
    operation = binding["operation"]
    parser_family = binding["parserFamily"]
    result: Dict[str, Any] = {
        "schemaVersion": "qinao.network-git-result.v1",
        "operation": operation,
        "parserFamily": parser_family,
        "argvBindingDigest": binding["bindingDigest"],
        "exitCode": exit_code,
        "stdoutByteCount": len(stdout),
        "stdoutSha256": _sha256(stdout),
        "stderrByteCount": len(stderr),
        "stderrSha256": _sha256(stderr),
    }

    if parser_family == "git-ls-remote":
        if stderr:
            raise AuditError("network Git ls-remote stderr output drift")
        if not stdout or not stdout.endswith(b"\n"):
            raise AuditError("network Git ls-remote result is empty or unframed")
        rows = []
        seen_refs = set()
        object_length: Optional[int] = None
        for line in stdout[:-1].split(b"\n"):
            if line.count(b"\t") != 1:
                raise AuditError("network Git ls-remote output framing drift")
            oid_bytes, ref_bytes = line.split(b"\t", 1)
            try:
                oid = oid_bytes.decode("ascii", "strict")
                ref = ref_bytes.decode("ascii", "strict")
            except UnicodeDecodeError as exc:
                raise AuditError("network Git ls-remote output encoding drift") from exc
            _network_git_oid(oid, "network Git ls-remote result")
            _network_git_ref(ref, allow_tag=True)
            if ref in seen_refs:
                raise AuditError("network Git ls-remote duplicate ref")
            if object_length is None:
                object_length = len(oid)
            elif len(oid) != object_length:
                raise AuditError("network Git ls-remote mixed object format")
            seen_refs.add(ref)
            rows.append({"oid": oid, "ref": ref})
        if rows != sorted(rows, key=lambda row: row["ref"]):
            raise AuditError("network Git ls-remote ref ordering drift")
        if binding.get("mode") == "exact-ref" and (
            len(rows) != 1 or rows[0]["ref"] != binding.get("remoteRef")
        ):
            raise AuditError("network Git ls-remote bound ref result drift")
        result["remoteRefs"] = rows
        return _self_digest_record(result)

    if parser_family in ("git-fetch-empty", "git-fetch-known"):
        if stdout:
            raise AuditError("network Git fetch stdout result must be empty")
        remote_ref = binding.get("remoteRef")
        _network_git_ref(remote_ref, allow_tag=True)
        local_ref = binding.get("localRef")
        if local_ref != _NETWORK_FETCH_LOCAL_REF:
            raise AuditError("network Git fetch result local ref drift")
        ref_kind = "branch" if remote_ref.startswith("refs/heads/") else "tag"
        ref_name = remote_ref.split("/", 2)[2]
        try:
            diagnostic = stderr.decode("ascii", "strict")
        except UnicodeDecodeError as exc:
            raise AuditError("network Git fetch diagnostic encoding drift") from exc
        endpoint_display = _NETWORK_GIT_ENDPOINT.removesuffix(".git")
        pattern = (
            r"From " + re.escape(endpoint_display) + r"\n"
            r" \* \[new " + ref_kind + r"\]\s+" + re.escape(ref_name)
            + r"\s+-> " + re.escape(local_ref) + r"\n"
        )
        if re.fullmatch(pattern, diagnostic) is None:
            raise AuditError("network Git fetch diagnostic result drift")
        result["remoteRef"] = remote_ref
        result["localRef"] = local_ref
        result["diagnosticKind"] = "explicit-local-ref"
        return _self_digest_record(result)

    if parser_family == "git-push":
        if not stdout.endswith(b"\n"):
            raise AuditError("network Git push output framing drift")
        try:
            text = stdout.decode("ascii", "strict")
        except UnicodeDecodeError as exc:
            raise AuditError("network Git push output encoding drift") from exc
        lines = text.splitlines()
        if (
            len(lines) != 3
            or lines[0] != "To " + _NETWORK_GIT_ENDPOINT
            or lines[2] != "Done"
            or lines[1].count("\t") != 2
        ):
            raise AuditError("network Git push result output drift")
        flag, refspec, summary = lines[1].split("\t", 2)
        expected_refspec = (
            binding["sourceOid"] + ":" + binding["destinationRef"]
        )
        if flag not in {" ", "+", "*", "="}:
            raise AuditError("network Git push delete or reject result")
        if refspec != expected_refspec:
            raise AuditError("network Git push destination ref result drift")
        if (
            not summary
            or len(summary.encode("ascii", "strict")) > 4096
            or any(ord(character) < 0x20 for character in summary)
        ):
            raise AuditError("network Git push summary result drift")
        result.update(
            {
                "sourceOid": binding["sourceOid"],
                "destinationRef": binding["destinationRef"],
                "leaseExpectedOid": binding["expectedOid"],
                "pushStatus": flag,
                "summarySha256": _sha256(summary.encode("ascii")),
            }
        )
        return _self_digest_record(result)
    raise AuditError("network Git result parser family drift")


def _collect_network_git_chunks(chunks: Any, label: str) -> bytearray:
    try:
        iterator = iter(chunks)
    except TypeError as exc:
        raise AuditError("network Git " + label + " chunks type drift") from exc
    owner = bytearray()
    try:
        for chunk in iterator:
            if not isinstance(chunk, (bytes, bytearray, memoryview)):
                raise AuditError("network Git " + label + " chunk type drift")
            if len(owner) + len(chunk) > 8 * 1024 * 1024:
                raise AuditError("network Git " + label + " exceeds bound")
            owner.extend(chunk)
        return owner
    except BaseException:
        for index in range(len(owner)):
            owner[index] = 0
        raise


def _capture_git_transport_streams(
    stdout_chunks: Iterable[Any], stderr_chunks: Iterable[Any]
) -> Tuple[str, str, Dict[str, Any]]:
    stdout_digest = hashlib.sha256()
    stderr_digest = hashlib.sha256()
    totals = {"stdout": 0, "stderr": 0, "aggregate": 0}
    marker = b"\x00qinao-stderr\x00"

    def combined_stream() -> Iterable[Any]:
        for label, chunks, digest in (
            ("stdout", stdout_chunks, stdout_digest),
            ("stderr", stderr_chunks, stderr_digest),
        ):
            if label == "stderr":
                totals["aggregate"] += len(marker)
                if totals["aggregate"] > 16 * 1024 * 1024:
                    raise AuditError(
                        "network Git output exceeds aggregate bound"
                    )
                yield marker
            for chunk in chunks:
                if not isinstance(chunk, (bytes, bytearray, memoryview)):
                    raise AuditError(
                        "network Git output chunk type drift"
                    )
                view = memoryview(chunk)
                totals[label] += len(view)
                totals["aggregate"] += len(view)
                if totals[label] > 8 * 1024 * 1024:
                    raise AuditError(
                        "network Git " + label + " exceeds bound"
                    )
                if totals["aggregate"] > 16 * 1024 * 1024:
                    raise AuditError(
                        "network Git output exceeds aggregate bound"
                    )
                digest.update(view)
                yield view

    captured = safe_capture(combined_stream(), profile="git-transport")
    return stdout_digest.hexdigest(), stderr_digest.hexdigest(), captured


def _release_owned_git_streams(
    owners: Sequence[Any], primary: Optional[BaseException] = None,
    *, cleanup_events: Optional[List[Tuple[str, BaseException]]] = None,
) -> None:
    """Attempt every stream; a finite fallback destroys the same failed backing."""
    cleanup_primary = primary
    for owner_index, owner in enumerate(owners):
        if not isinstance(owner, OwnedSecretBuffer):
            continue
        backing = owner._owner
        if backing is None:
            continue
        try:
            owner.release()
        except BaseException as cleanup:
            if cleanup_events is not None:
                cleanup_events.append((str(owner_index) + "-release", cleanup))
            if cleanup_primary is None:
                cleanup_primary = cleanup
            else:
                _retain_git_cleanup_error(cleanup_primary, cleanup)
            try:
                backing[:] = b"\x00" * len(backing)
                owner._owner = None
            except BaseException as destruction_error:
                if cleanup_events is not None:
                    cleanup_events.append((str(owner_index) + "-fallback", destruction_error))
                _retain_git_cleanup_error(cleanup_primary, destruction_error)
    if primary is None and cleanup_primary is not None:
        raise cleanup_primary


def _capture_owned_git_transport_streams(
    stdout_owner: OwnedSecretBuffer,
    stderr_owner: OwnedSecretBuffer,
) -> Tuple[str, str, Dict[str, Any]]:
    """Stream-scan two sensitive child owners and destroy both on every exit."""

    capture_primary: Optional[BaseException] = None
    try:
        if (
            not isinstance(stdout_owner, OwnedSecretBuffer)
            or not isinstance(stderr_owner, OwnedSecretBuffer)
            or stdout_owner is stderr_owner
        ):
            raise AuditError("network Git stream owner drift")
        return _capture_git_transport_streams(
            (stdout_owner.view(),), (stderr_owner.view(),)
        )
    except BaseException as primary:
        capture_primary = primary
        raise
    finally:
        _release_owned_git_streams((stdout_owner, stderr_owner), capture_primary)


@_git_child_mint_permit_scope
@_network_attempt_recovery_scope
def execute_network_wrapper(
    root: Path,
    frontier_id: str,
    *,
    wrapper: str,
    operation: str,
    argv: Sequence[str],
    preflight: Mapping[str, Any],
    manifest: Mapping[str, Any],
    transport: Any,
    quarantine_empty: Optional[bool] = None,
    credential_broker: Optional[OneShotCredentialBroker] = None,
    request_seal_record_path: Optional[str] = None,
    request_parent_payload: Optional[Mapping[str, Any]] = None,
    lfs_request_objects: Optional[Sequence[Mapping[str, Any]]] = None,
    lfs_request_bytes: Optional[bytes] = None,
    lfs_approved_manifest: Optional[Mapping[str, Any]] = None,
    gh_request_body_record: Optional[Mapping[str, Any]] = None,
    git_execution_capsule: Optional[Mapping[str, Any]] = None,
    git_execution_capsule_snapshot: Optional[Mapping[str, Any]] = None,
    execution_reservation: Optional[Mapping[str, Any]] = None,
    _faults: Optional[DurabilityFaults] = None,
    _network_recovery_scope: Any = None,
    _network_recovery_permit_sink: Optional[List[Any]] = None,
) -> Dict[str, Any]:
    root = Path(root).resolve()
    faults = _faults or DurabilityFaults()
    normalized = _validate_argv(argv)
    specification = _network_operation_contract(operation)
    if specification["wrapper"] != wrapper:
        raise AuditError("network operation/wrapper contract drift")
    parser_family = specification["parserFamily"]
    executor_family = specification["executorFamily"]
    credential_kind = specification["credentialKind"]
    preflight = _require_mapping(preflight, "network wrapper preflight")
    manifest = _require_mapping(manifest, "network wrapper manifest")
    _verify_self_digest(preflight)
    _verify_self_digest(manifest)
    selected_row = select_network_request_row(
        manifest,
        operation,
        normalized,
        preflight,
        request_body_record=gh_request_body_record,
    )
    git_binding: Optional[Dict[str, Any]] = None
    capsule_value: Optional[Dict[str, Any]] = None
    capsule_snapshot_value: Optional[Dict[str, Any]] = None
    if executor_family == "git-child":
        git_binding = _parse_network_git_argv(operation, normalized)
        expected_capsule_profile = {
            "git-ls-remote": "ls-remote-read",
            "git-fetch-empty": "fetch-quarantine",
            "git-fetch-known": "fetch-quarantine",
            "git-push": "push-outbound",
        }.get(parser_family)
        if expected_capsule_profile is None:
            raise AuditError("network Git execution capsule profile drift")
        capsule_supplied = git_execution_capsule is not None
        snapshot_supplied = git_execution_capsule_snapshot is not None
        if not capsule_supplied or not snapshot_supplied:
            raise AuditError("network Git execution capsule is required")
        capsule_value = dict(
            _require_mapping(
                git_execution_capsule,
                "network Git execution capsule",
            )
        )
        capsule_snapshot_value = dict(
            _require_mapping(
                git_execution_capsule_snapshot,
                "network Git execution capsule snapshot",
            )
        )
        capsule_value = reopen_git_execution_capsule(
            root,
            capsule_value,
            capsule_snapshot_value,
            expected_profile=expected_capsule_profile,
            preflight=preflight,
        )
        if (
            parser_family == "git-push"
            and capsule_value.get("sourceOid")
            != git_binding.get("sourceOid")
        ):
            raise AuditError("network Git push capsule source drift")
        if parser_family in ("git-fetch-empty", "git-fetch-known"):
            _validate_network_git_fetch_binding(
                operation,
                normalized,
                preflight,
                manifest,
                quarantine_empty=quarantine_empty,
            )
    elif executor_family in ("github-pages", "github-job-log"):
        pass
    elif executor_family == "lfs-batch":
        if (
            not isinstance(lfs_request_objects, (list, tuple))
            or not isinstance(lfs_request_bytes, bytes)
        ):
            raise AuditError("LFS request/preflight manifest drift")
    else:
        raise AuditError("unknown network wrapper")
    use_key = _network_request_use_key(
        manifest["recordDigest"], selected_row["requestId"], 1
    )
    logical_key = use_key
    attempt_id = secrets.token_hex(16)
    request_parent: Optional[Dict[str, Any]] = None

    def reopen_request_parent(recovered: Mapping[str, Any]) -> Optional[Dict[str, Any]]:
        if request_seal_record_path is None:
            return None
        parents = _reopen_parent_capture_records(root, recovered, [request_seal_record_path])
        if len(parents) != 1:
            raise AuditError("network request seal parent is absent")
        expected_parent = (
            manifest
            if request_parent_payload is None
            else _require_mapping(
                request_parent_payload, "network request parent payload"
            )
        )
        _sealed_capture_contains_record(recovered, parents[0], expected_parent)
        return parents[0]

    recovered_terminal = recover_or_reopen_network_logical_key_no_network(
        root, logical_key
    )
    if recovered_terminal is not None:
        if executor_family == "git-child":
            assert capsule_value is not None
            assert capsule_snapshot_value is not None
            recovered_reentry = recover_run_state(root)
            matches = [
                value
                for value in recovered_reentry.get("networkAttempts", [])
                if value.get("logicalKey") == logical_key
            ]
            attempt_reentry = (
                matches[0].get("attempt") if len(matches) == 1 else None
            )
            if (
                recovered_reentry.get("classification") != "complete"
                or not isinstance(attempt_reentry, Mapping)
                or attempt_reentry.get("capsuleProfile")
                != capsule_value.get("profile")
                or attempt_reentry.get("capsuleResourceId")
                != capsule_value.get("resourceId")
                or attempt_reentry.get("capsuleRecordDigest")
                != capsule_value.get("recordDigest")
                or attempt_reentry.get("capsuleSnapshotDigest")
                != capsule_snapshot_value.get("snapshotDigest")
                or attempt_reentry.get("capsuleSnapshotRecordDigest")
                != capsule_snapshot_value.get("recordDigest")
                or recovered_terminal.get("attemptRecordDigest")
                != attempt_reentry.get("recordDigest")
            ):
                raise AuditError(
                    "network Git terminal reentry capsule binding drift"
                )
        return recovered_terminal
    if credential_kind == "git" and type(
        credential_broker
    ) is not OneShotCredentialBroker:
        raise AuditError("network Git credential broker is required")
    if credential_kind == "git":
        credential_broker.assert_credential_binding(root, preflight)
    initial_recovery = recover_run_state(root)
    if initial_recovery["classification"] != "complete":
        raise AuditError("ledger is indeterminate")
    request_parent = reopen_request_parent(initial_recovery)
    initial_frontiers = [
        row for row in initial_recovery["openFrontiers"]
        if row.get("frontierId") == frontier_id
    ]
    if len(initial_frontiers) != 1:
        raise AuditError("network wrapper frontier is absent")
    bound_resource_id = (
        initial_frontiers[0].get("resourceId")
        if initial_frontiers[0].get("frontierKind") == "local-resource"
        else None
    )
    if capsule_value is not None:
        capsule_resource_id = capsule_value["resourceId"]
        if (
            parser_family in ("git-fetch-empty", "git-fetch-known")
            and bound_resource_id != capsule_resource_id
        ):
            raise AuditError(
                "network Git fetch frontier/capsule resource drift"
            )
        bound_resource_id = (
            capsule_resource_id
            if parser_family in ("git-fetch-empty", "git-fetch-known")
            else None
        )

    # Direct callers acquire the retained execution owner only after every
    # static ledger/capsule/frontier check has succeeded.  Command callers may
    # pass an earlier reservation so dynamic preflight remains fail-closed;
    # their enclosing reserved-step authority owns any earlier cleanup.
    if execution_reservation is None:
        reservation = reserve_network_execution_no_live_work(
            root,
            frontier_id,
            wrapper=wrapper,
            operation=operation,
            argv=normalized,
            preflight=preflight,
            manifest=manifest,
            request_body_record=gh_request_body_record,
        )
    else:
        reservation = reopen_network_execution_reservation_no_live_work(
            root,
            execution_reservation,
            wrapper=wrapper,
            frontier_id=frontier_id,
            operation=operation,
            argv=normalized,
            preflight=preflight,
            manifest=manifest,
            request_body_record=gh_request_body_record,
        )

    def validate_attempt(recovered: Mapping[str, Any]) -> None:
        matches = [row for row in recovered["openFrontiers"] if row.get("frontierId") == frontier_id]
        if len(matches) != 1 or matches[0].get("frontierKind") not in (
            "remote-mutation", "local-resource"
        ):
            raise AuditError("network wrapper frontier is absent or wrong kind")
        if any(row.get("logicalKey") == logical_key for row in recovered.get("networkAttempts", [])):
            raise AuditError("network request replay")
        selected_reservation = _selected_network_reservation(
            recovered, use_key
        )
        if (
            selected_reservation is None
            or selected_reservation.get("state") != "reserved"
            or selected_reservation.get("reservation") != reservation
        ):
            raise AuditError("network execution reservation is unavailable")
        if capsule_value is not None:
            assert capsule_snapshot_value is not None
            resource = recovered.get("resources", {}).get(
                capsule_value["resourceId"]
            )
            snapshots = (
                resource.get("snapshots", [])
                if isinstance(resource, Mapping) else []
            )
            latest = snapshots[-1] if snapshots else None
            if (
                not isinstance(resource, Mapping)
                or resource.get("consumption") is not None
                or resource.get("taint") is not None
                or not isinstance(latest, Mapping)
                or latest.get("snapshotDigest")
                != capsule_snapshot_value["snapshotDigest"]
                or latest.get("recordDigest")
                != capsule_snapshot_value["recordDigest"]
                or any(
                    projected.get("attempt", {}).get(
                        "capsuleResourceId"
                    ) == capsule_value["resourceId"]
                    for projected in recovered.get("networkAttempts", [])
                )
            ):
                raise AuditError(
                    "network Git capsule is unavailable or already used"
                )
        reopened_parent = reopen_request_parent(recovered)
        if reopened_parent != request_parent:
            raise AuditError("network request seal parent drift")

    def validate_terminal(
        recovered: Mapping[str, Any], allowed_states: Sequence[str]
    ) -> None:
        matches = [
            row for row in recovered.get("networkAttempts", [])
            if row.get("attemptId") == attempt_id
            and row.get("logicalKey") == logical_key
        ]
        if len(matches) != 1 or matches[0].get("state") not in allowed_states:
            raise AuditError("network terminal predecessor drift")
        if isinstance(matches[0].get("terminal"), Mapping):
            raise AuditError("network terminal already exists")

    attempt_payload: Dict[str, Any] = {
        "attemptId": attempt_id,
        "logicalKey": logical_key,
        "frontierId": frontier_id,
        "wrapper": wrapper,
        "operation": operation,
        "argvDigest": _sha256(canonical_json_bytes(normalized)),
        "preflightRecordDigest": preflight["recordDigest"],
        "stableProjectionDigest": preflight["stableProjectionDigest"],
        "manifestRecordDigest": manifest["recordDigest"],
        "manifestSchemaVersion": manifest["schemaVersion"],
        "requestId": selected_row["requestId"],
        "requestSequence": selected_row["sequence"],
        "rowDigest": selected_row["rowDigest"],
        "maximumUses": selected_row["maximumUses"],
        "useKey": use_key,
        "reservationRecordDigest": reservation["recordDigest"],
        "requestSealRecordPath": (
            None if request_parent is None else request_parent["recordPath"]
        ),
        "requestSealRecordDigest": (
            None if request_parent is None else request_parent["recordDigest"]
        ),
        "requestCaptureId": (
            None if request_parent is None else request_parent["captureId"]
        ),
    }
    if capsule_value is not None:
        assert capsule_snapshot_value is not None
        attempt_payload.update(
            {
                "capsuleProfile": capsule_value["profile"],
                "capsuleResourceId": capsule_value["resourceId"],
                "capsuleRecordDigest": capsule_value["recordDigest"],
                "capsuleSnapshotDigest": capsule_snapshot_value[
                    "snapshotDigest"
                ],
                "capsuleSnapshotRecordDigest": capsule_snapshot_value[
                    "recordDigest"
                ],
            }
        )
    mint_permit_sink: List[Any] = []
    if (
        type(_network_recovery_permit_sink) is not list
        or _network_recovery_permit_sink
    ):
        raise AuditError("network recovery permit sink drift")
    recovery_permit_sink = _network_recovery_permit_sink
    attempt: Optional[Dict[str, Any]] = None
    observation: Optional[Dict[str, Any]] = None
    lfs_cleanup_context = None
    # Append, arming, caller publication and transport share one recovery
    # region: no durable attempt-live transition can escape through a try gap.
    try:
        if executor_family == "git-child":
            attempt = _append_network_git_attempt_and_mint(
                root,
                manifest["recordDigest"],
                attempt_payload,
                reservation=reservation,
                state_validator=validate_attempt,
                permit_sink=mint_permit_sink,
                recovery_scope=_network_recovery_scope,
                recovery_permit_sink=recovery_permit_sink,
                _faults=faults,
            )
        else:
            attempt = _append_record(
                root,
                "network-attempt",
                manifest["recordDigest"],
                [],
                "attempted",
                attempt_payload,
                state_validator=validate_attempt,
                _faults=faults,
            )
            _mint_network_attempt_recovery_permit(
                _network_recovery_scope,
                recovery_permit_sink,
                root,
                attempt,
                reservation,
            )
        capsule_consumption: Optional[Dict[str, Any]] = None
        if capsule_value is not None:
            assert capsule_snapshot_value is not None
            # The wrapper, rather than a concrete transport adapter, owns the
            # irreversible pre-child boundary.  This keeps injected, test,
            # and production transports under the same durable order:
            # attempt -> capsule consumption -> external child.
            capsule_consumption = consume_git_execution_capsule(
                root,
                capsule_value,
                capsule_snapshot_value,
                expected_profile=capsule_value["profile"],
                preflight=preflight,
            )
        if not hasattr(transport, "execute"):
            raise AuditError("network transport adapter lacks execute")
        transport_request: Dict[str, Any] = {
            "wrapper": wrapper,
            "operation": operation,
            "argv": list(normalized),
            "environment": dict(_NETWORK_CHILD_ENVIRONMENT),
            "credentialBroker": credential_broker,
            "preflight": dict(preflight),
            "manifest": dict(manifest),
        }
        git_child_grant: Any = None
        if capsule_value is not None:
            assert capsule_snapshot_value is not None
            assert capsule_consumption is not None
            transport_request.update(
                {
                    "gitExecutionCapsule": dict(capsule_value),
                    "gitExecutionCapsuleSnapshot": dict(
                        capsule_snapshot_value
                    ),
                    # Durable evidence is carried for transport-level audit,
                    # but it is never accepted as live child authority.
                    "gitExecutionCapsuleConsumption": dict(
                        capsule_consumption
                    ),
                }
            )
        if credential_broker is not None:
            transport_request.update(
                {
                    "credentialReadFd": credential_broker.read_fd,
                    "brokerArgv": credential_broker.broker_argv(),
                }
            )
        if executor_family == "lfs-batch":
            transport_request["requestBytes"] = lfs_request_bytes
        initial_git_child_grants = (
            _current_thread_git_child_execution_grants()
        )
        transport_primary: Optional[BaseException] = None
        result: Any = None
        try:
            if executor_family == "git-child":
                assert capsule_value is not None
                assert capsule_snapshot_value is not None
                assert capsule_consumption is not None
                assert credential_broker is not None
                if len(mint_permit_sink) != 1:
                    raise AuditError("network Git mint permit is unavailable")
                git_child_grant = _issue_git_child_execution_grant(
                    root,
                    mint_permit=mint_permit_sink[0],
                    attempt=attempt,
                    consumption=capsule_consumption,
                    operation=operation,
                    argv=normalized,
                    preflight=preflight,
                    manifest=manifest,
                    capsule=capsule_value,
                    snapshot=capsule_snapshot_value,
                    broker=credential_broker,
                )
                transport_request["gitExecutionGrant"] = (
                    git_child_grant
                )
            if type(transport) is _NetworkLfsDirectTransport:
                lfs_cleanup_context = _capture_cleanup_diagnostic_context(root, "lfs-network-attempt",
                    _network_execution_guard(root, reservation), attempt)
                transport_request["cleanupDiagnosticContext"] = lfs_cleanup_context
            result = transport.execute(**transport_request)
        except BaseException as primary:
            transport_primary = primary
            raise
        finally:
            try:
                _revoke_git_child_execution_grants_since(
                    initial_git_child_grants
                )
            except BaseException as cleanup:
                if transport_primary is not None:
                    _retain_git_cleanup_error(transport_primary, cleanup)
                else:
                    if isinstance(result, Mapping):
                        _release_owned_git_streams(
                            (result.get("stdoutOwner"), result.get("stderrOwner")), cleanup
                        )
                    raise
        result = _require_mapping(result, "network transport result")
        if executor_family == "git-child":
            owned_streams = set(result) == {
                "status", "stdoutOwner", "stderrOwner"
            }
            injected_chunks = set(result) == {
                "status", "stdoutChunks", "stderrChunks"
            }
            if not owned_streams and not injected_chunks:
                raise AuditError("network Git transport result shape drift")
            stdout_owner = result.get("stdoutOwner")
            stderr_owner = result.get("stderrOwner")
            typed_result: Optional[Dict[str, Any]] = None
            stream_primary: Optional[BaseException] = None
            try:
                if owned_streams and (
                    not isinstance(stdout_owner, OwnedSecretBuffer)
                    or not isinstance(stderr_owner, OwnedSecretBuffer)
                ):
                    raise AuditError("network Git stream owner drift")
                status = result.get("status")
                if (
                    not isinstance(status, int)
                    or isinstance(status, bool)
                    or status != 0
                ):
                    raise AuditError(
                        "network Git child did not complete successfully"
                    )
                broker_projection = credential_broker.projection()
                if (
                    broker_projection.get("consumed") is not True
                    or broker_projection.get("consumptionCount") != 1
                ):
                    raise AuditError(
                        "network Git credential broker was not consumed exactly once"
                    )
                if owned_streams:
                    if git_binding is None:
                        raise AuditError("network Git argv binding is absent")
                    typed_result = _parse_network_git_result(
                        git_binding,
                        status,
                        stdout_owner.view(),
                        stderr_owner.view(),
                    )
                    stdout_digest, stderr_digest, captured = (
                        _capture_owned_git_transport_streams(
                            stdout_owner, stderr_owner
                        )
                    )
                else:
                    stdout_backing = bytearray()
                    stderr_backing = bytearray()
                    try:
                        stdout_backing = _collect_network_git_chunks(
                            result["stdoutChunks"], "stdout"
                        )
                        stderr_backing = _collect_network_git_chunks(
                            result["stderrChunks"], "stderr"
                        )
                        if git_binding is None:
                            raise AuditError("network Git argv binding is absent")
                        typed_result = _parse_network_git_result(
                            git_binding,
                            status,
                            memoryview(stdout_backing),
                            memoryview(stderr_backing),
                        )
                        stdout_digest, stderr_digest, captured = (
                            _capture_git_transport_streams(
                                (memoryview(stdout_backing),),
                                (memoryview(stderr_backing),),
                            )
                        )
                    finally:
                        for backing in (stdout_backing, stderr_backing):
                            for index in range(len(backing)):
                                backing[index] = 0
            except BaseException as primary:
                stream_primary = primary
                raise
            finally:
                _release_owned_git_streams((stdout_owner, stderr_owner), stream_primary)
            observation = _self_digest_record(
                {
                    "schemaVersion": "qinao.network-git-observation.v1",
                    "operation": operation,
                    "exitCode": status,
                    "stdoutSha256": stdout_digest,
                    "stderrSha256": stderr_digest,
                    "safeCaptureDigest": captured["recordDigest"],
                    "typedResult": typed_result,
                    "typedResultDigest": typed_result["recordDigest"],
                    "credentialGenerationDigest": broker_projection[
                        "generationDigest"
                    ],
                    "credentialBrokerProjectionDigest": _digest_projection(
                        broker_projection
                    ),
                }
            )
        elif executor_family in ("github-pages", "github-job-log"):
            if set(result) == {"observation"}:
                observation = dict(
                    _require_mapping(
                        result["observation"],
                        "network GitHub direct observation",
                    )
                )
                _verify_self_digest(observation)
                if (
                    observation.get("schemaVersion")
                    != "qinao.network-gh-observation.v1"
                    or observation.get("operation") != operation
                    or observation.get("preflightRecordDigest")
                    != preflight["recordDigest"]
                    or observation.get("manifestRecordDigest")
                    != manifest["recordDigest"]
                    or observation.get("redirectCount")
                    != (1 if executor_family == "github-job-log" else 0)
                ):
                    raise AuditError("network GitHub direct observation drift")
            elif set(result) == {"status", "headers", "bodyChunks"}:
                observation = validate_network_gh_response(
                    operation,
                    normalized,
                    preflight,
                    manifest,
                    result["status"],
                    result["headers"],
                    result["bodyChunks"],
                )
            else:
                raise AuditError("network GitHub transport result shape drift")
        else:
            if set(result) != {"status", "contentType", "bodyChunks"}:
                raise AuditError("LFS Batch transport result shape drift")
            response_bytes = _read_bounded_chunks(
                result["bodyChunks"], maximum=16 * 1024 * 1024,
                label="LFS Batch response",
            )
            safe_capture([response_bytes], profile="lfs-batch")
            parsed = parse_lfs_batch_response(
                lfs_request_objects,
                result["status"],
                result["contentType"],
                response_bytes,
            )
            broker_projection = credential_broker.projection()
            if (
                broker_projection.get("consumed") is not True
                or broker_projection.get("consumptionCount") != 1
            ):
                raise AuditError("LFS credential broker was not consumed exactly once")
            observation = dict(parsed)
            observation.pop("recordDigest")
            observation.update(
                {
                    "requestByteCount": len(lfs_request_bytes),
                    "requestSha256": _sha256(lfs_request_bytes),
                    "preflightRecordDigest": preflight["recordDigest"],
                    "manifestRecordDigest": manifest["recordDigest"],
                    "credentialHelperIdentityDigest": preflight[
                        "gitCredentialIdentityDigest"
                    ],
                    "credentialGenerationDigest": preflight[
                        "gitCredentialGenerationDigest"
                    ],
                    "credentialBrokerProjectionDigest": _digest_projection(
                        broker_projection
                    ),
                }
            )
            if lfs_approved_manifest is not None:
                approved = validate_lfs_approved_manifest(
                    lfs_approved_manifest
                )
                observation.update(
                    {
                        "approvedManifestRecordDigest": approved[
                            "recordDigest"
                        ],
                        "sourceReviewDigest": approved[
                            "sourceReviewDigest"
                        ],
                        "sourceReviewSealRecordPath": approved[
                            "sourceReviewSealRecordPath"
                        ],
                        "sourceReviewCaptureId": approved[
                            "sourceReviewCaptureId"
                        ],
                        "sourceReviewRecordDigest": approved[
                            "sourceReviewRecordDigest"
                        ],
                        "candidateIdentityDigest": approved[
                            "candidateIdentityDigest"
                        ],
                        "objectSetDigest": approved["objectSetDigest"],
                    }
                )
            observation = _self_digest_record(observation)
        if (
            capsule_value is not None
            and parser_family not in ("git-fetch-empty", "git-fetch-known")
        ):
            assert capsule_snapshot_value is not None
            try:
                reopen_git_execution_capsule(
                    root,
                    capsule_value,
                    capsule_snapshot_value,
                    expected_profile=capsule_value["profile"],
                    preflight=preflight,
                )
            except BaseException:
                mark_git_execution_capsule_tainted(
                    root,
                    capsule_value,
                    capsule_snapshot_value,
                    reason_code="post-child-resource-drift",
                )
                raise
        observation_record = _append_record(
            root,
            "network-observation",
            observation["recordDigest"],
            [],
            "observed",
            {
                "attemptId": attempt_id,
                "attemptRecordDigest": attempt["recordDigest"],
                "logicalKey": logical_key,
                "observation": observation,
            },
            allow_resource_drift_id=bound_resource_id,
            _faults=faults,
        )
        terminal = _append_record(
            root,
            "network-terminal",
            observation_record["recordDigest"],
            [],
            "completed",
            {
                "attemptId": attempt_id,
                "attemptRecordDigest": attempt["recordDigest"],
                "observationRecordDigest": observation_record["recordDigest"],
                "logicalKey": logical_key,
                "outcome": "completed",
            },
            allow_resource_drift_id=bound_resource_id,
            state_validator=lambda recovered: validate_terminal(
                recovered, ("observed",)
            ),
            _faults=faults,
        )
        _network_execution_guard(
            root, reservation
        ).mark_terminal(reservation, terminal)
        faults.hit(
            "before-terminal-return", "network-terminal", logical_key
        )
        return terminal
    except BaseException as primary:
        # The transport path and cold-start path share one recovery authority.
        # It raw-scans the durable attempt before projection, admits drift only
        # for that attempt's exact capsule, burns/taints it in ledger order, and
        # never replays transport.  If an observation or terminal was already
        # durable when a return-path fault fired, its completed result wins.
        if mint_permit_sink:
            try:
                _revoke_git_child_execution_mint_permit(
                    mint_permit_sink[0]
                )
            except BaseException as cleanup:
                _retain_git_cleanup_error(primary, cleanup)
        if attempt is not None and len(recovery_permit_sink) == 1:
            try:
                recovered_terminal = _recover_live_network_attempt_no_network(
                    root,
                    logical_key,
                    recovery_permit=recovery_permit_sink[0],
                    recovery_scope=_network_recovery_scope,
                    attempt=attempt,
                    reservation=reservation,
                )
                if recovered_terminal.get("completionState") == "completed":
                    return recovered_terminal
            except BaseException as recovery_error:
                _retain_git_cleanup_error(primary, recovery_error)
        # Unpublished arming owners are rediscovered by scope. If append
        # itself never returned, a still-reserved guard can close safely and
        # durable history remains the sole no-replay authority for cold entry.
        if lfs_cleanup_context is not None:
            with _CLEANUP_DIAGNOSTIC_LOCK:
                pending = _CLEANUP_DIAGNOSTIC_CONTEXTS.get(id(lfs_cleanup_context))
            if pending is not None and pending["payload"] is None:
                try:
                    _drop_cleanup_diagnostic_context(lfs_cleanup_context)
                except BaseException as cleanup:
                    _retain_git_cleanup_error(primary, cleanup)
        raise


def _validate_network_git_fetch_binding(
    operation: str,
    argv: Sequence[str],
    preflight: Mapping[str, Any],
    manifest: Mapping[str, Any],
    *,
    quarantine_empty: bool,
    _tool_mode: str = "current",
) -> Dict[str, Any]:
    specification = _network_operation_contract(operation)
    parser_family = specification["parserFamily"]
    binding = _parse_network_git_argv(operation, argv)
    normalized = binding["argv"]
    selected_row = _select_network_request_row(
        manifest, operation, normalized, preflight, _tool_mode=_tool_mode,
    )
    if not isinstance(quarantine_empty, bool):
        raise AuditError("quarantine state type drift")
    if (
        specification["wrapper"] != "network-git"
        or parser_family not in ("git-fetch-empty", "git-fetch-known")
        or normalized[0] != "fetch"
    ):
        raise AuditError("invocation is not a closed fetch operation")
    if parser_family == "git-fetch-empty":
        if not quarantine_empty:
            raise AuditError("fetch-empty requires a proved empty quarantine")
        if binding["negotiationTips"]:
            raise AuditError("empty quarantine cannot disclose a negotiation tip")
    else:
        if quarantine_empty:
            raise AuditError("fetch-known requires a nonempty quarantine")
        if len(binding["negotiationTips"]) != 1:
            raise AuditError("nonempty quarantine fetch lacks a proved negotiation tip")
    return _self_digest_record(
        {
            "schemaVersion": "qinao.network-git-validation.v1",
            "operation": operation,
            "argvDigest": _sha256(canonical_json_bytes(normalized)),
            "preflightRecordDigest": preflight["recordDigest"],
            "manifestRecordDigest": manifest["recordDigest"],
            "requestId": selected_row["requestId"],
            "networkAttempted": False,
        }
    )


