# Frozen low-level references: target code cannot redirect these names through
# ordinary monkey-patching. This remains a cooperative same-process boundary.
_FD_PIPE, _FD_DUP, _FD_DUP2 = os.pipe, os.dup, os.dup2
_FD_CLOSE, _FD_READ, _FD_WRITE = os.close, os.read, os.write
_FD_FSTAT = os.fstat
_FD_GET_INHERITABLE, _FD_SET_INHERITABLE = (
    os.get_inheritable, os.set_inheritable
)
_FD_SET_BLOCKING = os.set_blocking
_FD_THREAD, _FD_EVENT, _FD_LOCK = (
    threading.Thread, threading.Event, threading.Lock
)
_FD_SHA256, _FD_MONOTONIC, _FD_SLEEP = (
    hashlib.sha256, time.monotonic, time.sleep
)
_FD_SET_SYS_SLOT = setattr


@dataclass(frozen=True)
class _StrictFDOwnershipToken:
    generation: int
    role: str
    channel: int
    fd: int


class _StrictFDFatalQuarantine(BaseException):
    pass


class _StrictProcessFDBinaryProxy:
    __slots__ = ("_owner", "_fd")

    def __init__(self, owner: "_StrictProcessFDCapture", fd: int) -> None:
        self._owner, self._fd = owner, fd

    def write(self, payload: Any) -> int:
        if isinstance(payload, str):
            self._owner._fail("proxy-binary-type")
            raise TypeError("binary fd capture requires bytes-like data")
        try:
            view = memoryview(payload).cast("B")
        except (TypeError, ValueError):
            self._owner._fail("proxy-binary-type")
            raise
        offset = 0
        while offset < len(view):
            try:
                count = _FD_WRITE(self._fd, view[offset:])
            except InterruptedError:
                continue
            if count <= 0:
                self._owner._fail("proxy-write-failed")
                raise OSError("fd capture write made no progress")
            offset += count
        return len(view)

    def flush(self) -> None:
        return None

    def fileno(self) -> int:
        return self._fd

    def isatty(self) -> bool:
        return False

    def close(self) -> None:
        self._owner._fail("proxy-close")
        raise io.UnsupportedOperation("fd capture proxy cannot close")

    def detach(self) -> Any:
        self._owner._fail("proxy-detach")
        raise io.UnsupportedOperation("fd capture proxy cannot detach")


class _StrictProcessFDTextProxy:
    __slots__ = ("_owner", "_fd", "_buffer")
    encoding, errors = "utf-8", "surrogatepass"

    def __init__(self, owner: "_StrictProcessFDCapture", fd: int) -> None:
        self._owner, self._fd = owner, fd
        self._buffer = _StrictProcessFDBinaryProxy(owner, fd)

    @property
    def buffer(self) -> _StrictProcessFDBinaryProxy:
        return self._buffer

    def write(self, value: Any) -> int:
        if not isinstance(value, str):
            self._owner._fail("proxy-text-type")
            raise TypeError("text fd capture requires str")
        self._buffer.write(value.encode("utf-8", "surrogatepass"))
        return len(value)

    def writelines(self, values: Any) -> None:
        for value in values:
            self.write(value)

    def flush(self) -> None:
        return None

    def fileno(self) -> int:
        return self._fd

    def isatty(self) -> bool:
        return False

    def close(self) -> None:
        self._owner._fail("proxy-close")
        raise io.UnsupportedOperation("fd capture proxy cannot close")

    def detach(self) -> Any:
        self._owner._fail("proxy-detach")
        raise io.UnsupportedOperation("fd capture proxy cannot detach")


