def _read_record(path: str) -> Dict[str, Any]:
    value = _read_canonical_file(Path(path).resolve())
    if not isinstance(value, dict):
        raise AuditError("canonical record must be an object")
    return value


def _persist_result(output: str, record: Mapping[str, Any]) -> int:
    write_canonical_exclusive(Path(output), dict(record))
    return _emit_canonical(record)


def _outside_protected_worktree(path: Path) -> Path:
    candidate = Path(path).resolve()
    protected = Path(PROTECTED_WITNESS["worktree"]).resolve()
    if candidate == protected or protected in candidate.parents:
        raise AuditError("output path is inside the protected worktree")
    return candidate


def _verify_topology_record(record: Mapping[str, Any]) -> Dict[str, Any]:
    record = _require_mapping(record, "topology record")
    required = {
        "schemaVersion", "sourceTip", "designBase", "designTip", "D",
        "C", "H", "orderedCParents", "designContainsS",
        "designContainsTip", "headContainsC", "recordDigest",
    }
    if set(record) != required or record.get("schemaVersion") != "qinao.convergence-topology.v1":
        raise AuditError("topology record field drift")
    _verify_self_digest(record)
    widths = set()
    for field in ("sourceTip", "designBase", "designTip", "D", "C", "H"):
        value = record.get(field)
        if not isinstance(value, str) or re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", value) is None:
            raise AuditError("topology record object ID drift")
        widths.add(len(value))
    if len(widths) != 1:
        raise AuditError("topology record object format drift")
    if record.get("orderedCParents") != [record["sourceTip"], record["D"]]:
        raise AuditError("topology record ordered-parent drift")
    if any(
        record.get(field) is not True
        for field in ("designContainsS", "designContainsTip", "headContainsC")
    ):
        raise AuditError("topology record containment drift")
    return dict(record)


def _command_topology(argv: Sequence[str]) -> int:
    parser = argparse.ArgumentParser(prog="topology")
    parser.add_argument("--root", required=True)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--capture-id")
    mode.add_argument("--verify")
    parser.add_argument("--repository")
    parser.add_argument("--S")
    parser.add_argument("--design-base")
    parser.add_argument("--design-tip")
    parser.add_argument("--D")
    parser.add_argument("--C")
    parser.add_argument("--H")
    parser.add_argument("--require-seal-record")
    parser.add_argument("--print-field")
    options = parser.parse_args(list(argv))
    root = Path(options.root).resolve()
    if options.verify is not None:
        if any(
            value is not None
            for value in (
                options.repository, options.S, options.design_base,
                options.design_tip, options.D, options.C, options.H,
            )
        ):
            raise AuditError("topology verify/create argument drift")
        if options.require_seal_record is None or options.print_field is None:
            raise AuditError("topology verify selector is incomplete")
        selection = reopen_generic_seal(root, options.require_seal_record)
        expected = _outside_protected_worktree(
            Path(selection["absolutePath"]) / "topology.json"
        )
        if Path(options.verify).resolve() != expected:
            raise AuditError("topology verification lineage drift")
        record = reopen_sealed_named_record(
            root,
            options.require_seal_record,
            "topology.json",
            expected_phase="topology",
        )
        try:
            record = _verify_topology_record(record)
        except AuditError as exc:
            raise VerificationFailure(str(exc)) from exc
        if options.print_field not in {
            "recordDigest", "sourceTip", "designBase", "designTip", "D", "C", "H"
        }:
            raise AuditError("topology print field drift")
        return _emit_named_scalar(record, options.print_field)
    if (
        options.repository is None
        or options.require_seal_record is not None
        or options.print_field is not None
    ):
        raise AuditError("topology create selector is incomplete")
    output = _outside_protected_worktree(
        _capture_output_path(
            root,
            options.capture_id,
            "topology.json",
            expected_phase="topology",
        )
    )
    repository = Path(options.repository).resolve()
    _ordinary_directory(repository)
    H = options.H or _ascii_git_line(repository, ["rev-parse", "HEAD"], "topology HEAD")
    try:
        record = verify_convergence_topology(
            repository,
            {
                "sourceTip": options.S or FROZEN_S,
                "designBase": options.design_base or FROZEN_DESIGN_BASE,
                "designTip": options.design_tip or "5c87355d5870b8559cadbe3105adbbb86f2008e7",
                "D": options.D or FROZEN_D,
                "C": options.C or FROZEN_C,
                "H": H,
            },
        )
    except (LocalGitInvocationFailure, ObservationIncomplete):
        raise
    except AuditError as exc:
        raise VerificationFailure(str(exc)) from exc
    write_canonical_exclusive(output, record)
    return _emit_canonical(record)


def _verify_protected_record(record: Mapping[str, Any]) -> Dict[str, Any]:
    required = {"schemaVersion", "repository", "snapshot", "witnessDigest", "recordDigest"}
    if set(record) != required or record.get("schemaVersion") != "qinao.protected-snapshot.v1":
        raise AuditError("protected record field drift")
    _verify_self_digest(record)
    expected = _protected_expected(PROTECTED_WITNESS)
    verify_protected_projection(expected, _require_mapping(record.get("snapshot"), "protected snapshot"))
    if record.get("repository") != PROTECTED_WITNESS["worktree"]:
        raise AuditError("protected record worktree drift")
    if record.get("witnessDigest") != _sha256(canonical_json_bytes(PROTECTED_WITNESS)):
        raise AuditError("protected record witness digest drift")
    return dict(record)


def _command_protected(argv: Sequence[str]) -> int:
    parser = argparse.ArgumentParser(prog="protected")
    parser.add_argument("--root", required=True)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--capture-id")
    mode.add_argument("--verify")
    parser.add_argument("--repository")
    parser.add_argument("--require-seal-record")
    parser.add_argument("--print-field")
    options = parser.parse_args(list(argv))
    root = Path(options.root).resolve()
    if options.verify is not None:
        if options.repository is not None:
            raise AuditError("protected verify/create argument drift")
        if options.require_seal_record is None or options.print_field is None:
            raise AuditError("protected verify selector is incomplete")
        selection = reopen_generic_seal(root, options.require_seal_record)
        expected_path = _outside_protected_worktree(
            Path(selection["absolutePath"]) / "protected.json"
        )
        if Path(options.verify).resolve() != expected_path:
            raise AuditError("protected verification lineage drift")
        persisted = reopen_sealed_named_record(
            root,
            options.require_seal_record,
            "protected.json",
            expected_phase="protected",
        )
        try:
            record = _verify_protected_record(persisted)
        except AuditError as exc:
            raise VerificationFailure(str(exc)) from exc
        if options.print_field in ("recordDigest", "witnessDigest", "repository"):
            value = record[options.print_field]
        elif options.print_field in {field.name for field in fields(ProtectedSnapshot)}:
            value = record["snapshot"][options.print_field]
        else:
            raise AuditError("unknown protected scalar field")
        if not isinstance(value, (str, int)) or isinstance(value, bool):
            raise AuditError("protected selected field is not scalar")
        sys.stdout.write(str(value) + "\n")
        return 0
    if options.require_seal_record is not None or options.print_field is not None:
        raise AuditError("protected create selector is incomplete")
    output = _outside_protected_worktree(
        _capture_output_path(
            root,
            options.capture_id,
            "protected.json",
            expected_phase="protected",
        )
    )
    repository = Path(
        options.repository or PROTECTED_WITNESS["worktree"]
    ).resolve()
    try:
        record = verify_protected_snapshot(repository, PROTECTED_WITNESS)
    except LocalGitInvocationFailure:
        raise
    except AuditError as exc:
        raise VerificationFailure(str(exc)) from exc
    write_canonical_exclusive(output, record)
    return _emit_canonical(record)


