def _verify_inventory_record(record: Mapping[str, Any]) -> Dict[str, Any]:
    required = {
        "schemaVersion", "revision", "entryCount", "entries", "inventoryDigest", "recordDigest",
    }
    if set(record) != required or record.get("schemaVersion") != "qinao.plan-spec-inventory.v1":
        raise AuditError("plan/spec inventory record field drift")
    _verify_self_digest(record)
    revision = record.get("revision")
    if not isinstance(revision, str) or re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", revision) is None:
        raise AuditError("plan/spec inventory record revision drift")
    entries = record.get("entries")
    if not isinstance(entries, list) or record.get("entryCount") != len(entries) or not entries:
        raise AuditError("plan/spec inventory record count drift")
    if record.get("inventoryDigest") != _sha256(canonical_json_bytes(entries)):
        raise AuditError("plan/spec inventory manifest digest drift")
    seen = set()
    for row in entries:
        row = _require_mapping(row, "plan/spec inventory row")
        if set(row) != {"path", "mode", "oid", "byteCount", "sha256"}:
            raise AuditError("plan/spec inventory row field drift")
        path = _document_path(row.get("path"))
        if path in seen or row.get("mode") != "100644":
            raise AuditError("duplicate or nonordinary plan/spec row")
        seen.add(path)
        if not isinstance(row.get("byteCount"), int) or row["byteCount"] < 0:
            raise AuditError("plan/spec inventory size drift")
        _require_lower_hex(row.get("sha256"), 64, "plan/spec content digest")
    return dict(record)


def _verify_three_way_record(record: Mapping[str, Any]) -> Dict[str, Any]:
    record = _require_mapping(record, "three-way plan/spec record")
    required = {
        "schemaVersion", "C", "mergeBase", "parent1", "parent2",
        "entryCount", "entries", "mapDigest", "recordDigest",
    }
    if set(record) != required or record.get("schemaVersion") != "qinao.plan-spec-three-way.v1":
        raise AuditError("three-way plan/spec record field drift")
    _verify_self_digest(record)
    for field in ("C", "mergeBase", "parent1", "parent2"):
        value = record.get(field)
        if not isinstance(value, str) or re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", value) is None:
            raise AuditError("three-way plan/spec revision drift")
    entries = record.get("entries")
    if (
        not isinstance(entries, list)
        or not entries
        or record.get("entryCount") != len(entries)
        or record.get("mapDigest") != _sha256(canonical_json_bytes(entries))
    ):
        raise AuditError("three-way plan/spec manifest drift")
    if [row.get("path") for row in entries if isinstance(row, Mapping)] != sorted(
        row.get("path") for row in entries if isinstance(row, Mapping)
    ):
        raise AuditError("three-way plan/spec path order drift")
    seen = set()
    for row in entries:
        row = _require_mapping(row, "three-way plan/spec row")
        if set(row) != {
            "path", "sourceObject", "mergeBaseObject",
            "parent1Object", "parent2Object",
        }:
            raise AuditError("three-way plan/spec row field drift")
        path = _document_path(row.get("path"))
        if path in seen:
            raise AuditError("duplicate three-way plan/spec path")
        seen.add(path)
        for name in (
            "sourceObject", "mergeBaseObject", "parent1Object", "parent2Object"
        ):
            descriptor = _require_mapping(row.get(name), "three-way object")
            if set(descriptor) != {"mode", "type", "oid"}:
                raise AuditError("three-way object field drift")
            values = tuple(descriptor.get(field) for field in ("mode", "type", "oid"))
            if values == (None, None, None):
                continue
            if (
                descriptor.get("mode") != "100644"
                or descriptor.get("type") != "blob"
                or not isinstance(descriptor.get("oid"), str)
                or re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", descriptor["oid"]) is None
            ):
                raise AuditError("three-way object descriptor drift")
    return dict(record)


def _verify_documents_capture_record(record: Mapping[str, Any]) -> Dict[str, Any]:
    record = _require_mapping(record, "documents capture")
    required = {
        "schemaVersion", "C", "mergeBase", "parent4a", "parentD",
        "inventory", "inventoryRecordDigest", "threeWay",
        "threeWayRecordDigest", "recordDigest",
    }
    if set(record) != required or record.get("schemaVersion") != "qinao.documents-capture.v1":
        raise AuditError("documents capture field drift")
    _verify_self_digest(record)
    inventory = _verify_inventory_record(
        _require_mapping(record.get("inventory"), "documents inventory")
    )
    three_way = _verify_three_way_record(
        _require_mapping(record.get("threeWay"), "documents three-way")
    )
    if (
        inventory.get("revision") != record.get("C")
        or record.get("inventoryRecordDigest") != inventory.get("recordDigest")
        or record.get("threeWayRecordDigest") != three_way.get("recordDigest")
        or three_way.get("C") != record.get("C")
        or three_way.get("mergeBase") != record.get("mergeBase")
        or three_way.get("parent1") != record.get("parent4a")
        or three_way.get("parent2") != record.get("parentD")
    ):
        raise AuditError("documents capture lineage drift")
    return dict(record)


def _command_documents_verify(argv: Sequence[str]) -> int:
    parser = argparse.ArgumentParser(prog="documents-verify")
    parser.add_argument("--repository", required=True)
    parser.add_argument("--capture", required=True)
    parser.add_argument("--dispositions", required=True)
    parser.add_argument("--pointers", required=True)
    parser.add_argument("--final-revision", required=True)
    parser.add_argument("--output", required=True)
    options = parser.parse_args(list(argv))
    capture = _verify_documents_capture_record(_read_record(options.capture))
    source_record = capture["inventory"]
    source = capture_plan_spec_inventory(Path(options.repository), capture["C"])
    if _inventory_record(source, capture["C"]) != source_record:
        raise AuditError("source plan/spec inventory cannot be reopened")
    contract = _read_record(options.dispositions)
    contract_verification = verify_document_disposition_contract(source, contract)
    pointers_record = _read_record(options.pointers)
    pointers = verify_document_pointer_record(pointers_record, contract)
    dispositions = {
        row["path"]: row["disposition"] for row in contract["entries"]
    }
    final_inventory = verify_final_plan_spec_inventory(
        Path(options.repository),
        source,
        options.final_revision,
        dispositions=dispositions,
        pointers=pointers,
    )
    result = _self_digest_record(
        {
            "schemaVersion": "qinao.documents-verification.v1",
            "C": capture["C"],
            "H": options.final_revision,
            "sourceCaptureDigest": capture["recordDigest"],
            "sourceInventoryDigest": source_record["recordDigest"],
            "dispositionVerificationDigest": contract_verification["recordDigest"],
            "pointerRecordDigest": pointers_record["recordDigest"],
            "pointerCount": len(pointers),
            "finalInventory": final_inventory,
            "finalInventoryDigest": final_inventory["recordDigest"],
        }
    )
    return _persist_result(options.output, result)


def _command_diff_inventory(argv: Sequence[str]) -> int:
    parser = argparse.ArgumentParser(prog="diff-inventory")
    parser.add_argument("--raw-diff", required=True)
    parser.add_argument("--object-format", choices=("sha1", "sha256"), required=True)
    parser.add_argument("--output", required=True)
    options = parser.parse_args(list(argv))
    raw = _read_ordinary(Path(options.raw_diff).resolve(), maximum=256 * 1024 * 1024)
    entries = parse_raw_diff_z(raw, options.object_format)
    rows = [_raw_entry_projection(entry) for entry in entries]
    record = _self_digest_record(
        {
            "schemaVersion": "qinao.raw-diff-manifest.v1",
            "objectFormat": options.object_format,
            "rawDiffSha256": _sha256(raw),
            "entryCount": len(rows),
            "entries": rows,
            "manifestDigest": _sha256(canonical_json_bytes(rows)),
        }
    )
    return _persist_result(options.output, record)


