def _command_ci_bind(argv: Sequence[str], binder: Any, program: str, context: CommandContext) -> int:
    parser = argparse.ArgumentParser(prog=program)
    parser.add_argument("--repository", required=True)
    parser.add_argument("--event-path", required=True)
    parser.add_argument("--output", required=True)
    options = parser.parse_args(list(argv))
    event_path = Path(options.event_path).resolve()
    event_bytes = _read_ordinary(event_path, maximum=16 * 1024 * 1024)
    journal = context.policy_capture
    if not isinstance(journal, _PolicyCaptureJournal):
        raise AuditError("CI binder lacks owned capture context")
    if journal.profile_context is not None and (
            journal.profile_context["eventPathSha256"] != _sha256(os.fsencode(str(event_path)))
            or journal.profile_context["eventBytesSha256"] != _sha256(event_bytes)):
        raise AuditError("CI binder event differs from prepared profile")
    event_value = _parse_json_response(event_bytes)
    event = dict(_require_mapping(event_value, "CI event"))
    observation = capture_ci_observation(
        Path(options.repository), event, program, context=context,
    )
    return _persist_result(options.output, binder(event, observation))


