def _command_secret_scan_objects(argv: Sequence[str]) -> int:
    parser = argparse.ArgumentParser(prog="secret-scan-objects")
    source = parser.add_mutually_exclusive_group(required=True)
    source.add_argument("--input")
    source.add_argument("--repository")
    parser.add_argument("--root", action="append", default=[])
    parser.add_argument("--output", required=True)
    options = parser.parse_args(list(argv))
    if options.repository is not None:
        if not options.root:
            raise AuditError("repository object scan requires exact roots")
        return _persist_result(
            options.output,
            secret_scan_repository_object_closure(
                Path(options.repository), options.root
            ),
        )
    if options.root:
        raise AuditError("object roots require repository closure mode")
    value = _read_record(options.input)
    if set(value) != {"schemaVersion", "fields"} or value.get("schemaVersion") != "qinao.secret-scan-object-input.v1":
        raise AuditError("secret-scan object input schema drift")
    rows = value.get("fields")
    if not isinstance(rows, list) or not rows:
        raise AuditError("secret-scan object input is empty")
    objects: Dict[str, bytes] = {}
    for row in rows:
        row = _require_mapping(row, "secret-scan object input row")
        if set(row) != {"fieldId", "bytesB64"}:
            raise AuditError("secret-scan object row field drift")
        field_id = row.get("fieldId")
        encoded = row.get("bytesB64")
        if not isinstance(field_id, str) or field_id in objects or not isinstance(encoded, str):
            raise AuditError("secret-scan object row identity drift")
        try:
            objects[field_id] = base64.b64decode(encoded, validate=True)
        except (ValueError, binascii.Error) as exc:
            raise AuditError("secret-scan object base64 drift") from exc
    return _persist_result(options.output, secret_scan_objects(objects))


def _command_network_egress_preflight(
    argv: Sequence[str], context: CommandContext
) -> int:
    parser = argparse.ArgumentParser(prog="network-egress-preflight")
    parser.add_argument("--root", required=True)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--capture-id")
    mode.add_argument("--verify")
    parser.add_argument("--repository")
    parser.add_argument("--local-only", action="store_true")
    parser.add_argument("--baseline-local-seal")
    parser.add_argument("--git-credential-seal")
    parser.add_argument("--gh-credential-seal")
    parser.add_argument("--fetch-policy")
    parser.add_argument("--require-seal-record")
    parser.add_argument("--print-field")
    options = parser.parse_args(list(argv))
    root = Path(options.root).resolve()
    if options.verify is not None:
        if any(
            value is not None
            for value in (
                options.repository,
                options.baseline_local_seal,
                options.git_credential_seal,
                options.gh_credential_seal,
                options.fetch_policy,
            )
        ) or options.local_only:
            raise AuditError("network preflight verify/create argument drift")
        if options.require_seal_record is None or options.print_field is None:
            raise AuditError("network preflight verify selector is incomplete")
        selection = reopen_generic_seal(root, options.require_seal_record)
        expected_path = (
            Path(selection["absolutePath"]) / "network-egress.json"
        ).resolve()
        if Path(options.verify).resolve() != expected_path:
            raise AuditError("network preflight verification lineage drift")
        record = reopen_sealed_named_record(
            root, options.require_seal_record, "network-egress.json"
        )
        validate_network_egress_record(record)
        allowed_fields = {
            "recordDigest", "localConfigProjectionDigest",
        }
        if record.get("profile") == "full":
            allowed_fields.add("stableProjectionDigest")
        if options.print_field not in allowed_fields:
            raise AuditError("network preflight print field drift")
        return _emit_named_scalar(record, options.print_field)
    if (
        options.repository is None
        or options.require_seal_record is not None
        or options.print_field is not None
    ):
        raise AuditError("network preflight create selector is incomplete")
    local = capture_live_network_local_projection(Path(options.repository))
    if options.local_only:
        if any(
            value is not None
            for value in (
                options.baseline_local_seal,
                options.git_credential_seal,
                options.gh_credential_seal,
                options.fetch_policy,
            )
        ):
            raise AuditError("local-only preflight cannot bind network authority")
        record = build_network_egress_preflight(local, local_only=True)
    else:
        if any(
            value is None
            for value in (
                options.baseline_local_seal,
                options.git_credential_seal,
                options.gh_credential_seal,
                options.fetch_policy,
            )
        ):
            raise AuditError("full network preflight authority is incomplete")
        if options.fetch_policy != "qinao-fixed-v1":
            raise AuditError("network fetch policy drift")
        baseline = reopen_sealed_named_record(
            root, options.baseline_local_seal, "network-egress.json"
        )
        validate_network_egress_record(baseline)
        if (
            baseline.get("profile") != "local-only"
            or baseline.get("localConfigProjectionDigest")
            != local["localConfigProjectionDigest"]
        ):
            raise AuditError("network local baseline drift")
        git_credential = reopen_sealed_named_record(
            root, options.git_credential_seal, "credential-proof.json"
        )
        gh_credential = reopen_sealed_named_record(
            root, options.gh_credential_seal, "credential-proof.json"
        )
        validate_credential_authority_record(git_credential, "git")
        validate_credential_authority_record(gh_credential, "gh")
        record = build_network_egress_preflight(
            local,
            local_only=False,
            destination={
                "git": "https://github.com/ChangGeng01/ProjectSix.git"
            },
            git_credential={
                "identityDigest": git_credential["identityDigest"],
                "generationDigest": git_credential["generationDigest"],
            },
            gh_credential={
                "identityDigest": gh_credential["identityDigest"],
                "generationDigest": gh_credential["generationDigest"],
            },
            fetch_policy={"version": options.fetch_policy},
        )
    validate_network_egress_record(record)
    output = _capture_output_path(
        root, options.capture_id, "network-egress.json"
    )
    write_canonical_exclusive(output, record)
    return _emit_canonical(record)


