def _command_network_git(
    argv: Sequence[str], context: CommandContext
) -> int:
    values = list(argv)
    if values.count("--") != 1:
        raise AuditError("network-git requires one child argv separator")
    separator = values.index("--")
    option_values = values[:separator]
    child_argv = values[separator + 1 :]
    parser = argparse.ArgumentParser(prog="network-git")
    parser.add_argument("--preflight", required=True)
    parser.add_argument("--intent", required=True)
    parser.add_argument(
        "--operation",
        choices=tuple(sorted(_network_operations_for_wrapper("network-git"))),
        required=True,
    )
    state = parser.add_mutually_exclusive_group()
    state.add_argument("--quarantine-empty", action="store_true")
    state.add_argument("--quarantine-nonempty", action="store_true")
    options = parser.parse_args(option_values)
    git_binding = _parse_network_git_argv(
        options.operation, child_argv
    )
    child_argv = git_binding["argv"]
    specification = _network_operation_contract(options.operation)
    parser_family = specification["parserFamily"]
    is_fetch = parser_family in ("git-fetch-empty", "git-fetch-known")
    if is_fetch != (
        options.quarantine_empty or options.quarantine_nonempty
    ):
        raise AuditError("network-git quarantine selector drift")
    if parser_family == "git-fetch-empty" and not options.quarantine_empty:
        raise AuditError("fetch-empty requires empty quarantine")
    if parser_family == "git-fetch-known" and not options.quarantine_nonempty:
        raise AuditError("fetch-known requires nonempty quarantine")
    root, preflight, _preflight_seal, _preflight_capture = (
        _reopen_sealed_network_member(
            options.preflight, "qinao.network-egress.v1"
        )
    )
    cold_tool_mode = _network_cold_preflight_mode(preflight)
    if preflight.get("profile") != "full":
        raise AuditError("network-git requires a full preflight")
    intent_root, manifest, intent_seal, intent_capture = (
        _reopen_sealed_network_member(
            options.intent, "qinao.network-request-manifest.v2"
        )
    )
    if intent_root != root:
        raise AuditError("network-git preflight/intent ledger drift")
    recovered = recover_run_state(root)
    allocation = intent_capture.get("allocation", {})
    bound_frontier = allocation.get("frontierId")
    open_frontiers = [
        row for row in recovered.get("openFrontiers", [])
        if row.get("frontierKind") in ("remote-mutation", "local-resource")
        and (
            bound_frontier is None
            or row.get("frontierId") == bound_frontier
        )
    ]
    if len(open_frontiers) != 1:
        raise AuditError("network-git operation frontier is absent or ambiguous")
    frontier_id = open_frontiers[0]["frontierId"]
    if is_fetch:
        _validate_network_git_fetch_binding(
            options.operation,
            child_argv,
            preflight,
            manifest,
            quarantine_empty=options.quarantine_empty,
            _tool_mode=cold_tool_mode,
        )
    else:
        _select_network_request_row(
            manifest, options.operation, child_argv, preflight, _tool_mode=cold_tool_mode,
        )
    logical_key = _select_network_cold_use_key(
        root, frontier_id, "network-git", options.operation,
        child_argv, preflight, manifest,
    )
    existing = recover_or_reopen_network_logical_key_no_network(
        root, logical_key
    )
    if existing is not None:
        return _emit_canonical(existing)
    validate_network_egress_record(preflight)
    reservation = reserve_network_execution_no_live_work(
        root,
        frontier_id,
        wrapper="network-git",
        operation=options.operation,
        argv=child_argv,
        preflight=preflight,
        manifest=manifest,
    )
    _run_reserved_network_preflight_step(
        root,
        reservation,
        "LiveProjectionDrift",
        lambda: _require_live_network_projection(
            preflight, "network-git"
        ),
    )
    adapter = _run_reserved_network_preflight_step(
        root,
        reservation,
        "BrokerBindingDrift",
        lambda: _runtime_capability(context),
    )
    capsule_profile = {
        "git-ls-remote": "ls-remote-read",
        "git-fetch-empty": "fetch-quarantine",
        "git-fetch-known": "fetch-quarantine",
        "git-push": "push-outbound",
    }[parser_family]
    if is_fetch:
        resource_id = open_frontiers[0].get("resourceId")
        if not isinstance(resource_id, str):
            raise AuditError("network-git fetch capsule resource is absent")
        prepared_capsule = _run_reserved_network_preflight_step(
            root,
            reservation,
            "ExecutionCapsuleUnavailable",
            lambda: reopen_prepared_git_execution_capsule(
                root,
                resource_id,
                expected_profile=capsule_profile,
                preflight=preflight,
            ),
        )
    else:
        prepared_capsule = _run_reserved_network_preflight_step(
            root,
            reservation,
            "ExecutionCapsuleUnavailable",
            lambda: prepare_git_execution_capsule(
                root,
                capsule_profile,
                preflight,
                source_repository=(
                    Path(preflight["repository"])
                    if capsule_profile == "push-outbound" else None
                ),
                source_oid=(
                    git_binding.get("sourceOid")
                    if capsule_profile == "push-outbound" else None
                ),
            ),
        )
    helper_secret: Optional[OwnedSecretBuffer] = None
    broker: Optional[OneShotCredentialBroker] = None
    try:
        helper_secret = _run_reserved_network_preflight_step(
            root,
            reservation,
            "CredentialUnavailable",
            lambda: _credential_fill_from_fresh_capsule(
                root,
                Path(preflight["repository"]),
                adapter,
                preflight=preflight,
            ),
        )
        if not isinstance(helper_secret, OwnedSecretBuffer):
            _raise_reserved_network_preflight_failure(
                root,
                reservation,
                "CredentialUnavailable",
                "network-git credential helper owner drift",
            )
        fields = _run_reserved_network_preflight_step(
            root,
            reservation,
            "CredentialUnavailable",
            lambda: _parse_owned_credential_helper(helper_secret),
        )
        source_identity = _git_credential_source_identity(
            fields.view("username")
        )
        if (
            _digest_projection(source_identity)
            != preflight["gitCredentialIdentityDigest"]
        ):
            _raise_reserved_network_preflight_failure(
                root,
                reservation,
                "CredentialIdentityDrift",
                "network-git credential helper identity drift",
            )
        generation = _run_reserved_network_preflight_step(
            root,
            reservation,
            "CredentialGenerationDrift",
            lambda: _credential_generation_digest(
                root, "git", fields.view("password")
            ),
        )
        if generation != preflight["gitCredentialGenerationDigest"]:
            _raise_reserved_network_preflight_failure(
                root,
                reservation,
                "CredentialGenerationDrift",
                "network-git credential generation drift",
            )
        broker = _run_reserved_network_preflight_step(
            root,
            reservation,
            "BrokerBindingDrift",
            lambda: OneShotCredentialBroker(
                helper_secret, generation_digest=generation
            ),
        )
        helper_secret = None
        terminal = _run_reserved_network_attempt_step(
            root,
            reservation,
            lambda: execute_network_wrapper(
                root,
                frontier_id,
                wrapper="network-git",
                operation=options.operation,
                argv=child_argv,
                preflight=preflight,
                manifest=manifest,
                transport=adapter,
                quarantine_empty=(
                    options.quarantine_empty if is_fetch else None
                ),
                credential_broker=broker,
                request_seal_record_path=intent_seal,
                git_execution_capsule=prepared_capsule["capsule"],
                git_execution_capsule_snapshot=prepared_capsule["snapshot"],
                execution_reservation=reservation,
            ),
        )
        return _emit_canonical(terminal)
    finally:
        if broker is not None:
            broker.close()
        if helper_secret is not None:
            helper_secret.release()


def _command_network_gh(
    argv: Sequence[str], context: CommandContext
) -> int:
    values = list(argv)
    if values.count("--") != 1:
        raise AuditError("network-gh requires one child argv separator")
    separator = values.index("--")
    option_values = values[:separator]
    child_argv = _validate_argv(values[separator + 1 :])
    parser = argparse.ArgumentParser(prog="network-gh")
    parser.add_argument("--preflight", required=True)
    parser.add_argument("--intent", required=True)
    parser.add_argument(
        "--operation",
        choices=tuple(sorted(_network_operations_for_wrapper("network-gh"))),
        required=True,
    )
    parser.add_argument("--request-body")
    parser.add_argument("--request-body-seal-record")
    options = parser.parse_args(option_values)
    _parse_network_gh_request(options.operation, child_argv)
    specification = _network_operation_contract(options.operation)
    root, preflight, _preflight_seal, _preflight_capture = (
        _reopen_sealed_network_member(
            options.preflight, "qinao.network-egress.v1"
        )
    )
    cold_tool_mode = _network_cold_preflight_mode(preflight)
    if preflight.get("profile") != "full":
        raise AuditError("network-gh requires a full preflight")
    body_required = specification["bodySchema"] is not None
    if body_required != (
        options.request_body is not None
        and options.request_body_seal_record is not None
    ):
        raise AuditError("network-gh sealed request-body option drift")
    request_body_record: Optional[Dict[str, Any]] = None
    if body_required:
        body_root, request_body_record, body_seal, body_capture = (
            _reopen_sealed_network_member(
                options.request_body,
                "qinao.network-gh-request-body.v1",
            )
        )
        if (
            body_root != root
            or body_seal != options.request_body_seal_record
            or body_capture.get("allocation", {}).get("phase")
            != "network-gh-request-body"
        ):
            raise AuditError("network-gh request-body sealed lineage drift")
        validate_network_gh_request_body(
            request_body_record, options.operation
        )
    intent_root, manifest, intent_seal, intent_capture = (
        _reopen_sealed_network_member(
            options.intent, "qinao.network-request-manifest.v2"
        )
    )
    if intent_root != root:
        raise AuditError("network-gh preflight/intent ledger drift")
    _select_network_request_row(
        manifest,
        options.operation,
        child_argv,
        preflight,
        request_body_record=request_body_record,
        _tool_mode=cold_tool_mode,
    )
    recovered = recover_run_state(root)
    bound_frontier = intent_capture.get("allocation", {}).get("frontierId")
    open_frontiers = [
        row for row in recovered.get("openFrontiers", [])
        if row.get("frontierKind") in ("remote-mutation", "local-resource")
        and (
            bound_frontier is None
            or row.get("frontierId") == bound_frontier
        )
    ]
    if len(open_frontiers) != 1:
        raise AuditError("network-gh operation frontier is absent or ambiguous")
    frontier_id = open_frontiers[0]["frontierId"]
    logical_key = _select_network_cold_use_key(
        root, frontier_id, "network-gh", options.operation,
        child_argv, preflight, manifest,
        request_body_record=request_body_record,
    )
    existing = recover_or_reopen_network_logical_key_no_network(
        root, logical_key
    )
    if existing is not None:
        return _emit_canonical(existing)
    validate_network_egress_record(preflight)
    reservation = reserve_network_execution_no_live_work(
        root,
        frontier_id,
        wrapper="network-gh",
        operation=options.operation,
        argv=child_argv,
        preflight=preflight,
        manifest=manifest,
        request_body_record=request_body_record,
    )
    _run_reserved_network_preflight_step(
        root,
        reservation,
        "LiveProjectionDrift",
        lambda: _require_live_network_projection(preflight, "network-gh"),
    )
    adapter = _run_reserved_network_preflight_step(
        root,
        reservation,
        "BrokerBindingDrift",
        lambda: _runtime_capability(context),
    )
    selected_gh = _run_reserved_network_preflight_step(
        root,
        reservation,
        "CredentialIdentityDrift",
        lambda: _selected_gh_from_projection(preflight["localProjection"]),
    )
    token_secret = _run_reserved_network_preflight_step(
        root,
        reservation,
        "CredentialUnavailable",
        lambda: adapter.resolve_gh_token(selected_tool=selected_gh),
    )
    if not isinstance(token_secret, OwnedSecretBuffer):
        _raise_reserved_network_preflight_failure(
            root,
            reservation,
            "CredentialUnavailable",
            "network-gh token owner drift",
        )
    with token_secret:
        token = token_secret.view()
        if not token or len(token) > 64 * 1024 or any(
            value in (0, 10, 13) for value in token
        ):
            _raise_reserved_network_preflight_failure(
                root,
                reservation,
                "CredentialUnavailable",
                "network-gh token framing drift",
            )
        source_identity = _gh_credential_source_identity(selected_gh)
        if (
            _digest_projection(source_identity)
            != preflight["ghCredentialIdentityDigest"]
        ):
            _raise_reserved_network_preflight_failure(
                root,
                reservation,
                "CredentialIdentityDrift",
                "network-gh token source identity drift",
            )
        generation = _run_reserved_network_preflight_step(
            root,
            reservation,
            "CredentialGenerationDrift",
            lambda: _credential_generation_digest(root, "gh", token),
        )
        if generation != preflight["ghCredentialGenerationDigest"]:
            _raise_reserved_network_preflight_failure(
                root,
                reservation,
                "CredentialGenerationDrift",
                "network-gh credential generation drift",
            )
        terminal = _run_reserved_network_attempt_step(
            root,
            reservation,
            lambda: execute_network_wrapper(
                root,
                frontier_id,
                wrapper="network-gh",
                operation=options.operation,
                argv=child_argv,
                preflight=preflight,
                manifest=manifest,
                transport=_NetworkGhDirectTransport(
                    adapter, token, request_body_record
                ),
                request_seal_record_path=intent_seal,
                gh_request_body_record=request_body_record,
                execution_reservation=reservation,
            ),
        )
        return _emit_canonical(terminal)


def _quarantine_live_broker(
    root: Path, preflight: Mapping[str, Any], adapter: Any
) -> OneShotCredentialBroker:
    _require_live_network_projection(preflight, "quarantine")
    helper_secret = _credential_fill_from_fresh_capsule(
        root,
        Path(preflight["repository"]),
        adapter,
        preflight=preflight,
    )
    if not isinstance(helper_secret, OwnedSecretBuffer):
        raise AuditError("quarantine credential helper owner drift")
    try:
        fields = _parse_owned_credential_helper(helper_secret)
        source_identity = _git_credential_source_identity(
            fields.view("username")
        )
        generation = _credential_generation_digest(
            Path(root).resolve(), "git", fields.view("password")
        )
        if (
            _digest_projection(source_identity)
            != preflight["gitCredentialIdentityDigest"]
            or generation != preflight["gitCredentialGenerationDigest"]
        ):
            raise AuditError("quarantine credential generation drift")
        broker = OneShotCredentialBroker(
            helper_secret, generation_digest=generation
        )
        helper_secret = None
        return broker
    finally:
        if helper_secret is not None:
            helper_secret.release()


def _recover_quarantine_frontier_state(
    root: Path, frontier_id: str
) -> Dict[str, Any]:
    root = Path(root).resolve()
    recovered = recover_run_state(root)
    if recovered["classification"] == "complete":
        return recovered
    _identity, records = _recover_records(root)
    starts = [
        record for record in records
        if record.get("operationKind") == "frontier-start"
        and record.get("frontierId") == frontier_id
    ]
    if (
        len(starts) != 1
        or starts[0].get("frontierKind") != "local-resource"
    ):
        raise AuditError("quarantine frontier recovery is indeterminate")
    resource_id = starts[0].get("resourceId")
    _require_lower_hex(resource_id, 32, "quarantine recovery resource ID")
    return _recover_complete_state(
        root, allow_resource_drift_id=resource_id
    )


def _quarantine_outcomes_for_frontier(
    root: Path, frontier_id: str
) -> List[Dict[str, Any]]:
    recovered = _recover_quarantine_frontier_state(root, frontier_id)
    rows = []
    for value in recovered.get("captures", {}).values():
        allocation = value.get("allocation", {})
        if (
            value.get("state") != "sealed"
            or allocation.get("phase") not in (
                "quarantine-outcome", "quarantine-observation"
            )
        ):
            continue
        filename = (
            "observation.json"
            if allocation["phase"] == "quarantine-observation"
            else "outcome.json"
        )
        member = Path(allocation["absolutePath"]) / filename
        record = _recovered_canonical_capture_member(
            value, filename, "quarantine frontier outcome"
        )
        _verify_self_digest(record)
        context = record.get("context", {})
        if frontier_id in {
            record.get("componentFrontierId"),
            context.get("fetchFrontierId"),
            context.get("importFrontierId"),
        }:
            rows.append(
                dict(
                    _quarantine_outcome_wrapper(
                        record, member, value["seal"], Path(root).resolve()
                    ),
                    _sequence=value["seal"]["sequence"],
                )
            )
    rows.sort(key=lambda row: row["_sequence"])
    return rows


def recover_quarantine_frontier_no_network(
    root: Path, frontier_id: str, shared_adapter: Optional[Any] = None
) -> Dict[str, Any]:
    root = Path(root).resolve()
    outcomes = _quarantine_outcomes_for_frontier(root, frontier_id)
    if not outcomes:
        raise AuditError("quarantine recovery frontier has no typed outcome")
    selected = dict(outcomes[-1])
    selected.pop("_sequence", None)
    context = _require_mapping(selected.get("context"), "recovery context")
    if selected["state"] == "advertisement-sealed":
        recovered = _recover_quarantine_frontier_state(root, frontier_id)
        attempts = [
            value for value in recovered.get("networkAttempts", [])
            if (value.get("attempt") or {}).get("frontierId") == frontier_id
        ]
        if attempts:
            if len(attempts) != 1:
                raise AuditError(
                    "quarantine recovery network attempt is ambiguous"
                )
            logical_key = attempts[0].get("logicalKey")
            if not isinstance(logical_key, str):
                raise AuditError(
                    "quarantine recovery logical key is absent"
                )
            terminal = recover_or_reopen_network_logical_key_no_network(
                root, logical_key
            )
            if not isinstance(terminal, Mapping):
                raise AuditError(
                    "quarantine recovery network terminal is absent"
                )
            return recover_quarantine_outcome_no_network(
                root, selected["outcomeRecordPath"]
            )
        snapshot = snapshot_resource(
            root, context["resourceId"], frontier_id
        )
        completion = frontier_complete(
            root,
            frontier_id,
            input_digest=context["fetchInputDigest"],
            declared_paths=[],
            outcome="tainted-preserved",
            resource_snapshot_digest=snapshot["snapshotDigest"],
        )
        updated = dict(context)
        updated.update(
            {
                "networkTerminalRecordPath": None,
                "fetchTerminalRecordPath": _ledger_record_path(
                    root, completion
                ),
                "resourceFinalSnapshotDigest": snapshot["snapshotDigest"],
                "observedOid": None,
            }
        )
        return _persist_quarantine_outcome(
            root,
            state="fetch-tainted",
            next_action="allocate-fresh-generation",
            component_kind="quarantine-fetch",
            component_frontier_id=frontier_id,
            context=updated,
        )
    if selected["state"] == "fetch-completed":
        if shared_adapter is None:
            raise AuditError("quarantine import recovery adapter is absent")
        return resume_quarantine_outcome(
            root,
            selected["outcomeRecordPath"],
            shared_adapter=shared_adapter,
            stop_after="import-completed",
        )
    return selected


def _command_quarantine_ref_observe(
    argv: Sequence[str], context: CommandContext
) -> int:
    if "--empty" in argv or "--nonempty" in argv:
        parser = argparse.ArgumentParser(prog="quarantine-ref-observe")
        state = parser.add_mutually_exclusive_group(required=True)
        state.add_argument("--empty", action="store_true")
        state.add_argument("--nonempty", action="store_true")
        parser.add_argument("--remote-ref", action="append", default=[])
        parser.add_argument("--negotiation-tip", action="append", default=[])
        parser.add_argument("--output", required=True)
        options = parser.parse_args(list(argv))
        return _persist_result(
            options.output,
            build_quarantine_fetch_plan(
                options.empty, options.remote_ref, options.negotiation_tip
            ),
        )
    parser = argparse.ArgumentParser(prog="quarantine-ref-observe")
    parser.add_argument("--root", required=True)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--start-composition", action="store_true")
    mode.add_argument("--resume-outcome")
    mode.add_argument("--recover-existing")
    parser.add_argument("--parent-frontier")
    parser.add_argument("--request-manifest")
    parser.add_argument("--request-seal-record")
    parser.add_argument("--advertisement-seal-record")
    parser.add_argument("--preflight")
    parser.add_argument("--supersede-tainted-outcome")
    parser.add_argument("--to-terminal", action="store_true")
    parser.add_argument("--no-network", action="store_true")
    parser.add_argument(
        "--stop-after",
        choices=("advertisement-sealed", "fetch-completed", "import-completed"),
    )
    options = parser.parse_args(list(argv))
    root = Path(options.root).resolve()
    if options.recover_existing is not None:
        if (
            not options.no_network
            or options.to_terminal
            or options.stop_after is not None
            or any(
                value is not None
                for value in (
                    options.parent_frontier,
                    options.request_manifest,
                    options.request_seal_record,
                    options.advertisement_seal_record,
                    options.preflight,
                    options.supersede_tainted_outcome,
                )
            )
        ):
            raise AuditError("quarantine no-network recovery option drift")
        return _emit_canonical(
            recover_quarantine_frontier_no_network(
                root, options.recover_existing
            )
        )
    if options.no_network or not options.to_terminal:
        raise AuditError("quarantine continuation mode drift")
    adapter = _runtime_capability(context)
    if options.resume_outcome is not None:
        if (
            options.stop_after is not None
            or any(
                value is not None
                for value in (
                    options.parent_frontier,
                    options.request_manifest,
                    options.request_seal_record,
                    options.advertisement_seal_record,
                    options.preflight,
                    options.supersede_tainted_outcome,
                )
            )
        ):
            raise AuditError("quarantine resume option drift")
        reopened = _reopen_quarantine_outcome(
            root, options.resume_outcome
        )
        selected = _latest_quarantine_outcome(root, reopened)
        reopened_preflight = _require_mapping(
            _require_mapping(
                selected.get("context"), "quarantine resume context"
            ).get("preflight"),
            "quarantine resume preflight",
        )
        adapter = adapter.for_repository(
            Path(reopened_preflight["repository"])
        )
        broker: Optional[OneShotCredentialBroker] = None
        try:
            if selected["state"] == "advertisement-sealed":
                broker = _quarantine_live_broker(
                    root, selected["context"]["preflight"], adapter
                )
            result = resume_quarantine_outcome(
                root,
                options.resume_outcome,
                shared_adapter=adapter,
                transport=adapter if broker is not None else None,
                credential_broker=broker,
            )
            return _emit_canonical(result)
        finally:
            if broker is not None:
                broker.close()
    required = (
        options.parent_frontier,
        options.request_manifest,
        options.request_seal_record,
        options.advertisement_seal_record,
        options.preflight,
    )
    if not all(value is not None for value in required):
        raise AuditError("quarantine composition arguments are incomplete")
    preflight_root, preflight, _preflight_seal, _capture = (
        _reopen_sealed_network_member(
            options.preflight, "qinao.network-egress.v1"
        )
    )
    validate_network_egress_record(preflight)
    adapter = adapter.for_repository(Path(preflight["repository"]))
    manifest_root, manifest, request_seal, _request_capture = (
        _reopen_sealed_network_member(
            options.request_manifest,
            "qinao.network-request-manifest.v2",
        )
    )
    if (
        preflight_root != root
        or manifest_root != root
        or request_seal != options.request_seal_record
    ):
        raise AuditError("quarantine sealed input lineage drift")
    typed, _advertisement, _seals = _reopen_quarantine_inputs(
        root,
        options.request_seal_record,
        options.advertisement_seal_record,
        manifest,
    )
    if typed.get("predecessorOutcomeRecordPath") != (
        options.supersede_tainted_outcome
    ):
        raise AuditError("quarantine typed predecessor repetition drift")
    broker = _quarantine_live_broker(root, preflight, adapter)
    try:
        result = execute_quarantine_composition(
            root,
            parent_frontier_id=options.parent_frontier,
            request_seal_record_path=options.request_seal_record,
            advertisement_seal_record_path=(
                options.advertisement_seal_record
            ),
            preflight=preflight,
            manifest=manifest,
            transport=adapter,
            shared_adapter=adapter,
            credential_broker=broker,
            stop_after=options.stop_after,
        )
        return _emit_canonical(result)
    finally:
        broker.close()


def _ensure_sealed_lfs_network_request(
    root: Path,
    frontier_id: str,
    approved_seal: str,
    manifest: Mapping[str, Any],
) -> Tuple[str, str]:
    """Cold-select or publish the exact LFS request parent generation."""

    root = Path(root).resolve()
    recovered = recover_run_state(root)
    if recovered.get("classification") != "complete":
        raise AuditError("LFS request ledger is indeterminate")
    candidates = [
        value
        for value in recovered.get("captures", {}).values()
        if value.get("allocation", {}).get("phase")
        == "lfs-network-request"
        and value.get("allocation", {}).get("frontierId") == frontier_id
    ]
    sealed = [value for value in candidates if value.get("state") == "sealed"]
    allocated = [
        value for value in candidates if value.get("state") == "allocated"
    ]
    if len(sealed) > 1 or len(allocated) > 1:
        raise AuditError("LFS request generation is ambiguous")
    if sealed:
        selected = sealed[0]
        allocation = selected["allocation"]
        if [
            row.get("recordPath")
            for row in allocation.get("parentCaptures", [])
        ] != [approved_seal]:
            raise AuditError("LFS request approved-parent lineage drift")
        seal_path = _ledger_record_path(root, selected["seal"])
        record = reopen_sealed_named_record(
            root,
            seal_path,
            "network-request.json",
            expected_phase="lfs-network-request",
        )
        if record != dict(manifest):
            raise AuditError("LFS sealed request generation substitution")
        return str(
            Path(allocation["absolutePath"]) / "network-request.json"
        ), seal_path
    replacement = (
        None if not allocated
        else allocated[0]["allocation"]["captureId"]
    )
    allocation = allocate_capture(
        root,
        "lfs-network-request",
        frontier_id=frontier_id,
        parent_capture_records=[approved_seal],
        replace_incomplete_capture=replacement,
    )
    member = Path(allocation["absolutePath"]) / "network-request.json"
    write_canonical_exclusive(member, dict(manifest))
    seal = seal_capture(
        root, allocation["captureId"], ["network-request.json"]
    )
    return str(member), _ledger_record_path(root, seal)


def _reopen_historical_lfs_network_request(
    root: Path,
    frontier_id: str,
    approved_seal: str,
    preflight: Mapping[str, Any],
    operation: str,
    argv: Sequence[str],
) -> Tuple[Dict[str, Any], str]:
    """Read the prior exact sealed generation; never create a request."""

    recovered = recover_run_state(root)
    if recovered.get("classification") != "complete":
        raise AuditError("LFS request ledger is indeterminate")
    candidates = [
        value for value in recovered.get("captures", {}).values()
        if value.get("allocation", {}).get("phase") == "lfs-network-request"
        and value.get("allocation", {}).get("frontierId") == frontier_id
    ]
    sealed = [value for value in candidates if value.get("state") == "sealed"]
    allocated = [value for value in candidates if value.get("state") == "allocated"]
    if len(sealed) > 1 or len(allocated) > 1:
        raise AuditError("LFS request generation is ambiguous")
    if not sealed:
        validate_network_egress_record(preflight)
        raise AuditError("historical LFS sealed request is absent")
    selected = sealed[0]
    if [row.get("recordPath") for row in selected["allocation"].get("parentCaptures", [])] != [approved_seal]:
        raise AuditError("LFS request approved-parent lineage drift")
    seal_path = _ledger_record_path(root, selected["seal"])
    manifest = reopen_sealed_named_record(
        root, seal_path, "network-request.json", expected_phase="lfs-network-request",
    )
    _select_network_request_row(
        manifest, operation, argv, preflight, _tool_mode="historical-seven",
    )
    if manifest["rowCount"] != 1 or manifest["parentObservationRecordDigest"] is not None:
        raise AuditError("LFS sealed request generation substitution")
    return manifest, seal_path


def _command_lfs_batch_observe(
    argv: Sequence[str], context: CommandContext
) -> int:
    parser = argparse.ArgumentParser(prog="lfs-batch-observe")
    parser.add_argument("--endpoint", required=True)
    parser.add_argument("--ref", required=True)
    parser.add_argument("--manifest", required=True)
    parser.add_argument("--preflight", required=True)
    parser.add_argument(
        "--empty-policy", choices=("emit-no-network",), required=True
    )
    parser.add_argument("--output", required=True)
    options = parser.parse_args(list(argv))
    if options.endpoint != (
        "https://github.com/ChangGeng01/ProjectSix.git/info/lfs/"
        "objects/batch"
    ):
        raise AuditError("LFS CLI endpoint drift")
    root, preflight, _preflight_seal, _preflight_capture = (
        _reopen_sealed_network_member(
            options.preflight, "qinao.network-egress.v1"
        )
    )
    cold_tool_mode = _network_cold_preflight_mode(preflight)
    if (
        preflight.get("profile") != "full"
        or preflight.get("lfsEndpoint") + "/objects/batch"
        != options.endpoint
    ):
        raise AuditError("LFS CLI preflight endpoint drift")
    manifest_root, approved, approved_seal, _approved_capture = (
        _reopen_sealed_network_member(
            options.manifest, "qinao.lfs-approved-manifest.v1"
        )
    )
    if manifest_root != root or approved["candidateRef"] != options.ref:
        raise AuditError("LFS CLI manifest lineage/ref drift")
    lineage = reopen_lfs_approved_lineage(
        root, approved, approved_seal
    )
    approved = lineage["approved"]
    output = Path(options.output)
    if not output.is_absolute() or output.name != "lfs-remote-observation.json":
        raise AuditError("LFS CLI output path drift")
    output_root = _network_run_root_from_member(str(output))
    if output_root != root:
        raise AuditError("LFS CLI output ledger drift")
    recovered = recover_run_state(root)
    output_captures = [
        value for value in recovered.get("captures", {}).values()
        if Path(value.get("allocation", {}).get("absolutePath", ""))
        == output.parent
        and value.get("state") == "allocated"
    ]
    if len(output_captures) != 1:
        raise AuditError("LFS CLI output capture is absent or terminal")
    output_capture = output_captures[0]
    allocation = output_capture["allocation"]
    if (
        allocation.get("phase") != "lfs-presence-observation"
        or [row.get("recordPath") for row in allocation.get("parentCaptures", [])]
        != [approved_seal]
    ):
        raise AuditError("LFS CLI output capture lineage drift")
    frontier_id = allocation.get("frontierId")
    open_frontiers = [
        row for row in recovered.get("openFrontiers", [])
        if row.get("frontierId") == frontier_id
        and row.get("frontierKind") in ("remote-mutation", "local-resource")
    ]
    if len(open_frontiers) != 1:
        raise AuditError("LFS CLI operation frontier is absent")
    objects = approved["objects"]
    if not objects:
        validate_network_egress_record(preflight)
        _require_live_network_projection(preflight, "LFS CLI")
        observation = _self_digest_record(
            {
                "schemaVersion": "qinao.lfs-remote-observation.v1",
                "requestObjectCount": 0,
                "requestByteCount": 0,
                "requestSha256": _sha256(b""),
                "responseByteCount": 0,
                "responseSha256": _sha256(b""),
                "redirectCount": 0,
                "followedActionCount": 0,
                "objects": [],
                "networkAttempted": False,
                "preflightRecordDigest": preflight["recordDigest"],
                "approvedManifestRecordDigest": approved["recordDigest"],
                "sourceReviewDigest": approved["sourceReviewDigest"],
                "sourceReviewSealRecordPath": approved[
                    "sourceReviewSealRecordPath"
                ],
                "sourceReviewCaptureId": approved[
                    "sourceReviewCaptureId"
                ],
                "sourceReviewRecordDigest": approved[
                    "sourceReviewRecordDigest"
                ],
                "candidateIdentityDigest": approved[
                    "candidateIdentityDigest"
                ],
                "objectSetDigest": approved["objectSetDigest"],
                "credentialHelperIdentityDigest": preflight[
                    "gitCredentialIdentityDigest"
                ],
                "credentialGenerationDigest": preflight[
                    "gitCredentialGenerationDigest"
                ],
            }
        )
        if output.exists():
            if _read_canonical_file(output) != observation:
                raise AuditError("LFS empty observation output drift")
        else:
            write_canonical_exclusive(output, observation)
        _emit_canonical(observation)
        return 0
    operation = _sole_network_operation("lfs-batch")
    if cold_tool_mode == "historical-seven":
        # Approved lineage already validated these normalized objects and ref.
        # Derive only an equality key, not a fresh historical request capability.
        request_argv = [
            "POST", options.endpoint, options.ref,
            _sha256(canonical_json_bytes({
                "operation": "upload", "objects": objects,
                "ref": {"name": options.ref}, "transfers": ["basic"],
            })),
        ]
        manifest, request_seal = _reopen_historical_lfs_network_request(
            root, frontier_id, approved_seal, preflight, operation, request_argv,
        )
    else:
        request = build_lfs_batch_request(objects, options.ref, preflight)
        request_argv = request["argv"]
        manifest = seal_network_request_manifest(operation, request_argv, preflight)
        _request_member, request_seal = _ensure_sealed_lfs_network_request(
            root, frontier_id, approved_seal, manifest
        )
    logical_key = _select_network_cold_use_key(
        root, frontier_id, "lfs-batch", operation,
        request_argv, preflight, manifest,
    )
    existing = recover_or_reopen_network_logical_key_no_network(
        root, logical_key
    )
    if existing is not None:
        if existing.get("completionState") == "unknown-no-replay":
            return _emit_canonical(existing)
        observation = _network_observation_for_terminal(root, existing)
    else:
        validate_network_egress_record(preflight)
        reservation = reserve_network_execution_no_live_work(
            root,
            frontier_id,
            wrapper="lfs-batch",
            operation=operation,
            argv=request["argv"],
            preflight=preflight,
            manifest=manifest,
        )
        _run_reserved_network_preflight_step(
            root,
            reservation,
            "LiveProjectionDrift",
            lambda: _require_live_network_projection(
                preflight, "LFS CLI"
            ),
        )
        adapter = _run_reserved_network_preflight_step(
            root,
            reservation,
            "BrokerBindingDrift",
            lambda: _runtime_capability(context),
        )
        helper_secret: Optional[OwnedSecretBuffer] = None
        broker: Optional[OneShotCredentialBroker] = None
        try:
            helper_secret = _run_reserved_network_preflight_step(
                root,
                reservation,
                "CredentialUnavailable",
                lambda: _credential_fill_from_fresh_capsule(
                    root,
                    Path(preflight["repository"]),
                    adapter,
                    preflight=preflight,
                ),
            )
            if not isinstance(helper_secret, OwnedSecretBuffer):
                _raise_reserved_network_preflight_failure(
                    root,
                    reservation,
                    "CredentialUnavailable",
                    "LFS credential helper owner drift",
                )
            fields = _run_reserved_network_preflight_step(
                root,
                reservation,
                "CredentialUnavailable",
                lambda: _parse_owned_credential_helper(helper_secret),
            )
            source_identity = _git_credential_source_identity(
                fields.view("username")
            )
            if (
                _digest_projection(source_identity)
                != preflight["gitCredentialIdentityDigest"]
            ):
                _raise_reserved_network_preflight_failure(
                    root,
                    reservation,
                    "CredentialIdentityDrift",
                    "LFS credential helper identity drift",
                )
            generation = _run_reserved_network_preflight_step(
                root,
                reservation,
                "CredentialGenerationDrift",
                lambda: _credential_generation_digest(
                    root, "git", fields.view("password")
                ),
            )
            if generation != preflight["gitCredentialGenerationDigest"]:
                _raise_reserved_network_preflight_failure(
                    root,
                    reservation,
                    "CredentialGenerationDrift",
                    "LFS credential generation drift",
                )
            broker = _run_reserved_network_preflight_step(
                root,
                reservation,
                "BrokerBindingDrift",
                lambda: OneShotCredentialBroker(
                    helper_secret, generation_digest=generation
                ),
            )
            helper_secret = None
            terminal = _run_reserved_network_attempt_step(
                root,
                reservation,
                lambda: execute_network_wrapper(
                    root,
                    frontier_id,
                    wrapper="lfs-batch",
                    operation=operation,
                    argv=request["argv"],
                    preflight=preflight,
                    manifest=manifest,
                    transport=_NetworkLfsDirectTransport(adapter),
                    credential_broker=broker,
                    request_seal_record_path=request_seal,
                    request_parent_payload=manifest,
                    lfs_request_objects=request["requestObjects"],
                    lfs_request_bytes=request["requestBytes"],
                    lfs_approved_manifest=approved,
                    execution_reservation=reservation,
                ),
            )
            observation = _network_observation_for_terminal(root, terminal)
        finally:
            if broker is not None:
                broker.close()
            if helper_secret is not None:
                helper_secret.release()
    if output.exists():
        if _read_canonical_file(output) != observation:
            raise AuditError("LFS observation output drift")
    else:
        write_canonical_exclusive(output, observation)
    _emit_canonical(observation)
    return (
        1
        if any(
            row.get("disposition") == "remote-missing"
            for row in observation.get("objects", [])
        )
        else 0
    )


_TASK5_FORBIDDEN_DYNAMIC_GLOBAL_BUILTINS = frozenset(
    {
        "__import__",
        "compile",
        "eval",
        "exec",
        "globals",
        "locals",
        "vars",
    }
)


def _task5_constant_projection(value: Any) -> Dict[str, Any]:
    if value is None:
        return {"kind": "none"}
    if value is Ellipsis:
        return {"kind": "ellipsis"}
    if value is NotImplemented:
        return {"kind": "not-implemented"}
    if type(value) is bool:
        return {"kind": "bool", "value": value}
    if type(value) is int:
        return {"kind": "int", "value": str(value)}
    if type(value) is float:
        return {"kind": "float", "value": value.hex()}
    if type(value) is complex:
        return {
            "kind": "complex",
            "real": value.real.hex(),
            "imag": value.imag.hex(),
        }
    if type(value) is str:
        return {"kind": "str", "value": value}
    if type(value) is bytes:
        return {
            "kind": "bytes",
            "size": len(value),
            "sha256": _sha256(value),
        }
    if type(value) is tuple:
        return {
            "kind": "tuple",
            "items": [_task5_constant_projection(item) for item in value],
        }
    if type(value) is frozenset:
        items = [_task5_constant_projection(item) for item in value]
        items.sort(key=canonical_json_bytes)
        return {"kind": "frozenset", "items": items}
    if type(value) is CodeType:
        return {"kind": "code", "value": _task5_code_projection(value)}
    raise AuditError("Task 5 classifier constant binding is unsupported")


def _task5_code_projection(code: CodeType) -> Dict[str, Any]:
    if type(code) is not CodeType:
        raise AuditError("Task 5 classifier code binding drift")
    exception_table = getattr(code, "co_exceptiontable", b"")
    if type(exception_table) is not bytes:
        raise AuditError("Task 5 classifier exception table drift")
    return {
        "schemaVersion": "qinao.task5-code-projection.v1",
        "name": code.co_name,
        "qualname": getattr(code, "co_qualname", code.co_name),
        "argCount": code.co_argcount,
        "positionalOnlyArgCount": getattr(
            code, "co_posonlyargcount", 0
        ),
        "keywordOnlyArgCount": code.co_kwonlyargcount,
        "localCount": code.co_nlocals,
        "stackSize": code.co_stacksize,
        "flags": code.co_flags,
        "bytecodeSize": len(code.co_code),
        "bytecodeSha256": _sha256(code.co_code),
        "exceptionTableSize": len(exception_table),
        "exceptionTableSha256": _sha256(exception_table),
        "constants": [
            _task5_constant_projection(value) for value in code.co_consts
        ],
        "names": list(code.co_names),
        "variableNames": list(code.co_varnames),
        "freeVariables": list(code.co_freevars),
        "cellVariables": list(code.co_cellvars),
    }


def _task5_code_global_names(code: CodeType) -> Tuple[str, ...]:
    names = set(code.co_names)
    for value in code.co_consts:
        if type(value) is CodeType:
            names.update(_task5_code_global_names(value))
    return tuple(sorted(names))


def _task5_builtins_mapping(function: FunctionType) -> Mapping[str, Any]:
    value = getattr(function, "__builtins__", None)
    if isinstance(value, ModuleType):
        value = value.__dict__
    if not isinstance(value, Mapping):
        value = function.__globals__.get("__builtins__")
        if isinstance(value, ModuleType):
            value = value.__dict__
    if not isinstance(value, Mapping):
        raise AuditError("Task 5 classifier builtins binding drift")
    return value


def _task5_value_projection(
    value: Any,
    namespace: Mapping[str, Any],
    builtins_mapping: Mapping[str, Any],
    function_stack: Dict[int, str],
    container_stack: set,
) -> Dict[str, Any]:
    if (
        value is None
        or value is Ellipsis
        or value is NotImplemented
        or type(value)
        in (bool, int, float, complex, str, bytes, tuple, frozenset, CodeType)
    ):
        if type(value) is tuple:
            return {
                "kind": "tuple",
                "items": [
                    _task5_value_projection(
                        item,
                        namespace,
                        builtins_mapping,
                        function_stack,
                        container_stack,
                    )
                    for item in value
                ],
            }
        if type(value) is frozenset:
            items = [
                _task5_value_projection(
                    item,
                    namespace,
                    builtins_mapping,
                    function_stack,
                    container_stack,
                )
                for item in value
            ]
            items.sort(key=canonical_json_bytes)
            return {"kind": "frozenset", "items": items}
        return _task5_constant_projection(value)
    if type(value) is FunctionType:
        return _task5_function_projection(
            value,
            namespace,
            builtins_mapping,
            function_stack,
            container_stack,
        )
    if isinstance(value, type) and value.__module__ == "builtins":
        return {
            "kind": "builtin-type",
            "module": value.__module__,
            "qualname": value.__qualname__,
        }
    if inspect.isbuiltin(value):
        return {
            "kind": "builtin-callable",
            "module": getattr(value, "__module__", None),
            "qualname": getattr(
                value, "__qualname__", getattr(value, "__name__", None)
            ),
        }
    if type(value) in (list, dict, set):
        identifier = id(value)
        if identifier in container_stack:
            raise AuditError("Task 5 classifier container cycle drift")
        container_stack.add(identifier)
        try:
            if type(value) is list:
                return {
                    "kind": "list",
                    "items": [
                        _task5_value_projection(
                            item,
                            namespace,
                            builtins_mapping,
                            function_stack,
                            container_stack,
                        )
                        for item in value
                    ],
                }
            if type(value) is set:
                items = [
                    _task5_value_projection(
                        item,
                        namespace,
                        builtins_mapping,
                        function_stack,
                        container_stack,
                    )
                    for item in value
                ]
                items.sort(key=canonical_json_bytes)
                return {"kind": "set", "items": items}
            return {
                "kind": "dict",
                "items": [
                    {
                        "key": _task5_value_projection(
                            key,
                            namespace,
                            builtins_mapping,
                            function_stack,
                            container_stack,
                        ),
                        "value": _task5_value_projection(
                            item,
                            namespace,
                            builtins_mapping,
                            function_stack,
                            container_stack,
                        ),
                    }
                    for key, item in value.items()
                ],
            }
        finally:
            container_stack.remove(identifier)
    raise AuditError("Task 5 classifier value binding is unsupported")


def _task5_function_projection(
    function: FunctionType,
    namespace: Mapping[str, Any],
    builtins_mapping: Mapping[str, Any],
    function_stack: Dict[int, str],
    container_stack: set,
) -> Dict[str, Any]:
    if type(function) is not FunctionType or function.__globals__ is not namespace:
        raise AuditError("Task 5 classifier function binding drift")
    identifier = id(function)
    if identifier in function_stack:
        return {
            "kind": "function-reference",
            "label": function_stack[identifier],
        }
    label = "function-%d" % len(function_stack)
    function_stack[identifier] = label
    try:
        global_names = _task5_code_global_names(function.__code__)
        forbidden = set(global_names) & _TASK5_FORBIDDEN_DYNAMIC_GLOBAL_BUILTINS
        if forbidden:
            raise AuditError(
                "Task 5 classifier dynamic-global binding is forbidden"
            )
        global_rows = []
        for name in global_names:
            if name in namespace:
                source = "module"
                value = namespace[name]
            elif name in builtins_mapping:
                source = "builtins"
                value = builtins_mapping[name]
            else:
                global_rows.append({"name": name, "source": "absent"})
                continue
            global_rows.append(
                {
                    "name": name,
                    "source": source,
                    "value": _task5_value_projection(
                        value,
                        namespace,
                        builtins_mapping,
                        function_stack,
                        container_stack,
                    ),
                }
            )
        closure_rows = []
        for cell in function.__closure__ or ():
            try:
                cell_value = cell.cell_contents
            except ValueError as exc:
                raise AuditError(
                    "Task 5 classifier closure binding drift"
                ) from exc
            closure_rows.append(
                _task5_value_projection(
                    cell_value,
                    namespace,
                    builtins_mapping,
                    function_stack,
                    container_stack,
                )
            )
        return {
            "kind": "function",
            "label": label,
            "name": function.__name__,
            "qualname": function.__qualname__,
            "module": function.__module__,
            "code": _task5_code_projection(function.__code__),
            "defaults": _task5_value_projection(
                function.__defaults__,
                namespace,
                builtins_mapping,
                function_stack,
                container_stack,
            ),
            "keywordDefaults": _task5_value_projection(
                function.__kwdefaults__,
                namespace,
                builtins_mapping,
                function_stack,
                container_stack,
            ),
            "annotations": _task5_value_projection(
                function.__annotations__,
                namespace,
                builtins_mapping,
                function_stack,
                container_stack,
            ),
            "doc": _task5_value_projection(
                function.__doc__,
                namespace,
                builtins_mapping,
                function_stack,
                container_stack,
            ),
            "closure": closure_rows,
            "attributes": _task5_value_projection(
                function.__dict__,
                namespace,
                builtins_mapping,
                function_stack,
                container_stack,
            ),
            "globals": global_rows,
        }
    finally:
        del function_stack[identifier]


def _task5_callable_projection(
    classifier: FunctionType,
    namespace: Mapping[str, Any],
    builtins_mapping: Mapping[str, Any],
) -> Dict[str, Any]:
    return {
        "schemaVersion": "qinao.task5-callable-projection.v1",
        "callable": _task5_function_projection(
            classifier,
            namespace,
            builtins_mapping,
            {},
            set(),
        ),
    }


@dataclass(frozen=True)
class _Task5ClassifierBinding:
    classifier: FunctionType
    _namespace: Dict[str, Any]
    _code: CodeType
    _builtins: Mapping[str, Any]
    _callable_projection_bytes: bytes
    _binding_record_bytes: bytes

    def validate(self) -> str:
        try:
            if (
                type(self) is not _Task5ClassifierBinding
                or type(self.classifier) is not FunctionType
                or self.classifier.__globals__ is not self._namespace
                or self._namespace.get("classify_risk")
                is not self.classifier
                or self.classifier.__code__ is not self._code
                or _task5_builtins_mapping(self.classifier)
                is not self._builtins
            ):
                raise AuditError("Task 5 classifier binding drift")
            fresh_projection_bytes = canonical_json_bytes(
                _task5_callable_projection(
                    self.classifier,
                    self._namespace,
                    self._builtins,
                )
            )
            if not hmac.compare_digest(
                fresh_projection_bytes, self._callable_projection_bytes
            ):
                raise AuditError("Task 5 classifier callable drift")
            binding_record = parse_canonical_json(
                self._binding_record_bytes
            )
            if not isinstance(binding_record, Mapping):
                raise AuditError("Task 5 classifier binding record drift")
            _verify_self_digest(
                binding_record, "classifierBindingDigest"
            )
            if (
                binding_record.get("schemaVersion")
                != "qinao.task5-classifier-binding.v1"
                or binding_record.get("loaderSchemaVersion")
                != "qinao.immutable-source-exec.v1"
                or binding_record.get("moduleRelativePath")
                != "scripts/qinao_pr_validation.py"
                or binding_record.get("exportName") != "classify_risk"
                or binding_record.get("callableProjectionDigest")
                != _sha256(self._callable_projection_bytes)
                or canonical_json_bytes(binding_record)
                != self._binding_record_bytes
            ):
                raise AuditError("Task 5 classifier binding record drift")
            return _require_lower_hex(
                binding_record.get("classifierBindingDigest"),
                64,
                "Task 5 classifier binding digest",
            )
        except AuditError as exc:
            if str(exc).startswith("Task 5 classifier"):
                raise
            raise AuditError("Task 5 classifier binding drift") from exc
        except (AttributeError, KeyError, TypeError, ValueError) as exc:
            raise AuditError("Task 5 classifier binding drift") from exc

    def __call__(self, *args: Any, **kwargs: Any) -> Any:
        before = self.validate()
        try:
            return self.classifier(*args, **kwargs)
        finally:
            after = self.validate()
            if after != before:
                raise AuditError("Task 5 classifier binding drift")


def _load_task5_classifier(repository: Path) -> _Task5ClassifierBinding:
    repository = Path(repository).resolve()
    module_path = repository / "scripts" / "qinao_pr_validation.py"
    source, _observed = _read_ordinary_snapshot(
        module_path,
        maximum=16 * 1024 * 1024,
        single_link=False,
    )
    source_digest = _sha256(source)
    name = "qinao_task5_" + source_digest
    loaded = ModuleType(name)
    loaded.__file__ = "scripts/qinao_pr_validation.py"
    loaded.__package__ = ""
    loaded.__loader__ = None
    loaded.__spec__ = None
    try:
        code = compile(
            source,
            "scripts/qinao_pr_validation.py",
            "exec",
            dont_inherit=True,
            optimize=0,
        )
        exec(code, loaded.__dict__)
    except BaseException as exc:
        raise AuditError("Task 5 classifier module cannot be loaded") from exc
    classifier = loaded.__dict__.get("classify_risk")
    if (
        type(classifier) is not FunctionType
        or classifier.__globals__ is not loaded.__dict__
    ):
        raise AuditError("Task 5 classifier is unavailable")
    builtins_mapping = _task5_builtins_mapping(classifier)
    projection_bytes = canonical_json_bytes(
        _task5_callable_projection(
            classifier, loaded.__dict__, builtins_mapping
        )
    )
    cache_tag = getattr(sys.implementation, "cache_tag", None)
    if not isinstance(cache_tag, str) or not cache_tag:
        raise AuditError("Task 5 classifier Python cache tag drift")
    binding_record = _self_digest_record(
        {
            "schemaVersion": "qinao.task5-classifier-binding.v1",
            "loaderSchemaVersion": "qinao.immutable-source-exec.v1",
            "moduleRelativePath": "scripts/qinao_pr_validation.py",
            "sourceByteCount": len(source),
            "sourceSha256": source_digest,
            "pythonCacheTag": cache_tag,
            "exportName": "classify_risk",
            "callableProjectionDigest": _sha256(projection_bytes),
        },
        field="classifierBindingDigest",
    )
    binding = _Task5ClassifierBinding(
        classifier=classifier,
        _namespace=loaded.__dict__,
        _code=classifier.__code__,
        _builtins=builtins_mapping,
        _callable_projection_bytes=projection_bytes,
        _binding_record_bytes=canonical_json_bytes(binding_record),
    )
    binding.validate()
    return binding


def _risk_event_raw_diff(repository: Path, identity: Mapping[str, Any]) -> bytes:
    validated = validate_ci_identity(identity, purpose="candidate")
    base = _require_lower_hex(validated.get("B"), 40, "risk event B")
    target = _require_lower_hex(validated.get("T"), 40, "risk event T")
    return _run_git(
        Path(repository).resolve(),
        [
            "diff-tree", "--raw", "-z", "--no-renames", "--no-commit-id",
            base + "^{tree}", target,
        ],
    )


def _command_risk_check(argv: Sequence[str], program: str) -> int:
    parser = argparse.ArgumentParser(prog=program)
    parser.add_argument("--root", required=True)
    parser.add_argument("--frontier-id", required=True)
    parser.add_argument("--repository", required=True)
    parser.add_argument("--identity", required=True)
    parser.add_argument("--raw-manifest", required=True)
    parser.add_argument("--raw-manifest-seal-record", required=True)
    parser.add_argument("--content-observation", required=True)
    parser.add_argument("--output", required=True)
    parser.add_argument("--raw-diff", required=(program == "risk-check-raw"))
    options = parser.parse_args(list(argv))
    identity = _read_record(options.identity)
    manifest = _read_record(options.raw_manifest)
    repository = Path(options.repository).resolve()
    if program == "risk-check-event":
        if options.raw_diff is not None:
            raise AuditError("risk-check-event does not accept caller raw diff bytes")
        raw = _risk_event_raw_diff(repository, identity)
    else:
        raw = _read_ordinary(
            Path(options.raw_diff).resolve(), maximum=256 * 1024 * 1024
        )
    classifier = _load_task5_classifier(repository)
    result = execute_risk_check(
        Path(options.root),
        frontier_id=options.frontier_id,
        identity=identity,
        raw_bytes=raw,
        raw_manifest=manifest,
        raw_manifest_seal_record=options.raw_manifest_seal_record,
        observation_seal_record=options.content_observation,
        classifier=classifier,
    )
    return _persist_result(options.output, result)


def _dispatch_command(
    argv: Sequence[str], *, context: Optional[CommandContext] = None
) -> int:
    if not argv:
        raise AuditError("command required")
    command_context = context or CommandContext()
    command = argv[0]
    remainder = argv[1:]
    route = COMMAND_ROUTE_SPEC.get(command)
    if route is None:
        raise AuditError("closed command not implemented: " + command)
    handler_name, style, auxiliary_name = route
    handler = globals().get(handler_name)
    if not callable(handler):
        raise AuditError("registered command handler is unavailable")
    initial_network_guards = _current_thread_network_execution_guards()
    try:
        if style == "plain":
            result = handler(remainder)
        elif style == "context":
            result = handler(remainder, command_context)
        elif style == "binder":
            binder = globals().get(auxiliary_name)
            if not callable(binder):
                raise AuditError(
                    "registered command binder is unavailable"
                )
            result = handler(remainder, binder, command, command_context)
        elif style == "program":
            result = handler(remainder, command)
        else:
            raise AuditError("registered command route is invalid")
    except BaseException as exc:
        try:
            _close_network_execution_guards_since(
                initial_network_guards
            )
        except BaseException as cleanup_error:
            _retain_git_cleanup_error(exc, cleanup_error)
        raise
    _close_network_execution_guards_since(initial_network_guards)
    return result


def main(argv: Optional[Sequence[str]] = None) -> int:
    arguments = list(sys.argv[1:] if argv is None else argv)
    if not arguments:
        raise AuditError("command required")
    outer_route = PUBLIC_COMMAND_ROUTE_SPEC.get(arguments[0])
    if outer_route is not None and outer_route[1] == "outer":
        handler = globals().get(outer_route[0])
        if not callable(handler):
            raise AuditError("registered outer command handler is unavailable")
        return handler(arguments[1:])
    return _dispatch_command(
        arguments,
        context=CommandContext(
            runtime=_make_production_runtime_capability()
        ),
    )


def _main_exit_code(argv: Optional[Sequence[str]] = None) -> int:
    try:
        return main(argv)
    except VerificationFailure as exc:
        sys.stderr.write("qinao audit: " + str(exc) + "\n")
        return 1
    except AuditError as exc:
        sys.stderr.write("qinao audit: " + str(exc) + "\n")
        return 2
    except (OSError, subprocess.SubprocessError, UnicodeError):
        sys.stderr.write("qinao audit: operating-system failure\n")
        return 2
    except (ValueError, TypeError, KeyError, binascii.Error):
        sys.stderr.write("qinao audit: parse failure\n")
        return 2
    except SystemExit as exc:
        code = exc.code
        if code == 0:
            return 0
        if code == 1:
            return 1
        return 2


_FORK_BARRIER_MUST_EXIT = True
_FORK_BARRIER_BEFORE_ERROR: Optional[BaseException] = None
_FORK_BARRIER_PARENT_ERROR: Optional[BaseException] = None


def _authority_before_fork() -> None:
    global _FORK_BARRIER_MUST_EXIT, _FORK_BARRIER_BEFORE_ERROR
    _FORK_BARRIER_MUST_EXIT = True
    _FORK_BARRIER_BEFORE_ERROR = None
    try:
        active = False
        for callback in (
            _network_execution_reservation_before_fork,
            _network_attempt_recovery_permit_before_fork,
            _git_child_execution_grant_before_fork,
            _credential_brokers_before_fork,
            _ledger_transaction_before_fork,
        ):
            snapshot = callback()
            if type(snapshot) is not bool:
                raise AuditError("fork authority snapshot is uncertain")
            active = active or snapshot
        _FORK_BARRIER_MUST_EXIT = active
    except BaseException as exc:
        # CPython ignores at-fork exceptions. Never depend on propagation.
        _FORK_BARRIER_MUST_EXIT = True
        _FORK_BARRIER_BEFORE_ERROR = exc


def _authority_after_fork_parent() -> None:
    global _FORK_BARRIER_MUST_EXIT, _FORK_BARRIER_PARENT_ERROR
    _FORK_BARRIER_MUST_EXIT = True
    _FORK_BARRIER_PARENT_ERROR = None
    for callback in (
        _ledger_transaction_after_fork_parent,
        _credential_brokers_after_fork_parent,
        _git_child_execution_grant_after_fork_parent,
        _network_attempt_recovery_permit_after_fork_parent,
        _network_execution_reservation_after_fork_parent,
    ):
        try:
            callback()
        except BaseException as exc:
            if _FORK_BARRIER_PARENT_ERROR is None:
                _FORK_BARRIER_PARENT_ERROR = exc
            else:
                _retain_git_cleanup_error(_FORK_BARRIER_PARENT_ERROR, exc)


def _authority_after_fork_child() -> None:
    global _FORK_BARRIER_MUST_EXIT
    must_exit = _FORK_BARRIER_MUST_EXIT
    _FORK_BARRIER_MUST_EXIT = True
    if must_exit:
        os._exit(70)
    try:
        _ledger_transaction_after_fork_child()
        _network_execution_reservation_after_fork_child()
        _network_attempt_recovery_permit_after_fork_child()
        _git_child_execution_grant_after_fork_child()
        _credential_brokers_after_fork_child()
        _git_capsule_preparation_after_fork_child()
        _task_test_execution_guard_after_fork_child()
        _cleanup_diagnostics_after_fork_child()
    except BaseException:
        os._exit(70)


# Publish only after every authority and child-only cleanup family exists.
if hasattr(os, "register_at_fork"):
    os.register_at_fork(
        before=_authority_before_fork,
        after_in_parent=_authority_after_fork_parent,
        after_in_child=_authority_after_fork_child,
    )


if __name__ == "__main__":
    raise SystemExit(_main_exit_code())
